INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52053, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「義務を負う」で、負う対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「義務が負った」は主語が二つになり、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「義務へ負った」は方向を表す助詞で、成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「義務で負った」は対象を表せず、成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「義務を負う」で、負う対象を表す。", "が": "「義務が負った」は主語が二つになり、成り立たない。", "へ": "「義務へ負った」は方向を表す助詞で、成り立たない。", "で": "「義務で負った」は対象を表せず、成り立たない。"}, "error_tags": {"が": "subject", "へ": "direction", "で": "means"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放棄する", "is_correct": true, "explanation": "役目を引き受けて背負う「負う」の反対で、手放すこと。"}, {"text": "担う", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}, {"text": "背負う", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}, {"text": "引き受ける", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}], "correct_answer": "放棄する", "explanations": {"放棄する": "役目を引き受けて背負う「負う」の反対で、手放すこと。", "担う": "「負う」と近い意味で、反対ではない。", "背負う": "「負う」と近い意味で、反対ではない。", "引き受ける": "「負う」と近い意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52053, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使命を負う」で、負う対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「使命が負って」は主語が二つになり、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「使命へ負って」は方向を表す助詞で、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「使命と負って」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「使命を負う」で、負う対象を表す。", "が": "「使命が負って」は主語が二つになり、成り立たない。", "へ": "「使命へ負って」は方向を表す助詞で、成り立たない。", "と": "「使命と負って」は成り立たない。"}, "error_tags": {"が": "subject", "へ": "direction", "と": "quotation"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逃れる", "is_correct": true, "explanation": "責任を引き受ける「負う」の反対で、避けて引き受けないこと。"}, {"text": "抱える", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}, {"text": "果たす", "is_correct": false, "explanation": "引き受けたことを成し遂げる意味で、反対ではない。"}, {"text": "請け負う", "is_correct": false, "explanation": "引き受ける意味で、反対ではない。"}], "correct_answer": "逃れる", "explanations": {"逃れる": "責任を引き受ける「負う」の反対で、避けて引き受けないこと。", "抱える": "「負う」と近い意味で、反対ではない。", "果たす": "引き受けたことを成し遂げる意味で、反対ではない。", "請け負う": "引き受ける意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52053, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分がやらなくてはいけないことを、背負うこと。", "primary_collocate": null, "pronunciation": "おう", "ipa": "oɯ", "syllable_count": 2, "sentences": [{"text": "私が役目を負います。", "target_word": "負います", "complexity_tier": "T2", "furigana": "私[わたし]が役目[やくめ]を負[お]います。", "sentence_source": "generated"}, {"text": "彼は家族を養う義務を負った。", "target_word": "負った", "complexity_tier": "T3", "furigana": "彼[かれ]は家族[かぞく]を養[やしな]う義務[ぎむ]を負[お]った。", "sentence_source": "generated"}, {"text": "長男として、家を守る責任を負う。", "target_word": "負う", "complexity_tier": "T3", "furigana": "長男[ちょうなん]として、家[いえ]を守[まも]る責任[せきにん]を負[お]う。", "sentence_source": "generated"}, {"text": "新しい委員長は、大きな役目を負っている。", "target_word": "負っている", "complexity_tier": "T3", "furigana": "新[あたら]しい委員長[いいんちょう]は、大[おお]きな役目[やくめ]を負[お]っている。", "sentence_source": "generated"}, {"text": "彼女は一人で全部を負う必要はない。", "target_word": "負う", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は一人[ひとり]で全部[ぜんぶ]を負[お]う必要[ひつよう]はない。", "sentence_source": "generated"}, {"text": "国民に対する義務を負うのは政府だ。", "target_word": "負う", "complexity_tier": "T3", "furigana": "国民[こくみん]に対[たい]する義務[ぎむ]を負[お]うのは政府[せいふ]だ。", "sentence_source": "generated"}, {"text": "彼は費用の一部を負うことになった。", "target_word": "負う", "complexity_tier": "T3", "furigana": "彼[かれ]は費用[ひよう]の一部[いちぶ]を負[お]うことになった。", "sentence_source": "generated"}, {"text": "重い使命を負って、彼は旅に出た。", "target_word": "負って", "complexity_tier": "T3", "furigana": "重[おも]い使命[しめい]を負[お]って、彼[かれ]は旅[たび]に出[で]た。", "sentence_source": "generated"}, {"text": "みんなで責任を負えば、一人の負担は軽くなる。", "target_word": "負えば", "complexity_tier": "T4", "furigana": "みんなで責任[せきにん]を負[お]えば、一人[ひとり]の負担[ふたん]は軽[かる]くなる。", "sentence_source": "generated"}, {"text": "失敗した場合の責任は、私が負います。", "target_word": "負います", "complexity_tier": "T3", "furigana": "失敗[しっぱい]した場合[ばあい]の責任[せきにん]は、私[わたし]が負[お]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負った", "label": "活用"}, {"form": "負って", "label": "活用"}, {"form": "負わない", "label": "活用"}, {"form": "負えば", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | やるべきことを背負うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52053, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "負う", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "甥", "is_correct": false, "explanation": "おい。「う」が「い」に変わった別の語です。"}, {"text": "億", "is_correct": false, "explanation": "おく。「う」が「く」に変わった別の語です。"}, {"text": "音", "is_correct": false, "explanation": "おと。「う」が「と」に変わった別の語です。"}, {"text": "乞う", "is_correct": false, "explanation": "こう。「お」が「こ」に変わった別の語です。"}], "explanations": {"負う": "見出し語そのものです。", "甥": "おい。「う」が「い」に変わった別の語です。", "億": "おく。「う」が「く」に変わった別の語です。", "音": "おと。「う」が「と」に変わった別の語です。", "乞う": "こう。「お」が「こ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "負う"}, "level_3": {"options": [{"text": "負います", "is_correct": true, "explanation": "役目を引き受ける、という意味で合う。"}, {"text": "食べます", "is_correct": false, "explanation": "形は合うが、役目は食べるものではなく、意味が合わない。"}, {"text": "洗います", "is_correct": false, "explanation": "形は合うが、役目を洗うという意味は成り立たない。"}, {"text": "壊します", "is_correct": false, "explanation": "形は合うが、役目を壊すと申し出るのは意味が合わない。"}], "explanations": {"負います": "役目を引き受ける、という意味で合う。", "食べます": "形は合うが、役目は食べるものではなく、意味が合わない。", "洗います": "形は合うが、役目を洗うという意味は成り立たない。", "壊します": "形は合うが、役目を壊すと申し出るのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "負います"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎日、水泳の練習を負って、体力をつけた。", "explanation": "「負う」は役目や義務を引き受ける意味で、練習をする意味にはならない。"}, {"text": "彼は先生に宿題を負って、ほめられた。", "explanation": "宿題は「出す」ものであり、「負う」は合わない。"}, {"text": "新しい仕事の知識を負って、会社に入った。", "explanation": "知識には「身につける」を使い、「負う」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52053, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "負う", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "問う", "is_correct": false, "explanation": "とう。「お」が「と」に変わった別の語です。"}, {"text": "斧", "is_correct": false, "explanation": "おの。「う」が「の」に変わった別の語です。"}, {"text": "叔母", "is_correct": false, "explanation": "おば。「う」が「ば」に変わった別の語です。"}, {"text": "帯", "is_correct": false, "explanation": "おび。「う」が「び」に変わった別の語です。"}], "explanations": {"負う": "見出し語そのものです。", "問う": "とう。「お」が「と」に変わった別の語です。", "斧": "おの。「う」が「の」に変わった別の語です。", "叔母": "おば。「う」が「ば」に変わった別の語です。", "帯": "おび。「う」が「び」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "負う"}, "level_3": {"options": [{"text": "負う", "is_correct": true, "explanation": "費用の一部を引き受ける、という意味で合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、費用は食べるものではなく、意味が合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが、費用を洗うという意味は成り立たない。"}, {"text": "焼く", "is_correct": false, "explanation": "形は合うが、費用を焼くという意味は成り立たない。"}], "explanations": {"負う": "費用の一部を引き受ける、という意味で合う。", "食べる": "形は合うが、費用は食べるものではなく、意味が合わない。", "洗う": "形は合うが、費用を洗うという意味は成り立たない。", "焼く": "形は合うが、費用を焼くという意味は成り立たない。"}, "sentence_index": 6, "correct_answer": "負う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は去年、百メートル走で二位を負った。", "explanation": "順位には「取る」などを使い、「負う」は責任や義務を引き受ける意味なので合わない。"}, {"text": "彼は友人の誕生日を負って、プレゼントを買った。", "explanation": "誕生日は引き受けるものではない。「祝う」の代わりに「負う」を使った誤用。"}, {"text": "彼は歌を負って、人前で楽しそうに笑った。", "explanation": "歌は「歌う」もので、「負う」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52053, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私が役目が負います。", "corrected_sentence": "私が役目を負います。", "error_description": "「負う」の対象を表す助詞は「が」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "負った", "is_correct": true, "explanation": "過去形で、文を自然に終える。"}, {"text": "負えば", "is_correct": false, "explanation": "仮定形で、文末に置くと文が終わらない。"}, {"text": "負って", "is_correct": false, "explanation": "テ形で、文末に置くと文が終わらない。"}, {"text": "負い", "is_correct": false, "explanation": "連用形で、文末に置くと文が終わらない。"}], "correct_form": "負った", "base_form": "負う", "form_label": "過去形", "sentence_index": 1, "explanations": {"負った": "過去形で、文を自然に終える。", "負えば": "仮定形で、文末に置くと文が終わらない。", "負って": "テ形で、文末に置くと文が終わらない。", "負い": "連用形で、文末に置くと文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52053, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は費用の一部に負うことになった。", "corrected_sentence": "彼は費用の一部を負うことになった。", "error_description": "「負う」の対象を表す助詞は「に」ではなく「を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "負って", "is_correct": true, "explanation": "「負って、彼は旅に出た」と続くテ形で、文がつながる。"}, {"text": "負う", "is_correct": false, "explanation": "終止形で、「、彼は」と続けると理由や順序の関係が表せない。"}, {"text": "負おう", "is_correct": false, "explanation": "意志形で、後ろの過去の文と合わない。"}, {"text": "負え", "is_correct": false, "explanation": "命令形で、この文には合わない。"}], "correct_form": "負って", "base_form": "負う", "form_label": "テ形", "sentence_index": 7, "explanations": {"負って": "「負って、彼は旅に出た」と続くテ形で、文がつながる。", "負う": "終止形で、「、彼は」と続けると理由や順序の関係が表せない。", "負おう": "意志形で、後ろの過去の文と合わない。", "負え": "命令形で、この文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52054, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「責務を負う」で、負う対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「責務が負っている」は主語が二つになり、成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「責務で負っている」は対象を表せず、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「責務へ負っている」は方向を表す助詞で、成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「責務を負う」で、負う対象を表す。", "が": "「責務が負っている」は主語が二つになり、成り立たない。", "で": "「責務で負っている」は対象を表せず、成り立たない。", "へ": "「責務へ負っている」は方向を表す助詞で、成り立たない。"}, "error_tags": {"が": "subject", "で": "means", "へ": "direction"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免れる", "is_correct": true, "explanation": "責任や災いを引き受ける「負う」の反対で、避けて受けずにすむこと。"}, {"text": "担う", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}, {"text": "背負う", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}, {"text": "引き受ける", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}], "correct_answer": "免れる", "explanations": {"免れる": "責任や災いを引き受ける「負う」の反対で、避けて受けずにすむこと。", "担う": "「負う」と近い意味で、反対ではない。", "背負う": "「負う」と近い意味で、反対ではない。", "引き受ける": "「負う」と近い意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52054, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「責任を負う」で、負う対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「責任が負わなかった」は主語が二つになり、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「責任へ負わなかった」は方向を表す助詞で、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「責任と負わなかった」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「責任を負う」で、負う対象を表す。", "が": "「責任が負わなかった」は主語が二つになり、成り立たない。", "へ": "「責任へ負わなかった」は方向を表す助詞で、成り立たない。", "と": "「責任と負わなかった」は成り立たない。"}, "error_tags": {"が": "subject", "へ": "direction", "と": "quotation"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逃れる", "is_correct": true, "explanation": "傷や責任などを受けずにすむことで、「負う」の反対。"}, {"text": "抱える", "is_correct": false, "explanation": "「負う」と近い意味で、反対ではない。"}, {"text": "果たす", "is_correct": false, "explanation": "引き受けたことを成し遂げる意味で、反対ではない。"}, {"text": "請け負う", "is_correct": false, "explanation": "引き受ける意味で、反対ではない。"}], "correct_answer": "逃れる", "explanations": {"逃れる": "傷や責任などを受けずにすむことで、「負う」の反対。", "抱える": "「負う」と近い意味で、反対ではない。", "果たす": "引き受けたことを成し遂げる意味で、反対ではない。", "請け負う": "引き受ける意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52054, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "責任や義務などを、自分が引き受けて持つこと。また、災いなどを受けること。", "primary_collocate": null, "pronunciation": "おう", "ipa": "oɯ", "syllable_count": 2, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "負っている", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融[きんゆう]政策[せいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体[じったい]経済[けいざい]における物価[ぶっか]上昇[じょうしょう]圧力[あつりょく]と相乗[そうじょう]効果[こうか]を生[う]み、予期[よき]せぬスタグフレーションや財政[ざいせい]主導[しゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "責任を負う。", "target_word": "負う", "complexity_tier": "T1", "furigana": "責任[せきにん]を負[お]う。", "sentence_source": "generated"}, {"text": "彼は大きな責任を負った。", "target_word": "負った", "complexity_tier": "T2", "furigana": "彼[かれ]は大[おお]きな責任[せきにん]を負[お]った。", "sentence_source": "generated"}, {"text": "けがを負った選手が病院へ運ばれた。", "target_word": "負った", "complexity_tier": "T3", "furigana": "けがを負[お]った選手[せんしゅ]が病院[びょういん]へ運[はこ]ばれた。", "sentence_source": "generated"}, {"text": "社長が会社の責任を負うべきだ。", "target_word": "負う", "complexity_tier": "T3", "furigana": "社長[しゃちょう]が会社[かいしゃ]の責任[せきにん]を負[お]うべきだ。", "sentence_source": "generated"}, {"text": "私は家族を守る義務を負っている。", "target_word": "負っている", "complexity_tier": "T3", "furigana": "私[わたし]は家族[かぞく]を守[まも]る義務[ぎむ]を負[お]っている。", "sentence_source": "generated"}, {"text": "重い借金を負って、彼は苦しんでいる。", "target_word": "負って", "complexity_tier": "T3", "furigana": "重[おも]い借金[しゃっきん]を負[お]って、彼[かれ]は苦[くる]しんでいる。", "sentence_source": "generated"}, {"text": "誰も責任を負わなかったので、問題が残った。", "target_word": "負わなかった", "complexity_tier": "T4", "furigana": "誰[だれ]も責任[せきにん]を負[お]わなかったので、問題[もんだい]が残[のこ]った。", "sentence_source": "generated"}, {"text": "彼はその事故で足に重傷を負った。", "target_word": "負った", "complexity_tier": "T3", "furigana": "彼[かれ]はその事故[じこ]で足[あし]に重傷[じゅうしょう]を負[お]った。", "sentence_source": "generated"}, {"text": "彼女は心に深い傷を負ったままだ。", "target_word": "負った", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は心[こころ]に深[ふか]い傷[きず]を負[お]ったままだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負った", "label": "活用"}, {"form": "負って", "label": "活用"}, {"form": "負わない", "label": "活用"}, {"form": "負わせる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 責任や災いを引き受けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: スタグフレーション (Zipf 1.93)']::text[], '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52054, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "負う", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "甥", "is_correct": false, "explanation": "おい。「う」が「い」に変わった別の語です。"}, {"text": "億", "is_correct": false, "explanation": "おく。「う」が「く」に変わった別の語です。"}, {"text": "音", "is_correct": false, "explanation": "おと。「う」が「と」に変わった別の語です。"}, {"text": "乞う", "is_correct": false, "explanation": "こう。「お」が「こ」に変わった別の語です。"}], "explanations": {"負う": "見出し語そのものです。", "甥": "おい。「う」が「い」に変わった別の語です。", "億": "おく。「う」が「く」に変わった別の語です。", "音": "おと。「う」が「と」に変わった別の語です。", "乞う": "こう。「お」が「こ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "負う"}, "level_3": {"options": [{"text": "負っている", "is_correct": true, "explanation": "責務を引き受けて持っている、という意味で合う。"}, {"text": "食べている", "is_correct": false, "explanation": "形は合うが、責務は食べるものではなく、意味が合わない。"}, {"text": "洗っている", "is_correct": false, "explanation": "形は合うが、責務を洗うという意味は成り立たない。"}, {"text": "壊している", "is_correct": false, "explanation": "形は合うが、責務を認識する責任という文脈に合わない。"}], "explanations": {"負っている": "責務を引き受けて持っている、という意味で合う。", "食べている": "形は合うが、責務は食べるものではなく、意味が合わない。", "洗っている": "形は合うが、責務を洗うという意味は成り立たない。", "壊している": "形は合うが、責務を認識する責任という文脈に合わない。"}, "sentence_index": 0, "correct_answer": "負っている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はその試合で勝利を負った。", "explanation": "「負う」は責任や傷を引き受ける意味で、勝利とは結びつかない。「負ける」との混同。"}, {"text": "その選手は決勝で相手を負って、優勝した。", "explanation": "「負う」には相手を倒す意味はない。「負かす」との混同。"}, {"text": "彼は笑顔を負って、客を迎えた。", "explanation": "笑顔には「浮かべる」を使い、「負う」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52054, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "負う", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "問う", "is_correct": false, "explanation": "とう。「お」が「と」に変わった別の語です。"}, {"text": "斧", "is_correct": false, "explanation": "おの。「う」が「の」に変わった別の語です。"}, {"text": "叔母", "is_correct": false, "explanation": "おば。「う」が「ば」に変わった別の語です。"}, {"text": "帯", "is_correct": false, "explanation": "おび。「う」が「び」に変わった別の語です。"}], "explanations": {"負う": "見出し語そのものです。", "問う": "とう。「お」が「と」に変わった別の語です。", "斧": "おの。「う」が「の」に変わった別の語です。", "叔母": "おば。「う」が「ば」に変わった別の語です。", "帯": "おび。「う」が「び」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "負う"}, "level_3": {"options": [{"text": "負って", "is_correct": true, "explanation": "借金を引き受けて苦しんでいる、という意味で合う。"}, {"text": "食べて", "is_correct": false, "explanation": "形は合うが、借金は食べるものではなく、意味が合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "形は合うが、借金を洗うという意味は成り立たない。"}, {"text": "割って", "is_correct": false, "explanation": "形は合うが、借金を割るという意味は成り立たない。"}], "explanations": {"負って": "借金を引き受けて苦しんでいる、という意味で合う。", "食べて": "形は合うが、借金は食べるものではなく、意味が合わない。", "洗って": "形は合うが、借金を洗うという意味は成り立たない。", "割って": "形は合うが、借金を割るという意味は成り立たない。"}, "sentence_index": 6, "correct_answer": "負って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は風邪を負って、三日間寝込んだ。", "explanation": "風邪には「ひく」を使い、「負う」は合わない。"}, {"text": "彼女は毎日の宿題を負って、先生に提出した。", "explanation": "宿題は「出す」ものであり、責任ではない。「負う」の意味に合わない。"}, {"text": "社長は新しい服を負って、会議に出席した。", "explanation": "服には「着る」を使い、「負う」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors,