INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52054, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は心に深い傷を追ったままだ。", "corrected_sentence": "彼女は心に深い傷を負ったままだ。", "error_description": "傷を受ける意味の「おう」は「追う」ではなく「負う」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "負わなかった", "is_correct": true, "explanation": "「誰も」に合う否定の過去形で、文意に合う。"}, {"text": "負えば", "is_correct": false, "explanation": "仮定形で、「ので」に続けられない。"}, {"text": "負って", "is_correct": false, "explanation": "テ形で、「ので」に続けられない。"}, {"text": "負い", "is_correct": false, "explanation": "連用形で、「ので」に続けられない。"}], "correct_form": "負わなかった", "base_form": "負う", "form_label": "否定過去形", "sentence_index": 7, "explanations": {"負わなかった": "「誰も」に合う否定の過去形で、文意に合う。", "負えば": "仮定形で、「ので」に続けられない。", "負って": "テ形で、「ので」に続けられない。", "負い": "連用形で、「ので」に続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
