INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52055, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "色がたくさんついていること。たとえば、コーヒーのように色が黒いこと。", "primary_collocate": null, "pronunciation": "こい", "ipa": "koi", "syllable_count": 2, "sentences": [{"text": "濃い青のセーターを着ると、顔が引き締まって見える。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "こいあおのセーターをきると、かおがひきしまってみえる。", "sentence_source": "generated"}, {"text": "このコーヒーは色が濃くて、底が見えない。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "このコーヒーはいろがこくて、そこがみえない。", "sentence_source": "generated"}, {"text": "濃い緑の葉が、夏の日差しを受けて光っていた。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "こいみどりのはが、なつのひざしをうけてひかっていた。", "sentence_source": "generated"}, {"text": "絵の具を多く使ったので、空が濃い色になった。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "えのぐをおおくつかったので、そらがこいいろになった。", "sentence_source": "generated"}, {"text": "濃い紫のドレスを着た女性が、駅の前に立っていた。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "濃[こ]い紫[むらさき]のドレスを着[き]た女[じょ]性[せい]が、駅[えき]の前[まえ]に立[た]っていた。", "sentence_source": "generated"}, {"text": "紅茶を長く置いたら、色が濃くなってしまった。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "こうちゃをながくおいたら、いろがこくなってしまった。", "sentence_source": "generated"}, {"text": "濃いグレーのスーツは、冬の会議によく似合う。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "こいグレーのスーツは、ふゆのかいぎによくにあう。", "sentence_source": "generated"}, {"text": "濃い赤のカーテンは、部屋を暗く見せる。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "こいあかのカーテンは、へやをくらくみせる。", "sentence_source": "generated"}, {"text": "夕方になると、空の色が少しずつ濃くなっていく。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "夕[ゆう]方[がた]になると、空[そら]の色[いろ]が少[すこ]しずつ濃[こ]くなっていく。", "sentence_source": "generated"}, {"text": "濃い茶色の髪をした少年が、こちらに手を振っている。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "こいちゃいろのかみをしたしょうねんが、こちらにてをふっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "濃い", "label": "終止形・連体形"}, {"form": "濃く", "label": "連用形"}, {"form": "濃かった", "label": "過去形"}, {"form": "濃くない", "label": "否定形"}, {"form": "濃ければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "色が強く深い・暗い(濃い青・色が濃い)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52055, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濃い", "is_correct": true, "explanation": "連体形。名詞「セーター」を修飾する形なので、ここに入る。"}, {"text": "濃く", "is_correct": false, "explanation": "連用形。「濃く青のセーター」と名詞を修飾できない。"}, {"text": "濃くて", "is_correct": false, "explanation": "て形。「濃くて青のセーター」とは続かず、名詞を修飾できない。"}, {"text": "濃ければ", "is_correct": false, "explanation": "仮定形。「濃ければ青のセーター」では名詞を修飾できない。"}], "explanations": {"濃い": "連体形。名詞「セーター」を修飾する形なので、ここに入る。", "濃く": "連用形。「濃く青のセーター」と名詞を修飾できない。", "濃くて": "て形。「濃くて青のセーター」とは続かず、名詞を修飾できない。", "濃ければ": "仮定形。「濃ければ青のセーター」では名詞を修飾できない。"}, "sentence_index": 0, "correct_answer": "濃い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この荷物はとても濃い。", "explanation": "ここは〈重い〉の意味。荷物の重さは「重い」で表すので、〈濃い〉は色の濃さを表す語として合わない。"}, {"text": "この料理は味が濃い。", "explanation": "ここは〈味が強い〉の意味。味の濃さは色の語義ではないので、この文脈では合わない。"}, {"text": "雨が濃い。", "explanation": "ここは〈強い〉の意味。雨の勢いは「雨が強い」で表すので、〈濃い〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52055, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濃い", "is_correct": true, "explanation": "連体形。名詞「グレーのスーツ」を修飾する形なので、ここに入る。"}, {"text": "濃さ", "is_correct": false, "explanation": "名詞形。「濃さグレーのスーツ」と修飾関係が成り立たない。"}, {"text": "濃くなる", "is_correct": false, "explanation": "変化を表す語句。「濃くなるグレーのスーツ」は名詞を修飾できない。"}, {"text": "濃かろう", "is_correct": false, "explanation": "推量形。「濃かろうグレーのスーツ」とは続かず、名詞を修飾できない。"}], "explanations": {"濃い": "連体形。名詞「グレーのスーツ」を修飾する形なので、ここに入る。", "濃さ": "名詞形。「濃さグレーのスーツ」と修飾関係が成り立たない。", "濃くなる": "変化を表す語句。「濃くなるグレーのスーツ」は名詞を修飾できない。", "濃かろう": "推量形。「濃かろうグレーのスーツ」とは続かず、名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "濃い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店は評価が濃い。", "explanation": "ここは〈高い〉の意味。評価の高さは「評価が高い」で表すので、〈濃い〉は合わない。"}, {"text": "足が濃い少年が走っている。", "explanation": "ここは〈速い〉の意味。足の速さは「足が速い」で表すので、〈濃い〉は使わない。"}, {"text": "彼は濃い痛みに耐えて、じっと座っていた。", "explanation": "ここは〈激しい〉の意味。痛みの激しさは「激しい痛み」で表すので、〈濃い〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52055, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その壁は色が濃かくて、部屋が暗く見える。", "corrected_sentence": "その壁は色が濃くて、部屋が暗く見える。", "error_description": "「濃い」の連用形は「濃く」。「濃かくて」は過去形の語幹と連用形を混ぜた誤った形で、「濃くて」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "濃く", "is_correct": true, "explanation": "連用形。「色が濃くて」の「濃く」にあたり、「〜て」に続けて文を続ける形なので、ここに入る。"}, {"text": "濃い", "is_correct": false, "explanation": "終止形・連体形。「色が濃いて」とは続かず、「て」の前には連用形が必要。"}, {"text": "濃かった", "is_correct": false, "explanation": "過去形。「濃かったて」とは続かず、ここは〜て形の前の連用形が入る位置。"}, {"text": "濃ければ", "is_correct": false, "explanation": "仮定形。「色が濃ければて」とは続かず、文として成り立たない。"}], "correct_form": "濃く", "base_form": "濃い", "form_label": "連用形", "sentence_index": 1, "explanations": {"濃く": "連用形。「色が濃くて」の「濃く」にあたり、「〜て」に続けて文を続ける形なので、ここに入る。", "濃い": "終止形・連体形。「色が濃いて」とは続かず、「て」の前には連用形が必要。", "濃かった": "過去形。「濃かったて」とは続かず、ここは〜て形の前の連用形が入る位置。", "濃ければ": "仮定形。「色が濃ければて」とは続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52055, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その紅茶は色を濃い。", "corrected_sentence": "その紅茶は色が濃い。", "error_description": "「色が濃い」の主語は「が」で示す。「色を濃い」は「色」に誤って「を」を付けた格助詞の誤りで、「色が濃い」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "濃い", "is_correct": true, "explanation": "連体形。名詞「赤のカーテン」を修飾する形なので、ここに入る。"}, {"text": "濃さ", "is_correct": false, "explanation": "名詞形。「濃さ赤のカーテン」と修飾関係が成り立たない。"}, {"text": "濃くなる", "is_correct": false, "explanation": "変化を表す語句。「濃くなる赤のカーテン」は名詞を修飾できない。"}, {"text": "濃かろう", "is_correct": false, "explanation": "推量形。「濃かろう赤のカーテン」とは続かず、名詞を修飾できない。"}], "correct_form": "濃い", "base_form": "濃い", "form_label": "連体形", "sentence_index": 7, "explanations": {"濃い": "連体形。名詞「赤のカーテン」を修飾する形なので、ここに入る。", "濃さ": "名詞形。「濃さ赤のカーテン」と修飾関係が成り立たない。", "濃くなる": "変化を表す語句。「濃くなる赤のカーテン」は名詞を修飾できない。", "濃かろう": "推量形。「濃かろう赤のカーテン」とは続かず、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52056, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄い", "is_correct": true, "explanation": "対義語。「疑いが薄い」は「疑いが濃い」の反対で、度合いが弱いことを表す。"}, {"text": "高い", "is_correct": false, "explanation": "対義語ではない。度合いの反対を表す語ではなく、「疑いが高い」は不自然。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、度合いの強弱の対義語ではない。"}, {"text": "早い", "is_correct": false, "explanation": "速さ・時間を表す語で、「濃い」の対義語ではない。"}], "correct_answer": "薄い", "explanations": {"薄い": "対義語。「疑いが薄い」は「疑いが濃い」の反対で、度合いが弱いことを表す。", "高い": "対義語ではない。度合いの反対を表す語ではなく、「疑いが高い」は不自然。", "重い": "重さを表す語で、度合いの強弱の対義語ではない。", "早い": "速さ・時間を表す語で、「濃い」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52056, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄い", "is_correct": true, "explanation": "対義語。「薄く反映されている」は「濃く反映されている」の反対で、影響が弱いことを表す。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表す語で、度合いの強弱の対義語ではない。"}, {"text": "古い", "is_correct": false, "explanation": "時間を表す語で、「濃い」の対義語ではない。"}, {"text": "遠い", "is_correct": false, "explanation": "距離を表す語で、「濃い」の対義語ではない。"}], "correct_answer": "薄い", "explanations": {"薄い": "対義語。「薄く反映されている」は「濃く反映されている」の反対で、影響が弱いことを表す。", "大きい": "大きさを表す語で、度合いの強弱の対義語ではない。", "古い": "時間を表す語で、「濃い」の対義語ではない。", "遠い": "距離を表す語で、「濃い」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52056, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "味や香りなどが強いこと。また、程度がはなはだしいこと。", "primary_collocate": null, "pronunciation": "こい", "ipa": "koi", "syllable_count": 2, "sentences": [{"text": "夜更けの庭に、雨の匂いが濃く漂っていた。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "夜[よ]更[ふ]けの庭[にわ]に、雨[あめ]の匂[にお]いが濃[こ]く漂[ただよ]っていた。", "sentence_source": "generated"}, {"text": "この町には、まだ昔の雰囲気が濃く残っている。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "このまちには、まだむかしのふんいきがこくのこっている。", "sentence_source": "generated"}, {"text": "朝の霧が濃くて、数メートル先も見えなかった。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "あさのきりがこくて、すうメートルさきもみえなかった。", "sentence_source": "generated"}, {"text": "彼が犯人である疑いは日ごとに濃くなっていった。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "かれがはんにんであるうたがいはひごとにこくなっていった。", "sentence_source": "generated"}, {"text": "この料理は味が濃いので、ご飯が進む。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "このりょうりはあじがこいので、ごはんがすすむ。", "sentence_source": "generated"}, {"text": "夜が近づくにつれ、山の影は濃くなっていった。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "よるがちかづくにつれ、やまのかげはこくなっていった。", "sentence_source": "generated"}, {"text": "彼は父親の血を濃く受け継いでいて、顔つきもそっくりだ。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "かれはちちおやのちをこくうけついでいて、かおつきもそっくりだ。", "sentence_source": "generated"}, {"text": "今年の選挙は、与党の敗色が濃い。", "target_word": "濃い", "complexity_tier": "T3", "furigana": "ことしのせんきょは、よとうのはいしょくがこい。", "sentence_source": "generated"}, {"text": "梅の香りが濃く漂う庭で、祖母はお茶を飲んでいる。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "うめのかおりがこくただようにわで、そぼはおちゃをのんでいる。", "sentence_source": "generated"}, {"text": "この小説には作者の経験が濃く反映されている。", "target_word": "濃く", "complexity_tier": "T3", "furigana": "このしょうせつにはさくしゃのけいけんがこくはんえいされている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "濃い", "label": "終止形・連体形"}, {"form": "濃く", "label": "連用形"}, {"form": "濃かった", "label": "過去形"}, {"form": "濃くない", "label": "否定形"}, {"form": "濃ければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "味・香り・気配・疑いなどの度合いが強い(味が濃い・疑いが濃い・濃く残る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52056, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濃く", "is_correct": true, "explanation": "連用形。「匂いが濃く漂っていた」で、動詞「漂う」を修飾する形なので入る。"}, {"text": "濃い", "is_correct": false, "explanation": "終止・連体形。動詞「漂う」を修飾する位置に入れると「匂いが濃い漂っていた」となり成り立たない。"}, {"text": "濃かった", "is_correct": false, "explanation": "過去形。「匂いが濃かった漂っていた」とは続かず、漂う様子を修飾できない。"}, {"text": "濃くない", "is_correct": false, "explanation": "否定形。「匂いが濃くない漂っていた」では動詞を修飾する形にならず、文が成り立たない。"}], "explanations": {"濃く": "連用形。「匂いが濃く漂っていた」で、動詞「漂う」を修飾する形なので入る。", "濃い": "終止・連体形。動詞「漂う」を修飾する位置に入れると「匂いが濃い漂っていた」となり成り立たない。", "濃かった": "過去形。「匂いが濃かった漂っていた」とは続かず、漂う様子を修飾できない。", "濃くない": "否定形。「匂いが濃くない漂っていた」では動詞を修飾する形にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "濃く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は色が濃い。", "explanation": "ここは〈色が強い〉の意味。色の濃さは味や香り・度合いの語義ではないので、この文脈では合わない。"}, {"text": "木の影が濃い。", "explanation": "ここは〈暗い〉の意味。影の暗さは味や香り・程度の語義ではないので、この文脈では合わない。"}, {"text": "この店は値段が濃い。", "explanation": "ここは〈高い〉の意味。値段の高さは「値段が高い」で表すので、〈濃い〉は味・色・度合いの強さを指す語として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52056, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濃く", "is_correct": true, "explanation": "連用形。「血を濃く受け継いで」で、動詞「受け継ぐ」を修飾する形なので入る。"}, {"text": "濃くて", "is_correct": false, "explanation": "て形。「血を濃くて受け継いで」と続かず、動詞を修飾できない。"}, {"text": "濃かろう", "is_correct": false, "explanation": "推量形。「血を濃かろう受け継いで」は成り立たず、動詞を修飾できない。"}, {"text": "濃くなる", "is_correct": false, "explanation": "変化を表す語句。「血を濃くなる受け継いで」と続かず、文が成り立たない。"}], "explanations": {"濃く": "連用形。「血を濃く受け継いで」で、動詞「受け継ぐ」を修飾する形なので入る。", "濃くて": "て形。「血を濃くて受け継いで」と続かず、動詞を修飾できない。", "濃かろう": "推量形。「血を濃かろう受け継いで」は成り立たず、動詞を修飾できない。", "濃くなる": "変化を表す語句。「血を濃くなる受け継いで」と続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "濃く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は濃い荷物を運んでいる。", "explanation": "ここは〈重い〉の意味。荷物の重さは「重い荷物」で表すので、〈濃い〉は合わない。"}, {"text": "この机は濃い茶色だ。", "explanation": "ここは〈色が強い〉の意味。色の濃さは味や香り・程度の語義ではないので、この文脈では合わない。"}, {"text": "彼は濃い声で話すので、皆が驚いた。", "explanation": "ここは〈大きい〉の意味。声の大きさは「大きい声」で表すので、〈濃い〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52056, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この料理は味が濃いくて、ご飯が進む。", "corrected_sentence": "この料理は味が濃くて、ご飯が進む。", "error_description": "「濃い」の連用形は「濃く」。「濃いくて」は誤った活用形で、「濃くて」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "濃く", "is_correct": true, "explanation": "連用形。「濃く残っている」で、動詞「残る」を修飾する形なので入る。"}, {"text": "濃い", "is_correct": false, "explanation": "終止・連体形。「濃い残っている」と続かず、残る様子を修飾できない。"}, {"text": "濃かった", "is_correct": false, "explanation": "過去形。「濃かった残っている」とは続かず、文が成り立たない。"}, {"text": "濃ければ", "is_correct": false, "explanation": "仮定形。「濃ければ残っている」では残る様子を表せず、文が完結しない。"}], "correct_form": "濃く", "base_form": "濃い", "form_label": "連用形", "sentence_index": 1, "explanations": {"濃く": "連用形。「濃く残っている」で、動詞「残る」を修飾する形なので入る。", "濃い": "終止・連体形。「濃い残っている」と続かず、残る様子を修飾できない。", "濃かった": "過去形。「濃かった残っている」とは続かず、文が成り立たない。", "濃ければ": "仮定形。「濃ければ残っている」では残る様子を表せず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52056, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は味を濃い料理が好きだ。", "corrected_sentence": "彼女は味の濃い料理が好きだ。", "error_description": "「味の濃い料理」の「の」が正しい。「味を濃い」は「味」に誤って「を」を付けた格助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "濃い", "is_correct": true, "explanation": "終止形。文末に置いて「与党の敗色が濃い」と言い切る形なので入る。"}, {"text": "濃く", "is_correct": false, "explanation": "連用形。「敗色が濃く。」では文が終わらず、述語として成り立たない。"}, {"text": "濃くて", "is_correct": false, "explanation": "て形。文を止める形で、文末に置くと文が成り立たない。"}, {"text": "濃さ", "is_correct": false, "explanation": "名詞形。「敗色が濃さ。」は述語にならず、文が成り立たない。"}], "correct_form": "濃い", "base_form": "濃い", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"濃い": "終止形。文末に置いて「与党の敗色が濃い」と言い切る形なので入る。", "濃く": "連用形。「敗色が濃く。」では文が終わらず、述語として成り立たない。", "濃くて": "て形。文を止める形で、文末に置くと文が成り立たない。", "濃さ": "名詞形。「敗色が濃さ。」は述語にならず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52057, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「秋になる」の「なる」は変化の結果を表す「に」を取る。ここでは秋が変化の行き先になる。"}, {"text": "が", "is_correct": false, "explanation": "「秋がなる」の「が」は「なる」の結果語には付かず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「秋をなる」は「なる」が目的語を取らないので成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「秋のなると」は名詞修飾の「の」では「なる」とつながらず、文が壊れる。"}], "correct_answer": "に", "explanations": {"に": "「秋になる」の「なる」は変化の結果を表す「に」を取る。ここでは秋が変化の行き先になる。", "が": "「秋がなる」の「が」は「なる」の結果語には付かず、文が成り立たない。", "を": "「秋をなる」は「なる」が目的語を取らないので成り立たない。", "の": "「秋のなると」は名詞修飾の「の」では「なる」とつながらず、文が壊れる。"}, "error_tags": {"が": "主格", "を": "対格", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52057, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「秋が終わる」の主語を表す「が」。終わるものとして秋を示す。"}, {"text": "で", "is_correct": false, "explanation": "「秋で終わる」の「で」は手段・場所を表し、主語を示せないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「秋へ終わる」の「へ」は方向を表し、「終わる」とはつながらない。"}, {"text": "より", "is_correct": false, "explanation": "「秋より終わる」の「より」は比較を表し、主語を示せず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「秋が終わる」の主語を表す「が」。終わるものとして秋を示す。", "で": "「秋で終わる」の「で」は手段・場所を表し、主語を示せないので不自然。", "へ": "「秋へ終わる」の「へ」は方向を表し、「終わる」とはつながらない。", "より": "「秋より終わる」の「より」は比較を表し、主語を示せず文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52057, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あきは、きせつのひとつです。はっぱのいろがかわったり、すずしくなったりします。", "primary_collocate": null, "pronunciation": "あき", "ipa": "aki", "syllable_count": 2, "sentences": [{"text": "秋は、すずしくて気持ちのいい季節です。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]は、すずしくて気持[きも]ちのいい季節[きせつ]です。", "sentence_source": "generated"}, {"text": "秋になると、木の葉が赤くなります。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]になると、木[き]の葉[は]が赤[あか]くなります。", "sentence_source": "generated"}, {"text": "夏が終わって、秋が来ました。", "target_word": "秋", "complexity_tier": "T3", "furigana": "夏[なつ]が終[お]わって、秋[あき]が来[き]ました。", "sentence_source": "generated"}, {"text": "私は涼しい秋に、いちばん本をたくさん読みます。", "target_word": "秋", "complexity_tier": "T3", "furigana": "私[わたし]は涼[すず]しい秋[あき]に、いちばん本[ほん]をたくさん読[よ]みます。", "sentence_source": "generated"}, {"text": "夏のあとの秋の朝は、少し寒くなります。", "target_word": "秋", "complexity_tier": "T3", "furigana": "夏[なつ]のあとの秋[あき]の朝[あさ]は、少[すこ]し寒[さむ]くなります。", "sentence_source": "generated"}, {"text": "公園で、秋に落ちた葉を集めました。", "target_word": "秋", "complexity_tier": "T3", "furigana": "公園[こうえん]で、秋[あき]に落[お]ちた葉[は]を集[あつ]めました。", "sentence_source": "generated"}, {"text": "秋はくだものがおいしいので、梨をよく食べます。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]はくだものがおいしいので、梨[なし]をよく食[た]べます。", "sentence_source": "generated"}, {"text": "秋が終わると、冬になります。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]が終[お]わると、冬[ふゆ]になります。", "sentence_source": "generated"}, {"text": "暑い夏のあとに秋が来て、すごしやすくなりました。", "target_word": "秋", "complexity_tier": "T3", "furigana": "暑[あつ]い夏[なつ]のあとに秋[あき]が来[き]て、すごしやすくなりました。", "sentence_source": "generated"}, {"text": "学校の秋の遠足で、山に登りました。", "target_word": "秋", "complexity_tier": "T3", "furigana": "学校[がっこう]の秋[あき]の遠足[えんそく]で、山[やま]に登[のぼ]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "秋", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "四季のひとつ・葉の色が変わりすずしくなる季節", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: すずしく (Zipf 1.49)','sentence 6 above tier T2: contains vocabulary far above tier T2: くだもの (Zipf 2.34)']::text[], '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52057, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "季節の秋。涼しく気持ちのよい季節という定義に合う。"}, {"text": "冬", "is_correct": false, "explanation": "冬は寒い季節なので、「すずしくて気持ちのいい季節」とは合わない。"}, {"text": "夏", "is_correct": false, "explanation": "夏は暑い季節なので、「すずしくて気持ちのいい季節」とは合わない。"}, {"text": "梅雨", "is_correct": false, "explanation": "梅雨は雨の多い季節で、「すずしくて気持ちのいい季節」とは言わない。"}], "explanations": {"秋": "季節の秋。涼しく気持ちのよい季節という定義に合う。", "冬": "冬は寒い季節なので、「すずしくて気持ちのいい季節」とは合わない。", "夏": "夏は暑い季節なので、「すずしくて気持ちのいい季節」とは合わない。", "梅雨": "梅雨は雨の多い季節で、「すずしくて気持ちのいい季節」とは言わない。"}, "sentence_index": 0, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋を箱に入れて、押し入れにしまった。", "explanation": "季節は物ではないので、箱に入れて押し入れにしまうことはできない。"}, {"text": "秋に住むことにして、引っ越しをした。", "explanation": "季節は場所ではないので、そこに住むことはできない。"}, {"text": "秋の長さを定規で測った。", "explanation": "季節は定規で測れるものではないので、「長さを測る」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52057, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "季節の秋。果物が旬でおいしい時期という理由に自然につながる。"}, {"text": "雪", "is_correct": false, "explanation": "「雪はくだものがおいしい」は成り立たず、理由を示せない。"}, {"text": "鍋", "is_correct": false, "explanation": "「鍋はくだものがおいしい」は主語として不自然で、理由にならない。"}, {"text": "店", "is_correct": false, "explanation": "「店はくだものがおいしい」は意味が通らず、ここには当てはまらない。"}], "explanations": {"秋": "季節の秋。果物が旬でおいしい時期という理由に自然につながる。", "雪": "「雪はくだものがおいしい」は成り立たず、理由を示せない。", "鍋": "「鍋はくだものがおいしい」は主語として不自然で、理由にならない。", "店": "「店はくだものがおいしい」は意味が通らず、ここには当てはまらない。"}, "sentence_index": 6, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋を十分間待って、電車に乗った。", "explanation": "季節は「十分間待つ」の対象にはならないので、不自然。"}, {"text": "秋を二つ買って、家族に配った。", "explanation": "季節は数えて買える物ではないので、「二つ買う」とは合わない。"}, {"text": "感想文のために、秋を一冊読んだ。", "explanation": "季節は本のように読むものではないので、「読む」の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52057, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋を来ると、木の葉が赤くなります。", "corrected_sentence": "秋が来ると、木の葉が赤くなります。", "error_description": "「来る」の主語は「秋が」。「秋を」は対象を表す助詞で、到来の「来る」とは合わない。正しくは「秋が来ると」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52057, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋が終えると、朝晩が寒くなります。", "corrected_sentence": "秋が終わると、朝晩が寒くなります。", "error_description": "「終わる」は自動詞で「秋が」を主語に取る。「終える」は他動詞なので主語の「秋が」とは合わない。正しくは「終わると」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52058, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「秋になる」の「なる」は変化の結果を表す「に」を取る。ここでは秋が変化の行き先になっている。"}, {"text": "が", "is_correct": false, "explanation": "「秋がなると」の「が」は「なる」の結果語には付かず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「秋をなると」は「なる」が目的語を取らないので成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「秋のなると」は名詞修飾の「の」では「なる」とつながらず、文が壊れる。"}], "correct_answer": "に", "explanations": {"に": "「秋になる」の「なる」は変化の結果を表す「に」を取る。ここでは秋が変化の行き先になっている。", "が": "「秋がなると」の「が」は「なる」の結果語には付かず、文が成り立たない。", "を": "「秋をなると」は「なる」が目的語を取らないので成り立たない。", "の": "「秋のなると」は名詞修飾の「の」では「なる」とつながらず、文が壊れる。"}, "error_tags": {"が": "主格", "を": "対格", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52058, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「秋が深まる」の主語を表す「が」。秋が変化する主体になる。"}, {"text": "で", "is_correct": false, "explanation": "「秋で深まる」の「で」は手段・場所を表し、主体を示せないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「秋へ深まる」の「へ」は方向を表し、程度が進む変化には使えない。"}, {"text": "より", "is_correct": false, "explanation": "「秋より深まる」の「より」は比較を表し、主語を示せず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「秋が深まる」の主語を表す「が」。秋が変化する主体になる。", "で": "「秋で深まる」の「で」は手段・場所を表し、主体を示せないので不自然。", "へ": "「秋へ深まる」の「へ」は方向を表し、程度が進む変化には使えない。", "より": "「秋より深まる」の「より」は比較を表し、主語を示せず文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52058, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "秋は、夏の後、冬の前の季節で、気温が下がり、紅葉が見られる時期です。", "primary_collocate": null, "pronunciation": "あき", "ipa": "aki", "syllable_count": 2, "sentences": [{"text": "秋の気配がする縁側で、子どもが赤い果物を見つめている。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]の気配[けはい]がする縁側[えんがわ]で、子[こ]どもが赤[あか]い果物[くだもの]を見[み]つめている。", "sentence_source": "generated"}, {"text": "秋になると、山の木々が赤や黄色に色づく。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]になると、山[やま]の木々[きぎ]が赤[あか]や黄色[きいろ]に色[いろ]づく。", "sentence_source": "generated"}, {"text": "夏の暑さが和らぎ、ようやく秋が訪れた。", "target_word": "秋", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]さが和[やわ]らぎ、ようやく秋[あき]が訪[おとず]れた。", "sentence_source": "generated"}, {"text": "今年の秋は雨が多く、紅葉が例年より遅れている。", "target_word": "秋", "complexity_tier": "T3", "furigana": "今年[ことし]の秋[あき]は雨[あめ]が多[おお]く、紅葉[こうよう]が例年[れいねん]より遅[おく]れている。", "sentence_source": "generated"}, {"text": "秋の夜は気温が下がるので、薄手の上着が欠かせない。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]の夜[よる]は気温[きおん]が下[さ]がるので、薄手[うすで]の上着[うわぎ]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "私は暑い夏よりも涼しい秋のほうが好きだ。", "target_word": "秋", "complexity_tier": "T3", "furigana": "私[わたし]は暑[あつ]い夏[なつ]よりも涼[すず]しい秋[あき]のほうが好[す]きだ。", "sentence_source": "generated"}, {"text": "毎年、秋には家族で京都へ紅葉を見に行く。", "target_word": "秋", "complexity_tier": "T3", "furigana": "毎年[まいとし]、秋[あき]には家族[かぞく]で京都[きょうと]へ紅葉[もみじ]を見[み]に行[い]く。", "sentence_source": "generated"}, {"text": "秋が深まるにつれて、朝晩の冷え込みが厳しくなってきた。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]が深[ふか]まるにつれて、朝晩[あさばん]の冷[ひ]え込[こ]みが厳[きび]しくなってきた。", "sentence_source": "generated"}, {"text": "冬が来る前の秋のうちに、庭の落ち葉を片づけておこう。", "target_word": "秋", "complexity_tier": "T3", "furigana": "冬[ふゆ]が来[く]る前[まえ]の秋[あき]のうちに、庭[にわ]の落[お]ち葉[ば]を片[かた]づけておこう。", "sentence_source": "generated"}, {"text": "秋の公園は、色づいた木の葉を見に来る人でにぎわっていた。", "target_word": "秋", "complexity_tier": "T3", "furigana": "秋[あき]の公園[こうえん]は、色[いろ]づいた木[こ]の葉[は]を見[み]に来[く]る人[ひと]でにぎわっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "秋", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "夏と冬のあいだの季節・気温が下がり紅葉が見られる時期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 色づく (Zipf 2.35)','sentence 2 above tier T2: contains vocabulary far above tier T2: 和らぎ (Zipf 2.37)','sentence 9 above tier T2: contains vocabulary far above tier T2: 色づい (Zipf 2.13)']::text[], '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52058, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "季節の秋を表す。古びた縁側と赤い果物の季節感に合い、ここで唯一当てはまる。"}, {"text": "鉛", "is_correct": false, "explanation": "「鉛の気配が色濃く漂う」は意味が通らず、季節感を表せない。"}, {"text": "砂", "is_correct": false, "explanation": "「砂の気配が色濃く漂う」は不自然で、この情景に合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "物質名の「鉄」が「気配」の主語になるのはおかしく、ここでは成り立たない。"}], "explanations": {"秋": "季節の秋を表す。古びた縁側と赤い果物の季節感に合い、ここで唯一当てはまる。", "鉛": "「鉛の気配が色濃く漂う」は意味が通らず、季節感を表せない。", "砂": "「砂の気配が色濃く漂う」は不自然で、この情景に合わない。", "鉄": "物質名の「鉄」が「気配」の主語になるのはおかしく、ここでは成り立たない。"}, "sentence_index": 0, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏が終わったので、秋を引き出しにしまって冬の準備をした。", "explanation": "季節は時の流れを指す語で、物のように引き出しにしまうことはできない。"}, {"text": "秋に住んでいるので、通勤がずっと楽になった。", "explanation": "季節は場所ではないので、そこに住むことはできない。"}, {"text": "秋の重さを量ったら、思ったより軽かった。", "explanation": "季節は重さを量れる物ではないので、「重さを量る」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52058, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "季節の秋。毎年、紅葉を見に行く時期として自然に当てはまる。"}, {"text": "雨", "is_correct": false, "explanation": "「雨には家族で京都へ」は時期を表せず、文として成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布には」は時期を示せず、行事の文脈に合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便には」は時期にならず、紅葉を見に行く時間を示せない。"}], "explanations": {"秋": "季節の秋。毎年、紅葉を見に行く時期として自然に当てはまる。", "雨": "「雨には家族で京都へ」は時期を表せず、文として成り立たない。", "財布": "「財布には」は時期を示せず、行事の文脈に合わない。", "郵便": "「郵便には」は時期にならず、紅葉を見に行く時間を示せない。"}, "sentence_index": 6, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋を五分間待ってから、バスに乗った。", "explanation": "季節は「五分間待つ」のような時間の単位にはならないので、不自然。"}, {"text": "注文していた秋を一つ、店で受け取った。", "explanation": "季節は数えて受け取れるものではないので、「一つ」と数えるのは不自然。"}, {"text": "作文の宿題で、秋を三ページ読んだ。", "explanation": "季節は読むものではないので、「読む」の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52058, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋を来ると、山の木々が赤く色づく。", "corrected_sentence": "秋が来ると、山の木々が赤く色づく。", "error_description": "「来る」の主語は「秋が」。「秋を」は対象を表す助詞で、到来の「来る」には使えない。正しくは「秋が来ると」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52058, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋が深めると、朝晩の冷え込みが厳しくなる。", "corrected_sentence": "秋が深まると、朝晩の冷え込みが厳しくなる。", "error_description": "「深まる」は自動詞で「秋が」を主語に取る。「深める」は他動詞なので、主語の「秋が」とは合わない。正しくは「深まると」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52059, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「気配を感じて」で感じる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「気配が感じて」では気配が感じる主体になり、文の意味が合わない。主語の誤り。"}, {"text": "の", "is_correct": false, "explanation": "「人の気配の感じて」は続く名詞がなく、文が成り立たない。連体修飾の誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「気配へ感じて」は方向を示すが、感じる対象を表せず不自然。方向の誤り。"}], "correct_answer": "を", "explanations": {"を": "正解。「気配を感じて」で感じる対象を示す。", "が": "「気配が感じて」では気配が感じる主体になり、文の意味が合わない。主語の誤り。", "の": "「人の気配の感じて」は続く名詞がなく、文が成り立たない。連体修飾の誤り。", "へ": "「気配へ感じて」は方向を示すが、感じる対象を表せず不自然。方向の誤り。"}, "error_tags": {"が": "主語の誤り", "の": "連体修飾の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52059, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「気配に気づいて」で気づく対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「気配を気づいて」では「気づく」が対象を「に」で取るため、「を」は不自然。目的語の誤り。"}, {"text": "の", "is_correct": false, "explanation": "「気配の気づいて」は連体修飾になり、続く名詞がないので文が成り立たない。連体修飾の誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「気配へ気づいて」は方向を示すが、気づく対象を表せず不自然。方向の誤り。"}], "correct_answer": "に", "explanations": {"に": "正解。「気配に気づいて」で気づく対象を示す。", "を": "「気配を気づいて」では「気づく」が対象を「に」で取るため、「を」は不自然。目的語の誤り。", "の": "「気配の気づいて」は連体修飾になり、続く名詞がないので文が成り立たない。連体修飾の誤り。", "へ": "「気配へ気づいて」は方向を示すが、気づく対象を表せず不自然。方向の誤り。"}, "error_tags": {"を": "目的語の誤り", "の": "連体修飾の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52059, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがあるとわかる、そのようす。", "primary_collocate": null, "pronunciation": "けはい", "ipa": "kehai", "syllable_count": 3, "sentences": [{"text": "暗い部屋に入ると、だれかの気配がしました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]に入[はい]ると、だれかの気配[けはい]がしました。", "sentence_source": "generated"}, {"text": "夜中に、後ろに人の気配を感じて振り向きました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "夜中[よなか]に、後[うし]ろに人[ひと]の気配[けはい]を感[かん]じて振[ふ]り向[む]きました。", "sentence_source": "generated"}, {"text": "春の気配が、少しずつ町に近づいています。", "target_word": "気配", "complexity_tier": "T3", "furigana": "春[はる]の気配[けはい]が、少[すこ]しずつ町[まち]に近[ちか]づいています。", "sentence_source": "generated"}, {"text": "猫は気配を消して、静かに近づきました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "猫[ねこ]は気配[けはい]を消[け]して、静[しず]かに近[ちか]づきました。", "sentence_source": "generated"}, {"text": "家の中に人の気配がなかったので、留守だと思いました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "家[いえ]の中[なか]に人[ひと]の気配[けはい]がなかったので、留守[るす]だと思[おも]いました。", "sentence_source": "generated"}, {"text": "森の奥で動物の気配がしたので、足を止めました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]で動物[どうぶつ]の気配[けはい]がしたので、足[あし]を止[と]めました。", "sentence_source": "generated"}, {"text": "雨が降りそうな気配があるので、かさを持って出ました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]りそうな気配[けはい]があるので、かさを持[も]って出[で]ました。", "sentence_source": "generated"}, {"text": "兄はドアの外の気配に気づいて、すぐに開けました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "兄[あに]はドアの外[そと]の気配[けはい]に気[き]づいて、すぐに開[あ]けました。", "sentence_source": "generated"}, {"text": "部屋の外に気配がして、子どもが起きたのだとわかりました。", "target_word": "気配", "complexity_tier": "T3", "furigana": "部屋[へや]の外[そと]に気配[けはい]がして、子[こ]どもが起[お]きたのだとわかりました。", "sentence_source": "generated"}, {"text": "山では、冬の気配がもう感じられます。", "target_word": "気配", "complexity_tier": "T3", "furigana": "山[やま]では、冬[ふゆ]の気配[けはい]がもう感[かん]じられます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気配", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "姿は見えなくても何かがいる・あると感じるようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52059, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気配", "is_correct": true, "explanation": "暗い部屋で誰かがいると感じ取る文脈に合い、「気配がする」と自然に続く。"}, {"text": "色", "is_correct": false, "explanation": "「色がする」とは言わず、感じ取るものとして成り立たない。"}, {"text": "形", "is_correct": false, "explanation": "「形がする」とは言わず、感じ取る対象として不自然。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さがする」とは言わず、人の存在を感じる文脈に合わない。"}], "explanations": {"気配": "暗い部屋で誰かがいると感じ取る文脈に合い、「気配がする」と自然に続く。", "色": "「色がする」とは言わず、感じ取るものとして成り立たない。", "形": "「形がする」とは言わず、感じ取る対象として不自然。", "重さ": "「重さがする」とは言わず、人の存在を感じる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "気配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝の気配は十度でした。", "explanation": "ここは〈気温〉の意味。気配は何かがいると感じ取れる様子で、温度の数値には使わない。"}, {"text": "梅雨で気配が多くて、洗濯物が乾きません。", "explanation": "ここは〈湿気〉の意味。気配は存在を感じ取ることで、空気のじめじめには使わない。"}, {"text": "八百屋で、新しい気配を買いました。", "explanation": "ここは〈商品〉の意味。気配は何かがあるとわかる様子で、店で買える物としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52059, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気配", "is_correct": true, "explanation": "雨が降りそうな様子を感じ取る文脈に合い、「気配がある」と自然に続く。"}, {"text": "値段", "is_correct": false, "explanation": "「雨が降りそうな値段」は成り立たず、天気の様子を表せない。"}, {"text": "音量", "is_correct": false, "explanation": "「雨が降りそうな音量」は不自然で、天気の様子とは結びつかない。"}, {"text": "寿命", "is_correct": false, "explanation": "「雨が降りそうな寿命」は意味をなさず、文脈に合わない。"}], "explanations": {"気配": "雨が降りそうな様子を感じ取る文脈に合い、「気配がある」と自然に続く。", "値段": "「雨が降りそうな値段」は成り立たず、天気の様子を表せない。", "音量": "「雨が降りそうな音量」は不自然で、天気の様子とは結びつかない。", "寿命": "「雨が降りそうな寿命」は意味をなさず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "気配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の参加者の気配は三十人です。", "explanation": "ここは〈数〉の意味。気配は何かを感じ取る様子で、人数のような数量は表せない。"}, {"text": "私の気配は田中です。", "explanation": "ここは〈名前〉の意味。気配は何かがあるとわかる様子で、人の名前としては使えない。"}, {"text": "子どもの気配が上がったので、病院に行きました。", "explanation": "ここは〈体温〉の意味。気配は数値で測れる体の温度には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52059, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアの向こうに、人の気配に感じました。", "corrected_sentence": "ドアの向こうに、人の気配を感じました。", "error_description": "助詞の誤り。「感じる」は目的語に「を」を取るので、「気配を感じました」が正しい。「気配に感じました」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52059, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の外に、人の気配を見ました。", "corrected_sentence": "窓の外に、人の気配を感じました。", "error_description": "動詞の選び方の誤り。気配は「感じる」もので、「見る」は目に見えるものに使うので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52060, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「気配がして」の「が」。気配が感じられる主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「気配をして」は「する」が目的語を取る形になっておらず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「人の気配のして」は名詞修飾の「の」では「して」とつながらず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「気配でして」は手段・場所の「で」で、感じられる主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "「気配がして」の「が」。気配が感じられる主体を示す。", "を": "「気配をして」は「する」が目的語を取る形になっておらず、文が成り立たない。", "の": "「人の気配のして」は名詞修飾の「の」では「して」とつながらず、不自然。", "で": "「気配でして」は手段・場所の「で」で、感じられる主体を示せない。"}, "error_tags": {"を": "対格", "の": "連体修飾", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
