INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52060, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の存在や変化を感じさせる、かすかな兆しや様子。", "primary_collocate": null, "pronunciation": "けはい", "ipa": "kehai", "syllable_count": 3, "sentences": [{"text": "秋の気配が色濃く漂い、山の木々が赤く染まってきた。", "target_word": "気配", "complexity_tier": "T3", "furigana": "秋[あき]の気配[けはい]が色濃[いろこ]く漂[ただよ]い、山[やま]の木々[きぎ]が赤[あか]く染[そ]まってきた。", "sentence_source": "generated"}, {"text": "部屋の中に人の気配がして、思わず振り返った。", "target_word": "気配", "complexity_tier": "T3", "furigana": "部屋[へや]の中[なか]に人[ひと]の気配[けはい]がして、思[おも]わず振[ふ]り返[かえ]った。", "sentence_source": "generated"}, {"text": "まだ三月なのに、庭には春の気配が感じられる。", "target_word": "気配", "complexity_tier": "T3", "furigana": "まだ三月[さんがつ]なのに、庭[にわ]には春[はる]の気配[けはい]が感[かん]じられる。", "sentence_source": "generated"}, {"text": "森の奥から、何かが動く気配が伝わってきた。", "target_word": "気配", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]から、何[なに]かが動[うご]く気配[けはい]が伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "彼女は気配を消して、そっと部屋に入った。", "target_word": "気配", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は気配[けはい]を消[け]して、そっと部屋[へや]に入[はい]った。", "sentence_source": "generated"}, {"text": "夜道で後ろに誰かの気配を感じて、急ぎ足になった。", "target_word": "気配", "complexity_tier": "T3", "furigana": "夜道[よみち]で後[うし]ろに誰[だれ]かの気配[けはい]を感[かん]じて、急[いそ]ぎ足[あし]になった。", "sentence_source": "generated"}, {"text": "雨が上がる気配はなく、試合は延期になった。", "target_word": "気配", "complexity_tier": "T3", "furigana": "雨[あめ]が上[あ]がる気配[けはい]はなく、試合[しあい]は延期[えんき]になった。", "sentence_source": "generated"}, {"text": "空が暗くなり、嵐の気配が近づいてきた。", "target_word": "気配", "complexity_tier": "T3", "furigana": "空[そら]が暗[くら]くなり、嵐[あらし]の気配[けはい]が近[ちか]づいてきた。", "sentence_source": "generated"}, {"text": "猫は気配に敏感で、足音が聞こえる前に顔を上げる。", "target_word": "気配", "complexity_tier": "T3", "furigana": "猫[ねこ]は気配[けはい]に敏感[びんかん]で、足音[あしおと]が聞[き]こえる前[まえ]に顔[かお]を上[あ]げる。", "sentence_source": "generated"}, {"text": "庭の柿が色づき、冬の気配がほのかに漂い始めた。", "target_word": "気配", "complexity_tier": "T3", "furigana": "庭[にわ]の柿[かき]が色[いろ]づき、冬[ふゆ]の気配[けはい]がほのかに漂[ただよ]い始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気配", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "存在や変化をかすかに感じさせる兆し・様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 色づき (Zipf 1.92)']::text[], '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52060, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気配", "is_correct": true, "explanation": "かすかな兆しや様子を表す「気配」。「秋の気配が漂う」という情景に合う。"}, {"text": "石", "is_correct": false, "explanation": "「秋の石が色濃く漂う」は成り立たず、兆しを表せない。"}, {"text": "鍵", "is_correct": false, "explanation": "「秋の鍵が色濃く漂う」は意味が通らず、ここでは使えない。"}, {"text": "紙", "is_correct": false, "explanation": "「秋の紙が色濃く漂う」は不自然で、季節の兆しを表せない。"}], "explanations": {"気配": "かすかな兆しや様子を表す「気配」。「秋の気配が漂う」という情景に合う。", "石": "「秋の石が色濃く漂う」は成り立たず、兆しを表せない。", "鍵": "「秋の鍵が色濃く漂う」は意味が通らず、ここでは使えない。", "紙": "「秋の紙が色濃く漂う」は不自然で、季節の兆しを表せない。"}, "sentence_index": 0, "correct_answer": "気配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は気配がこまやかで、誰にでも親切だ。", "explanation": "ここは〈心づかい〉（気遣い）の意味。気配は周囲にかすかに感じられる兆しを指すので、人の心くばりには使えない。"}, {"text": "今日は朝から気配が晴れやかで、何でもうまくいきそうだ。", "explanation": "ここは〈気分〉の意味。気配は周囲にかすかに感じられる兆しなので、自分の心持ちには使えない。"}, {"text": "祖父の気配が荒くて、家族は静かにしていた。", "explanation": "ここは〈機嫌〉の意味。気配は感じ取れる様子を指すので、人の機嫌の良し悪しには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52060, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気配", "is_correct": true, "explanation": "かすかな兆し。雨が上がる兆しがなかったという意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "「雨が上がる色」は意味が通らず、兆しを表せない。"}, {"text": "声", "is_correct": false, "explanation": "「雨が上がる声」は不自然で、兆しの文脈に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "「雨が上がる窓」は成り立たず、ここでは使えない。"}], "explanations": {"気配": "かすかな兆し。雨が上がる兆しがなかったという意味に合う。", "色": "「雨が上がる色」は意味が通らず、兆しを表せない。", "声": "「雨が上がる声」は不自然で、兆しの文脈に合わない。", "窓": "「雨が上がる窓」は成り立たず、ここでは使えない。"}, "sentence_index": 6, "correct_answer": "気配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暗い廊下の先に、誰かの気配がはっきり見えた。", "explanation": "ここは〈人影〉の意味。気配は見えるものではなく感じ取るものなので、「見えた」とは合わない。"}, {"text": "店の気配を大事にして、常連客を迎えている。", "explanation": "ここは〈雰囲気〉の意味。店全体の空気は雰囲気と言い、気配は今まさに感じられる兆しを指すので合わない。"}, {"text": "今朝の母は気配が悪くて、話しかけづらかった。", "explanation": "ここは〈機嫌〉の意味。気配は感じ取れる兆しで、人の機嫌が悪いことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52060, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方になり、遠くの雷の気配を近づいてきた。", "corrected_sentence": "夕方になり、遠くの雷の気配が近づいてきた。", "error_description": "「近づく」の主語は「気配が」。「気配を」は目的語を表す助詞で、目的語を取らない「近づく」とは合わないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52060, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜道で、人の気配が消した。", "corrected_sentence": "夜道で、人の気配が消えた。", "error_description": "「消える」は自動詞で、主語の「気配が」に合う。「消した」は他動詞で、主語の「気配が」とは合わないので誤り。正しくは「消えた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
