INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52061, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "古びるは、ものが古くなることです。", "primary_collocate": null, "pronunciation": "ふるびる", "ipa": "ɸɯɾɯbiɾɯ", "syllable_count": 4, "sentences": [{"text": "古びた帽子を、まだ大切にかぶっています。", "target_word": "古びた", "complexity_tier": "T3", "furigana": "古[ふる]びた帽子[ぼうし]を、まだ大切[たいせつ]にかぶっています。", "sentence_source": "generated"}, {"text": "私の自転車は十年使って、古びてきました。", "target_word": "古びて", "complexity_tier": "T3", "furigana": "私[わたし]の自転車[じてんしゃ]は十年[じゅうねん]使[つか]って、古[ふる]びてきました。", "sentence_source": "generated"}, {"text": "古びた家に、おばあさんが一人で住んでいます。", "target_word": "古びた", "complexity_tier": "T3", "furigana": "古[ふる]びた家[いえ]に、おばあさんが一人[ひとり]で住[す]んでいます。", "sentence_source": "generated"}, {"text": "本は古びても、中のお話は変わりません。", "target_word": "古びて", "complexity_tier": "T3", "furigana": "本[ほん]は古[ふる]びても、中[なか]のお話[はなし]は変[か]わりません。", "sentence_source": "generated"}, {"text": "古びたくつは、そろそろ新しいものに買いかえます。", "target_word": "古びた", "complexity_tier": "T3", "furigana": "古[ふる]びたくつは、そろそろ新[あたら]しいものに買[か]いかえます。", "sentence_source": "generated"}, {"text": "この橋は古びて、ところどころさびています。", "target_word": "古びて", "complexity_tier": "T3", "furigana": "この橋[はし]は古[ふる]びて、ところどころさびています。", "sentence_source": "generated"}, {"text": "古びた時計が、まだ元気に動いています。", "target_word": "古びた", "complexity_tier": "T3", "furigana": "古[ふる]びた時計[とけい]が、まだ元気[げんき]に動[うご]いています。", "sentence_source": "generated"}, {"text": "毎日使うかばんは、すぐに古びます。", "target_word": "古びます", "complexity_tier": "T3", "furigana": "毎日[まいにち]使[つか]うかばんは、すぐに古[ふる]びます。", "sentence_source": "generated"}, {"text": "古びたノートに、むかしの絵がのこっていました。", "target_word": "古びた", "complexity_tier": "T3", "furigana": "古[ふる]びたノートに、むかしの絵[え]がのこっていました。", "sentence_source": "generated"}, {"text": "古びたカーテンが、風にゆれています。", "target_word": "古びた", "complexity_tier": "T3", "furigana": "古[ふる]びたカーテンが、風[かぜ]にゆれています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "古びる", "label": "終止形"}, {"form": "古び", "label": "連用形"}, {"form": "古びた", "label": "タ形"}, {"form": "古びて", "label": "テ形"}, {"form": "古びない", "label": "否定形"}, {"form": "古びれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ものが年月をへて古くなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52061, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古びた", "is_correct": true, "explanation": "連体形で、「帽子」を修飾する形として正しい。"}, {"text": "古びて", "is_correct": false, "explanation": "テ形は名詞を修飾できず、「古びて帽子」は成り立たない。"}, {"text": "古び", "is_correct": false, "explanation": "連用形は名詞を修飾できず、ここには入らない。"}, {"text": "古びれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「古びれば帽子」は文が成り立たない。"}], "explanations": {"古びた": "連体形で、「帽子」を修飾する形として正しい。", "古びて": "テ形は名詞を修飾できず、「古びて帽子」は成り立たない。", "古び": "連用形は名詞を修飾できず、ここには入らない。", "古びれば": "仮定形は名詞を修飾できず、「古びれば帽子」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "古びた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の花が一晩で古びて、しおれてしまった。", "explanation": "ここは〈しおれる〉の意味。花が生気を失うのは「しおれる」で、古びるは年月による古さを表すので合わない。"}, {"text": "父は最近、急に古びて白髪が増えた。", "explanation": "ここは〈老ける〉の意味。人が年を取るのは老けるで、古びるは物に使うので合わない。"}, {"text": "部屋の空気が閉め切ったまま古びてしまった。", "explanation": "ここは〈淀む〉の意味。空気が動かず悪くなるのは淀むで、古びるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52061, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古びた", "is_correct": true, "explanation": "連体形で、「時計」を修飾する形として正しい。"}, {"text": "古びます", "is_correct": false, "explanation": "ます形は名詞を修飾できず、「古びます時計」は成り立たない。"}, {"text": "古びよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「古びよう時計」は文が成り立たない。"}, {"text": "古びろ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、ここでは時計の状態を表せない。"}], "explanations": {"古びた": "連体形で、「時計」を修飾する形として正しい。", "古びます": "ます形は名詞を修飾できず、「古びます時計」は成り立たない。", "古びよう": "意志形は名詞を修飾できず、「古びよう時計」は文が成り立たない。", "古びろ": "命令形は名詞を修飾できず、ここでは時計の状態を表せない。"}, "sentence_index": 6, "correct_answer": "古びた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の木が水不足で古びて、枯れてしまった。", "explanation": "ここは〈枯れる〉の意味。植物が生命を失うのは「枯れる」で、古びるは年月による古さを表すので合わない。"}, {"text": "買ってきた食パンを戸棚に置き忘れて、古びてしまった。", "explanation": "ここは〈傷む〉の意味。食品が悪くなるのは傷むで、古びるは物の年月による古さに使うので合わない。"}, {"text": "子どもたちは一年で古びて、ずいぶん大きくなった。", "explanation": "ここは〈成長する〉の意味。子どもが大きくなるのは成長するで、古びるは物の年月による古さを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52061, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この時計は古びだのに、まだ正確に動く。", "corrected_sentence": "この時計は古びたのに、まだ正確に動く。", "error_description": "誤りは「古びだ」で、連用形に「だ」を付けている点。過去の状態を表すのはタ形の「古びた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "古びて", "is_correct": true, "explanation": "テ形で、文中の「古びてきました」の形。"}, {"text": "古びた", "is_correct": false, "explanation": "タ形は「古びた」で、「古びてきました」の形ではない。"}, {"text": "古びない", "is_correct": false, "explanation": "否定形は「古びていない」の意味で、文の内容と食い違う。"}, {"text": "古びれば", "is_correct": false, "explanation": "仮定形は条件を表し、「十年使って古びてきた」という事実と合わない。"}], "correct_form": "古びて", "base_form": "古びる", "form_label": "テ形", "sentence_index": 1, "explanations": {"古びて": "テ形で、文中の「古びてきました」の形。", "古びた": "タ形は「古びた」で、「古びてきました」の形ではない。", "古びない": "否定形は「古びていない」の意味で、文の内容と食い違う。", "古びれば": "仮定形は条件を表し、「十年使って古びてきた」という事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52061, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このかばんは使い込むと、すぐに古びに。", "corrected_sentence": "このかばんは使い込むと、すぐに古びます。", "error_description": "誤りは「古びに」という活用の形。習慣を述べる丁寧形は「古びます」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "古びます", "is_correct": true, "explanation": "ます形で、文末「すぐに古びます」の形として正しい。"}, {"text": "古び", "is_correct": false, "explanation": "連用形は文末に置けず、「すぐに古び。」では言い切れない。"}, {"text": "古びよう", "is_correct": false, "explanation": "意志形は意志を表し、習慣として物が古くなることを述べる文と合わない。"}, {"text": "古びろ", "is_correct": false, "explanation": "命令形は相手への指示になり、物の性質を述べる文と合わない。"}], "correct_form": "古びます", "base_form": "古びる", "form_label": "ます形", "sentence_index": 7, "explanations": {"古びます": "ます形で、文末「すぐに古びます」の形として正しい。", "古び": "連用形は文末に置けず、「すぐに古び。」では言い切れない。", "古びよう": "意志形は意志を表し、習慣として物が古くなることを述べる文と合わない。", "古びろ": "命令形は相手への指示になり、物の性質を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52063, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示し、「この幼子は、まだ二歳なので」と話題を立てる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「幼子を、まだ二歳なので」では文がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "帰着や相手を示すが、「幼子に、まだ二歳なので」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「幼子で、まだ二歳なので」は不自然。"}], "correct_answer": "は", "explanations": {"は": "主題を示し、「この幼子は、まだ二歳なので」と話題を立てる。", "を": "目的語を示すが、「幼子を、まだ二歳なので」では文がつながらない。", "に": "帰着や相手を示すが、「幼子に、まだ二歳なので」は意味が通らない。", "で": "場所や手段を示すが、「幼子で、まだ二歳なので」は不自然。"}, "error_tags": {"を": "object", "に": "direction", "で": "location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52063, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示し、「眠そうな幼子を、おぶって帰った」のおぶる対象となる。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「幼子で、父が背中におぶって」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「幼子へ、父が背中におぶって」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「幼子から、父が背中におぶって」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示し、「眠そうな幼子を、おぶって帰った」のおぶる対象となる。", "で": "場所や手段を示すが、「幼子で、父が背中におぶって」は成り立たない。", "へ": "方向を示すが、「幼子へ、父が背中におぶって」は不自然。", "から": "起点を示すが、「幼子から、父が背中におぶって」は意味が通らない。"}, "error_tags": {"で": "location", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52063, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とても小さな子どものこと。", "primary_collocate": null, "pronunciation": "おさなご", "ipa": "osanaɡo", "syllable_count": 4, "sentences": [{"text": "公園で、幼子が砂場で遊んでいる。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "公園[こうえん]で、幼子[おさなご]が砂場[すなば]で遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "この幼子はまだ二歳なので、一人では道を渡れない。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "この幼子[おさなご]はまだ二歳[にさい]なので、一人[ひとり]では道[みち]を渡[わた]れない。", "sentence_source": "generated"}, {"text": "幼子が転んで泣いたので、母がすぐにだっこした。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]が転[ころ]んで泣[な]いたので、母[はは]がすぐにだっこした。", "sentence_source": "generated"}, {"text": "電車の中で、幼子が窓の外を楽しそうに見ていた。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で、幼子[おさなご]が窓[まど]の外[そと]を楽[たの]しそうに見[み]ていた。", "sentence_source": "generated"}, {"text": "幼子の笑顔を見ると、疲れが消えてしまう。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]の笑顔[えがお]を見[み]ると、疲[つか]れが消[き]えてしまう。", "sentence_source": "generated"}, {"text": "隣の家の幼子は、いつも元気にあいさつしてくれる。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]の幼子[おさなご]は、いつも元気[げんき]にあいさつしてくれる。", "sentence_source": "generated"}, {"text": "幼子には熱い飲み物を近づけないでください。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]には熱[あつ]い飲[の]み物[もの]を近[ちか]づけないでください。", "sentence_source": "generated"}, {"text": "眠そうな幼子を、父が背中におぶって帰った。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "眠[ねむ]そうな幼子[おさなご]を、父[ちち]が背中[せなか]におぶって帰[かえ]った。", "sentence_source": "generated"}, {"text": "絵本を読むと、幼子はすぐに静かになった。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "絵本[えほん]を読[よ]むと、幼子[おさなご]はすぐに静[しず]かになった。", "sentence_source": "generated"}, {"text": "幼子が一人で歩き出したので、家族みんなが拍手した。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]が一人[ひとり]で歩[ある]き出[だ]したので、家族[かぞく]みんなが拍手[はくしゅ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幼子", "label": "基本形"}, {"form": "幼子たち", "label": "複数"}], "register": "中立（やや文章寄り）", "sense_fingerprint": "とても小さな子ども", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52063, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼子", "is_correct": true, "explanation": "名詞「幼子」は「遊んでいる」の主語になり、公園で遊ぶ子を指す。"}, {"text": "砂場", "is_correct": false, "explanation": "場所の名詞で、遊ぶ主語にならず「砂場が砂場で遊んでいる」となる。"}, {"text": "窓", "is_correct": false, "explanation": "物の名詞で、砂場で遊ぶことはなく、文の意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "物で、遊ぶ主語にならず、ここには入らない。"}], "explanations": {"幼子": "名詞「幼子」は「遊んでいる」の主語になり、公園で遊ぶ子を指す。", "砂場": "場所の名詞で、遊ぶ主語にならず「砂場が砂場で遊んでいる」となる。", "窓": "物の名詞で、砂場で遊ぶことはなく、文の意味が通らない。", "石": "物で、遊ぶ主語にならず、ここには入らない。"}, "sentence_index": 0, "correct_answer": "幼子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "幼子は、週末のデートに備えて服を選んでいた。", "explanation": "ここは〈恋人〉の意味。デートの相手を幼子と呼ぶことはなく、幼子はとても小さな子どもを指すので合わない。"}, {"text": "幼子は、夜遅くまで仕事をして家に帰った。", "explanation": "ここは〈大人〉の意味。働く大人を幼子と呼ぶことはなく、幼子は小さい子を指すので合わない。"}, {"text": "ベテラン幼子の大工が、丁寧に家を建てた。", "explanation": "ここは〈職人〉の意味。熟練の職人に幼子を当てるのは誤りで、幼子は小さな子を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52063, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼子", "is_correct": true, "explanation": "名詞「幼子」は、熱い飲み物から守る対象として「には」と続く。"}, {"text": "眠り", "is_correct": false, "explanation": "抽象名詞で、「眠りには熱い飲み物を近づけないで」とは続かず、文が成り立たない。"}, {"text": "夢", "is_correct": false, "explanation": "抽象名詞で、「夢には熱い飲み物を近づけないで」は意味を成さず、ここには入らない。"}, {"text": "会議", "is_correct": false, "explanation": "会合の名詞で、熱い飲み物を近づける対象にはならず、文の意味が通らない。"}], "explanations": {"幼子": "名詞「幼子」は、熱い飲み物から守る対象として「には」と続く。", "眠り": "抽象名詞で、「眠りには熱い飲み物を近づけないで」とは続かず、文が成り立たない。", "夢": "抽象名詞で、「夢には熱い飲み物を近づけないで」は意味を成さず、ここには入らない。", "会議": "会合の名詞で、熱い飲み物を近づける対象にはならず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "幼子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "幼子は、中学校の体育祭でリレーに出場した。", "explanation": "ここは〈生徒〉の意味。中学生を幼子と呼ぶことはなく、幼子は小さな子を指すので合わない。"}, {"text": "還暦を迎えた幼子が、家族と旅行に出かけた。", "explanation": "ここは〈年配者〉の意味。還暦を過ぎた人を幼子とは言わないので合わない。"}, {"text": "大学院の幼子が、研究の成果を学会で発表した。", "explanation": "ここは〈研究者〉の意味。大学院生や研究者を幼子と呼ぶことはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52063, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幼子が、母が背中におぶって歩いた。", "corrected_sentence": "幼子を、母が背中におぶって歩いた。", "error_description": "誤りは「幼子が」の「が」。おぶる対象は「を」で示し、「が」では幼子が主語になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52063, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼子の、ミルクを飲ませた。", "corrected_sentence": "幼子に、ミルクを飲ませた。", "error_description": "誤りは「幼子の」の「の」。飲ませる相手は「に」で示し、「の」では幼子が行為の主体にも相手にもならず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52064, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示し、「幼子は母の腕の中で眠っている」と文の話題を立てる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「幼子を眠っている」では眠る主体が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示すが、「幼子に母の腕の中で眠っている」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「幼子で眠っている」では主語を示せない。"}], "correct_answer": "は", "explanations": {"は": "主題を示し、「幼子は母の腕の中で眠っている」と文の話題を立てる。", "を": "目的語を示すが、「幼子を眠っている」では眠る主体が成り立たない。", "に": "方向や相手を示すが、「幼子に母の腕の中で眠っている」は意味が通らない。", "で": "場所や手段を示すが、「幼子で眠っている」では主語を示せない。"}, "error_tags": {"を": "object", "に": "direction", "で": "location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52064, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾を示し、「幼子の足取り」として直後の語とつながる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「幼子を足取り」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「幼子で足取り」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「幼子へ足取り」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾を示し、「幼子の足取り」として直後の語とつながる。", "を": "目的語を示すが、「幼子を足取り」では文が成り立たない。", "で": "場所や手段を示すが、「幼子で足取り」は不自然。", "へ": "方向を示すが、「幼子へ足取り」は成り立たない。"}, "error_tags": {"を": "object", "で": "location", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52064, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まだ歩いたり話したりすることがあまりできない、小さな子ども。特に、親に保護されて育てられている年ごろの子ども。", "primary_collocate": null, "pronunciation": "おさなご", "ipa": "osanaɡo", "syllable_count": 4, "sentences": [{"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "幼子", "complexity_tier": "T4", "furigana": "秋[あき]の気配[けはい]が色濃[いろこ]く漂[ただよ]う古[ふる]びた縁側[えんがわ]にて、一人[ひとり]の幼子[おさなご]が無心[むしん]なる眼差[まなざ]しを向[む]けているのは、掌[てのひら]に収[おさ]められた一[ひと]つの赤[あか]い果物[くだもの]である。", "sentence_source": "mined"}, {"text": "幼子は母の腕の中で、安心しきった顔で眠っている。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]は母[はは]の腕[うで]の中[なか]で、安心[あんしん]しきった顔[かお]で眠[ねむ]っている。", "sentence_source": "generated"}, {"text": "まだ言葉を話せない幼子が、指をさして何かを伝えようとした。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "まだ言葉[ことば]を話[はな]せない幼子[おさなご]が、指[ゆび]をさして何[なに]かを伝[つた]えようとした。", "sentence_source": "generated"}, {"text": "幼子を連れた夫婦が、ゆっくりと公園の道を歩いていく。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]を連[つ]れた夫婦[ふうふ]が、ゆっくりと公園[こうえん]の道[みち]を歩[ある]いていく。", "sentence_source": "generated"}, {"text": "幼子は親の手がなければ、一人で階段をのぼることもできない。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]は親[おや]の手[て]がなければ、一人[ひとり]で階段[かいだん]をのぼることもできない。", "sentence_source": "generated"}, {"text": "戦火の中で、幼子の泣き声だけが町に響いていた。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "戦火[せんか]の中[なか]で、幼子[おさなご]の泣[な]き声[ごえ]だけが町[まち]に響[ひび]いていた。", "sentence_source": "generated"}, {"text": "母親は熱を出した幼子を、一晩中そばで見守った。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "母親[ははおや]は熱[ねつ]を出[だ]した幼子[おさなご]を、一晩中[ひとばんじゅう]そばで見守[みまも]った。", "sentence_source": "generated"}, {"text": "幼子のよちよちした足取りに、祖父は思わず目を細めた。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]のよちよちした足取[あしど]りに、祖父[そふ]は思[おも]わず目[め]を細[ほそ]めた。", "sentence_source": "generated"}, {"text": "幼子を守り育てることは、親にとって何よりも大切な務めである。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]を守[まも]り育[そだ]てることは、親[おや]にとって何[なに]よりも大切[たいせつ]な務[つと]めである。", "sentence_source": "generated"}, {"text": "幼子は初めて見る雪に、小さな手を伸ばして喜んだ。", "target_word": "幼子", "complexity_tier": "T3", "furigana": "幼子[おさなご]は初[はじ]めて見[み]る雪[ゆき]に、小[ちい]さな手[て]を伸[の]ばして喜[よろこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幼子", "label": "基本形"}, {"form": "幼子たち", "label": "複数"}], "register": "文章語（やや文語的）", "sense_fingerprint": "親の保護のもとにある、まだ歩く・話すことが十分にできない小さな子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52064, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼子", "is_correct": true, "explanation": "名詞「幼子」は「一人の」を受けて、無心な眼差しの持ち主になれる。"}, {"text": "縁側", "is_correct": false, "explanation": "場所の名詞で、「一人の縁側が無心なる眼差し」となり文が成り立たない。"}, {"text": "果物", "is_correct": false, "explanation": "食べ物の名詞で、無心な眼差しを向ける主語にならない。"}, {"text": "眼差し", "is_correct": false, "explanation": "「眼差し」は文中で既に使われており、「一人の眼差しが無心なる眼差し」となって不自然。"}], "explanations": {"幼子": "名詞「幼子」は「一人の」を受けて、無心な眼差しの持ち主になれる。", "縁側": "場所の名詞で、「一人の縁側が無心なる眼差し」となり文が成り立たない。", "果物": "食べ物の名詞で、無心な眼差しを向ける主語にならない。", "眼差し": "「眼差し」は文中で既に使われており、「一人の眼差しが無心なる眼差し」となって不自然。"}, "sentence_index": 0, "correct_answer": "幼子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "幼子は、来春から中学校に入学する。", "explanation": "ここは〈生徒〉の意味。中学に入る年ごろの子は生徒で、親に育てられる幼い子を指す幼子とは合わない。"}, {"text": "会社に入ったばかりの幼子が、役員の前で緊張していた。", "explanation": "ここは〈新入社員〉の意味。社会人を幼子と呼ぶことはなく、幼子は小さな子を指すので合わない。"}, {"text": "定年後の幼子は、毎日庭の手入れに励んでいる。", "explanation": "ここは〈高齢者〉の意味。定年を迎えた人を幼子と呼ぶことはなく、幼子は幼い子どもを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52064, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼子", "is_correct": true, "explanation": "名詞「幼子」は「熱を出した」を受けて、看病される子を指せる。"}, {"text": "窓", "is_correct": false, "explanation": "物の名詞で、「熱を出した窓」は成り立たず、見守る対象にならない。"}, {"text": "石", "is_correct": false, "explanation": "物で、熱を出すことはなく、文が成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "物で、熱を出すことはなく、ここには入らない。"}], "explanations": {"幼子": "名詞「幼子」は「熱を出した」を受けて、看病される子を指せる。", "窓": "物の名詞で、「熱を出した窓」は成り立たず、見守る対象にならない。", "石": "物で、熱を出すことはなく、文が成り立たない。", "紙": "物で、熱を出すことはなく、ここには入らない。"}, "sentence_index": 6, "correct_answer": "幼子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "幼子は学校の帰りに、友達と公園で遊んで帰った。", "explanation": "ここは〈児童〉の意味。学校に通う子を幼子とは言わず、幼子は親に育てられる年ごろの子を指すので合わない。"}, {"text": "入試を控えた幼子は、毎晩遅くまで机に向かっている。", "explanation": "ここは〈受験生〉の意味。受験生を幼子と呼ぶことはなく、幼子は小さな子を指すので合わない。"}, {"text": "町の幼子たちが、市長選挙の結果を議論していた。", "explanation": "ここは〈市民〉の意味。大人の市民を幼子と呼ぶことはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52064, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幼子を母の手を借りて、やっと歩けるようになった。", "corrected_sentence": "幼子は母の手を借りて、やっと歩けるようになった。", "error_description": "誤りは「幼子を」の「を」。主題を示すのは「は」で、「歩けるようになった」に目的語は要らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52064, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼子が、祖母が絵本を読んで聞かせた。", "corrected_sentence": "幼子に、祖母が絵本を読んで聞かせた。", "error_description": "誤りは「幼子が」の「が」。聞かせる相手を示すには「に」が必要で、「が」では幼子が聞かせる側になってしまう。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52065, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は動作の場所を示し、「縁側でスイカを食べる」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「縁側を」は対象を示すことになり、「スイカを」と二つの「を」が重なって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。ここは静止した場所での動作なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。縁側が食べるという意味になり不自然。"}], "correct_answer": "で", "explanations": {"で": "「で」は動作の場所を示し、「縁側でスイカを食べる」と自然につながる。", "を": "「縁側を」は対象を示すことになり、「スイカを」と二つの「を」が重なって不自然。", "へ": "「へ」は移動の方向を示す。ここは静止した場所での動作なので合わない。", "が": "「が」は主語を示す。縁側が食べるという意味になり不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52065, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「縁側を」は「拭いている」の対象を示す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するが、後ろに名詞が続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。拭く動作の対象にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や相手を示す。拭く動作の対象としては合わない。"}], "correct_answer": "を", "explanations": {"を": "「縁側を」は「拭いている」の対象を示す。", "の": "「の」は名詞を修飾するが、後ろに名詞が続かず文が成り立たない。", "へ": "「へ」は移動の方向を示す。拭く動作の対象にはならない。", "に": "「に」は到着点や相手を示す。拭く動作の対象としては合わない。"}, "error_tags": {"の": "連体", "へ": "方向", "に": "相手・到着"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52065, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の外側に沿って作られた、長くて細い板張りの場所。外の空気を楽しみながら座ったり歩いたりする。", "primary_collocate": null, "pronunciation": "えんがわ", "ipa": "eŋɡawa", "syllable_count": 4, "sentences": [{"text": "祖父は縁側に座って、お茶を飲んでいる。", "target_word": "縁側", "complexity_tier": "T2", "furigana": "祖父[そふ]は縁側[えんがわ]に座[すわ]って、お茶[ちゃ]を飲[の]んでいる。", "sentence_source": "generated"}, {"text": "夏の夜、縁側でスイカを食べながら花火を見た。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "夏[なつ]の夜[よる]、縁側[えんがわ]でスイカを食[た]べながら花火[はなび]を見[み]た。", "sentence_source": "generated"}, {"text": "猫が縁側でひなたぼっこをしている。", "target_word": "縁側", "complexity_tier": "T2", "furigana": "猫[ねこ]が縁側[えんがわ]でひなたぼっこをしている。", "sentence_source": "generated"}, {"text": "雨の日は、縁側から庭の花を静かに見ていた。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、縁側[えんがわ]から庭[にわ]の花[はな]を静[しず]かに見[み]ていた。", "sentence_source": "generated"}, {"text": "縁側に洗濯物を干すと、よく乾く。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "縁側[えんがわ]に洗濯物[せんたくもの]を干[ほ]すと、よく乾[かわ]く。", "sentence_source": "generated"}, {"text": "祖母の家の縁側は、風が通って涼しい。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "祖母[そぼ]の家[いえ]の縁側[えんがわ]は、風[かぜ]が通[とお]って涼[すず]しい。", "sentence_source": "generated"}, {"text": "近所の人が、縁側に集まって話をしていた。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "近所[きんじょ]の人[ひと]が、縁側[えんがわ]に集[あつ]まって話[はなし]をしていた。", "sentence_source": "generated"}, {"text": "古い家の縁側を、毎朝ぞうきんで拭いている。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]の縁側[えんがわ]を、毎朝[まいあさ]ぞうきんで拭[ふ]いている。", "sentence_source": "generated"}, {"text": "子どものころ、縁側から庭にとび出して遊んだ。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "子[こ]どものころ、縁側[えんがわ]から庭[にわ]にとび出[だ]して遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "縁側に座布団を出して、お客さんをもてなした。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "縁側[えんがわ]に座布団[ざぶとん]を出[だ]して、お客[きゃく]さんをもてなした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "縁側", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "日本家屋の庭に面した細長い板張りの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52065, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "縁側", "is_correct": true, "explanation": "家の外に作られた板張りの場所で、座って寛ぐ文に合う。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、座る場所にはならない。"}, {"text": "水道", "is_correct": false, "explanation": "水道は水を出す設備で、座る場所ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす家電で、座る場所ではない。"}], "explanations": {"縁側": "家の外に作られた板張りの場所で、座って寛ぐ文に合う。", "天井": "天井は部屋の上の面で、座る場所にはならない。", "水道": "水道は水を出す設備で、座る場所ではない。", "冷蔵庫": "冷蔵庫は食品を冷やす家電で、座る場所ではない。"}, "sentence_index": 0, "correct_answer": "縁側"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜の縁側で、ピアノを練習した。", "explanation": "縁側は板張りの場所で、ピアノを練習する部屋ではないので合わない。"}, {"text": "縁側で五階まで行って、部屋に入った。", "explanation": "縁側は階を移動する設備ではないので、五階へ行く文には合わない。"}, {"text": "公園の縁側に乗って遊んだ。", "explanation": "縁側は座ったり歩いたりする場所で、乗って遊ぶ遊具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52065, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "縁側", "is_correct": true, "explanation": "人が集まって話す場所として自然で、近所の人の集まりに合う。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは布団をしまう収納で、人が集まって話す場所ではない。"}, {"text": "戸棚", "is_correct": false, "explanation": "戸棚は物をしまう家具で、人が集まって話す場所ではない。"}, {"text": "下駄箱", "is_correct": false, "explanation": "下駄箱は靴をしまう場所で、人が集まって話す場所ではない。"}], "explanations": {"縁側": "人が集まって話す場所として自然で、近所の人の集まりに合う。", "押し入れ": "押し入れは布団をしまう収納で、人が集まって話す場所ではない。", "戸棚": "戸棚は物をしまう家具で、人が集まって話す場所ではない。", "下駄箱": "下駄箱は靴をしまう場所で、人が集まって話す場所ではない。"}, "sentence_index": 6, "correct_answer": "縁側"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前で、縁側を待った。", "explanation": "縁側は待つ対象となる乗り物ではないので、駅前で待つ文には合わない。"}, {"text": "縁側で、車のエンジンをかけた。", "explanation": "縁側は車を入れて整備する場所ではないので、この文には合わない。"}, {"text": "自転車の縁側を握って、坂を下りた。", "explanation": "縁側は握って操作する部品ではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52065, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、縁側に風鈴を聞きながら涼んだ。", "corrected_sentence": "夕方、縁側で風鈴を聞きながら涼んだ。", "error_description": "「涼む」は場所を「で」で示す。「縁側に」の「に」が誤りで、「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52065, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い家の縁側を雑巾で弾いて、きれいにした。", "corrected_sentence": "古い家の縁側を雑巾で磨いて、きれいにした。", "error_description": "縁側は「磨く」「拭く」と組む。「弾く」は楽器や弦を対象とする動詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
