INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52067, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "何も考えていないこと。", "primary_collocate": null, "pronunciation": "むしん", "ipa": "mɯɕiɴ", "syllable_count": 3, "sentences": [{"text": "子どもは無心に砂で遊んでいた。", "target_word": "無心", "complexity_tier": "T3", "furigana": "子(こ)どもは無心(むしん)に砂(すな)で遊(あそ)んでいた。", "sentence_source": "generated"}, {"text": "無心で走っていたら、いつの間にかゴールだった。", "target_word": "無心", "complexity_tier": "T3", "furigana": "無心(むしん)で走(はし)っていたら、いつの間(ま)にかゴールだった。", "sentence_source": "generated"}, {"text": "赤ちゃんが無心にミルクを飲んでいる。", "target_word": "無心", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんが無心(むしん)にミルクを飲(の)んでいる。", "sentence_source": "generated"}, {"text": "彼は無心にボールを蹴り続けた。", "target_word": "無心", "complexity_tier": "T3", "furigana": "彼(かれ)は無心(むしん)にボールを蹴(け)り続(つづ)けた。", "sentence_source": "generated"}, {"text": "無心になって、庭の草をぬいた。", "target_word": "無心", "complexity_tier": "T3", "furigana": "無心(むしん)になって、庭(にわ)の草(くさ)をぬいた。", "sentence_source": "generated"}, {"text": "試合では、無心でプレーすることが大切だ。", "target_word": "無心", "complexity_tier": "T3", "furigana": "試合(しあい)では、無心(むしん)でプレーすることが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "無心に絵をかく姿は、とても美しい。", "target_word": "無心", "complexity_tier": "T3", "furigana": "無心(むしん)に絵(え)をかく姿(すがた)は、とても美(うつく)しい。", "sentence_source": "generated"}, {"text": "難しい問題も、無心で取り組めば解けることがある。", "target_word": "無心", "complexity_tier": "T3", "furigana": "難(むずか)しい問題(もんだい)も、無心(むしん)で取(と)り組(く)めば解(と)けることがある。", "sentence_source": "generated"}, {"text": "座禅では、無心になるように教えられた。", "target_word": "無心", "complexity_tier": "T3", "furigana": "座禅(ざぜん)では、無心(むしん)になるように教(おし)えられた。", "sentence_source": "generated"}, {"text": "犬が無心にしっぽを振って、私を迎えた。", "target_word": "無心", "complexity_tier": "T3", "furigana": "犬(いぬ)が無心(むしん)にしっぽを振(ふ)って、私(わたし)を迎(むか)えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無心だ", "label": "断定形"}, {"form": "無心な", "label": "連体形"}, {"form": "無心に", "label": "連用形（に）"}, {"form": "無心で", "label": "連用形（で）"}, {"form": "無心の", "label": "連体形（の）"}], "register": "標準語", "sense_fingerprint": "雑念がなく、一つのことに心を向けている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52067, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無心", "is_correct": true, "explanation": "「子どもは〜に砂で遊んでいた」の形。雑念なく一つのことに心を向けている様子を表す。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈に砂で遊ぶ」は、退屈な気持ちで遊ぶという矛盾した文になる。"}, {"text": "大変", "is_correct": false, "explanation": "「大変に砂で遊ぶ」は、遊ぶ様子を表す語として意味が合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹に砂で遊ぶ」は、空腹の状態で遊ぶという意味が文脈と合わない。"}], "explanations": {"無心": "「子どもは〜に砂で遊んでいた」の形。雑念なく一つのことに心を向けている様子を表す。", "退屈": "「退屈に砂で遊ぶ」は、退屈な気持ちで遊ぶという矛盾した文になる。", "大変": "「大変に砂で遊ぶ」は、遊ぶ様子を表す語として意味が合わない。", "空腹": "「空腹に砂で遊ぶ」は、空腹の状態で遊ぶという意味が文脈と合わない。"}, "sentence_index": 0, "correct_answer": "無心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その話を聞いて、彼は無心に怒り出した。", "explanation": "ここは「激しく怒る（感情が高ぶる）」の意味。無心は何も考えていない静かな状態なので、感情的に怒る様子とは合わない。"}, {"text": "彼は周りの出来事に無心だった。", "explanation": "ここは「無関心」の意味。無心は一つのことに心を集中させる状態で、物事に関心がないことは表さない。"}, {"text": "母は家計が苦しく、親戚に無心の電話をかけた。", "explanation": "ここは「金品をねだる」の意味。無心（名詞）は金銭の依頼を指し、雑念のない状態とは関係しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52067, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無心", "is_correct": true, "explanation": "「〜に絵をかく姿は」の形。雑念なく絵に心を向ける様子を表す。"}, {"text": "迷惑", "is_correct": false, "explanation": "「迷惑に絵をかく」は、迷惑をかける形で絵をかくという意味が通らない。"}, {"text": "憂鬱", "is_correct": false, "explanation": "「憂鬱に絵をかく」は、憂うつな気持ちで絵をかくという文脈と合わない。"}, {"text": "無知", "is_correct": false, "explanation": "「無知に絵をかく」は、知識がないまま絵をかくという意味で、姿の美しさを表す文に合わない。"}], "explanations": {"無心": "「〜に絵をかく姿は」の形。雑念なく絵に心を向ける様子を表す。", "迷惑": "「迷惑に絵をかく」は、迷惑をかける形で絵をかくという意味が通らない。", "憂鬱": "「憂鬱に絵をかく」は、憂うつな気持ちで絵をかくという文脈と合わない。", "無知": "「無知に絵をかく」は、知識がないまま絵をかくという意味で、姿の美しさを表す文に合わない。"}, "sentence_index": 6, "correct_answer": "無心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "無心の心で、彼はテストの答えを必死に考えた。", "explanation": "ここは「熟考」の意味。無心は何も考えていない状態で、深く考えを巡らせる場面には合わない。"}, {"text": "無心で負けを悔やみ、涙をこらえた。", "explanation": "ここは「悔しさ」の意味。無心は雑念がない状態で、悔しさで心が乱れる様子とは合わない。"}, {"text": "彼は親に無心して、新しい車を買ってもらった。", "explanation": "ここは「金品をねだる」の意味。無心する（動詞）は金銭を求める行為で、雑念のない状態とは関係しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52067, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールを追いかける子どもたちは、無心を走っていた。", "corrected_sentence": "ボールを追いかける子どもたちは、無心に走っていた。", "error_description": "誤：「を」。正：「に」。無心は状態を表す語で、動詞「走る」を修飾する場合は連用形「に」を付ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無心で", "is_correct": true, "explanation": "連用形（で）。「無心で走っていたら」の形で、雑念なく走る状態を表す。"}, {"text": "無心の", "is_correct": false, "explanation": "連体形（の）。名詞を修飾する形で、「走っていたら」の前には置けない。"}, {"text": "無心な", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、「走っていたら」の状態を表す文には合わない。"}, {"text": "無心だ", "is_correct": false, "explanation": "断定形。「走っていたら」の状態を表す文の形として文が成り立たない。"}], "correct_form": "無心で", "base_form": "無心", "form_label": "連用形（で）", "sentence_index": 1, "explanations": {"無心で": "連用形（で）。「無心で走っていたら」の形で、雑念なく走る状態を表す。", "無心の": "連体形（の）。名詞を修飾する形で、「走っていたら」の前には置けない。", "無心な": "連体形。名詞を修飾する形で、「走っていたら」の状態を表す文には合わない。", "無心だ": "断定形。「走っていたら」の状態を表す文の形として文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52067, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は無心したまま針仕事を続けていた。", "corrected_sentence": "彼女は無心に針仕事を続けていた。", "error_description": "誤：「無心したまま」。正：「無心に」。無心は「する」を付けると金品をねだる意味になるので、状態を表すには連用形「に」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無心で", "is_correct": true, "explanation": "連用形（で）。「無心で取り組めば」の形で、雑念なく取り組む状態を表す。"}, {"text": "無心だろう", "is_correct": false, "explanation": "推量形。「無心だろう取り組めば」と続かず、文として成り立たない。"}, {"text": "無心にする", "is_correct": false, "explanation": "「無心に」＋「する」の形。「無心にする、取り組めば」と続かず、文が成り立たない。"}, {"text": "無心だった", "is_correct": false, "explanation": "過去の断定形。「取り組めば」の仮定の文脈と時制が合わない。"}], "correct_form": "無心で", "base_form": "無心", "form_label": "連用形（で）", "sentence_index": 7, "explanations": {"無心で": "連用形（で）。「無心で取り組めば」の形で、雑念なく取り組む状態を表す。", "無心だろう": "推量形。「無心だろう取り組めば」と続かず、文として成り立たない。", "無心にする": "「無心に」＋「する」の形。「無心にする、取り組めば」と続かず、文が成り立たない。", "無心だった": "過去の断定形。「取り組めば」の仮定の文脈と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
