INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52069, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "手のひらのことです。", "primary_collocate": null, "pronunciation": "てのひら", "ipa": "tenoçiɾa", "syllable_count": 4, "sentences": [{"text": "掌に小さな雪がのって、すぐに溶けてしまった。", "target_word": "掌", "complexity_tier": "T3", "furigana": "掌[てのひら]に小[ちい]さな雪[ゆき]がのって、すぐに溶[と]けてしまった。", "sentence_source": "generated"}, {"text": "手を洗ったあと、掌をタオルでふいた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "手[て]を洗[あら]ったあと、掌[てのひら]をタオルでふいた。", "sentence_source": "generated"}, {"text": "先生は掌を前に出して、生徒たちを止めた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "先生[せんせい]は掌[てのひら]を前[まえ]に出[だ]して、生徒[せいと]たちを止[と]めた。", "sentence_source": "generated"}, {"text": "子どもが掌を開くと、中にどんぐりが入っていた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "子[こ]どもが掌[てのひら]を開[ひら]くと、中[なか]にどんぐりが入[はい]っていた。", "sentence_source": "generated"}, {"text": "暑い日は、掌にも汗をかく。", "target_word": "掌", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]は、掌[てのひら]にも汗[あせ]をかく。", "sentence_source": "generated"}, {"text": "両方の掌を合わせて、神社でお願いごとをした。", "target_word": "掌", "complexity_tier": "T3", "furigana": "両方[りょうほう]の掌[てのひら]を合[あ]わせて、神社[じんじゃ]でお願[ねが]いごとをした。", "sentence_source": "generated"}, {"text": "熱いお茶のカップで、掌がじんわりあたたかくなった。", "target_word": "掌", "complexity_tier": "T3", "furigana": "熱[あつ]いお茶[ちゃ]のカップで、掌[てのひら]がじんわりあたたかくなった。", "sentence_source": "generated"}, {"text": "犬に「お手」と言うと、私の掌に足をのせた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "犬[いぬ]に「お手[て]」と言[い]うと、私[わたし]の掌[てのひら]に足[あし]をのせた。", "sentence_source": "generated"}, {"text": "彼は掌に名前を書いて、忘れないようにした。", "target_word": "掌", "complexity_tier": "T3", "furigana": "彼[かれ]は掌[てのひら]に名前[なまえ]を書[か]いて、忘[わす]れないようにした。", "sentence_source": "generated"}, {"text": "掌でボールを強くたたくと、大きな音がした。", "target_word": "掌", "complexity_tier": "T3", "furigana": "掌[てのひら]でボールを強[つよ]くたたくと、大[おお]きな音[おと]がした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掌", "label": "基本形"}, {"form": "掌に", "label": "に格"}, {"form": "掌を", "label": "を格"}], "register": "中立（日常的）", "sense_fingerprint": "手の内側の面、手のひら", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52069, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掌", "is_correct": true, "explanation": "手のひらの上に雪がのって溶けた、という描写として自然。"}, {"text": "爪", "is_correct": false, "explanation": "爪に小さな雪がのって溶けるという場面は想定しにくく、不自然。"}, {"text": "声", "is_correct": false, "explanation": "声に雪がのって溶けるという描写は成り立たず、文の意味が通らない。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉に雪がのって溶けるという描写は成り立たず、文の意味が通らない。"}], "explanations": {"掌": "手のひらの上に雪がのって溶けた、という描写として自然。", "爪": "爪に小さな雪がのって溶けるという場面は想定しにくく、不自然。", "声": "声に雪がのって溶けるという描写は成り立たず、文の意味が通らない。", "言葉": "言葉に雪がのって溶けるという描写は成り立たず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "掌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ブレスレットを掌につけて、鈴を鳴らした。", "explanation": "ここは〈手首〉の意味。ブレスレットは手首につけるもので、掌にはつけない。"}, {"text": "鉛筆を掌でつまんで、字を書いた。", "explanation": "ここは〈指先〉の意味。つまむ動作は指先が担うので、掌では合わない。"}, {"text": "雨で濡れた靴の中で、掌が冷たくなった。", "explanation": "ここは〈足〉の意味。靴の中にあるのは足で、掌は手の内側なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52069, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌", "is_correct": true, "explanation": "熱いカップで手のひらが温まったという描写として自然。"}, {"text": "宿題", "is_correct": false, "explanation": "「熱いお茶のカップで宿題がじんわりあたたかくなった」は成り立たず、文脈に合わない。"}, {"text": "切符", "is_correct": false, "explanation": "「熱いお茶のカップで切符がじんわりあたたかくなった」は意味が通らず、ここでは使えない。"}, {"text": "尻", "is_correct": false, "explanation": "お茶のカップで尻が温まるという描写は、この文に合わない。"}], "explanations": {"掌": "熱いカップで手のひらが温まったという描写として自然。", "宿題": "「熱いお茶のカップで宿題がじんわりあたたかくなった」は成り立たず、文脈に合わない。", "切符": "「熱いお茶のカップで切符がじんわりあたたかくなった」は意味が通らず、ここでは使えない。", "尻": "お茶のカップで尻が温まるという描写は、この文に合わない。"}, "sentence_index": 6, "correct_answer": "掌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い朝、靴下を掌にはいて廊下を歩いた。", "explanation": "ここは〈足〉の意味。靴下は足にはくもので、掌は手にある部分なので合わない。"}, {"text": "裸足で砂浜を歩いたら、掌がひりひりした。", "explanation": "ここは〈足の裏〉の意味。掌は手にある面なので、足には使わない。"}, {"text": "眼鏡を掌にかけて、本を読んだ。", "explanation": "ここは〈耳〉（眼鏡をかける場所）の意味。眼鏡は耳にかけるもので、掌には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52069, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪の結晶を掌がのせて、よく見た。", "corrected_sentence": "雪の結晶を掌にのせて、よく見た。", "error_description": "誤りは「掌が」（主語の「が」）。正しくは「掌に」（のせる先の「に」）。「のせる」は場所を示すので、掌を主語にすると文が成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52069, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "かじかんだ掌が息を吹きかけた。", "corrected_sentence": "かじかんだ掌に息を吹きかけた。", "error_description": "誤りは「掌が」（主語の「が」）。正しくは「掌に」（吹きかける相手の「に」）。「息を吹きかける」は「〜に」で相手を示すので、掌を主語にすると文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52070, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「掌に汗をかく」の「に」は、汗をかく場所（掌）を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」だと「掌と汗をかく」となり、並べる相手がなく文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「汗をかく」と結びつかず、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "所有の「の」だと「掌の汗をかく」となり、動詞「かく」の場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「掌に汗をかく」の「に」は、汗をかく場所（掌）を示す。", "と": "並列の「と」だと「掌と汗をかく」となり、並べる相手がなく文が成立しない。", "より": "比較の「より」は「汗をかく」と結びつかず、意味が通らない。", "の": "所有の「の」だと「掌の汗をかく」となり、動詞「かく」の場所を示せない。"}, "error_tags": {"と": "並列の相手がなく文が成立しない", "より": "比較の語で「汗をかく」と接続しない", "の": "所有を示し、動詞の場所にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52070, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「患者の掌を押す」の「を」は、押す対象（掌）を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だと「掌が押して」となり、押す動作の主体にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」だと「掌と押して」となり、押す対象を示せず文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」だと押す対象にならず、動作と合わない。"}], "correct_answer": "を", "explanations": {"を": "「患者の掌を押す」の「を」は、押す対象（掌）を示す。", "が": "主語の「が」だと「掌が押して」となり、押す動作の主体にならず不自然。", "と": "並列の「と」だと「掌と押して」となり、押す対象を示せず文が成立しない。", "から": "起点を示す「から」だと押す対象にならず、動作と合わない。"}, "error_tags": {"が": "主語にすると押す動作の主体にならない", "から": "起点を示し、押す対象にならない", "と": "並列の相手がなく、押す対象を示せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52070, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "手のひら。手の内側の、指の付け根から手首までの平らな部分。", "primary_collocate": null, "pronunciation": "てのひら", "ipa": "tenoçiɾa", "syllable_count": 4, "sentences": [{"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "掌", "complexity_tier": "T4", "furigana": "秋[あき]の気配[けはい]が色濃[いろこ]く漂[ただよ]う古[ふる]びた縁側[えんがわ]にて、一人[ひとり]の幼子[おさなご]が無心[むしん]なる眼差[まなざ]しを向[む]けているのは、掌[てのひら]に収[おさ]められた一[ひと]つの赤[あか]い果物[くだもの]である。", "sentence_source": "mined"}, {"text": "掌に汗をかくほど、発表の前は緊張していた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "掌[てのひら]に汗[あせ]をかくほど、発表[はっぴょう]の前[まえ]は緊張[きんちょう]していた。", "sentence_source": "generated"}, {"text": "寒い朝、掌をこすり合わせて手をあたためた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]、掌[てのひら]をこすり合[あ]わせて手[て]をあたためた。", "sentence_source": "generated"}, {"text": "彼女は掌を上に向けて、雨が降っているか確かめた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は掌[てのひら]を上[うえ]に向[む]けて、雨[あめ]が降[ふ]っているか確[たし]かめた。", "sentence_source": "generated"}, {"text": "転んだときに地面についた掌を、すりむいてしまった。", "target_word": "掌", "complexity_tier": "T3", "furigana": "転[ころ]んだときに地面[じめん]についた掌[てのひら]を、すりむいてしまった。", "sentence_source": "generated"}, {"text": "掌の線を見て、占い師は私の未来を語り始めた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "掌[てのひら]の線[せん]を見[み]て、占[うらな]い師[し]は私[わたし]の未来[みらい]を語[かた]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "掌に乗るほど小さな子猫が、箱の中で鳴いていた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "掌[てのひら]に乗[の]るほど小[ちい]さな子猫[こねこ]が、箱[はこ]の中[なか]で鳴[な]いていた。", "sentence_source": "generated"}, {"text": "医者は患者の掌を押して、痛みがあるか確かめた。", "target_word": "掌", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]の掌[てのひら]を押[お]して、痛[いた]みがあるか確[たし]かめた。", "sentence_source": "generated"}, {"text": "握手をすると、彼の掌は大きくて温かかった。", "target_word": "掌", "complexity_tier": "T3", "furigana": "握手[あくしゅ]をすると、彼[かれ]の掌[てのひら]は大[おお]きくて温[あたた]かかった。", "sentence_source": "generated"}, {"text": "掌で水をすくい、冷たい川の水を一口飲んだ。", "target_word": "掌", "complexity_tier": "T3", "furigana": "掌[てのひら]で水[みず]をすくい、冷[つめ]たい川[かわ]の水[みず]を一口[ひとくち]飲[の]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掌", "label": "基本形"}, {"form": "掌に", "label": "に格"}, {"form": "掌を", "label": "を格"}], "register": "中立（漢字表記は文章寄り）", "sense_fingerprint": "手の内側の、指の付け根から手首までの平らな部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52070, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掌", "is_correct": true, "explanation": "「掌に収められた」は、果物を載せる手のひらを指し、文の流れに合う。"}, {"text": "指", "is_correct": false, "explanation": "指は物を収める場所にはならず、「指に収められた果物」は文脈として成り立たない。"}, {"text": "額", "is_correct": false, "explanation": "額に果物を収めるとは言わず、置く場所として不自然。"}, {"text": "足", "is_correct": false, "explanation": "足に果物を収めるのは不自然で、この文の意味に合わない。"}], "explanations": {"掌": "「掌に収められた」は、果物を載せる手のひらを指し、文の流れに合う。", "指": "指は物を収める場所にはならず、「指に収められた果物」は文脈として成り立たない。", "額": "額に果物を収めるとは言わず、置く場所として不自然。", "足": "足に果物を収めるのは不自然で、この文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "掌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "腕時計を掌に巻いて、留め金をかけた。", "explanation": "ここは〈手首〉の意味。腕時計は手首に巻くもので、掌には合わない。"}, {"text": "裸足で砂浜を歩くと、掌がくすぐったい。", "explanation": "ここは〈足の裏〉の意味。掌は手の内側の面を指すので、足には使わない。"}, {"text": "寒さで赤くなった掌の甲を、そっとなでた。", "explanation": "ここは〈手の甲〉の意味。甲は手の背側を指し、掌は手の内側なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52070, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌", "is_correct": true, "explanation": "子猫が乗れるほど小さいことを表す手のひらで、文の意味に合う。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉に子猫が乗るという描写は成り立たず、文の意味が通らない。"}, {"text": "耳", "is_correct": false, "explanation": "耳に子猫が乗るという状況は想定しにくく、文が成り立たない。"}, {"text": "唇", "is_correct": false, "explanation": "唇に子猫が乗るのは意味が通らず、文脈に合わない。"}], "explanations": {"掌": "子猫が乗れるほど小さいことを表す手のひらで、文の意味に合う。", "言葉": "言葉に子猫が乗るという描写は成り立たず、文の意味が通らない。", "耳": "耳に子猫が乗るという状況は想定しにくく、文が成り立たない。", "唇": "唇に子猫が乗るのは意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "掌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒いので、掌をはめて出かけた。", "explanation": "ここは〈手袋〉の意味。はめるのは手袋で、掌は体の部分なので合わない。"}, {"text": "ペンを掌でつまんで、字を書いた。", "explanation": "ここは〈指先〉の意味。つまむ動作は指先が担うので、掌では合わない。"}, {"text": "子どもの掌の爪を切ってやった。", "explanation": "ここは〈爪〉の意味。切るのは爪で、爪は指先にあるので、掌とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52070, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喉が渇いたので、掌を川の水をすくって飲んだ。", "corrected_sentence": "喉が渇いたので、掌で川の水をすくって飲んだ。", "error_description": "誤りは「掌を」。正しくは「掌で」（手段の「で」）。「すくう」の対象は「川の水」なので、「掌を」を使うと目的語が二つになり不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52070, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "かごから出てきた子ネズミを、彼は掌がそっとのせた。", "corrected_sentence": "かごから出てきた子ネズミを、彼は掌にそっとのせた。", "error_description": "誤りは「掌が」（主語の「が」）。正しくは「掌に」（のせる先の「に」）。「のせる」は「〜にのせる」で場所を示すので、掌を主語にすると文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52071, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「眼差しで」の「で」。様子や手段を表し、「真剣な眼差しで話を聞く」と自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「聞いている」の主語は子どもたちで、眼差しは主語にならない。"}, {"text": "を", "is_correct": false, "explanation": "「話を」と重なり、目的語が二つになってしまう。"}, {"text": "に", "is_correct": false, "explanation": "「に」は向かう先や位置を示し、手段の意味にならない。"}], "correct_answer": "で", "explanations": {"で": "「眼差しで」の「で」。様子や手段を表し、「真剣な眼差しで話を聞く」と自然に続く。", "が": "「聞いている」の主語は子どもたちで、眼差しは主語にならない。", "を": "「話を」と重なり、目的語が二つになってしまう。", "に": "「に」は向かう先や位置を示し、手段の意味にならない。"}, "error_tags": {"が": "「聞いている」の主語は子どもたちで、眼差しは主語にならない", "を": "「話を」と重なり、目的語が二つになってしまう", "に": "「に」は向かう先や位置を示し、手段の意味にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52071, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52071, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が何かを見るときの、目のようす。", "primary_collocate": null, "pronunciation": "まなざし", "ipa": "manadzaɕi", "syllable_count": 4, "sentences": [{"text": "母は心配そうな眼差しで、私の顔を見つめた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "母[はは]は心配[しんぱい]そうな眼差[まなざ]しで、私[わたし]の顔[かお]を見[み]つめた。", "sentence_source": "generated"}, {"text": "子どもたちは、真剣な眼差しで先生の話を聞いている。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、真剣[しんけん]な眼差[まなざ]しで先生[せんせい]の話[はなし]を聞[き]いている。", "sentence_source": "generated"}, {"text": "彼女は優しい眼差しを赤ちゃんに向けた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は優[やさ]しい眼差[まなざ]しを赤[あか]ちゃんに向[む]けた。", "sentence_source": "generated"}, {"text": "試合前、選手の鋭い眼差しに、会場の空気が変わった。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "試合前[しあいまえ]、選手[せんしゅ]の鋭[するど]い眼差[まなざ]しに、会場[かいじょう]の空気[くうき]が変[か]わった。", "sentence_source": "generated"}, {"text": "老人は遠くの山を、なつかしそうな眼差しで見ていた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "老人[ろうじん]は遠[とお]くの山[やま]を、なつかしそうな眼差[まなざ]しで見[み]ていた。", "sentence_source": "generated"}, {"text": "冷たい眼差しで見られて、私は何も言えなくなった。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "冷[つめ]たい眼差[まなざ]しで見[み]られて、私[わたし]は何[なに]も言[い]えなくなった。", "sentence_source": "generated"}, {"text": "彼は憧れの眼差しで、舞台の上の歌手を見上げた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "彼[かれ]は憧[あこが]れの眼差[まなざ]しで、舞台[ぶたい]の上[うえ]の歌手[かしゅ]を見上[みあ]げた。", "sentence_source": "generated"}, {"text": "犬が期待に満ちた眼差しで、私の手のおやつを見ている。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "犬[いぬ]が期待[きたい]に満[み]ちた眼差[まなざ]しで、私[わたし]の手[て]のおやつを見[み]ている。", "sentence_source": "generated"}, {"text": "先生の温かい眼差しに励まされて、私は最後まで発表できた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "先生[せんせい]の温[あたた]かい眼差[まなざ]しに励[はげ]まされて、私[わたし]は最後[さいご]まで発表[はっぴょう]できた。", "sentence_source": "generated"}, {"text": "彼女のまっすぐな眼差しから、強い決意が伝わってきた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のまっすぐな眼差[まなざ]しから、強[つよ]い決意[けつい]が伝[つた]わってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眼差し", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かを見るときの目つきに表れる気持ちやようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52071, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼差し", "is_correct": true, "explanation": "正解。「心配そうな眼差しで見つめた」は、目つきに気持ちが表れる文脈と合う。"}, {"text": "寝顔", "is_correct": false, "explanation": "眠っている顔のことで、起きて見つめる場面には合わない。"}, {"text": "瞼", "is_correct": false, "explanation": "目を覆う皮膚で、「心配そうな瞼で見つめた」は空所に入らない。"}, {"text": "眉間", "is_correct": false, "explanation": "眉の間の部分で、見つめる様子を表す語としては空所に合わない。"}], "explanations": {"眼差し": "正解。「心配そうな眼差しで見つめた」は、目つきに気持ちが表れる文脈と合う。", "寝顔": "眠っている顔のことで、起きて見つめる場面には合わない。", "瞼": "目を覆う皮膚で、「心配そうな瞼で見つめた」は空所に入らない。", "眉間": "眉の間の部分で、見つめる様子を表す語としては空所に合わない。"}, "sentence_index": 0, "correct_answer": "眼差し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は眼差しが大きくて、ぱっちりした目をしている。", "explanation": "ここは〈目の形〉の意味。眼差しは見るときの目つきで、目の大きさや形は指さないので合わない。"}, {"text": "彼女の眼差しは大きくて、教室中に響いた。", "explanation": "ここは〈声〉の意味。眼差しは目つきで、音の大きさや響きは指さないので合わない。"}, {"text": "その花の眼差しは強くて、部屋中に広がった。", "explanation": "ここは〈匂い〉の意味。眼差しは見るときの目つきで、香りは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52071, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼差し", "is_correct": true, "explanation": "正解。「憧れの眼差しで見上げた」は、目つきに気持ちが表れる文脈と合う。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸音で、「憧れの寝息で見上げた」は空所に入らない。"}, {"text": "耳たぶ", "is_correct": false, "explanation": "耳の下の柔らかい部分で、見上げる様子を表す語としては合わない。"}, {"text": "足首", "is_correct": false, "explanation": "足の関節のことで、「憧れの足首で見上げた」は意味をなさない。"}], "explanations": {"眼差し": "正解。「憧れの眼差しで見上げた」は、目つきに気持ちが表れる文脈と合う。", "寝息": "眠っている人の呼吸音で、「憧れの寝息で見上げた」は空所に入らない。", "耳たぶ": "耳の下の柔らかい部分で、見上げる様子を表す語としては合わない。", "足首": "足の関節のことで、「憧れの足首で見上げた」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "眼差し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この頃、父の眼差しがめっきり落ちて、新聞の小さな字が読めなくなった。", "explanation": "ここは〈視力〉の意味。眼差しは見るときの目つきで、目の見える力は指さないので合わない。"}, {"text": "彼の眼差しがはっきり聞こえた。", "explanation": "ここは〈寝言〉の意味。寝言は耳で聞くものだが、眼差しは見る目つきで聞くことはできないので合わない。"}, {"text": "彼の眼差しが額を流れた。", "explanation": "ここは〈汗〉の意味。汗は体から流れ出るもので、目つきが流れることはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52071, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は穏やかな眼差しが、庭の花を眺めた。", "corrected_sentence": "父は穏やかな眼差しで、庭の花を眺めた。", "error_description": "「眼差しで」は様子や手段を表すので「で」が正しい。「が」だと眼差しが主語になり、「眺めた」の主語は父なので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52071, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、まっすぐの眼差しでライバルを見返した。", "corrected_sentence": "彼女は、まっすぐな眼差しでライバルを見返した。", "error_description": "「まっすぐ」は形容動詞なので名詞に続けるには「な」が必要。「の」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52075, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「手の中に収める」で、収める先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「手の中を収めて」になり、収める先が示せない。"}, {"text": "が", "is_correct": false, "explanation": "「手の中が収めて」になり、主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「手の中と収めて」は並列の意味になり、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「手の中に収める」で、収める先を示す。", "を": "「手の中を収めて」になり、収める先が示せない。", "が": "「手の中が収めて」になり、主語にならない。", "と": "「手の中と収めて」は並列の意味になり、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "が": "主語の誤り", "と": "並列の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52075, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「手の中に収める」で、収める先を示す。"}, {"text": "で", "is_correct": false, "explanation": "「手の中で収めると」は手段や場所の意味になり、収める先を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「手の中から収めると」は出所の意味になり、収める先と逆になる。"}, {"text": "の", "is_correct": false, "explanation": "「手の中の収めると」は名詞を修飾できず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「手の中に収める」で、収める先を示す。", "で": "「手の中で収めると」は手段や場所の意味になり、収める先を示せない。", "から": "「手の中から収めると」は出所の意味になり、収める先と逆になる。", "の": "「手の中の収めると」は名詞を修飾できず、文が成り立たない。"}, "error_tags": {"で": "手段の誤り", "から": "出所の誤り", "の": "修飾の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52075, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手の中に入れること。", "primary_collocate": "手中", "pronunciation": "おさめる", "ipa": "osameɾɯ", "syllable_count": 4, "sentences": [{"text": "彼はついに長年探していた名画を手中に収めた。", "target_word": "収めた", "complexity_tier": "T3", "furigana": "彼[かれ]はついに長年[ながねん]探[さが]していた名画[めいが]を手中[しゅちゅう]に収[おさ]めた。", "sentence_source": "generated"}, {"text": "彼女は指輪を手の中に収めて、そっと隠した。", "target_word": "収めて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は指輪[ゆびわ]を手[て]の中[なか]に収[おさ]めて、そっと隠[かく]した。", "sentence_source": "generated"}, {"text": "少女は貝殻を手の中に収めて、耳に当てた。", "target_word": "収めて", "complexity_tier": "T3", "furigana": "少女[しょうじょ]は貝殻[かいがら]を手[て]の中[なか]に収[おさ]めて、耳[みみ]に当[あ]てた。", "sentence_source": "generated"}, {"text": "卵を手の中に収めるには、指を少し曲げてそっと持つとよい。", "target_word": "収める", "complexity_tier": "T3", "furigana": "卵[たまご]を手[て]の中[なか]に収[おさ]めるには、指[ゆび]を少[すこ]し曲[ま]げてそっと持[も]つとよい。", "sentence_source": "generated"}, {"text": "おにぎりを手の中に収めて、形をととのえた。", "target_word": "収めて", "complexity_tier": "T3", "furigana": "おにぎりを手[て]の中[なか]に収[おさ]めて、形[かたち]をととのえた。", "sentence_source": "generated"}, {"text": "子猫を手の中に収めると、冷たい鼻先が指に触れた。", "target_word": "収めると", "complexity_tier": "T3", "furigana": "子猫[こねこ]を手[て]の中[なか]に収[おさ]めると、冷[つめ]たい鼻先[はなさき]が指[ゆび]に触[ふ]れた。", "sentence_source": "generated"}, {"text": "祖母は小さな飴を手の中に収めて、孫に渡した。", "target_word": "収めて", "complexity_tier": "T3", "furigana": "祖母[そぼ]は小[ちい]さな飴[あめ]を手[て]の中[なか]に収[おさ]めて、孫[まご]に渡[わた]した。", "sentence_source": "generated"}, {"text": "小さな鳥を手の中に収めると、少年はそっと歩き出した。", "target_word": "収める", "complexity_tier": "T3", "furigana": "小[ちい]さな鳥[とり]を手[て]の中[なか]に収[おさ]めると、少年[しょうねん]はそっと歩[ある]き出[だ]した。", "sentence_source": "generated"}, {"text": "コインを手の中に収めて、ポケットに入れた。", "target_word": "収めて", "complexity_tier": "T3", "furigana": "コインを手[て]の中[なか]に収[おさ]めて、ポケットに入[い]れた。", "sentence_source": "generated"}, {"text": "鳥の雛を手の中に収めると、とても温かく感じた。", "target_word": "収めると", "complexity_tier": "T3", "furigana": "鳥[とり]の雛[ひな]を手[て]の中[なか]に収[おさ]めると、とても温[あたた]かく感[かん]じた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "収める", "label": "終止形"}, {"form": "収め", "label": "連用形"}, {"form": "収めた", "label": "過去形"}, {"form": "収めて", "label": "て形"}, {"form": "収めれば", "label": "仮定形"}, {"form": "収めよう", "label": "意志形"}, {"form": "収めない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "自分の手の中・支配の中に入れて、自分のものにする", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52075, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "収めた", "is_correct": true, "explanation": "過去形。「手中に収めた」で、名画を自分のものにした結果を表し、文に合う。"}, {"text": "収めて", "is_correct": false, "explanation": "て形は文末で止まれず、「収めて。」では文が完結しない。"}, {"text": "収めれば", "is_correct": false, "explanation": "仮定形は文末に立てず、「収めれば。」では文が成り立たない。"}, {"text": "収めよう", "is_correct": false, "explanation": "意志形は「ついに」と合わず、主語「彼は」の文として意味が通らない。"}], "explanations": {"収めた": "過去形。「手中に収めた」で、名画を自分のものにした結果を表し、文に合う。", "収めて": "て形は文末で止まれず、「収めて。」では文が完結しない。", "収めれば": "仮定形は文末に立てず、「収めれば。」では文が成り立たない。", "収めよう": "意志形は「ついに」と合わず、主語「彼は」の文として意味が通らない。"}, "sentence_index": 0, "correct_answer": "収めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "指に包帯を収めた。", "explanation": "ここは〈巻く〉の意味。収めるは中に入れることなので、包帯を巻き付ける場合には使わない。"}, {"text": "テーブルの上に皿を収めて、料理を並べた。", "explanation": "ここは〈上に載せる〉の意味。収めるは中に入れることなので、上に載せる場合には使わない。"}, {"text": "ランプを天井に収めて、部屋を明るくした。", "explanation": "ここは〈天井に吊るす〉の意味。収めるは中に入れることなので、吊るす場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52075, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "収めて", "is_correct": true, "explanation": "て形。「収めて、孫に渡した」で、手に収めた後に渡すという動作の流れを作る。文に合う。"}, {"text": "収めろ", "is_correct": false, "explanation": "命令形は文の過去の動作と合わず、命令になってしまう。"}, {"text": "収めない", "is_correct": false, "explanation": "否定形は「収めない、孫に渡した」と続かず、飴を手に収めた動作と逆になる。"}, {"text": "収めている", "is_correct": false, "explanation": "ている形は「収めている、」で文が止まらず、「孫に渡した」とつながらない。"}], "explanations": {"収めて": "て形。「収めて、孫に渡した」で、手に収めた後に渡すという動作の流れを作る。文に合う。", "収めろ": "命令形は文の過去の動作と合わず、命令になってしまう。", "収めない": "否定形は「収めない、孫に渡した」と続かず、飴を手に収めた動作と逆になる。", "収めている": "ている形は「収めている、」で文が止まらず、「孫に渡した」とつながらない。"}, "sentence_index": 6, "correct_answer": "収めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上着にボタンを収めた。", "explanation": "ここは〈縫い付ける〉の意味。収めるは中に入れることなので、ボタンを縫い付ける場合には使わない。"}, {"text": "財布を床に収めて、足で踏んだ。", "explanation": "ここは〈床に落とす〉の意味。収めるは中に入れることなので、床に落ちた状態には使わない。"}, {"text": "張り紙を玄関のドアに収めた。", "explanation": "ここは〈貼る〉の意味。収めるは中に入れることなので、ドアに貼る場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52075, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は鍵を手の中収めて、そっと隠した。", "corrected_sentence": "彼は鍵を手の中に収めて、そっと隠した。", "error_description": "誤りは助詞の欠落。収める先を示す「に」が抜けている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "収めて", "is_correct": true, "explanation": "て形。「収めて、そっと隠した」で、動作を続けて次の動作につなぐ形。文に合う。"}, {"text": "収めよう", "is_correct": false, "explanation": "意志形は「収めよう、」で文が続かず、「隠した」とつながらない。"}, {"text": "収めろ", "is_correct": false, "explanation": "命令形は「収めろ、」で文が続かず、「隠した」とつながらない。"}, {"text": "収めれば", "is_correct": false, "explanation": "仮定形は「収めれば、そっと隠した」と続かず、文の流れが不自然になる。"}], "correct_form": "収めて", "base_form": "収める", "form_label": "て形", "sentence_index": 1, "explanations": {"収めて": "て形。「収めて、そっと隠した」で、動作を続けて次の動作につなぐ形。文に合う。", "収めよう": "意志形は「収めよう、」で文が続かず、「隠した」とつながらない。", "収めろ": "命令形は「収めろ、」で文が続かず、「隠した」とつながらない。", "収めれば": "仮定形は「収めれば、そっと隠した」と続かず、文の流れが不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52075, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小石を手の中を収めて、ポケットに入れた。", "corrected_sentence": "小石を手の中に収めて、ポケットに入れた。", "error_description": "誤りは「を」。「手の中」は収める先なので「に」で示す。「を」では目的語になってしまい、収める先を表せない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "収める", "is_correct": true, "explanation": "終止形。「収めると」で条件を表し、「と」の前に置く形として文に合う。"}, {"text": "収めろ", "is_correct": false, "explanation": "命令形は「と」と続かず、命令の意味になってしまう。"}, {"text": "収めて", "is_correct": false, "explanation": "て形は「と」の前に置けず、「収めてと」では文が成り立たない。"}, {"text": "収め", "is_correct": false, "explanation": "連用形は「と」の前に置けず、「収めと」では文が成り立たない。"}], "correct_form": "収める", "base_form": "収める", "form_label": "終止形", "sentence_index": 7, "explanations": {"収める": "終止形。「収めると」で条件を表し、「と」の前に置く形として文に合う。", "収めろ": "命令形は「と」と続かず、命令の意味になってしまう。", "収めて": "て形は「と」の前に置けず、「収めてと」では文が成り立たない。", "収め": "連用形は「と」の前に置けず、「収めと」では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52076, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に収める」で、収める先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ポケットを収めた」になり、収める先が示せない。"}, {"text": "と", "is_correct": false, "explanation": "「ポケットと収めた」は並列の意味になり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語は「彼は」で既に示されており、「が」を置くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「〜に収める」で、収める先を示す。", "を": "「ポケットを収めた」になり、収める先が示せない。", "と": "「ポケットと収めた」は並列の意味になり、文が成り立たない。", "が": "主語は「彼は」で既に示されており、「が」を置くと文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "と": "並列の誤り", "が": "主語の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52076, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に収める」で、収める先を示す。"}, {"text": "で", "is_correct": false, "explanation": "「鞘で収める」は手段の意味になり、収める先を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「鞘から収める」は出所の意味になり、収める先と逆になる。"}, {"text": "の", "is_correct": false, "explanation": "「鞘の収めると」は名詞を修飾できず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「〜に収める」で、収める先を示す。", "で": "「鞘で収める」は手段の意味になり、収める先を示せない。", "から": "「鞘から収める」は出所の意味になり、収める先と逆になる。", "の": "「鞘の収めると」は名詞を修飾できず、文が成り立たない。"}, "error_tags": {"で": "手段の誤り", "から": "出所の誤り", "の": "修飾の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52076, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物をある場所の中に入れて、そこに置いたりしまったりすること。", "primary_collocate": null, "pronunciation": "おさめる", "ipa": "osameɾɯ", "syllable_count": 4, "sentences": [{"text": "箱に収められた古い手紙を見つけた。", "target_word": "収められた", "complexity_tier": "T3", "furigana": "箱[はこ]に収[おさ]められた古[ふる]い手紙[てがみ]を見[み]つけた。", "sentence_source": "generated"}, {"text": "彼は財布を上着のポケットに収めた。", "target_word": "収めた", "complexity_tier": "T2", "furigana": "彼[かれ]は財布[さいふ]を上着[うわぎ]のポケットに収[おさ]めた。", "sentence_source": "generated"}, {"text": "本をすべて箱に収めて、押し入れにしまった。", "target_word": "収めて", "complexity_tier": "T3", "furigana": "本[ほん]をすべて箱[はこ]に収[おさ]めて、押[お]し入[い]れにしまった。", "sentence_source": "generated"}, {"text": "この棚には辞書が全部収められるので、机の上がすっきりする。", "target_word": "収められる", "complexity_tier": "T3", "furigana": "この棚[たな]には辞書[じしょ]が全部[ぜんぶ]収[おさ]められるので、机[つくえ]の上[うえ]がすっきりする。", "sentence_source": "generated"}, {"text": "引っ越しの荷物は小さなトラックに収めることができた。", "target_word": "収める", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの荷物[にもつ]は小[ちい]さなトラックに収[おさ]めることができた。", "sentence_source": "generated"}, {"text": "カメラをかばんに収めてから、電車に乗った。", "target_word": "収めて", "complexity_tier": "T2", "furigana": "カメラをかばんに収[おさ]めてから、電車[でんしゃ]に乗[の]った。", "sentence_source": "generated"}, {"text": "使わない道具は、きちんと引き出しに収めておこう。", "target_word": "収めて", "complexity_tier": "T3", "furigana": "使[つか]わない道具[どうぐ]は、きちんと引[ひ]き出[だ]しに収[おさ]めておこう。", "sentence_source": "generated"}, {"text": "刀を鞘に収めると、武士は静かに頭を下げた。", "target_word": "収める", "complexity_tier": "T3", "furigana": "刀[かたな]を鞘[さや]に収[おさ]めると、武士[ぶし]は静[しず]かに頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "部屋が狭いので、服を全部クローゼットに収めるのは難しい。", "target_word": "収める", "complexity_tier": "T3", "furigana": "部屋[へや]が狭[せま]いので、服[ふく]を全部[ぜんぶ]クローゼットに収[おさ]めるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "重くなるので、本は一つの箱に収めないでください。", "target_word": "収めない", "complexity_tier": "T3", "furigana": "重[おも]くなるので、本[ほん]は一[ひと]つの箱[はこ]に収[おさ]めないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "収める", "label": "終止形"}, {"form": "収め", "label": "連用形"}, {"form": "収めた", "label": "過去形"}, {"form": "収めて", "label": "て形"}, {"form": "収めない", "label": "否定形"}, {"form": "収められる", "label": "可能形・受身形"}], "register": "neutral", "sense_fingerprint": "物を箱・かばん・棚などの決まった場所の中に入れてしまう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52076, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "収められた", "is_correct": true, "explanation": "「掌に収められた一つの赤い果物」と名詞を修飾する受身の過去形。文の流れに合う。"}, {"text": "収めて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「収めて古い手紙」と続かない。"}, {"text": "収めれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「収めれば古い手紙」と続かない。"}, {"text": "収めよう", "is_correct": false, "explanation": "意志形は後ろの「古い手紙」を修飾できず、文の意味が通らない。"}], "explanations": {"収められた": "「掌に収められた一つの赤い果物」と名詞を修飾する受身の過去形。文の流れに合う。", "収めて": "て形は名詞を修飾できず、「収めて古い手紙」と続かない。", "収めれば": "仮定形は名詞を修飾できず、「収めれば古い手紙」と続かない。", "収めよう": "意志形は後ろの「古い手紙」を修飾できず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "収められた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓枠を白く収めた。", "explanation": "ここは〈塗る〉の意味。収めるは中に入れることなので、色を塗る場合には使わない。"}, {"text": "もめごとを穏便に収めた。", "explanation": "ここは〈解決する〉の意味。収めるは物を中に入れることなので、もめごとを治める場合には使わない。"}, {"text": "ポスターを壁に収めて、部屋を明るくした。", "explanation": "ここは〈壁に貼る〉の意味。収めるは中に入れることなので、壁に貼る場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52076, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "収めて", "is_correct": true, "explanation": "て形＋「おこう」で「しまっておこう」の意味になり、文に合う。"}, {"text": "収めた", "is_correct": false, "explanation": "過去形は「おこう」と続かず、「収めたおこう」は成り立たない。"}, {"text": "収めない", "is_correct": false, "explanation": "否定形は「おこう」と続かず、文が成り立たない。"}, {"text": "収められる", "is_correct": false, "explanation": "可能・受身形は「おこう」と続かず、文に合わない。"}], "explanations": {"収めて": "て形＋「おこう」で「しまっておこう」の意味になり、文に合う。", "収めた": "過去形は「おこう」と続かず、「収めたおこう」は成り立たない。", "収めない": "否定形は「おこう」と続かず、文が成り立たない。", "収められる": "可能・受身形は「おこう」と続かず、文に合わない。"}, "sentence_index": 6, "correct_answer": "収めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エレベーターの階数ボタンを指で収めた。", "explanation": "ここは〈押す〉の意味。収めるは中に入れることなので、ボタンを押す場合には使わない。"}, {"text": "コートをフックに収めて、玄関を出た。", "explanation": "ここは〈掛ける〉の意味。収めるは中に入れることなので、フックに掛ける場合には使わない。"}, {"text": "騒ぎを穏便に収めた。", "explanation": "ここは〈鎮める〉の意味。収めるは物を中に入れることなので、騒ぎを鎮める場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52076, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カードを財布の中収めた。", "corrected_sentence": "カードを財布の中に収めた。", "error_description": "誤りは助詞の欠落。収める先を示す「に」が抜けている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "収めた", "is_correct": true, "explanation": "過去形。財布を入れる動作が完了したことを表し、文に合う。"}, {"text": "収めて", "is_correct": false, "explanation": "て形は文末で止まれず、「収めて。」では述語として終わらない。"}, {"text": "収めれば", "is_correct": false, "explanation": "仮定形は文末に立てず、「収めれば。」では文が成り立たない。"}, {"text": "収め", "is_correct": false, "explanation": "連用形は文末に立てず、「収め。」では文が途中で切れてしまう。"}], "correct_form": "収めた", "base_form": "収める", "form_label": "過去形", "sentence_index": 1, "explanations": {"収めた": "過去形。財布を入れる動作が完了したことを表し、文に合う。", "収めて": "て形は文末で止まれず、「収めて。」では述語として終わらない。", "収めれば": "仮定形は文末に立てず、「収めれば。」では文が成り立たない。", "収め": "連用形は文末に立てず、「収め。」では文が途中で切れてしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52076, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍵を引き出し収めてから、部屋を出た。", "corrected_sentence": "鍵を引き出しに収めてから、部屋を出た。", "error_description": "誤りは助詞の欠落。収める先を示す「に」が抜けている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "収める", "is_correct": true, "explanation": "終止形。「と」の前に置き、「収めると」で条件を表す。文に合う。"}, {"text": "収めたり", "is_correct": false, "explanation": "並列の「たり」形は「と」と続かず、「収めたりと」では文が成り立たない。"}, {"text": "収めなく", "is_correct": false, "explanation": "中止形の否定は「と」の前に置けず、「収めなくと」では文が成り立たない。"}, {"text": "収めろ", "is_correct": false, "explanation": "命令形は「と」と続かず、命令の意味になってしまう。"}], "correct_form": "収める", "base_form": "収める", "form_label": "終止形", "sentence_index": 7, "explanations": {"収める": "終止形。「と」の前に置き、「収めると」で条件を表す。文に合う。", "収めたり": "並列の「たり」形は「と」と続かず、「収めたりと」では文が成り立たない。", "収めなく": "中止形の否定は「と」の前に置けず、「収めなくと」では文が成り立たない。", "収めろ": "命令形は「と」と続かず、命令の意味になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
