INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52077, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "濃くて深みのある赤い色のこと。", "primary_collocate": null, "pronunciation": "しんく", "ipa": "ɕiŋkɯ", "syllable_count": 3, "sentences": [{"text": "彼女は深紅のドレスを着てパーティーに行った。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は深紅[しんく]のドレスを着[き]てパーティーに行[い]った。", "sentence_source": "generated"}, {"text": "夕日が空を深紅に染めた。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "夕日[ゆうひ]が空[そら]を深紅[しんく]に染[そ]めた。", "sentence_source": "generated"}, {"text": "深紅のバラを一本、花瓶にさした。", "target_word": "深紅", "complexity_tier": "T2", "furigana": "深紅[しんく]のバラを一本[いっぽん]、花瓶[かびん]にさした。", "sentence_source": "generated"}, {"text": "秋になると、山の木々が深紅に色づく。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "秋[あき]になると、山[やま]の木々[きぎ]が深紅[しんく]に色[いろ]づく。", "sentence_source": "generated"}, {"text": "舞台の幕は深紅で、とても華やかだった。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の幕[まく]は深紅[しんく]で、とても華[はな]やかだった。", "sentence_source": "generated"}, {"text": "深紅の旗が風にゆれている。", "target_word": "深紅", "complexity_tier": "T2", "furigana": "深紅[しんく]の旗[はた]が風[かぜ]にゆれている。", "sentence_source": "generated"}, {"text": "深紅のカーペットの上を、主役がゆっくり歩いた。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "深紅[しんく]のカーペットの上[うえ]を、主役[しゅやく]がゆっくり歩[ある]いた。", "sentence_source": "generated"}, {"text": "深紅のワインをグラスに注いだ。", "target_word": "深紅", "complexity_tier": "T2", "furigana": "深紅[しんく]のワインをグラスに注[そそ]いだ。", "sentence_source": "generated"}, {"text": "優勝のしるしとして、深紅の優勝旗が渡された。", "target_word": "深紅", "complexity_tier": "T4", "furigana": "優勝[ゆうしょう]のしるしとして、深紅[しんく]の優勝旗[ゆうしょうき]が渡[わた]された。", "sentence_source": "generated"}, {"text": "窓のカーテンを深紅のものに取りかえた。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "窓[まど]のカーテンを深紅[しんく]のものに取[と]りかえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深紅", "label": "基本形"}, {"form": "深紅の", "label": "連体形(の)"}, {"form": "深紅に", "label": "連用形(に)"}], "register": "標準", "sense_fingerprint": "名詞。濃くて深みのある赤い色。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52077, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深紅", "is_correct": true, "explanation": "ドレスの色を表す名詞で、空所に入ると意味が通る。"}, {"text": "霧", "is_correct": false, "explanation": "「霧のドレス」は色の名として成り立たず、空所に合わない。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "時間帯を表す語で、ドレスの色には使えない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品の名詞で、ドレスを修飾する色の語にはならない。"}], "explanations": {"深紅": "ドレスの色を表す名詞で、空所に入ると意味が通る。", "霧": "「霧のドレス」は色の名として成り立たず、空所に合わない。", "夕暮れ": "時間帯を表す語で、ドレスの色には使えない。", "砂糖": "食品の名詞で、ドレスを修飾する色の語にはならない。"}, "sentence_index": 0, "correct_answer": "深紅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は深紅の眠りに落ちて、朝まで目が覚めなかった。", "explanation": "ここは〈深い〉の意味。深紅は色の名前で、眠りの深さは表せない。"}, {"text": "この古い酒は深紅の味がして、なめらかだ。", "explanation": "ここは〈深み〉の意味。深紅は色を表す語で、味の深みには使えない。"}, {"text": "彼女は深紅の性格で、誰とでもすぐ打ち解ける。", "explanation": "ここは〈明るい〉の意味。深紅は色の名前で、人の性格には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52077, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深紅", "is_correct": true, "explanation": "カーペットの色を表す名詞で、空所に入ると意味が通る。"}, {"text": "鉛筆", "is_correct": false, "explanation": "筆記用具の名詞で、カーペットの色には使えない。"}, {"text": "氷", "is_correct": false, "explanation": "「氷のカーペット」は色の表現にならず、空所に合わない。"}, {"text": "雷", "is_correct": false, "explanation": "自然現象の名詞で、カーペットを修飾する語にはならない。"}], "explanations": {"深紅": "カーペットの色を表す名詞で、空所に入ると意味が通る。", "鉛筆": "筆記用具の名詞で、カーペットの色には使えない。", "氷": "「氷のカーペット」は色の表現にならず、空所に合わない。", "雷": "自然現象の名詞で、カーペットを修飾する語にはならない。"}, "sentence_index": 6, "correct_answer": "深紅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事態は深紅に悪化して、もう手がつけられない。", "explanation": "ここは〈深刻〉の意味。深紅は色の名前で、事態の重大さは表せない。"}, {"text": "彼は深紅の努力で、ついに試験に合格した。", "explanation": "ここは〈大きな〉の意味。深紅は色の名前で、努力の大きさは表せない。"}, {"text": "このバッグは深紅の値段で、学生には買えない。", "explanation": "ここは〈高い〉の意味。深紅は色の名前で、値段の高さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52077, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今朝の空は深紅で染まっていた。", "corrected_sentence": "今朝の空は深紅に染まっていた。", "error_description": "「染まる」は「に」を取る。「深紅で」の「で」は手段を表すので誤り。正しくは「深紅に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52077, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舞台の幕が深紅を染まっていた。", "corrected_sentence": "舞台の幕が深紅に染まっていた。", "error_description": "「染まる」は「に」を取る。「深紅を」の「を」は目的語を表すので誤り。正しくは「深紅に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52079, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「演技に凝縮された」で、凝縮される先（対象）を示す。受身文の「〜に〜される」の形。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示す。ここは受身文なので「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。凝縮される対象は方向ではないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用の相手を示す。凝縮の対象を示す位置には当たらない。"}], "correct_answer": "に", "explanations": {"に": "「演技に凝縮された」で、凝縮される先（対象）を示す。受身文の「〜に〜される」の形。", "を": "「を」は他動詞の目的語を示す。ここは受身文なので「を」は使えない。", "へ": "「へ」は方向を示す。凝縮される対象は方向ではないので合わない。", "と": "「と」は並列や引用の相手を示す。凝縮の対象を示す位置には当たらない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
