INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52079, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ぎゅっと小さくなって、中に大事なものがつまっていること。", "primary_collocate": null, "pronunciation": "ぎょうしゅく", "ipa": "ɡʲoːɕɯkɯ", "syllable_count": 4, "sentences": [{"text": "この一冊には著者の長年の研究が凝縮されている。", "target_word": "凝縮", "complexity_tier": "T4", "furigana": "この一冊[いっさつ]には著者[ちょしゃ]の長年[ながねん]の研究[けんきゅう]が凝縮[ぎょうしゅく]されている。", "sentence_source": "generated"}, {"text": "一年間の努力が、この五分の演技に凝縮された。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "一年間[いちねんかん]の努力[どりょく]が、この五分[ごふん]の演技[えんぎ]に凝縮[ぎょうしゅく]された。", "sentence_source": "generated"}, {"text": "旨みが凝縮したトマトソースを作った。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "旨[うま]みが凝縮[ぎょうしゅく]したトマトソースを作[つく]った。", "sentence_source": "generated"}, {"text": "彼の人生は、この短い詩に凝縮されている。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "彼[かれ]の人生[じんせい]は、この短[みじか]い詩[し]に凝縮[ぎょうしゅく]されている。", "sentence_source": "generated"}, {"text": "長い会議の内容を一枚の資料に凝縮した。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "長[なが]い会議[かいぎ]の内容[ないよう]を一枚[いちまい]の資料[しりょう]に凝縮[ぎょうしゅく]した。", "sentence_source": "generated"}, {"text": "この小説には、作者が生きた時代の空気が凝縮されている。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]には、作者[さくしゃ]が生[い]きた時代[じだい]の空気[くうき]が凝縮[ぎょうしゅく]されている。", "sentence_source": "generated"}, {"text": "町の魅力が凝縮された一日の散歩コースだ。", "target_word": "凝縮", "complexity_tier": "T4", "furigana": "町[まち]の魅力[みりょく]が凝縮[ぎょうしゅく]された一日[いちにち]の散歩[さんぽ]コースだ。", "sentence_source": "generated"}, {"text": "凝縮された文章なので、何度も読み返す必要がある。", "target_word": "凝縮", "complexity_tier": "T4", "furigana": "凝縮[ぎょうしゅく]された文章[ぶんしょう]なので、何度[なんど]も読[よ]み返[かえ]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "この映画は、家族の愛が二時間に凝縮された作品だ。", "target_word": "凝縮", "complexity_tier": "T4", "furigana": "この映画[えいが]は、家族[かぞく]の愛[あい]が二時間[にじかん]に凝縮[ぎょうしゅく]された作品[さくひん]だ。", "sentence_source": "generated"}, {"text": "素材の味が凝縮した干しぶどうは、とても甘い。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "素材[そざい]の味[あじ]が凝縮[ぎょうしゅく]した干[ほ]しぶどうは、とても甘[あま]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝縮", "label": "基本形"}, {"form": "凝縮する", "label": "サ変動詞"}, {"form": "凝縮した", "label": "連体形・過去"}, {"form": "凝縮される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "名詞(サ変)。大事な内容や持ち味が、小さな形の中にぎゅっとつまっていること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52079, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凝縮", "is_correct": true, "explanation": "中の大事な内容がぎゅっと詰まっている意味。研究の内容を表すこの文に当てはまる。"}, {"text": "購入", "is_correct": false, "explanation": "「購入」は物を買うことで、研究という内容には使えない。"}, {"text": "解雇", "is_correct": false, "explanation": "「解雇」は雇用を打ち切ることで、研究の対象とは合わない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、研究には当てはまらない。"}], "explanations": {"凝縮": "中の大事な内容がぎゅっと詰まっている意味。研究の内容を表すこの文に当てはまる。", "購入": "「購入」は物を買うことで、研究という内容には使えない。", "解雇": "「解雇」は雇用を打ち切ることで、研究の対象とは合わない。", "点火": "「点火」は火をつけることで、研究には当てはまらない。"}, "sentence_index": 0, "correct_answer": "凝縮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一晩中パソコンに向かっていたので、肩が凝縮した。", "explanation": "ここは〈凝る〉（筋肉がこわばる）の意味。凝縮は内容がぎゅっと詰まる意味で、肩のこりには使えない。"}, {"text": "彼は試験勉強に凝縮した。", "explanation": "ここは〈集中〉（注意を一点に向ける）の意味。凝縮は内容が小さくまとまることで、人が注意を向ける動作とは合わない。"}, {"text": "洗濯したら、セーターが凝縮した。", "explanation": "ここは〈縮む〉（大きさが小さくなる）の意味。凝縮は中身が濃く詰まることで、布の大きさが小さくなる現象には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52079, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凝縮", "is_correct": true, "explanation": "中身が濃く詰まっている意味。町の魅力が詰まった散歩コースという文に当てはまる。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去」は設置物を取り除くことで、町の魅力の文脈には合わない。"}, {"text": "追放", "is_correct": false, "explanation": "「追放」は人や物を追い出すことで、魅力を表す語とは合わない。"}, {"text": "換金", "is_correct": false, "explanation": "「換金」は物を現金に換えることで、町の魅力には当てはまらない。"}], "explanations": {"凝縮": "中身が濃く詰まっている意味。町の魅力が詰まった散歩コースという文に当てはまる。", "撤去": "「撤去」は設置物を取り除くことで、町の魅力の文脈には合わない。", "追放": "「追放」は人や物を追い出すことで、魅力を表す語とは合わない。", "換金": "「換金」は物を現金に換えることで、町の魅力には当てはまらない。"}, "sentence_index": 6, "correct_answer": "凝縮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お湯が冷えて、ゼリーが凝縮した。", "explanation": "ここは〈凝固〉（液体が固まる）の意味。凝縮は中身が小さく詰まる意味で、固まる変化は表さない。"}, {"text": "彼女は黒板の文字を凝縮していた。", "explanation": "ここは〈凝視〉（じっと見つめる）の意味。凝縮は内容を小さくまとめる意味で、目で見つめる動作には使えない。"}, {"text": "走り込みで体が凝縮した。", "explanation": "ここは〈引き締まる〉（体つきがしまる）の意味。凝縮は中身が詰まることで、体つきを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52079, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この一枚の写真には、新人の一年間の苦労が凝縮れている。", "corrected_sentence": "この一枚の写真には、新人の一年間の苦労が凝縮されている。", "error_description": "「凝縮れる」という形はない。サ変動詞「凝縮する」の受身は「凝縮される」なので、「凝縮されている」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52079, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの熱気が凝縮になった一晩だった。", "corrected_sentence": "祭りの熱気が凝縮された一晩だった。", "error_description": "「凝縮になった」は誤り。「凝縮」は「凝縮された」の形で受身として使い、「〜になった」とは続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52081, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「厚いコート」を「纏った」の目的語として示す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「纏う」は主語ではなく目的語を取るため誤り。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示すが、「厚いコートに纏った」では纏う対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「厚いコートで纏った」は目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「厚いコート」を「纏った」の目的語として示す。", "が": "主格を示すが、「纏う」は主語ではなく目的語を取るため誤り。", "に": "位置や相手を示すが、「厚いコートに纏った」では纏う対象を示せない。", "で": "手段や場所を示すが、「厚いコートで纏った」は目的語を示せない。"}, "error_tags": {"が": "主格", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52081, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「毛布」を「纏って」の目的語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「毛布へ纏って」では纏う対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示すが、「毛布と纏って」は目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「毛布より纏って」では意味が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「毛布」を「纏って」の目的語として示す。", "へ": "方向を示すが、「毛布へ纏って」では纏う対象を示せない。", "と": "並列や共同を示すが、「毛布と纏って」は目的語にならない。", "より": "比較を示すが、「毛布より纏って」では意味が成り立たない。"}, "error_tags": {"へ": "方向", "と": "並列・共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52081, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "からだに何かをまとうこと。", "primary_collocate": null, "pronunciation": "まとう", "ipa": "matoɯ", "syllable_count": 3, "sentences": [{"text": "彼女は白いドレスを纏って舞台に立った。", "target_word": "纏って", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は白[しろ]いドレスを纏[まと]って舞台[ぶたい]に立[た]った。", "sentence_source": "generated"}, {"text": "寒い朝、彼は厚いコートを纏った姿で家を出た。", "target_word": "纏った", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]、彼[かれ]は厚[あつ]いコートを纏[まと]った姿[すがた]で家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "巫女は赤い衣を纏って、静かに舞った。", "target_word": "纏って", "complexity_tier": "T4", "furigana": "巫女[みこ]は赤[あか]い衣[ころも]を纏[まと]って、静[しず]かに舞[ま]った。", "sentence_source": "generated"}, {"text": "彼は王にふさわしい、立派なマントを纏っていた。", "target_word": "纏って", "complexity_tier": "T4", "furigana": "彼[かれ]は王[おう]にふさわしい、立派[りっぱ]なマントを纏[まと]っていた。", "sentence_source": "generated"}, {"text": "香水を纏う女性が、すれ違いざまに振り向いた。", "target_word": "纏う", "complexity_tier": "T4", "furigana": "香水[こうすい]を纏[まと]う女性[じょせい]が、すれ違[ちが]いざまに振[ふ]り向[む]いた。", "sentence_source": "generated"}, {"text": "騎士は銀色の鎧を纏い、城門の前に立った。", "target_word": "纏い", "complexity_tier": "T3", "furigana": "騎[き]士[し]は銀[ぎん]色[いろ]の鎧[よろい]を纏[まと]い、城[じょう]門[もん]の前[まえ]に立[た]った。", "sentence_source": "generated"}, {"text": "踊り子は鮮やかな布を纏い、軽やかに回った。", "target_word": "纏い", "complexity_tier": "T4", "furigana": "踊[おど]り子[こ]は鮮[あざ]やかな布[ぬの]を纏[まと]い、軽[かろ]やかに回[まわ]った。", "sentence_source": "generated"}, {"text": "冬の夜は、毛布を纏って本を読むのが好きだ。", "target_word": "纏って", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜[よる]は、毛布[もうふ]を纏[まと]って本[ほん]を読[よ]むのが好[す]きだ。", "sentence_source": "generated"}, {"text": "僧は黒い法衣を纏って、庭を掃いていた。", "target_word": "纏って", "complexity_tier": "T4", "furigana": "僧[そう]は黒[くろ]い法衣[ほうえ]を纏[まと]って、庭[にわ]を掃[は]いていた。", "sentence_source": "generated"}, {"text": "彼女は着物を纏うと、姿勢まで美しくなる。", "target_word": "纏う", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は着物[きもの]を纏[まと]うと、姿勢[しせい]まで美[うつく]しくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "纏う", "label": "終止形"}, {"form": "纏わない", "label": "否定形"}, {"form": "纏い", "label": "連用形"}, {"form": "纏って", "label": "て形"}, {"form": "纏った", "label": "過去形"}, {"form": "纏えば", "label": "仮定形"}, {"form": "纏おう", "label": "意志形"}], "register": "やや改まった書き言葉寄り", "sense_fingerprint": "動詞(五段)。衣服や布などを体にゆったり身につける。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52081, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纏って", "is_correct": true, "explanation": "「白いドレスを〜舞台に立った」に入る、衣服を身につける動詞のて形。"}, {"text": "光って", "is_correct": false, "explanation": "自動詞で、「ドレスを」を目的語に取れず空所に合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "自動詞で、「ドレスを」に続かず文が成り立たない。"}, {"text": "落ちて", "is_correct": false, "explanation": "自動詞で、「ドレスを」を目的語に取れず空所に合わない。"}], "explanations": {"纏って": "「白いドレスを〜舞台に立った」に入る、衣服を身につける動詞のて形。", "光って": "自動詞で、「ドレスを」を目的語に取れず空所に合わない。", "眠って": "自動詞で、「ドレスを」に続かず文が成り立たない。", "落ちて": "自動詞で、「ドレスを」を目的語に取れず空所に合わない。"}, "sentence_index": 0, "correct_answer": "纏って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は重いリュックを纏って山道を登った。", "explanation": "ここは〈背負う〉の意味。纏うは衣服や香りなど体を包むものに使い、荷物には使わない。"}, {"text": "彼女は子犬を纏って、やさしくなでていた。", "explanation": "ここは〈抱く〉の意味。纏うは体にまとうものに使い、生き物を腕に抱く意味はない。"}, {"text": "祖母はお茶を纏って、客の前に置いた。", "explanation": "ここは〈注ぐ〉の意味。纏うは液体を器に入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52081, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纏い", "is_correct": true, "explanation": "「布を纏い、軽やかに回った」の連用形。衣装を身につける意味で文が通る。"}, {"text": "咲き", "is_correct": false, "explanation": "自動詞で、「布を」を目的語に取れず空所に合わない。"}, {"text": "流れ", "is_correct": false, "explanation": "自動詞で、「布を」に続かず文が成り立たない。"}, {"text": "凍り", "is_correct": false, "explanation": "自動詞で、「布を」を目的語に取れず空所に合わない。"}], "explanations": {"纏い": "「布を纏い、軽やかに回った」の連用形。衣装を身につける意味で文が通る。", "咲き": "自動詞で、「布を」を目的語に取れず空所に合わない。", "流れ": "自動詞で、「布を」に続かず文が成り立たない。", "凍り": "自動詞で、「布を」を目的語に取れず空所に合わない。"}, "sentence_index": 6, "correct_answer": "纏い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職人は重い木箱を纏って、倉庫まで運んだ。", "explanation": "ここは〈運ぶ〉の意味。纏うは体にまとう意味で、物を移動させる動作には使えない。"}, {"text": "彼は紙袋を纏って、駅まで歩いた。", "explanation": "ここは〈提げる〉の意味。纏うは体を包むものに使い、手に下げる物には使わない。"}, {"text": "母は料理を大皿に纏って、食卓に出した。", "explanation": "ここは〈盛る〉の意味。纏うは衣服などに使い、料理を器に盛る意味は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52081, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏祭りの夜、彼は浴衣を纏いで会場に来た。", "corrected_sentence": "夏祭りの夜、彼は浴衣を纏って会場に来た。", "error_description": "正しくは「纏って」(て形)。「纏いで」は連用形に「で」をつけた誤った活用。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "纏った", "is_correct": true, "explanation": "過去形の連体修飾。「纏った姿」として直後の名詞を修飾する正しい形。"}, {"text": "纏い", "is_correct": false, "explanation": "連用形。名詞を修飾する形ではなく、「姿」に続けると文が成り立たない。"}, {"text": "纏って", "is_correct": false, "explanation": "て形。「纏って姿で」となり、名詞を修飾できない。"}, {"text": "纏おう", "is_correct": false, "explanation": "意志形。「纏おうの姿」という修飾関係にはならず、過去の意味も表せない。"}], "correct_form": "纏った", "base_form": "纏う", "form_label": "過去形", "sentence_index": 1, "explanations": {"纏った": "過去形の連体修飾。「纏った姿」として直後の名詞を修飾する正しい形。", "纏い": "連用形。名詞を修飾する形ではなく、「姿」に続けると文が成り立たない。", "纏って": "て形。「纏って姿で」となり、名詞を修飾できない。", "纏おう": "意志形。「纏おうの姿」という修飾関係にはならず、過去の意味も表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52081, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の朝、彼は厚い外套を纏れて、駅へ向かった。", "corrected_sentence": "冬の朝、彼は厚い外套を纏って、駅へ向かった。", "error_description": "「纏う」の活用は「纏って」。「纏れて」は存在しない活用形で、「って」の部分が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "纏って", "is_correct": true, "explanation": "て形。「毛布を纏って本を読む」と動作を並べる正しい形。"}, {"text": "纏った", "is_correct": false, "explanation": "過去形。「毛布を纏った本」となり、本を読む動作の前につながらない。"}, {"text": "纏わない", "is_correct": false, "explanation": "否定形。「纏わないで」なら意味が変わり、文が成り立たない。"}, {"text": "纏おう", "is_correct": false, "explanation": "意志形。「毛布を纏おう本を読む」と続かず成り立たない。"}], "correct_form": "纏って", "base_form": "纏う", "form_label": "て形", "sentence_index": 7, "explanations": {"纏って": "て形。「毛布を纏って本を読む」と動作を並べる正しい形。", "纏った": "過去形。「毛布を纏った本」となり、本を読む動作の前につながらない。", "纏わない": "否定形。「纏わないで」なら意味が変わり、文が成り立たない。", "纏おう": "意志形。「毛布を纏おう本を読む」と続かず成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52083, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「さつまいもの表皮はよく洗ってから焼く」で、話題としての表皮を示す。"}, {"text": "で", "is_correct": false, "explanation": "「表皮でよく洗ってから焼く」は手段の意味になり、文の対象として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「表皮によく洗ってから焼く」は位置の意味になり、文の対象として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「表皮とよく洗ってから焼く」は並列の意味になり、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「さつまいもの表皮はよく洗ってから焼く」で、話題としての表皮を示す。", "で": "「表皮でよく洗ってから焼く」は手段の意味になり、文の対象として成り立たない。", "に": "「表皮によく洗ってから焼く」は位置の意味になり、文の対象として成り立たない。", "と": "「表皮とよく洗ってから焼く」は並列の意味になり、文が成り立たない。"}, "error_tags": {"で": "手段の誤り", "に": "位置の誤り", "と": "並列の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52083, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「手の表皮が荒れたので」で、荒れた状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「手の表皮を荒れたので」は目的語の形になり、状態の表現として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「手の表皮へ荒れたので」は方向の意味になり、状態の変化として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「手の表皮で荒れたので」は手段の意味になり、状態の変化として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「手の表皮が荒れたので」で、荒れた状態の主語を示す。", "を": "「手の表皮を荒れたので」は目的語の形になり、状態の表現として成り立たない。", "へ": "「手の表皮へ荒れたので」は方向の意味になり、状態の変化として成り立たない。", "で": "「手の表皮で荒れたので」は手段の意味になり、状態の変化として成り立たない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "で": "手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52083, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物のいちばん外側にある、うすい皮のことです。", "primary_collocate": null, "pronunciation": "ひょうひ", "ipa": "çoːçi", "syllable_count": 3, "sentences": [{"text": "バナナの表皮は、黄色から黒に変わっていく。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "バナナの表皮[ひょうひ]は、黄色[きいろ]から黒[くろ]に変[か]わっていく。", "sentence_source": "generated"}, {"text": "さつまいもの表皮はよく洗ってから焼く。", "target_word": "表皮", "complexity_tier": "T2", "furigana": "さつまいもの表皮[ひょうひ]はよく洗[あら]ってから焼[や]く。", "sentence_source": "generated"}, {"text": "表皮に傷がつくと、果物はすぐ傷んでしまう。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "表皮[ひょうひ]に傷[きず]がつくと、果物[くだもの]はすぐ傷[いた]んでしまう。", "sentence_source": "generated"}, {"text": "とかげは成長すると、古い表皮を脱ぎ捨てる。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "とかげは成長[せいちょう]すると、古[ふる]い表皮[ひょうひ]を脱[ぬ]ぎ捨[す]てる。", "sentence_source": "generated"}, {"text": "この桃は表皮に細かい毛が生えている。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "この桃[もも]は表皮[ひょうひ]に細[こま]かい毛[け]が生[は]えている。", "sentence_source": "generated"}, {"text": "湯むきして表皮を取ると、ソースがなめらかになる。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "湯[ゆ]むきして表皮[ひょうひ]を取[と]ると、ソースがなめらかになる。", "sentence_source": "generated"}, {"text": "ヘビの表皮は乾いていて、触るとひんやりした。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "ヘビの表皮[ひょうひ]は乾[かわ]いていて、触[さわ]るとひんやりした。", "sentence_source": "generated"}, {"text": "手の表皮が荒れたので、クリームをぬった。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "手[て]の表皮[ひょうひ]が荒[あ]れたので、クリームをぬった。", "sentence_source": "generated"}, {"text": "ソーセージの表皮がぱりっと焼けて、おいしかった。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "ソーセージの表皮[ひょうひ]がぱりっと焼[や]けて、おいしかった。", "sentence_source": "generated"}, {"text": "柿の表皮は、干すと少しずつ硬くなる。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "柿[かき]の表皮[ひょうひ]は、干[ほ]すと少[すこ]しずつ硬[かた]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表皮", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物のいちばん外側にある薄い皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T4: contains vocabulary far above tier T4: ぱりっと (Zipf 1.26)']::text[], '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52083, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表皮", "is_correct": true, "explanation": "「バナナの表皮は、黄色から黒に変わっていく」で、外側の皮の色が変わる様子を表し文に合う。"}, {"text": "果汁", "is_correct": false, "explanation": "果汁は中の液体なので、色が黄色から黒に変わるという文の主語として意味が通らない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは色が変わるものではないので、文の主語として成り立たない。"}, {"text": "甘み", "is_correct": false, "explanation": "甘みは色が変わるものではないので、文の主語として意味が通らない。"}], "explanations": {"表皮": "「バナナの表皮は、黄色から黒に変わっていく」で、外側の皮の色が変わる様子を表し文に合う。", "果汁": "果汁は中の液体なので、色が黄色から黒に変わるという文の主語として意味が通らない。", "香り": "香りは色が変わるものではないので、文の主語として成り立たない。", "甘み": "甘みは色が変わるものではないので、文の主語として意味が通らない。"}, "sentence_index": 0, "correct_answer": "表皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説は表皮が長くて、覚えにくい。", "explanation": "ここは〈表題〉の意味。表皮は物の外側の薄い皮を指すので、作品名には使わない。"}, {"text": "かにの表皮はかたいので、中身を取り出しにくい。", "explanation": "ここは〈殻〉の意味。表皮は薄い皮を指すので、かたい殻の説明には合わない。"}, {"text": "このみかんは表皮がたっぷりで、絞るのに向く。", "explanation": "ここは〈果汁〉の意味。表皮は汁を含む部分ではないので、〈たっぷり〉とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52083, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表皮", "is_correct": true, "explanation": "「ヘビの表皮は乾いていて、触るとひんやりした」で、外側の皮の状態を表し文に合う。"}, {"text": "毒", "is_correct": false, "explanation": "毒は乾いていて触るとひんやりするものではないので、主語として文が成り立たない。"}, {"text": "声", "is_correct": false, "explanation": "声は触れるものではないので、「触るとひんやりした」の主語として意味が通らない。"}, {"text": "血", "is_correct": false, "explanation": "血は乾いていて触るとひんやりするものとして文が成り立たない。"}], "explanations": {"表皮": "「ヘビの表皮は乾いていて、触るとひんやりした」で、外側の皮の状態を表し文に合う。", "毒": "毒は乾いていて触るとひんやりするものではないので、主語として文が成り立たない。", "声": "声は触れるものではないので、「触るとひんやりした」の主語として意味が通らない。", "血": "血は乾いていて触るとひんやりするものとして文が成り立たない。"}, "sentence_index": 6, "correct_answer": "表皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この詩は表皮が豊かで、読むたびに新しい発見がある。", "explanation": "ここは〈表現〉の意味。表皮は物の外側の薄い皮なので、言葉の表し方には使わない。"}, {"text": "この箱は表皮がぎっしり詰まっている。", "explanation": "ここは〈中身〉の意味。表皮は薄い外側の皮なので、中に詰まっているという意味にはならない。"}, {"text": "この饅頭は表皮にあんこがたっぷり入っている。", "explanation": "ここは〈具〉の意味。表皮は外側の薄い皮なので、中に入っているものを表すのに使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52083, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桃の表皮を毛が生えている。", "corrected_sentence": "桃の表皮に毛が生えている。", "error_description": "誤りは「を」。「毛が生えている」の場所は「に」で示す。「を」では目的語となり、場所の意味が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52083, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "かばんの表皮を革でできている。", "corrected_sentence": "かばんの表皮は革でできている。", "error_description": "誤りは「を」。「革でできている」の主語は「表皮は」で示す。「を」では目的語になり、主語の関係が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52084, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「表皮が薄い」で、薄いという状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「表皮を薄い」は目的語の形になり、形容詞の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「表皮に薄い」は位置の意味になり、主語と状態の関係が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「表皮で薄い」は手段の意味になり、薄いという状態を表せない。"}], "correct_answer": "が", "explanations": {"が": "「表皮が薄い」で、薄いという状態の主語を示す。", "を": "「表皮を薄い」は目的語の形になり、形容詞の文として成り立たない。", "に": "「表皮に薄い」は位置の意味になり、主語と状態の関係が成り立たない。", "で": "「表皮で薄い」は手段の意味になり、薄いという状態を表せない。"}, "error_tags": {"を": "目的語の誤り", "に": "位置の誤り", "で": "手段の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52084, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「表皮が、しわしわになっていた」で、状態の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「表皮としわしわになっていた」は並列の意味になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「表皮へしわしわになっていた」は方向の意味になり、状態の変化として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「表皮でしわしわになっていた」は手段の意味になり、状態の変化として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「表皮が、しわしわになっていた」で、状態の主語を示す。", "と": "「表皮としわしわになっていた」は並列の意味になり、文が成り立たない。", "へ": "「表皮へしわしわになっていた」は方向の意味になり、状態の変化として成り立たない。", "で": "「表皮でしわしわになっていた」は手段の意味になり、状態の変化として成り立たない。"}, "error_tags": {"と": "並列の誤り", "へ": "方向の誤り", "で": "手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52084, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物の体や物の表面を覆っている薄い皮。特に、果物や皮膚の外側の部分。", "primary_collocate": null, "pronunciation": "ひょうひ", "ipa": "çoːçi", "syllable_count": 3, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "表皮", "complexity_tier": "T4", "furigana": "子供[こども]は躊躇[ためら]いなくその表皮[ひょうひ]に歯[は]を立[た]て、甘酸[あまず]っぱい果汁[かじゅう]を唇[くちびる]に伝[つた]わせながら貪[むさぼ]るように食[た]べる。", "sentence_source": "mined"}, {"text": "このぶどうは表皮が薄いので、皮ごと食べられる。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "このぶどうは表皮[ひょうひ]が薄[うす]いので、皮[かわ]ごと食[た]べられる。", "sentence_source": "generated"}, {"text": "トマトの表皮をむくには、お湯にさっと通すとよい。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "トマトの表皮[ひょうひ]をむくには、お湯[ゆ]にさっと通[とお]すとよい。", "sentence_source": "generated"}, {"text": "日焼けをすると、肌の表皮がはがれることがある。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "日焼[ひや]けをすると、肌[はだ]の表皮[ひょうひ]がはがれることがある。", "sentence_source": "generated"}, {"text": "なすの表皮は紫色で、つやがある。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "なすの表皮[ひょうひ]は紫色[むらさきいろ]で、つやがある。", "sentence_source": "generated"}, {"text": "ナイフでりんごの表皮をうすくむいた。", "target_word": "表皮", "complexity_tier": "T2", "furigana": "ナイフでりんごの表皮[ひょうひ]をうすくむいた。", "sentence_source": "generated"}, {"text": "皮膚の一番外側にある表皮は、体を守る働きをする。", "target_word": "表皮", "complexity_tier": "T4", "furigana": "皮膚[ひふ]の一番[いちばん]外側[そとがわ]にある表皮[ひょうひ]は、体[からだ]を守[まも]る働[はたら]きをする。", "sentence_source": "generated"}, {"text": "古くなったみかんは、表皮がしわしわになっていた。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "古[ふる]くなったみかんは、表皮[ひょうひ]がしわしわになっていた。", "sentence_source": "generated"}, {"text": "きゅうりの表皮は濃い緑色で、ところどころに白いつぶがある。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "きゅうりの表皮[ひょうひ]は濃い緑色[こいみどりいろ]で、ところどころに白[しろ]いつぶがある。", "sentence_source": "generated"}, {"text": "玉ねぎの表皮を一枚むくと、白い中身が出てきた。", "target_word": "表皮", "complexity_tier": "T3", "furigana": "玉[たま]ねぎの表皮[ひょうひ]を一枚[いちまい]むくと、白[しろ]い中身[なかみ]が出[で]てきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表皮", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "果物・皮膚など生物の外側を覆う薄い皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52084, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表皮", "is_correct": true, "explanation": "果物の外側の薄い皮を指し、「その表皮に歯を立て」の文に合う。"}, {"text": "果汁", "is_correct": false, "explanation": "果汁は皮ではなく中の液体なので、「歯を立て」る対象として文の意味が通らない。"}, {"text": "指先", "is_correct": false, "explanation": "指先は食べ物の外側の部分ではないので、「歯を立て」る文の対象にならない。"}, {"text": "縁側", "is_correct": false, "explanation": "縁側は建物の一部なので、食べるための対象として文が成り立たない。"}], "explanations": {"表皮": "果物の外側の薄い皮を指し、「その表皮に歯を立て」の文に合う。", "果汁": "果汁は皮ではなく中の液体なので、「歯を立て」る対象として文の意味が通らない。", "指先": "指先は食べ物の外側の部分ではないので、「歯を立て」る文の対象にならない。", "縁側": "縁側は建物の一部なので、食べるための対象として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "表皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このももは表皮がジューシーで、甘い。", "explanation": "ここは〈果肉〉の意味。表皮は外側の薄い皮で汁気を含む部分ではないので、〈ジューシー〉とは言わない。"}, {"text": "彼女は表皮が豊かで、よく笑う。", "explanation": "ここは〈表情〉の意味。表皮は皮の部分を指すので、感情を表す顔つきには使わない。"}, {"text": "この本は表皮が難しくて、読み進められなかった。", "explanation": "ここは〈内容〉の意味。表皮は物の外側の薄い皮なので、文章の難しさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52084, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表皮", "is_correct": true, "explanation": "「皮膚の一番外側にある表皮は、体を守る働きをする」で、外側を覆う薄い皮を表し文に合う。"}, {"text": "果肉", "is_correct": false, "explanation": "果肉は内側の部分なので、「一番外側にある」と「体を守る」の文の意味に合わない。"}, {"text": "種", "is_correct": false, "explanation": "種は内側にあるもので、「体を守る働き」の主語として文が成り立たない。"}, {"text": "芯", "is_correct": false, "explanation": "芯は中心部分なので、「一番外側にある」の文と合わない。"}], "explanations": {"表皮": "「皮膚の一番外側にある表皮は、体を守る働きをする」で、外側を覆う薄い皮を表し文に合う。", "果肉": "果肉は内側の部分なので、「一番外側にある」と「体を守る」の文の意味に合わない。", "種": "種は内側にあるもので、「体を守る働き」の主語として文が成り立たない。", "芯": "芯は中心部分なので、「一番外側にある」の文と合わない。"}, "sentence_index": 6, "correct_answer": "表皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この梨は表皮がたっぷりで、のどが潤う。", "explanation": "ここは〈果汁〉の意味。表皮は汁を含む部分ではないので、〈たっぷり〉とは言えない。"}, {"text": "玄関に表皮を掛けておいた。", "explanation": "ここは〈表札〉の意味。表皮は生物や果物の外側の皮を指すので、家の名札には使わない。"}, {"text": "この饅頭は表皮にあんこがたっぷり入っている。", "explanation": "ここは〈具〉の意味。表皮は外側の薄い皮なので、中に詰めるものを表すのに使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52084, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バナナの表皮をしだいに黒くなった。", "corrected_sentence": "バナナの表皮がしだいに黒くなった。", "error_description": "誤りは「を」。「黒くなる」は自動詞なので、主語の「表皮」は「が」で示す。「を」は他動詞の目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52084, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "キャベツの表皮へむくと、白い芯が出てきた。", "corrected_sentence": "キャベツの表皮をむくと、白い芯が出てきた。", "error_description": "誤りは「へ」。「むく」の対象は「を」で示す。「へ」は方向を表すため、動作の対象にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
