INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52085, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "味が、すっぱいとあまいの両方があること。", "primary_collocate": null, "pronunciation": "あまずっぱい", "ipa": "amazɯppai", "syllable_count": 6, "sentences": [{"text": "夏みかんは甘酸っぱくて、疲れた体に元気をくれる。", "target_word": "甘酸っぱくて", "complexity_tier": "T3", "furigana": "夏[なつ]みかんは甘酸[あまず]っぱくて、疲[つか]れた体[からだ]に元気[げんき]をくれる。", "sentence_source": "generated"}, {"text": "この甘酸っぱいゼリーは、さっぱりして食べやすい。", "target_word": "甘酸っぱい", "complexity_tier": "T3", "furigana": "この甘酸[あまず]っぱいゼリーは、さっぱりして食[た]べやすい。", "sentence_source": "generated"}, {"text": "ラズベリーの甘酸っぱい味が、ケーキによく合う。", "target_word": "甘酸っぱい", "complexity_tier": "T3", "furigana": "ラズベリーの甘酸[あまず]っぱい味[あじ]が、ケーキによく合[あ]う。", "sentence_source": "generated"}, {"text": "甘酸っぱいたれをつけた唐揚げを、弟は二つ食べた。", "target_word": "甘酸っぱい", "complexity_tier": "T3", "furigana": "甘酸[あまず]っぱいたれをつけた唐揚[からあ]げを、弟[おとうと]は二[ふた]つ食[た]べた。", "sentence_source": "generated"}, {"text": "すもものジャムは甘酸っぱく、パンによく合う。", "target_word": "甘酸っぱく", "complexity_tier": "T3", "furigana": "すもものジャムは甘酸[あまず]っぱく、パンによく合[あ]う。", "sentence_source": "generated"}, {"text": "完熟したトマトは甘酸っぱくて、そのまま食べてもおいしい。", "target_word": "甘酸っぱくて", "complexity_tier": "T3", "furigana": "完熟[かんじゅく]したトマトは甘酸[あまず]っぱくて、そのまま食[た]べてもおいしい。", "sentence_source": "generated"}, {"text": "このドレッシングは甘酸っぱいので、サラダがすすむ。", "target_word": "甘酸っぱい", "complexity_tier": "T3", "furigana": "このドレッシングは甘酸[あまず]っぱいので、サラダがすすむ。", "sentence_source": "generated"}, {"text": "パッションフルーツは甘酸っぱい味で、ジュースにするとさっぱりする。", "target_word": "甘酸っぱい", "complexity_tier": "T3", "furigana": "パッションフルーツは甘酸[あまず]っぱい味[あじ]で、ジュースにするとさっぱりする。", "sentence_source": "generated"}, {"text": "さくらんぼを食べたら、甘酸っぱい味が口に残った。", "target_word": "甘酸っぱい", "complexity_tier": "T3", "furigana": "さくらんぼを食[た]べたら、甘酸[あまず]っぱい味[あじ]が口[くち]に残[のこ]った。", "sentence_source": "generated"}, {"text": "甘酸っぱいオレンジを搾って、朝のジュースにした。", "target_word": "甘酸っぱい", "complexity_tier": "T3", "furigana": "甘酸[あまず]っぱいオレンジを搾[しぼ]って、朝[あさ]のジュースにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "甘酸っぱい", "label": "終止形・連体形"}, {"form": "甘酸っぱく", "label": "連用形"}, {"form": "甘酸っぱかった", "label": "過去形"}, {"form": "甘酸っぱくない", "label": "否定形"}, {"form": "甘酸っぱければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "すっぱさとあまさの両方がある味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52085, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甘酸っぱくて", "is_correct": true, "explanation": "甘さと酸味が両方ある夏みかんの味を表し、元気をくれるという文に合う。"}, {"text": "硬くて", "is_correct": false, "explanation": "固さを表す語で、夏みかんの味を説明できないので合わない。"}, {"text": "眠くて", "is_correct": false, "explanation": "眠気を表す語で、夏みかんの味には使えない。"}, {"text": "騒がしくて", "is_correct": false, "explanation": "音や場の様子を表す語で、味を表せない。"}], "explanations": {"甘酸っぱくて": "甘さと酸味が両方ある夏みかんの味を表し、元気をくれるという文に合う。", "硬くて": "固さを表す語で、夏みかんの味を説明できないので合わない。", "眠くて": "眠気を表す語で、夏みかんの味には使えない。", "騒がしくて": "音や場の様子を表す語で、味を表せない。"}, "sentence_index": 0, "correct_answer": "甘酸っぱくて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "踏切の警報が甘酸っぱく響いて、電車の音がかき消された。", "explanation": "ここは〈甲高い〉の意味。甘酸っぱいは味の語で、響きの高さや鋭さには使わない。"}, {"text": "このシロップは甘酸っぱくて、砂糖の甘さだけが舌に残る。", "explanation": "ここは〈甘ったるい〉の意味。甘酸っぱいは酸味も含む味なので、甘さだけを言う文には合わない。"}, {"text": "この鍋のスープは甘酸っぱくて、ごまの匂いが部屋中に広がる。", "explanation": "ここは〈香ばしさ〉の意味。甘酸っぱいは味の語で、匂いの香ばしさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52085, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甘酸っぱい", "is_correct": true, "explanation": "甘さと酸味が両方ある味を表し、サラダがすすむドレッシングの味に合う。"}, {"text": "寂しい", "is_correct": false, "explanation": "気持ちを表す語で、ドレッシングの味には使えない。"}, {"text": "苦しい", "is_correct": false, "explanation": "苦痛を表す語で、ドレッシングの味には合わない。"}, {"text": "怖い", "is_correct": false, "explanation": "恐れを表す語で、味の説明にはならない。"}], "explanations": {"甘酸っぱい": "甘さと酸味が両方ある味を表し、サラダがすすむドレッシングの味に合う。", "寂しい": "気持ちを表す語で、ドレッシングの味には使えない。", "苦しい": "苦痛を表す語で、ドレッシングの味には合わない。", "怖い": "恐れを表す語で、味の説明にはならない。"}, "sentence_index": 6, "correct_answer": "甘酸っぱい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このオレンジは甘酸っぱいのに、甘さをまったく感じないほど酸っぱい。", "explanation": "ここは〈酸味だけ〉の意味。甘酸っぱいは甘さも感じられる味なので、甘さがまったくないという文には合わない。"}, {"text": "この皿は甘酸っぱくて、片手で持つと腕がずしりと疲れる。", "explanation": "ここは〈重さ〉の意味。甘酸っぱいは味の語で、皿の重さを言うときには使わない。"}, {"text": "この靴下は甘酸っぱくて、足を入れるとひどく窮屈だ。", "explanation": "ここは〈きつい〉の意味。甘酸っぱいは味を表す語で、靴下の締め付けや大きさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52085, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "りんごのジャムは甘酸っぱいくて、パンによく合う。", "corrected_sentence": "りんごのジャムは甘酸っぱくて、パンによく合う。", "error_description": "て形は連用形「甘酸っぱく」に「て」をつける。「い」を残して「甘酸っぱいくて」とすると誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "甘酸っぱく", "is_correct": false, "explanation": "連用形。名詞を直接修飾できず、「ゼリー」の前に置けない。"}, {"text": "甘酸っぱくて", "is_correct": false, "explanation": "て形。名詞の前に置けず、「ゼリー」を修飾できない。"}, {"text": "甘酸っぱい", "is_correct": true, "explanation": "連体形。「ゼリー」を直接修飾して、どんなゼリーかを示す。"}, {"text": "甘酸っぱければ", "is_correct": false, "explanation": "仮定形。名詞を修飾できず、文が成り立たない。"}], "correct_form": "甘酸っぱい", "base_form": "甘酸っぱい", "form_label": "連体形", "sentence_index": 1, "explanations": {"甘酸っぱく": "連用形。名詞を直接修飾できず、「ゼリー」の前に置けない。", "甘酸っぱくて": "て形。名詞の前に置けず、「ゼリー」を修飾できない。", "甘酸っぱい": "連体形。「ゼリー」を直接修飾して、どんなゼリーかを示す。", "甘酸っぱければ": "仮定形。名詞を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52085, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このレモン酒は甘酸っぱいで、ゼリーにぴったりだ。", "corrected_sentence": "このレモン酒は甘酸っぱくて、ゼリーにぴったりだ。", "error_description": "い形容詞は「で」ではなく「くて」で続ける。「甘酸っぱいで」は誤りで、正しくは「甘酸っぱくて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "甘酸っぱかった", "is_correct": false, "explanation": "過去形。「味」を修飾すると以前の味という意味になり、今の味を述べる文と合わない。"}, {"text": "甘酸っぱかろう", "is_correct": false, "explanation": "推量形。名詞の前に置けず、「味」を修飾できない。"}, {"text": "甘酸っぱい", "is_correct": true, "explanation": "連体形。「味」を修飾して、パッションフルーツの味を述べる。"}, {"text": "甘酸っぱくなかった", "is_correct": false, "explanation": "過去の否定形。以前は甘酸っぱくなかったという意味になり、文脈に合わない。"}], "correct_form": "甘酸っぱい", "base_form": "甘酸っぱい", "form_label": "連体形", "sentence_index": 7, "explanations": {"甘酸っぱかった": "過去形。「味」を修飾すると以前の味という意味になり、今の味を述べる文と合わない。", "甘酸っぱかろう": "推量形。名詞の前に置けず、「味」を修飾できない。", "甘酸っぱい": "連体形。「味」を修飾して、パッションフルーツの味を述べる。", "甘酸っぱくなかった": "過去の否定形。以前は甘酸っぱくなかったという意味になり、文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
