INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52087, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「躊躇いのない」は「ためらわない」という形容で、後ろの「声」を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「躊躇いを」は目的語を示す形で、「ない声」を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "「躊躇いに」は対象や場所を表すが、「ない声」を修飾できない。"}, {"text": "と", "is_correct": false, "explanation": "「躊躇いと」は並列を表すが、「ない声」とは続かない。"}], "correct_answer": "の", "explanations": {"の": "「躊躇いのない」は「ためらわない」という形容で、後ろの「声」を修飾する。", "を": "「躊躇いを」は目的語を示す形で、「ない声」を修飾できない。", "に": "「躊躇いに」は対象や場所を表すが、「ない声」を修飾できない。", "と": "「躊躇いと」は並列を表すが、「ない声」とは続かない。"}, "error_tags": {"を": "目的語", "に": "対象", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52087, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ためらうこと。何かをしようかどうか迷うこと。", "primary_collocate": null, "pronunciation": "ためらい", "ipa": "tameɾai", "syllable_count": 4, "sentences": [{"text": "試験の結果を見る前に、少し躊躇いを感じた。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]を見[み]る前[まえ]に、少[すこ]し躊躇[ためら]いを感[かん]じた。", "sentence_source": "generated"}, {"text": "彼は躊躇いもなく手を挙げて質問した。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "彼[かれ]は躊躇[ためら]いもなく手[て]を挙[あ]げて質問[しつもん]した。", "sentence_source": "generated"}, {"text": "転職を決めるまで、長い躊躇いの時間が続いた。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "転職[てんしょく]を決[き]めるまで、長[なが]い躊躇[ためら]いの時間[じかん]が続[つづ]いた。", "sentence_source": "generated"}, {"text": "彼女の躊躇いに気づいて、先輩はやさしく声をかけた。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の躊躇[ためら]いに気[き]づいて、先輩[せんぱい]はやさしく声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "告白する勇気がなく、彼の躊躇いは最後まで消えなかった。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "告白[こくはく]する勇気[ゆうき]がなく、彼[かれ]の躊躇[ためら]いは最後[さいご]まで消[き]えなかった。", "sentence_source": "generated"}, {"text": "躊躇いを振り切って、彼はドアをノックした。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "躊躇[ためら]いを振[ふ]り切[き]って、彼[かれ]はドアをノックした。", "sentence_source": "generated"}, {"text": "高い値段を見て、買うかどうかの躊躇いが生まれた。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "高[たか]い値段[ねだん]を見[み]て、買[か]うかどうかの躊躇[ためら]いが生[う]まれた。", "sentence_source": "generated"}, {"text": "社長は躊躇いのない声で、新しい店を開くと宣言した。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は躊躇[ためら]いのない声[こえ]で、新[あたら]しい店[みせ]を開[ひら]くと宣言[せんげん]した。", "sentence_source": "generated"}, {"text": "嘘をつくことに躊躇いがないのは、よくないと思う。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "嘘[うそ]をつくことに躊躇[ためら]いがないのは、よくないと思[おも]う。", "sentence_source": "generated"}, {"text": "彼女の返事には、はっきりとした躊躇いが感じられた。", "target_word": "躊躇い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の返事[へんじ]には、はっきりとした躊躇[ためら]いが感[かん]じられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "躊躇い", "label": "基本形"}, {"form": "ためらい", "label": "ひらがな表記"}], "register": "neutral（書き言葉寄り）", "sense_fingerprint": "するかどうか決められずに迷う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52087, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "躊躇い", "is_correct": true, "explanation": "迷う気持ちを表し、試験の結果を見る前に少し感じたという文に合う。"}, {"text": "手続き", "is_correct": false, "explanation": "事務の段取りを表す語で、感じるものではないので合わない。"}, {"text": "順序", "is_correct": false, "explanation": "並びを表す語で、感じる対象にはならない。"}, {"text": "合計", "is_correct": false, "explanation": "数の和を表す語で、感じるものではない。"}], "explanations": {"躊躇い": "迷う気持ちを表し、試験の結果を見る前に少し感じたという文に合う。", "手続き": "事務の段取りを表す語で、感じるものではないので合わない。", "順序": "並びを表す語で、感じる対象にはならない。", "合計": "数の和を表す語で、感じるものではない。"}, "sentence_index": 0, "correct_answer": "躊躇い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は躊躇いを固めて、ついに留学を決意した。", "explanation": "ここは〈決心〉の意味。躊躇いは迷う気持ちなので、迷いを固めて決めるという文には合わない。"}, {"text": "先輩の助言に、躊躇いを込めて深く感謝した。", "explanation": "ここは〈ありがたく思う気持ち〉の意味。躊躇いは迷いの気持ちで、お礼の思いを込める文には合わない。"}, {"text": "この鍋の具は躊躇いが多くて、食べ応えがある。", "explanation": "ここは〈量〉の意味。躊躇いは迷う気持ちで、分量を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52087, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "躊躇い", "is_correct": true, "explanation": "買うかどうか迷う気持ちを表し、「躊躇いが生まれた」という文に合う。"}, {"text": "納期", "is_correct": false, "explanation": "品物を届ける期限で、迷う気持ちの対象ではない。"}, {"text": "配送", "is_correct": false, "explanation": "品物を届ける仕組みで、買うかどうかの迷いには当たらない。"}, {"text": "送料", "is_correct": false, "explanation": "送るための料金で、買うかどうかの気持ちの前提にはならない。"}], "explanations": {"躊躇い": "買うかどうか迷う気持ちを表し、「躊躇いが生まれた」という文に合う。", "納期": "品物を届ける期限で、迷う気持ちの対象ではない。", "配送": "品物を届ける仕組みで、買うかどうかの迷いには当たらない。", "送料": "送るための料金で、買うかどうかの気持ちの前提にはならない。"}, "sentence_index": 6, "correct_answer": "躊躇い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の返事には、確信に満ちた躊躇いが感じられた。", "explanation": "ここは〈自信〉の意味。躊躇いは迷う気持ちなので、自信に満ちた様子とは矛盾する。"}, {"text": "合格の知らせを聞き、彼は安堵の躊躇いで胸をなで下ろした。", "explanation": "ここは〈ほっとした気持ち〉の意味。躊躇いは迷う気持ちで、安心して胸をなで下ろす場面には合わない。"}, {"text": "ノーベル賞の知らせに、感激の躊躇いが込み上げて涙をこぼした。", "explanation": "ここは〈強い感動〉の意味。躊躇いは迷う気持ちで、感動して涙をこぼす文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52087, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は躊躇いなくで、その提案を引き受けた。", "corrected_sentence": "彼は躊躇いなく、その提案を引き受けた。", "error_description": "「なく」の後に助詞「で」は続かない。「躊躇いなくで」は誤りで、正しくは「躊躇いなく」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52087, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家を買うかどうか、夫婦は長く躊躇いを覚えてい。", "corrected_sentence": "家を買うかどうか、夫婦は長く躊躇いを覚えていた。", "error_description": "過去を表す「覚えていた」の「た」が抜けている。「覚えてい」は文として不完全で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52089, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「果汁の割合」の所属を示す「の」。果汁に関する割合を表す。"}, {"text": "が", "is_correct": false, "explanation": "「果汁が割合を見て」は主語と動作が合わず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「果汁に割合」は所属や対象を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、割合を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「果汁の割合」の所属を示す「の」。果汁に関する割合を表す。", "が": "「果汁が割合を見て」は主語と動作が合わず、不自然。", "に": "「果汁に割合」は所属や対象を示せず、文が成り立たない。", "へ": "「へ」は方向を表し、割合を修飾する形にならない。"}, "error_tags": {"が": "主語の誤り", "に": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52089, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「搾る」の目的語を示す「を」。新鮮な果汁を搾る、と正しく読める。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、搾る対象を示せないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、搾る対象にならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、搾る対象を示す形にならない。"}], "correct_answer": "を", "explanations": {"を": "「搾る」の目的語を示す「を」。新鮮な果汁を搾る、と正しく読める。", "より": "「より」は比較を表し、搾る対象を示せないので合わない。", "から": "「から」は起点を表し、搾る対象にならないので合わない。", "と": "「と」は並列や相手を表し、搾る対象を示す形にならない。"}, "error_tags": {"より": "比較の誤り", "から": "起点の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52089, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "果物からとったしる", "primary_collocate": null, "pronunciation": "かじゅう", "ipa": "kad͡ʑɯː", "syllable_count": 3, "sentences": [{"text": "梨は果汁が多くて、とてもみずみずしい果物だ。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "梨[なし]は果汁[かじゅう]が多[おお]くて、とてもみずみずしい果物[くだもの]だ。", "sentence_source": "generated"}, {"text": "缶に書かれた果汁の割合を見てから、飲み物を選んだ。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "缶[かん]に書[か]かれた果汁[かじゅう]の割合[わりあい]を見[み]てから、飲[の]み物[もの]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "りんごをすりおろして、果汁をガーゼでこした。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "りんごをすりおろして、果汁[かじゅう]をガーゼでこした。", "sentence_source": "generated"}, {"text": "夏になると、果汁入りのアイスをよく食べる。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "夏[なつ]になると、果汁[かじゅう]入[い]りのアイスをよく食[た]べる。", "sentence_source": "generated"}, {"text": "グレープフルーツの果汁が目に入って、涙が出た。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "グレープフルーツの果汁[かじゅう]が目[め]に入[はい]って、涙[なみだ]が出[で]た。", "sentence_source": "generated"}, {"text": "果汁を凍らせて、手作りのシャーベットを作った。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "果汁[かじゅう]を凍[こお]らせて、手作[てづく]りのシャーベットを作[つく]った。", "sentence_source": "generated"}, {"text": "彼はスイカの果汁で口の周りをべたべたにして笑った。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "彼[かれ]はスイカの果汁[かじゅう]で口[くち]の周[まわ]りをべたべたにして笑[わら]った。", "sentence_source": "generated"}, {"text": "この店では、新鮮な果汁をその場で搾ってくれる。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "この店[みせ]では、新鮮[しんせん]な果汁[かじゅう]をその場[ば]で搾[しぼ]ってくれる。", "sentence_source": "generated"}, {"text": "果汁の酸味が強すぎるので、はちみつを少し足した。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "果汁[かじゅう]の酸味[さんみ]が強[つよ]すぎるので、はちみつを少[すこ]し足[た]した。", "sentence_source": "generated"}, {"text": "ソースには、りんごの果汁が隠し味として入っている。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "ソースには、りんごの果汁[かじゅう]が隠[かく]し味[あじ]として入[はい]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "果汁", "label": "基本形"}, {"form": "かじゅう", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "果物の中に含まれる、またはそこから取った汁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52089, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果汁", "is_correct": true, "explanation": "「多くて、みずみずしい」と合う、水分の多さを示す果汁が正解。"}, {"text": "塩", "is_correct": false, "explanation": "塩が多いと梨の説明として「みずみずしい」と矛盾する。"}, {"text": "油", "is_correct": false, "explanation": "油が多い梨はみずみずしい果物とは言えないので合わない。"}, {"text": "卵", "is_correct": false, "explanation": "卵が多いと梨の説明にならず、文が成り立たない。"}], "explanations": {"果汁": "「多くて、みずみずしい」と合う、水分の多さを示す果汁が正解。", "塩": "塩が多いと梨の説明として「みずみずしい」と矛盾する。", "油": "油が多い梨はみずみずしい果物とは言えないので合わない。", "卵": "卵が多いと梨の説明にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "果汁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "すいかの果汁を一口大に切って、皿に盛った。", "explanation": "ここは〈果肉〉の意味。一口大に切れるのは果肉で、液体の果汁は切れない。"}, {"text": "みかんの果汁を指でむいて、房を取り出した。", "explanation": "ここは〈果皮〉の意味。指でむくのは果皮で、液体の果汁はむけない。"}, {"text": "梅の果汁を噛んで砕いた。", "explanation": "ここは〈種〉の意味。噛んで砕けるのは種で、液体の果汁は噛めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52089, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果汁", "is_correct": true, "explanation": "スイカの汁で口の周りがべたべたになるという文脈に合う果汁が正解。"}, {"text": "芯", "is_correct": false, "explanation": "芯は固く、口の周りをべたべたにしないので合わない。"}, {"text": "殻", "is_correct": false, "explanation": "殻は固く、べたつく汁を出さないので合わない。"}, {"text": "核", "is_correct": false, "explanation": "核は固い種で、口の周りをべたべたにする原因にならないので合わない。"}], "explanations": {"果汁": "スイカの汁で口の周りがべたべたになるという文脈に合う果汁が正解。", "芯": "芯は固く、口の周りをべたべたにしないので合わない。", "殻": "殻は固く、べたつく汁を出さないので合わない。", "核": "核は固い種で、口の周りをべたべたにする原因にならないので合わない。"}, "sentence_index": 6, "correct_answer": "果汁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パイナップルの果汁を切り落として、一口大に切った。", "explanation": "ここは〈芯〉の意味。切り落とすのは芯の部分で、液体の果汁は切り落とせない。"}, {"text": "木になっているなしの果汁をもいだ。", "explanation": "ここは〈果実〉の意味。木からもぐのは果実で、液体の果汁は木になっていない。"}, {"text": "いちごの果汁を包丁でえぐり取った。", "explanation": "ここは〈へた〉の意味。えぐり取るのはへたで、果汁を取り除くことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52089, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "梨は果汁を多くて、冷やして食べるとおいしい。", "corrected_sentence": "梨は果汁が多くて、冷やして食べるとおいしい。", "error_description": "「多い」の主語は果汁なので「が」が正しい。「を」にすると目的語になり、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52089, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "缶に入った果汁を、コップに注いたで飲んだ。", "corrected_sentence": "缶に入った果汁を、コップに注いで飲んだ。", "error_description": "「注ぐ」のて形は「注いで」。「注いたで」は活用の誤りで、正しくない形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52090, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52090, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「薄める」の目的語を示す「を」。果汁を水で薄めた、と正しく読める。"}, {"text": "が", "is_correct": false, "explanation": "「が」だと果汁が主語になり、薄める対象が合わなくなる。"}, {"text": "に", "is_correct": false, "explanation": "「果汁に」では薄める対象を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、薄める対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「薄める」の目的語を示す「を」。果汁を水で薄めた、と正しく読める。", "が": "「が」だと果汁が主語になり、薄める対象が合わなくなる。", "に": "「果汁に」では薄める対象を示せず、文が成り立たない。", "へ": "「へ」は方向を表すので、薄める対象にはならない。"}, "error_tags": {"が": "主語の誤り", "に": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52090, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "果物などから絞り取った液体。ジュース。", "primary_collocate": null, "pronunciation": "かじゅう", "ipa": "kad͡ʑɯː", "syllable_count": 3, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "果汁", "complexity_tier": "T4", "furigana": "子供[こども]は躊躇[ためら]いなくその表皮[ひょうひ]に歯[は]を立[た]て、甘酸[あまず]っぱい果汁[かじゅう]を唇[くちびる]に伝[つた]わせながら貪[むさぼ]るように食[た]べる。", "sentence_source": "mined"}, {"text": "このジュースは果汁百パーセントで、砂糖が入っていない。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "このジュースは果汁[かじゅう]百[ひゃく]パーセントで、砂糖[さとう]が入[はい]っていない。", "sentence_source": "generated"}, {"text": "オレンジを絞ると、冷たい果汁が手のひらを伝った。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "オレンジを絞[しぼ]ると、冷[つめ]たい果汁[かじゅう]が手[て]のひらを伝[つた]った。", "sentence_source": "generated"}, {"text": "母はゼリーを作るために、ぶどうの果汁を鍋で温めた。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "母[はは]はゼリーを作[つく]るために、ぶどうの果汁[かじゅう]を鍋[なべ]で温[あたた]めた。", "sentence_source": "generated"}, {"text": "果汁が服に飛んで、白いシャツにしみができてしまった。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "果汁[かじゅう]が服[ふく]に飛[と]んで、白[しろ]いシャツにしみができてしまった。", "sentence_source": "generated"}, {"text": "肉を柔らかくするために、パイナップルの果汁に漬けた。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "肉[にく]を柔[やわ]らかくするために、パイナップルの果汁[かじゅう]に漬[つ]けた。", "sentence_source": "generated"}, {"text": "桃をかじると、甘い果汁があふれ出した。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "桃[もも]をかじると、甘[あま]い果汁[かじゅう]があふれ出[だ]した。", "sentence_source": "generated"}, {"text": "子どもが飲みやすいように、果汁を水で薄めた。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "子[こ]どもが飲[の]みやすいように、果汁[かじゅう]を水[みず]で薄[うす]めた。", "sentence_source": "generated"}, {"text": "魚にレモンの果汁をかけると、さっぱりして食べやすい。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "魚[さかな]にレモンの果汁[かじゅう]をかけると、さっぱりして食[た]べやすい。", "sentence_source": "generated"}, {"text": "工場では、集めたみかんから果汁を搾って瓶に詰める。", "target_word": "果汁", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、集[あつ]めたみかんから果汁[かじゅう]を搾[しぼ]って瓶[びん]に詰[つ]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "果汁", "label": "基本形"}, {"form": "かじゅう", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "果物を絞って得られる液体、ジュース", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52090, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果汁", "is_correct": true, "explanation": "「伝わせる」と合う液体で、甘酸っぱい味を表す果汁が正解。"}, {"text": "果肉", "is_correct": false, "explanation": "果肉は固い果実の部分で、唇へ流れ伝わるものではないので合わない。"}, {"text": "果皮", "is_correct": false, "explanation": "果皮は外側の固い皮で、唇へ伝わせる対象にならないので合わない。"}, {"text": "種", "is_correct": false, "explanation": "種は固い粒で、液体のように唇へ伝わせることはできないので合わない。"}], "explanations": {"果汁": "「伝わせる」と合う液体で、甘酸っぱい味を表す果汁が正解。", "果肉": "果肉は固い果実の部分で、唇へ流れ伝わるものではないので合わない。", "果皮": "果皮は外側の固い皮で、唇へ伝わせる対象にならないので合わない。", "種": "種は固い粒で、液体のように唇へ伝わせることはできないので合わない。"}, "sentence_index": 0, "correct_answer": "果汁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "りんごの果汁を薄く切って、サラダに入れた。", "explanation": "ここは〈果肉〉の意味。果汁は液体なので薄く切ることはできず、薄く切るのは果肉。"}, {"text": "ぶどうの果汁を一粒ずつもいで、かごに入れた。", "explanation": "ここは〈果実〉の意味。一粒ずつもぐのは果実で、液体の果汁は枝になっていないので合わない。"}, {"text": "オレンジの果汁をすりおろして、ケーキに入れた。", "explanation": "ここは〈果皮〉の意味。すりおろして香りを使うのは果皮で、液体の果汁はすりおろせない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52090, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果汁", "is_correct": true, "explanation": "「あふれ出す」は液体の動きに合い、甘い果汁が正解。"}, {"text": "芯", "is_correct": false, "explanation": "芯は固い中心部で、あふれ出すものではないので合わない。"}, {"text": "殻", "is_correct": false, "explanation": "殻は固い外側で、あふれ出すものではないので合わない。"}, {"text": "核", "is_correct": false, "explanation": "核は固い種の部分で、あふれ出すものではないので合わない。"}], "explanations": {"果汁": "「あふれ出す」は液体の動きに合い、甘い果汁が正解。", "芯": "芯は固い中心部で、あふれ出すものではないので合わない。", "殻": "殻は固い外側で、あふれ出すものではないので合わない。", "核": "核は固い種の部分で、あふれ出すものではないので合わない。"}, "sentence_index": 6, "correct_answer": "果汁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "いちごの果汁を包丁でえぐり取った。", "explanation": "ここは〈へた〉の意味。包丁でえぐり取るのはへたで、液体の果汁は取り除けるものではない。"}, {"text": "りんごの果汁をくり抜いて、中にバターを詰めた。", "explanation": "ここは〈芯〉の意味。くり抜くのは芯の部分で、液体の果汁はくり抜けない。"}, {"text": "くるみの果汁を一つずつむいた。", "explanation": "ここは〈殻〉の意味。むくのは殻で、液体の果汁はむけない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52090, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "絞ったばかりの果汁を手のひらを伝い、指の間から落ちた。", "corrected_sentence": "絞ったばかりの果汁が手のひらを伝い、指の間から落ちた。", "error_description": "「伝う」の主語は果汁なので「が」が正しい。「を」にすると果汁が目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52090, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ジューサーで果汁を砕いてから、グラスに注いだ。", "corrected_sentence": "ジューサーで果汁を搾ってから、グラスに注いだ。", "error_description": "果汁は液体なので砕けず、絞り取る「搾る」が正しい。「砕く」は固形物に使う動詞。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52091, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52091, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「唇についた」の付着先を示す「に」。米粒が唇に付いた、と正しく読める。"}, {"text": "で", "is_correct": false, "explanation": "「唇でついた」は手段の意味になり、付着を表せないので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「唇とついた」は並列や相手の意味になり、付着先を示せないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、付着先にならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「唇についた」の付着先を示す「に」。米粒が唇に付いた、と正しく読める。", "で": "「唇でついた」は手段の意味になり、付着を表せないので不自然。", "と": "「唇とついた」は並列や相手の意味になり、付着先を示せないので不自然。", "より": "「より」は比較を表し、付着先にならないので合わない。"}, "error_tags": {"で": "手段の誤り", "と": "並列の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52091, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "口のまわりの、赤いふちの部分のことです。", "primary_collocate": null, "pronunciation": "くちびる", "ipa": "kɯt͡ɕibiɾɯ", "syllable_count": 4, "sentences": [{"text": "唇の端に、ケーキのクリームがついているよ。", "target_word": "唇", "complexity_tier": "T3", "furigana": "唇[くちびる]の端[はし]に、ケーキのクリームがついているよ。", "sentence_source": "generated"}, {"text": "風が強くて、唇がかさかさになった。", "target_word": "唇", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]くて、唇[くちびる]がかさかさになった。", "sentence_source": "generated"}, {"text": "彼女はリップクリームを唇に塗るのが習慣だ。", "target_word": "唇", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はリップクリームを唇[くちびる]に塗[ぬ]るのが習慣[しゅうかん]だ。", "sentence_source": "generated"}, {"text": "寒さで唇が紫色になるまで、海で遊んでいた。", "target_word": "唇", "complexity_tier": "T3", "furigana": "寒[さむ]さで唇[くちびる]が紫色[むらさきいろ]になるまで、海[うみ]で遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "妹は笑うと、唇の両端が上がってかわいい。", "target_word": "唇", "complexity_tier": "T3", "furigana": "妹[いもうと]は笑[わら]うと、唇[くちびる]の両端[りょうはし]が上[あ]がってかわいい。", "sentence_source": "generated"}, {"text": "彼は何か言いたそうに、唇を動かした。", "target_word": "唇", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]か言[い]いたそうに、唇[くちびる]を動[うご]かした。", "sentence_source": "generated"}, {"text": "冷たいアイスが唇に触れて、びっくりした。", "target_word": "唇", "complexity_tier": "T3", "furigana": "冷[つめ]たいアイスが唇[くちびる]に触[ふ]れて、びっくりした。", "sentence_source": "generated"}, {"text": "母は私の唇についた米粒を、指でそっと取ってくれた。", "target_word": "唇", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の唇[くちびる]についた米粒[こめつぶ]を、指[ゆび]でそっと取[と]ってくれた。", "sentence_source": "generated"}, {"text": "唇が荒れたときは、水をたくさん飲むとよい。", "target_word": "唇", "complexity_tier": "T3", "furigana": "唇[くちびる]が荒[あ]れたときは、水[みず]をたくさん飲[の]むとよい。", "sentence_source": "generated"}, {"text": "彼は唇を引き結んで、じっと前を見つめていた。", "target_word": "唇", "complexity_tier": "T3", "furigana": "彼[かれ]は唇[くちびる]を引[ひ]き結[むす]んで、じっと前[まえ]を見[み]つめていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "唇", "label": "基本形"}, {"form": "くちびる", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "口のまわりの赤いふちの部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: かさかさ (Zipf 1.95)']::text[], '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52091, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唇", "is_correct": true, "explanation": "口の周りの端を指す唇が自然で、ケーキのクリームがつく場所に合う。"}, {"text": "膝", "is_correct": false, "explanation": "膝の端にケーキのクリームがつく状況は考えられないので合わない。"}, {"text": "肘", "is_correct": false, "explanation": "肘の端にクリームがつく状況は通常なく、文が不自然になる。"}, {"text": "踵", "is_correct": false, "explanation": "踵の端にクリームがつくのは不自然で、文脈に合わない。"}], "explanations": {"唇": "口の周りの端を指す唇が自然で、ケーキのクリームがつく場所に合う。", "膝": "膝の端にケーキのクリームがつく状況は考えられないので合わない。", "肘": "肘の端にクリームがつく状況は通常なく、文が不自然になる。", "踵": "踵の端にクリームがつくのは不自然で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "唇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "虫歯になった唇を削って、詰め物をした。", "explanation": "ここは〈歯〉の意味。虫歯を削って詰め物をするのは歯で、唇には行わない。"}, {"text": "彼の演技には唇を巻いた。", "explanation": "ここは〈舌〉の意味。「舌を巻く」は感心する慣用句で、唇では成り立たない。"}, {"text": "彼は首ではなく唇を振って、いやだと否定した。", "explanation": "ここは〈首〉の意味。首を振るのは首の動作で、唇を振ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52091, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唇", "is_correct": true, "explanation": "冷たいアイスが口元に触れる文脈に合い、驚いた場面として自然。"}, {"text": "眉", "is_correct": false, "explanation": "眉に冷たいアイスが触れる場面は、この文脈では不自然。"}, {"text": "雲", "is_correct": false, "explanation": "雲に冷たいアイスが触れることはなく、文として成り立たない。"}, {"text": "星", "is_correct": false, "explanation": "星に冷たいアイスが触れる状況はなく、文として成り立たない。"}], "explanations": {"唇": "冷たいアイスが口元に触れる文脈に合い、驚いた場面として自然。", "眉": "眉に冷たいアイスが触れる場面は、この文脈では不自然。", "雲": "雲に冷たいアイスが触れることはなく、文として成り立たない。", "星": "星に冷たいアイスが触れる状況はなく、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "唇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その返事を聞いて、彼女は唇をひそめた。", "explanation": "ここは〈眉〉の意味。ひそめるのは眉で、唇にはこの動詞を使わない。"}, {"text": "驚いて唇が外れそうになった。", "explanation": "ここは〈顎〉の意味。顎が外れるほど驚く慣用句で、唇は外れない。"}, {"text": "笑うと唇にえくぼができる。", "explanation": "ここは〈頬〉の意味。えくぼは頬にできるもので、唇にはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52091, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "唇を端に、チョコレートがついているよ。", "corrected_sentence": "唇の端に、チョコレートがついているよ。", "error_description": "「唇の端」の所属を示すのは「の」。「を」にすると目的語になり、文の構造が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52091, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緊張して唇を噛まいた。", "corrected_sentence": "緊張して唇を噛んだ。", "error_description": "「噛む」の過去形は「噛んだ」。「噛まいた」は活用の誤りで、正しくない形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52092, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「唇が乾く」の主語を示す「が」。唇が乾いてひび割れる、と正しく読める。"}, {"text": "に", "is_correct": false, "explanation": "「唇に乾いて」は対象を示せず、主語にならないので不自然。"}, {"text": "で", "is_correct": false, "explanation": "「唇で乾いて」は手段の意味になり、状態の説明として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、状態を示す主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「唇が乾く」の主語を示す「が」。唇が乾いてひび割れる、と正しく読める。", "に": "「唇に乾いて」は対象を示せず、主語にならないので不自然。", "で": "「唇で乾いて」は手段の意味になり、状態の説明として成り立たない。", "へ": "「へ」は方向を表し、状態を示す主語にはならない。"}, "error_tags": {"に": "対象の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52092, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「閉じる」の目的語を示す「を」。唇を閉じる、と正しく読める。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、閉じる対象にならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、唇を閉じる対象にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、閉じる対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「閉じる」の目的語を示す「を」。唇を閉じる、と正しく読める。", "より": "「より」は比較を表し、閉じる対象にならないので合わない。", "から": "「から」は起点を表し、唇を閉じる対象にはならないので合わない。", "と": "「と」は並列や相手を表し、閉じる対象を示せないので合わない。"}, "error_tags": {"より": "比較の誤り", "から": "起点の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52092, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間の口の周りの、上下のふちを指す器官。食べ物や飲み物を口に入れたり、発音の際に使う。", "primary_collocate": null, "pronunciation": "くちびる", "ipa": "kɯt͡ɕibiɾɯ", "syllable_count": 4, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "唇", "complexity_tier": "T4", "furigana": "子供[こども]は躊躇[ためら]いなくその表皮[ひょうひ]に歯[は]を立[た]て、甘酸[あまず]っぱい果汁[かじゅう]を唇[くちびる]に伝[つた]わせながら貪[むさぼ]るように食[た]べる。", "sentence_source": "mined"}, {"text": "寒い冬は、唇が乾いてひび割れてしまう。", "target_word": "唇", "complexity_tier": "T3", "furigana": "寒[さむ]い冬[ふゆ]は、唇[くちびる]が乾[かわ]いてひび割[わ]れてしまう。", "sentence_source": "generated"}, {"text": "彼女は赤い口紅を唇に塗って、出かけた。", "target_word": "唇", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は赤[あか]い口紅[くちべに]を唇[くちびる]に塗[ぬ]って、出[で]かけた。", "sentence_source": "generated"}, {"text": "緊張して、唇が小さく震えていた。", "target_word": "唇", "complexity_tier": "T3", "furigana": "緊張[きんちょう]して、唇[くちびる]が小[ちい]さく震[ふる]えていた。", "sentence_source": "generated"}, {"text": "熱いスープで唇をやけどしてしまった。", "target_word": "唇", "complexity_tier": "T3", "furigana": "熱[あつ]いスープで唇[くちびる]をやけどしてしまった。", "sentence_source": "generated"}, {"text": "彼は唇に指を当てて、静かにするように合図した。", "target_word": "唇", "complexity_tier": "T3", "furigana": "彼[かれ]は唇[くちびる]に指[ゆび]を当[あ]てて、静[しず]かにするように合図[あいず]した。", "sentence_source": "generated"}, {"text": "悔しくて、唇を強くかんだ。", "target_word": "唇", "complexity_tier": "T3", "furigana": "悔[くや]しくて、唇[くちびる]を強[つよ]くかんだ。", "sentence_source": "generated"}, {"text": "「ぱ」の音は、両方の唇を閉じてから出す。", "target_word": "唇", "complexity_tier": "T3", "furigana": "「ぱ」の音[おと]は、両方[りょうほう]の唇[くちびる]を閉[と]じてから出[だ]す。", "sentence_source": "generated"}, {"text": "赤ちゃんは唇をとがらせて、ミルクをほしがった。", "target_word": "唇", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは唇[くちびる]をとがらせて、ミルクをほしがった。", "sentence_source": "generated"}, {"text": "唇の色が悪いので、医者に見てもらった。", "target_word": "唇", "complexity_tier": "T3", "furigana": "唇[くちびる]の色[いろ]が悪[わる]いので、医者[いしゃ]に見[み]てもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "唇", "label": "基本形"}, {"form": "くちびる", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "口の上下のふちの器官で、食べる・飲む・発音に使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 躊躇い (Zipf 2.5), 表皮 (Zipf 3.15), 甘酸っぱい (Zipf 2.99), 伝わ (Zipf 2.78), 貪る (Zipf 2.82)','sentence 8 above tier T3: contains vocabulary far above tier T3: とがら (Zipf 1.91)']::text[], '1227d442-b6e8-416c-9a42-2ae7e4b0c392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52092, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唇", "is_correct": true, "explanation": "果汁を伝わせながら食べる口元の部位は唇で、文脈に合う。"}, {"text": "膝", "is_correct": false, "explanation": "膝に果汁が伝って食べる流れにはならないので合わない。"}, {"text": "踵", "is_correct": false, "explanation": "踵は食べる動作と結びつかず、果汁が伝う場所ではないので合わない。"}, {"text": "肘", "is_correct": false, "explanation": "肘に果汁を伝わせて食べるのは、貪る食べ方の流れと合わない。"}], "explanations": {"唇": "果汁を伝わせながら食べる口元の部位は唇で、文脈に合う。", "膝": "膝に果汁が伝って食べる流れにはならないので合わない。", "踵": "踵は食べる動作と結びつかず、果汁が伝う場所ではないので合わない。", "肘": "肘に果汁を伝わせて食べるのは、貪る食べ方の流れと合わない。"}, "sentence_index": 0, "correct_answer": "唇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "笑うと唇にえくぼができる。", "explanation": "ここは〈頬〉の意味。えくぼは頬にできるもので、唇にはできない。"}, {"text": "乳歯が抜けて、新しい唇が生えてきた。", "explanation": "ここは〈歯〉の意味。生えてくるのは歯で、唇は生えてこない。"}, {"text": "酔って唇が回らず、うまく話せなかった。", "explanation": "ここは〈舌〉の意味。「舌が回らない」は舌の状態で、唇では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52092, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唇", "is_correct": true, "explanation": "悔しさの表現として唇をかむのが自然で、文脈に合う。"}, {"text": "肩", "is_correct": false, "explanation": "肩を強くかむ動作は悔しさの表現にならないので合わない。"}, {"text": "眉", "is_correct": false, "explanation": "眉をかむ動作は成立せず、表現として不自然。"}, {"text": "額", "is_correct": false, "explanation": "額をかむ動作は悔しさの表現にならないので合わない。"}], "explanations": {"唇": "悔しさの表現として唇をかむのが自然で、文脈に合う。", "肩": "肩を強くかむ動作は悔しさの表現にならないので合わない。", "眉": "眉をかむ動作は成立せず、表現として不自然。", "額": "額をかむ動作は悔しさの表現にならないので合わない。"}, "sentence_index": 6, "correct_answer": "唇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は不満そうに唇をひそめた。", "explanation": "ここは〈眉〉の意味。ひそめるのは眉で、唇にはこの動詞を使わない。"}, {"text": "大きなあくびで唇が外れそうになった。", "explanation": "ここは〈顎〉の意味。顎が外れるほどの表現で、唇は外れない。"}, {"text": "彼は唇で窓の外を指さして、笑った。", "explanation": "ここは〈指〉の意味。指さすのは指の動作で、唇では行えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52092, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、唇を乾いて荒れやすい。", "corrected_sentence": "寒い日は、唇が乾いて荒れやすい。", "error_description": "「乾く」は唇が主語になる動詞なので「が」が正しい。「を」にすると目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52092, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "唇をぎゅっと閉めて、涙をこらえた。", "corrected_sentence": "唇をぎゅっと閉じて、涙をこらえた。", "error_description": "唇は「閉じる」もので、「閉める」は戸や蓋に使う動詞。唇には合わないので「閉じて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26ce746e-f716-4418-8fdc-00da21c67bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52095, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す格助詞。「餌を貪り」で貪る対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、餌は貪る対象で主語ではないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表すが、貪る対象を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同を表すが、貪る対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す格助詞。「餌を貪り」で貪る対象を示す。", "が": "主語を表すが、餌は貪る対象で主語ではないので合わない。", "で": "手段・場所を表すが、貪る対象を示せないので合わない。", "と": "共同を表すが、貪る対象を示せないので合わない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52095, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す格助詞。「米を貪るように」で貪る対象を示す。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、貪る対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、貪る対象を示せないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を表すが、貪る対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す格助詞。「米を貪るように」で貪る対象を示す。", "から": "起点を表すが、貪る対象を示せないので合わない。", "より": "比較を表すが、貪る対象を示せないので合わない。", "の": "所属や修飾を表すが、貪る対象を示せないので合わない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52095, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "食べ物を、とてもほしがって、急いで食べること。", "primary_collocate": null, "pronunciation": "むさぼる", "ipa": "mɯsaboɾɯ", "syllable_count": 4, "sentences": [{"text": "空腹の子供たちは、配られたパンを貪って食べた。", "target_word": "貪って", "complexity_tier": "T3", "furigana": "空腹[くうふく]の子供[こども]たちは、配[くば]られたパンを貪[むさぼ]って食[た]べた。", "sentence_source": "generated"}, {"text": "犬は餌を貪り、あっという間に皿を空にした。", "target_word": "貪り", "complexity_tier": "T3", "furigana": "犬[いぬ]は餌[えさ]を貪[むさぼ]り、あっという間[ま]に皿[さら]を空[から]にした。", "sentence_source": "generated"}, {"text": "山で迷った男は、見つけた木の実を貪った。", "target_word": "貪った", "complexity_tier": "T3", "furigana": "山[やま]で迷[まよ]った男[おとこ]は、見[み]つけた木[き]の実[み]を貪[むさぼ]った。", "sentence_source": "generated"}, {"text": "試合のあと、選手たちは弁当を貪っていた。", "target_word": "貪って", "complexity_tier": "T3", "furigana": "試合[しあい]のあと、選手[せんしゅ]たちは弁当[べんとう]を貪[むさぼ]っていた。", "sentence_source": "generated"}, {"text": "彼は朝から何も食べていなかったので、おにぎりを貪るように食べた。", "target_word": "貪る", "complexity_tier": "T3", "furigana": "彼[かれ]は朝[あさ]から何[なに]も食[た]べていなかったので、おにぎりを貪[むさぼ]るように食[た]べた。", "sentence_source": "generated"}, {"text": "腹を空かせた兄は、母が作った煮物を貪り、おかわりまで頼んだ。", "target_word": "貪り", "complexity_tier": "T3", "furigana": "腹[はら]を空[す]かせた兄[あに]は、母[はは]が作[つく]った煮物[にもの]を貪[むさぼ]り、おかわりまで頼[たの]んだ。", "sentence_source": "generated"}, {"text": "野良猫が捨てられた魚を貪っているのを見かけた。", "target_word": "貪って", "complexity_tier": "T3", "furigana": "野良猫[のらねこ]が捨[す]てられた魚[さかな]を貪[むさぼ]っているのを見[み]かけた。", "sentence_source": "generated"}, {"text": "飢えた兵士たちは、わずかな米を貪るように口に運んだ。", "target_word": "貪る", "complexity_tier": "T3", "furigana": "飢[う]えた兵士[へいし]たちは、わずかな米[こめ]を貪[むさぼ]るように口[くち]に運[はこ]んだ。", "sentence_source": "generated"}, {"text": "弟は焼きたてのピザを貪り、熱さで舌をやけどした。", "target_word": "貪り", "complexity_tier": "T3", "furigana": "弟[おとうと]は焼[や]きたてのピザを貪[むさぼ]り、熱[あつ]さで舌[した]をやけどした。", "sentence_source": "generated"}, {"text": "長い登山の末、私たちは山小屋の温かい汁を貪った。", "target_word": "貪った", "complexity_tier": "T3", "furigana": "長[なが]い登山[とざん]の末[すえ]、私[わたし]たちは山小屋[やまごや]の温[あたた]かい汁[しる]を貪[むさぼ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貪る", "label": "辞書形"}, {"form": "貪り", "label": "連用形"}, {"form": "貪って", "label": "て形"}, {"form": "貪った", "label": "た形"}, {"form": "貪らない", "label": "ない形"}, {"form": "貪れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "空腹などで食べ物をがつがつと急いで食べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52095, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "貪って", "is_correct": true, "explanation": "て形で「貪って食べた」と続けて、急いで食べた様子を表す。"}, {"text": "貪る", "is_correct": false, "explanation": "辞書形は「貪る食べた」となり、「食べた」に直接続かない。"}, {"text": "貪った", "is_correct": false, "explanation": "た形は「貪った食べた」となり、文の形として合わない。"}, {"text": "貪れば", "is_correct": false, "explanation": "仮定形は「貪れば食べた」となり、文として続かない。"}], "explanations": {"貪って": "て形で「貪って食べた」と続けて、急いで食べた様子を表す。", "貪る": "辞書形は「貪る食べた」となり、「食べた」に直接続かない。", "貪った": "た形は「貪った食べた」となり、文の形として合わない。", "貪れば": "仮定形は「貪れば食べた」となり、文として続かない。"}, "sentence_index": 0, "correct_answer": "貪って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は差し出された弁当を貪るように、そっと返した。", "explanation": "ここは〈返す〉の意味。貪るは食べる意味で、返す場面では使わないので合わない。"}, {"text": "母はスープを鍋で貪った。", "explanation": "ここは〈温める〉の意味。貪るは加熱する意味ではないので合わない。"}, {"text": "店員はサラダを皿に貪った。", "explanation": "ここは〈盛り付ける〉の意味。貪るは皿に並べる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52095, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貪って", "is_correct": true, "explanation": "て形で「貪っているのを」の形を作り、見かけた様子を表す。"}, {"text": "貪り", "is_correct": false, "explanation": "連用形は「貪りているのを」となり、続かないので合わない。"}, {"text": "貪ら", "is_correct": false, "explanation": "未然形は「貪らているのを」となり、続かないので合わない。"}, {"text": "貪ろう", "is_correct": false, "explanation": "意志形は「貪ろうているのを」となり、続かないので合わない。"}], "explanations": {"貪って": "て形で「貪っているのを」の形を作り、見かけた様子を表す。", "貪り": "連用形は「貪りているのを」となり、続かないので合わない。", "貪ら": "未然形は「貪らているのを」となり、続かないので合わない。", "貪ろう": "意志形は「貪ろうているのを」となり、続かないので合わない。"}, "sentence_index": 6, "correct_answer": "貪って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主は客の器に温かい汁を貪るように注いだ。", "explanation": "ここは〈注ぐ〉の意味。貪るは食べる意味で、器に注ぐ動作には使わない。"}, {"text": "子供は皿に野菜を貪るように並べた。", "explanation": "ここは〈並べる〉の意味。貪るは食べる意味で、皿に並べる場面では使わない。"}, {"text": "母は騒いだ子供を貪った。", "explanation": "ここは〈叱る〉の意味。貪るは叱る意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52095, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空腹の少女は、配られたパンに貪って食べた。", "corrected_sentence": "空腹の少女は、配られたパンを貪って食べた。", "error_description": "誤りは「パンに」。「貪る」は対象を「を」で示すので、「に」は誤り。正しくは「パンを」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "貪り", "is_correct": true, "explanation": "連用形で、「餌を貪り、〜した」と並べる形として正しい。"}, {"text": "貪る", "is_correct": false, "explanation": "辞書形は文を言い切る形で、「、」で続ける形として不自然。"}, {"text": "貪れ", "is_correct": false, "explanation": "命令形で、過去の出来事を述べる文と合わない。"}, {"text": "貪らない", "is_correct": false, "explanation": "ない形で、餌を貪ったという文の意味と合わない。"}], "correct_form": "貪り", "base_form": "貪る", "form_label": "連用形", "sentence_index": 1, "explanations": {"貪り": "連用形で、「餌を貪り、〜した」と並べる形として正しい。", "貪る": "辞書形は文を言い切る形で、「、」で続ける形として不自然。", "貪れ": "命令形で、過去の出来事を述べる文と合わない。", "貪らない": "ない形で、餌を貪ったという文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52095, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "少年は焼きたてのパンを貪りた。", "corrected_sentence": "少年は焼きたてのパンを貪った。", "error_description": "誤りは「貪りた」。連用形「貪り」は「た」の前で音便により「貪っ」となるので、正しくは「貪った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "貪る", "is_correct": true, "explanation": "辞書形で、「貪るように」と続けて、食べる様子を表す。"}, {"text": "貪り", "is_correct": false, "explanation": "連用形は「貪りように」となり、「ように」に続かないので合わない。"}, {"text": "貪ら", "is_correct": false, "explanation": "未然形は「ように」に続かないので合わない。"}, {"text": "貪ろう", "is_correct": false, "explanation": "意志形は「ように」に続かないので合わない。"}], "correct_form": "貪る", "base_form": "貪る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"貪る": "辞書形で、「貪るように」と続けて、食べる様子を表す。", "貪り": "連用形は「貪りように」となり、「ように」に続かないので合わない。", "貪ら": "未然形は「ように」に続かないので合わない。", "貪ろう": "意志形は「ように」に続かないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52096, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す格助詞。「利益ばかりを貪る」で貪る対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、利益は貪る対象で主語ではないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表すが、貪る対象を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を表すが、貪る対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す格助詞。「利益ばかりを貪る」で貪る対象を示す。", "が": "主語を表すが、利益は貪る対象で主語ではないので合わない。", "で": "手段・場所を表すが、貪る対象を示せないので合わない。", "と": "共同の相手を表すが、貪る対象を示せないので合わない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52096, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す格助詞。「権力を貪り」で貪る対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を表すが、「権力に貪る」は不自然で合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、貪る対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、貪る対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す格助詞。「権力を貪り」で貪る対象を示す。", "に": "方向や相手を表すが、「権力に貪る」は不自然で合わない。", "から": "起点を表すが、貪る対象を示せないので合わない。", "より": "比較を表すが、貪る対象を示せないので合わない。"}, "error_tags": {"に": "方向・相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52096, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "欲しがる気持ちが強く、夢中になって何かを食べたり、手に入れたりすること。", "primary_collocate": null, "pronunciation": "むさぼる", "ipa": "mɯsaboɾɯ", "syllable_count": 4, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "貪る", "complexity_tier": "T3", "furigana": "子供[こども]は躊躇[ためら]いなくその表皮[ひょうひ]に歯[は]を立[た]て、甘酸[あまず]っぱい果汁[かじゅう]を唇[くちびる]に伝[つた]わせながら貪[むさぼ]るように食[た]べる。", "sentence_source": "mined"}, {"text": "彼は利益ばかりを貪って、周りの人の苦労を見ようとしなかった。", "target_word": "貪って", "complexity_tier": "T3", "furigana": "彼[かれ]は利益[りえき]ばかりを貪[むさぼ]って、周[まわ]りの人[ひと]の苦労[くろう]を見[み]ようとしなかった。", "sentence_source": "generated"}, {"text": "休日は昼まで惰眠を貪るのが私の楽しみだ。", "target_word": "貪る", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]は昼[ひる]まで惰眠[だみん]を貪[むさぼ]るのが私[わたし]の楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "一部の業者が暴利を貪っているため、市は調査を始めた。", "target_word": "貪って", "complexity_tier": "T3", "furigana": "一部[いちぶ]の業者[ぎょうしゃ]が暴利[ぼうり]を貪[むさぼ]っているため、市[し]は調査[ちょうさ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼は成功しても満足せず、さらに名声を貪った。", "target_word": "貪った", "complexity_tier": "T3", "furigana": "彼[かれ]は成功[せいこう]しても満足[まんぞく]せず、さらに名声[めいせい]を貪[むさぼ]った。", "sentence_source": "generated"}, {"text": "彼は新しい知識を貪り、毎晩遅くまで勉強した。", "target_word": "貪り", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しい知識[ちしき]を貪[むさぼ]り、毎晩[まいばん]遅[おそ]くまで勉強[べんきょう]した。", "sentence_source": "generated"}, {"text": "平和な日々に慣れた人々は、安逸を貪っているうちに危機に気づかなかった。", "target_word": "貪って", "complexity_tier": "T3", "furigana": "平和[へいわ]な日々[ひび]に慣[な]れた人々[ひとびと]は、安逸[あんいつ]を貪[むさぼ]っているうちに危機[きき]に気[き]づかなかった。", "sentence_source": "generated"}, {"text": "彼は権力を貪り、反対する者を次々と追い出した。", "target_word": "貪り", "complexity_tier": "T3", "furigana": "彼[かれ]は権力[けんりょく]を貪[むさぼ]り、反対[はんたい]する者[もの]を次々[つぎつぎ]と追[お]い出[だ]した。", "sentence_source": "generated"}, {"text": "彼女は面白い小説を、夜が明けるまで貪るように読んだ。", "target_word": "貪る", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は面白[おもしろ]い小説[しょうせつ]を、夜[よ]が明[あ]けるまで貪[むさぼ]るように読[よ]んだ。", "sentence_source": "generated"}, {"text": "彼女は空腹のあまり、出されたスープを貪るように飲んだ。", "target_word": "貪る", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は空腹[くうふく]のあまり、出[だ]されたスープを貪[むさぼ]るように飲[の]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貪る", "label": "辞書形"}, {"form": "貪り", "label": "連用形"}, {"form": "貪って", "label": "て形"}, {"form": "貪った", "label": "た形"}, {"form": "貪らない", "label": "ない形"}, {"form": "貪れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "強い欲求から夢中で食べる・手に入れようとする(利益・名声・眠りなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52096, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "貪る", "is_correct": true, "explanation": "辞書形で、「貪るように」と続けて食べる様子を表す。"}, {"text": "貪って", "is_correct": false, "explanation": "て形は「ように」に続かないので合わない。"}, {"text": "貪り", "is_correct": false, "explanation": "連用形は「ように」に続かないので合わない。"}, {"text": "貪れば", "is_correct": false, "explanation": "仮定形は「ように」に続かないので合わない。"}], "explanations": {"貪る": "辞書形で、「貪るように」と続けて食べる様子を表す。", "貪って": "て形は「ように」に続かないので合わない。", "貪り": "連用形は「ように」に続かないので合わない。", "貪れば": "仮定形は「ように」に続かないので合わない。"}, "sentence_index": 0, "correct_answer": "貪る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は差し出されたケーキを貪って断った。", "explanation": "ここは〈断る〉の意味。貪るは欲しがって手に入れる意味で、断る場面とは矛盾する。"}, {"text": "彼女はゆっくり料理を貪った。", "explanation": "ここは〈味わう〉の意味。貪るは急いで夢中で食べる意味で、ゆっくり味わう場面には合わない。"}, {"text": "彼は遠慮して、ケーキを一つだけ貪った。", "explanation": "ここは〈遠慮する〉の意味。貪るは欲しがって取ることなので、控えめにする場面では矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52096, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貪って", "is_correct": true, "explanation": "て形で「貪っている」の形を作り、「うちに」と続けられる。"}, {"text": "貪ら", "is_correct": false, "explanation": "未然形は「貪らているうちに」となり、続かないので合わない。"}, {"text": "貪れ", "is_correct": false, "explanation": "命令形は文脈の「うちに」に続かないので合わない。"}, {"text": "貪ろう", "is_correct": false, "explanation": "意志形は「貪ろうているうちに」となり、続かないので合わない。"}], "explanations": {"貪って": "て形で「貪っている」の形を作り、「うちに」と続けられる。", "貪ら": "未然形は「貪らているうちに」となり、続かないので合わない。", "貪れ": "命令形は文脈の「うちに」に続かないので合わない。", "貪ろう": "意志形は「貪ろうているうちに」となり、続かないので合わない。"}, "sentence_index": 6, "correct_answer": "貪って"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "彼は貧しい人に食料を貪るように寄付した。", "explanation": "ここは〈寄付する〉の意味。貪るは欲しがって手に入れる意味で、与える場面では使わない。"}, {"text": "祖母は庭にハーブを貪った。", "explanation": "ここは〈植える〉の意味。貪るは手に入れる意味で、植える場面では使わない。"}, {"text": "祖母は孫におもちゃを貪った。", "explanation": "ここは〈譲る〉の意味。貪るは人に渡す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52096, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はパンに貪るように食べた。", "corrected_sentence": "彼はパンを貪るように食べた。", "error_description": "誤りは「パンに」。「貪る」は対象を「を」で示すので、「に」は誤り。正しくは「パンを」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "貪って", "is_correct": true, "explanation": "て形で、「利益ばかりを貪って、〜しなかった」と続けられる。"}, {"text": "貪る", "is_correct": false, "explanation": "辞書形で、「貪る、〜」と続けると文の形が合わない。"}, {"text": "貪った", "is_correct": false, "explanation": "た形で、「〜なかった」と続く文の形として合わない。"}, {"text": "貪らない", "is_correct": false, "explanation": "ない形で、利益を貪ったという文の意味と合わない。"}], "correct_form": "貪って", "base_form": "貪る", "form_label": "て形", "sentence_index": 1, "explanations": {"貪って": "て形で、「利益ばかりを貪って、〜しなかった」と続けられる。", "貪る": "辞書形で、「貪る、〜」と続けると文の形が合わない。", "貪った": "た形で、「〜なかった」と続く文の形として合わない。", "貪らない": "ない形で、利益を貪ったという文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52096, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "役人は賄賂を貪りた。", "corrected_sentence": "役人は賄賂を貪った。", "error_description": "誤りは「貪りた」。連用形「貪り」は「た」の前で音便により「貪っ」となるので、正しくは「貪った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "貪り", "is_correct": true, "explanation": "連用形で、「権力を貪り、〜追い出した」と並べる形として正しい。"}, {"text": "貪ら", "is_correct": false, "explanation": "未然形で、「〜た」の文の形として続かない。"}, {"text": "貪れ", "is_correct": false, "explanation": "命令形で、文の流れと合わない。"}, {"text": "貪ろう", "is_correct": false, "explanation": "意志形で、過去の行為を述べる文と合わない。"}], "correct_form": "貪り", "base_form": "貪る", "form_label": "連用形", "sentence_index": 7, "explanations": {"貪り": "連用形で、「権力を貪り、〜追い出した」と並べる形として正しい。", "貪ら": "未然形で、「〜た」の文の形として続かない。", "貪れ": "命令形で、文の流れと合わない。", "貪ろう": "意志形で、過去の行為を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52097, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「抜ける」の主語で、抜けた主体が歯であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「抜ける」は自動詞なので目的語の「を」は合わず、「歯を一本抜けて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示し、「歯に一本抜けて」は主語の位置に入らず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「歯へ一本抜けて」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「抜ける」の主語で、抜けた主体が歯であることを示す。", "を": "「抜ける」は自動詞なので目的語の「を」は合わず、「歯を一本抜けて」は成り立たない。", "に": "「に」は場所や相手を示し、「歯に一本抜けて」は主語の位置に入らず不自然。", "へ": "「へ」は方向を示すので、「歯へ一本抜けて」は成り立たない。"}, "error_tags": {"を": "目的語の誤用", "に": "場所の誤用", "へ": "方向の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
