INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52097, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "口の中にあって、ものをかむための白いもの。", "primary_collocate": null, "pronunciation": "は", "ipa": "ha", "syllable_count": 1, "sentences": [{"text": "食事のあとは、歯を磨きます。", "target_word": "歯", "complexity_tier": "T3", "furigana": "食事[しょくじ]のあとは、歯[は]を磨[みが]きます。", "sentence_source": "generated"}, {"text": "弟は歯が一本抜けて、泣いていた。", "target_word": "歯", "complexity_tier": "T3", "furigana": "弟[おとうと]は歯[は]が一本[いっぽん]抜[ぬ]けて、泣[な]いていた。", "sentence_source": "generated"}, {"text": "歯が痛いので、今日は固い物が食べられない。", "target_word": "歯", "complexity_tier": "T3", "furigana": "歯[は]が痛[いた]いので、今日[きょう]は固[かた]い物[もの]が食[た]べられない。", "sentence_source": "generated"}, {"text": "犬が大きな口を開けて、鋭い歯を見せた。", "target_word": "歯", "complexity_tier": "T3", "furigana": "犬[いぬ]が大[おお]きな口[くち]を開[あ]けて、鋭[するど]い歯[は]を見[み]せた。", "sentence_source": "generated"}, {"text": "りんごをかじったら、歯に皮がはさまった。", "target_word": "歯", "complexity_tier": "T3", "furigana": "りんごをかじったら、歯[は]に皮[かわ]がはさまった。", "sentence_source": "generated"}, {"text": "毎晩、寝る前に歯をていねいに磨く習慣がある。", "target_word": "歯", "complexity_tier": "T3", "furigana": "毎晩[まいばん]、寝[ね]る前[まえ]に歯[は]をていねいに磨[みが]く習慣[しゅうかん]がある。", "sentence_source": "generated"}, {"text": "祖母は八十歳だが、自分の歯がほとんど残っている。", "target_word": "歯", "complexity_tier": "T3", "furigana": "祖母[そぼ]は八十歳[はちじゅっさい]だが、自分[じぶん]の歯[は]がほとんど残[のこ]っている。", "sentence_source": "generated"}, {"text": "冷たい水がしみて、歯がずきずきした。", "target_word": "歯", "complexity_tier": "T3", "furigana": "冷[つめ]たい水[みず]がしみて、歯[は]がずきずきした。", "sentence_source": "generated"}, {"text": "笑うと、彼女の白い歯がきれいに見えた。", "target_word": "歯", "complexity_tier": "T3", "furigana": "笑[わら]うと、彼女[かのじょ]の白[しろ]い歯[は]がきれいに見[み]えた。", "sentence_source": "generated"}, {"text": "赤ちゃんの歯が生えはじめて、よだれが増えた。", "target_word": "歯", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの歯[は]が生[は]えはじめて、よだれが増[ふ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "口の中にある、ものをかむための白いもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: はさまっ (Zipf 2.13)','sentence 7 above tier T2: contains vocabulary far above tier T2: ずきずき (Zipf 1.73)']::text[], '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52097, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歯", "is_correct": true, "explanation": "「歯を磨く」は食後に歯ブラシで手入れする対象を示し、文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は磨く対象にならず、「天気を磨きます」は意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は磨く対象にならず、食事のあとの動作の文脈に合わない。"}, {"text": "海", "is_correct": false, "explanation": "海は磨く対象にならず、「海を磨きます」は食事の文脈で成り立たない。"}], "explanations": {"歯": "「歯を磨く」は食後に歯ブラシで手入れする対象を示し、文脈に合う。", "天気": "天気は磨く対象にならず、「天気を磨きます」は意味が通らない。", "季節": "季節は磨く対象にならず、食事のあとの動作の文脈に合わない。", "海": "海は磨く対象にならず、「海を磨きます」は食事の文脈で成り立たない。"}, "sentence_index": 0, "correct_answer": "歯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "並木の歯が、秋の雨に打たれて散っていた。", "explanation": "ここは〈葉〉（木につく薄い部分）の意味。歯は食べ物をかむ器官で、木の一部には使わない。同じ「は」の音で混同しやすい。"}, {"text": "ドアの隙間に歯をかけて、力いっぱい引いた。", "explanation": "隙間に引っかけて引くのは爪であり、歯では成り立たない。"}, {"text": "つばめが歯をひろげて、夕空へ飛び立った。", "explanation": "ここは〈羽〉（鳥の翼や羽毛）の意味。歯は食べ物をかむ器官で、鳥の翼には使わない。同じ「は」の音で混同しやすい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52097, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歯", "is_correct": true, "explanation": "「自分の歯がほとんど残っている」は高齢者の口の中の歯の残り具合を表し、文脈に合う。"}, {"text": "足音", "is_correct": false, "explanation": "足音は残るものとして文脈に合わず、「自分の足音がほとんど残っている」は意味が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は体の一部ではないので、「自分の雲がほとんど残っている」は成り立たない。"}, {"text": "稲妻", "is_correct": false, "explanation": "稲妻は体に残るものではなく、「自分の稲妻がほとんど残っている」は文脈に合わない。"}], "explanations": {"歯": "「自分の歯がほとんど残っている」は高齢者の口の中の歯の残り具合を表し、文脈に合う。", "足音": "足音は残るものとして文脈に合わず、「自分の足音がほとんど残っている」は意味が通らない。", "雲": "雲は体の一部ではないので、「自分の雲がほとんど残っている」は成り立たない。", "稲妻": "稲妻は体に残るものではなく、「自分の稲妻がほとんど残っている」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "歯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は歯に口紅を塗って、鏡の前で笑った。", "explanation": "口紅を塗るのは唇であり、歯には塗らない。"}, {"text": "歯が回らなくなり、うまく発音できなかった。", "explanation": "発音で回るのは舌であり、歯は回らない。"}, {"text": "雨上がりの道の歯に沿って、子どもたちが走った。", "explanation": "ここは〈端〉（へり、はし）の意味。歯は食べ物をかむ器官で、道のへりには使わない。同じ「は」の音で混同しやすい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52097, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝は、いつも歯が磨いてから家を出る。", "corrected_sentence": "朝は、いつも歯を磨いてから家を出る。", "error_description": "「磨く」の対象は「歯を」で表す。「歯が」と主語の形にしたため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52097, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は歯が痛くった日、お粥しか食べられなかった。", "corrected_sentence": "祖母は歯が痛かった日、お粥しか食べられなかった。", "error_description": "形容詞「痛い」の過去形は「痛かった」。「痛くった」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52098, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「磨く」の直接の目的語で、「歯を磨いている」は自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「歯が磨いている」では歯が磨く主体になり文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示し、「歯に磨いている」は磨く対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すので、磨く対象にはならない。「歯へ磨いている」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「磨く」の直接の目的語で、「歯を磨いている」は自然な文になる。", "が": "「が」は主語を示すので、「歯が磨いている」では歯が磨く主体になり文が成り立たない。", "に": "「に」は場所や相手を示し、「歯に磨いている」は磨く対象を表せない。", "へ": "「へ」は移動の方向を示すので、磨く対象にはならない。「歯へ磨いている」は不自然。"}, "error_tags": {"が": "主語の誤用", "に": "場所の誤用", "へ": "方向の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52098, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食いしばる」は歯を対象にとる動詞で、「歯を」が直接の目的語になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「歯と食いしばった」では対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「歯から食いしばった」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「歯より食いしばった」は文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「食いしばる」は歯を対象にとる動詞で、「歯を」が直接の目的語になる。", "と": "「と」は並列や引用を示すので、「歯と食いしばった」では対象を示せない。", "から": "「から」は起点を示すので、「歯から食いしばった」は成り立たない。", "より": "「より」は比較を示すので、「歯より食いしばった」は文脈に合わない。"}, "error_tags": {"と": "並列・引用の誤用", "から": "起点の誤用", "より": "比較の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52098, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の口の中にある、食べ物をかんだり噛み切ったりするための固い器官。", "primary_collocate": null, "pronunciation": "は", "ipa": "ha", "syllable_count": 1, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "歯", "complexity_tier": "T3", "furigana": "子供[こども]は躊躇[ためら]いなくその表皮[ひょうひ]に歯[は]を立[た]て、甘酸[あまず]っぱい果汁[かじゅう]を唇[くちびる]に伝[つた]わせながら貪[むさぼ]るように食[た]べる。", "sentence_source": "mined"}, {"text": "朝と夜、毎日欠かさず歯を磨いている。", "target_word": "歯", "complexity_tier": "T3", "furigana": "朝[あさ]と夜[よる]、毎日[まいにち]欠[か]かさず歯[は]を磨[みが]いている。", "sentence_source": "generated"}, {"text": "固いせんべいを食べたとき、歯が欠けてしまった。", "target_word": "歯", "complexity_tier": "T3", "furigana": "固[かた]いせんべいを食[た]べたとき、歯[は]が欠[か]けてしまった。", "sentence_source": "generated"}, {"text": "甘い物を食べすぎたせいで、歯が痛くて眠れなかった。", "target_word": "歯", "complexity_tier": "T3", "furigana": "甘[あま]い物[もの]を食[た]べすぎたせいで、歯[は]が痛[いた]くて眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "五歳の妹は、前の歯が抜けて笑うと穴が見える。", "target_word": "歯", "complexity_tier": "T3", "furigana": "五歳[ごさい]の妹[いもうと]は、前[まえ]の歯[は]が抜[ぬ]けて笑[わら]うと穴[あな]が見[み]える。", "sentence_source": "generated"}, {"text": "歯は食べ物を噛み切るために大切な器官だ。", "target_word": "歯", "complexity_tier": "T3", "furigana": "歯[は]は食[た]べ物[もの]を噛[か]み切[き]るために大切[たいせつ]な器官[きかん]だ。", "sentence_source": "generated"}, {"text": "寒さで歯がガチガチと鳴った。", "target_word": "歯", "complexity_tier": "T3", "furigana": "寒[さむ]さで歯[は]がガチガチと鳴[な]った。", "sentence_source": "generated"}, {"text": "痛みに耐えようと、彼は歯を食いしばった。", "target_word": "歯", "complexity_tier": "T3", "furigana": "痛[いた]みに耐[た]えようと、彼[かれ]は歯[は]を食[く]いしばった。", "sentence_source": "generated"}, {"text": "彼は驚くほど白い歯を見せて笑った。", "target_word": "歯", "complexity_tier": "T3", "furigana": "彼[かれ]は驚[おどろ]くほど白[しろ]い歯[は]を見[み]せて笑[わら]った。", "sentence_source": "generated"}, {"text": "赤ちゃんの小さな歯が初めて生えた日、家族みんなで喜んだ。", "target_word": "歯", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの小[ちい]さな歯[は]が初[はじ]めて生[は]えた日[ひ]、家族[かぞく]みんなで喜[よろこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人の口にある、食べ物を噛み切る固い器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 6 words above tier T2 (max 3): 躊躇い (Zipf 2.5), 表皮 (Zipf 3.15), 甘酸っぱい (Zipf 2.99), 果汁 (Zipf 3.45), 伝わ (Zipf 2.78), 貪る (Zipf 2.82)','sentence 7 above tier T2: contains vocabulary far above tier T2: 食いしばっ (Zipf 2.29)']::text[], '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52098, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歯", "is_correct": true, "explanation": "「歯を立てる」は歯で噛みつく動作を表し、表皮に歯を立てるという文脈に合う。"}, {"text": "舌", "is_correct": false, "explanation": "舌は味覚や発声に使う器官で、表皮に立てて噛む動作の主体にはならない。"}, {"text": "唇", "is_correct": false, "explanation": "唇は食べ物を噛む器官ではないので、「唇を立てる」は表皮に食い込む動作として成り立たない。"}, {"text": "頬", "is_correct": false, "explanation": "頬は噛む器官ではなく、「頬を立てる」は食べる動作の文脈に合わない。"}], "explanations": {"歯": "「歯を立てる」は歯で噛みつく動作を表し、表皮に歯を立てるという文脈に合う。", "舌": "舌は味覚や発声に使う器官で、表皮に立てて噛む動作の主体にはならない。", "唇": "唇は食べ物を噛む器官ではないので、「唇を立てる」は表皮に食い込む動作として成り立たない。", "頬": "頬は噛む器官ではなく、「頬を立てる」は食べる動作の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "歯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋になり、庭の木の歯がはらはらと散った。", "explanation": "ここは〈葉〉（木につく薄い部分）の意味。歯は食べ物をかむ器官で、木の一部には使わない。同じ「は」の音で混同しやすい。"}, {"text": "鳥が歯を広げて、いっせいに飛び立った。", "explanation": "ここは〈羽〉（鳥の翼や羽毛）の意味。歯は食べ物をかむ器官で、鳥の翼には使わない。同じ「は」の音で混同しやすい。"}, {"text": "岩のくぼみに歯をかけて、彼は必死によじ登った。", "explanation": "岩のくぼみに引っかけて体を支えるのは指先や爪であり、歯では支えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52098, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歯", "is_correct": true, "explanation": "「寒さで歯がガチガチと鳴る」は寒さによる歯の震えの音を表し、文脈に合う。"}, {"text": "傘", "is_correct": false, "explanation": "傘は寒さで震える体の部位ではないので、「傘がガチガチと鳴った」は文脈に合わない。"}, {"text": "絵", "is_correct": false, "explanation": "絵は寒さで音を立てる対象ではなく、ガチガチという震えの音に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は寒さで音を立てるものではなく、ガチガチと鳴る文脈に合わない。"}], "explanations": {"歯": "「寒さで歯がガチガチと鳴る」は寒さによる歯の震えの音を表し、文脈に合う。", "傘": "傘は寒さで震える体の部位ではないので、「傘がガチガチと鳴った」は文脈に合わない。", "絵": "絵は寒さで音を立てる対象ではなく、ガチガチという震えの音に合わない。", "手紙": "手紙は寒さで音を立てるものではなく、ガチガチと鳴る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "歯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪の日、私は道の歯をそっと歩いた。", "explanation": "ここは〈端〉（へり、はし）の意味。歯は食べ物をかむ器官で、道のへりには使わない。同じ「は」の音で混同しやすい。"}, {"text": "歯が肥えていて、料理の味にうるさい人だ。", "explanation": "味が分かり肥えるのは舌であり、歯は肥えない。"}, {"text": "彼女は歯に紅を引いて、鏡の前で微笑んだ。", "explanation": "紅を引くのは唇であり、歯には引かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52098, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝る前に歯が磨いてから、布団に入った。", "corrected_sentence": "寝る前に歯を磨いてから、布団に入った。", "error_description": "「磨く」の対象は「歯を」で表す。「歯が」と主語の形にしたため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52098, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は痛みに負けず、歯を食いしばりて立ち上がった。", "corrected_sentence": "彼は痛みに負けず、歯を食いしばって立ち上がった。", "error_description": "「食いしばる」のて形は「食いしばって」。「食いしばりて」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52099, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「捨てる」の直接の目的語で、「打算を捨てて」は自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「打算が捨てて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示し、「打算に捨てて」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「打算へ捨てて」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「捨てる」の直接の目的語で、「打算を捨てて」は自然な文になる。", "が": "「が」は主語を示すので、「打算が捨てて」は成り立たない。", "に": "「に」は場所や対象を示し、「打算に捨てて」は不自然。", "へ": "「へ」は方向を示すので、「打算へ捨てて」は成り立たない。"}, "error_tags": {"が": "主語の誤用", "に": "場所の誤用", "へ": "方向の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52099, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ない」の主語で、打算の有無を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「打算をまったくない」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「打算とまったくない」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「打算からまったくない」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「ない」の主語で、打算の有無を示す。", "を": "「を」は目的語を示すので、「打算をまったくない」は文が成り立たない。", "と": "「と」は並列や引用を示すので、「打算とまったくない」は不自然。", "から": "「から」は起点を示すので、「打算からまったくない」は成り立たない。"}, "error_tags": {"を": "目的語の誤用", "と": "並列・引用の誤用", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52099, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分のためになるかどうかを考えること", "primary_collocate": null, "pronunciation": "ださん", "ipa": "dasaɴ", "syllable_count": 3, "sentences": [{"text": "彼がやさしいのは、打算があるからだと思う。", "target_word": "打算", "complexity_tier": "T3", "furigana": "彼[かれ]がやさしいのは、打算[ださん]があるからだと思[おも]う。", "sentence_source": "generated"}, {"text": "打算を捨てて、本当にやりたい仕事を選んだ。", "target_word": "打算", "complexity_tier": "T3", "furigana": "打算[ださん]を捨[す]てて、本当[ほんとう]にやりたい仕事[しごと]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "彼女は打算なしに、毎週ボランティアに参加している。", "target_word": "打算", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は打算[ださん]なしに、毎週[まいしゅう]ボランティアに参加[さんか]している。", "sentence_source": "generated"}, {"text": "友達との付き合いに打算を持ち込みたくない。", "target_word": "打算", "complexity_tier": "T3", "furigana": "友達[ともだち]との付[つ]き合[あ]いに打算[ださん]を持[も]ち込[こ]みたくない。", "sentence_source": "generated"}, {"text": "打算から先輩に近づく後輩を、私は信用しなかった。", "target_word": "打算", "complexity_tier": "T3", "furigana": "打算[ださん]から先輩[せんぱい]に近[ちか]づく後輩[こうはい]を、私[わたし]は信用[しんよう]しなかった。", "sentence_source": "generated"}, {"text": "彼には打算があり、得にならない頼みは必ず断る。", "target_word": "打算", "complexity_tier": "T3", "furigana": "彼[かれ]には打算[ださん]があり、得[とく]にならない頼[たの]みは必[かなら]ず断[ことわ]る。", "sentence_source": "generated"}, {"text": "打算だけで動く人は、困ったときに頼りにならない。", "target_word": "打算", "complexity_tier": "T3", "furigana": "打算[ださん]だけで動[うご]く人[ひと]は、困[こま]ったときに頼[たよ]りにならない。", "sentence_source": "generated"}, {"text": "結婚に打算がまったくないと言えば、うそになるかもしれない。", "target_word": "打算", "complexity_tier": "T3", "furigana": "結婚[けっこん]に打算[ださん]がまったくないと言[い]えば、うそになるかもしれない。", "sentence_source": "generated"}, {"text": "父は打算を抜きにして、見知らぬ人を家に泊めてあげた。", "target_word": "打算", "complexity_tier": "T3", "furigana": "父[ちち]は打算[ださん]を抜[ぬ]きにして、見知[みし]らぬ人[ひと]を家[いえ]に泊[と]めてあげた。", "sentence_source": "generated"}, {"text": "今の態度には打算が見え見えで、聞いていて不愉快だった。", "target_word": "打算", "complexity_tier": "T3", "furigana": "今[いま]の態度[たいど]には打算[ださん]が見[み]え見[み]えで、聞[き]いていて不愉快[ふゆかい]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "打算", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自分の得になるかどうかを考えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52099, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "「やさしいのは打算があるから」は、自分の得を考えるからだという文脈に合う。"}, {"text": "海", "is_correct": false, "explanation": "海は人の態度の理由にならず、「やさしいのは海があるから」は意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は人の態度の理由にならず、「やさしいのは季節があるから」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は人の態度の理由にならず、「やさしいのは天気があるから」は文脈に合わない。"}], "explanations": {"打算": "「やさしいのは打算があるから」は、自分の得を考えるからだという文脈に合う。", "海": "海は人の態度の理由にならず、「やさしいのは海があるから」は意味が通らない。", "季節": "季節は人の態度の理由にならず、「やさしいのは季節があるから」は成り立たない。", "天気": "天気は人の態度の理由にならず、「やさしいのは天気があるから」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レジで金額の打算を間違えたので、店員に謝った。", "explanation": "「打算」は損得の見積もりを表すので、金額の数え間違いには使えない。"}, {"text": "試合の終盤、彼は痛烈な打算をくらった。", "explanation": "「打算」は損得の見積もりを表すので、殴られる衝撃の意味では使えない。"}, {"text": "夏の夜、川辺で花火を打算した。", "explanation": "「打算」は損得の見積もりを表すので、花火を上げる動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52099, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "「打算だけで動く」は損得だけを基準に動くという意味で、文脈に合う。"}, {"text": "足音", "is_correct": false, "explanation": "足音は行動の基準にならず、「足音だけで動く人」は文脈に合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は行動の基準にならず、「雲だけで動く人」は意味が通らない。"}, {"text": "稲妻", "is_correct": false, "explanation": "稲妻は行動の基準にならず、「稲妻だけで動く人」は成り立たない。"}], "explanations": {"打算": "「打算だけで動く」は損得だけを基準に動くという意味で、文脈に合う。", "足音": "足音は行動の基準にならず、「足音だけで動く人」は文脈に合わない。", "雲": "雲は行動の基準にならず、「雲だけで動く人」は意味が通らない。", "稲妻": "稲妻は行動の基準にならず、「稲妻だけで動く人」は成り立たない。"}, "sentence_index": 6, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の打算を払って、みんなで店を出た。", "explanation": "「打算」は損得の見積もりを表すので、代金を払う意味では使えない。"}, {"text": "この状況を打算するには、新しい方法が必要だ。", "explanation": "「打算」は損得の見積もりを表すので、膠着した状況を切り開く意味では使えない。"}, {"text": "彼女は打算の高い選手として、チームを支えている。", "explanation": "「打算」は損得の見積もりを表すので、安打の割合の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52099, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議に打算が持ち込むと、結論がゆがむ。", "corrected_sentence": "会議に打算を持ち込むと、結論がゆがむ。", "error_description": "「持ち込む」の対象は「打算を」で表す。「打算が」と主語の形にしたため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52099, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は打算を捨てるで、仕事を変えた。", "corrected_sentence": "彼は打算を捨てて、仕事を変えた。", "error_description": "「捨てる」のて形は「捨てて」。「捨てるで」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52100, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「あった」の主語で、損得の計算が存在したことを示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「打算へあった」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「打算よりあった」は文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「打算とあった」は存在の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「あった」の主語で、損得の計算が存在したことを示す。", "へ": "「へ」は方向を示すので、「打算へあった」は成り立たない。", "より": "「より」は比較を示すので、「打算よりあった」は文脈に合わない。", "と": "「と」は並列や引用を示すので、「打算とあった」は存在の主語にならない。"}, "error_tags": {"へ": "方向の誤用", "より": "比較の誤用", "と": "並列・引用の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52100, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「からではなく」で、動機や理由の起点として打算を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「打算がではなく」は文の構造を壊す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、動機を表す位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点や対象を示すので、「打算にではなく」は動機を表せない。"}], "correct_answer": "から", "explanations": {"から": "「からではなく」で、動機や理由の起点として打算を示す。", "が": "「が」は主語を示すので、「打算がではなく」は文の構造を壊す。", "を": "「を」は目的語を示すので、動機を表す位置には入らない。", "に": "「に」は帰着点や対象を示すので、「打算にではなく」は動機を表せない。"}, "error_tags": {"が": "主語の誤用", "を": "目的語の誤用", "に": "帰着点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52100, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "打算とは、自分の利益や損得を計算して行動すること。また、そのような考え方。", "primary_collocate": null, "pronunciation": "ださん", "ipa": "dasaɴ", "syllable_count": 3, "sentences": [{"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "打算", "complexity_tier": "T3", "furigana": "そこには、理屈[りくつ]や打算[ださん]といった人為的[じんいてき]な思惑[おもわく]が介在[かいざい]する余地[よち]はなく、ただ生命[せいめい]の根源的[こんげんてき]な渇望[かつぼう]と、眼前[がんぜん]の事物[じぶつ]に対[たい]する純粋[じゅんすい]な受容[じゅよう]があるのみだ。", "sentence_source": "mined"}, {"text": "彼の親切には打算があったと知り、私は少し悲しくなった。", "target_word": "打算", "complexity_tier": "T3", "furigana": "彼[かれ]の親切[しんせつ]には打算[ださん]があったと知[し]り、私[わたし]は少[すこ]し悲[かな]しくなった。", "sentence_source": "generated"}, {"text": "二人は打算だけで結婚したわけではなく、互いを尊敬していた。", "target_word": "打算", "complexity_tier": "T3", "furigana": "二人[ふたり]は打算[ださん]だけで結婚[けっこん]したわけではなく、互[たが]いを尊敬[そんけい]していた。", "sentence_source": "generated"}, {"text": "昇進を狙った打算が働いて、彼は上司の意見に反対しなかった。", "target_word": "打算", "complexity_tier": "T3", "furigana": "昇進[しょうしん]を狙[ねら]った打算[ださん]が働[はたら]いて、彼[かれ]は上司[じょうし]の意見[いけん]に反対[はんたい]しなかった。", "sentence_source": "generated"}, {"text": "彼女は打算抜きで、困っている友人を助けた。", "target_word": "打算", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は打算[ださん]抜[ぬ]きで、困[こま]っている友人[ゆうじん]を助[たす]けた。", "sentence_source": "generated"}, {"text": "打算ばかりの付き合いは長続きしない。", "target_word": "打算", "complexity_tier": "T3", "furigana": "打算[ださん]ばかりの付[つ]き合[あ]いは長続[ながつづ]きしない。", "sentence_source": "generated"}, {"text": "子どもの純粋な好意には、大人のような打算がない。", "target_word": "打算", "complexity_tier": "T3", "furigana": "子[こ]どもの純粋[じゅんすい]な好意[こうい]には、大人[おとな]のような打算[ださん]がない。", "sentence_source": "generated"}, {"text": "私が募金したのは打算からではなく、ただ力になりたかったからだ。", "target_word": "打算", "complexity_tier": "T3", "furigana": "私[わたし]が募金[ぼきん]したのは打算[ださん]からではなく、ただ力[ちから]になりたかったからだ。", "sentence_source": "generated"}, {"text": "ごまかせば得をするという打算が頭をよぎったが、結局は正直に話すことにした。", "target_word": "打算", "complexity_tier": "T3", "furigana": "ごまかせば得[とく]をするという打算[ださん]が頭[あたま]をよぎったが、結局[けっきょく]は正直[しょうじき]に話[はな]すことにした。", "sentence_source": "generated"}, {"text": "打算で人と付き合っていると、本当の友達はできない。", "target_word": "打算", "complexity_tier": "T3", "furigana": "打算[ださん]で人[ひと]と付[つ]き合[あ]っていると、本当[ほんとう]の友達[ともだち]はできない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "打算", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自分の損得を計算して行動する考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52100, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "「理屈や打算といった人為的な思惑」は損得を計算する考え方を指し、文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は人為的な思惑ではないので、「理屈や天気といった思惑」は意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は人為的な思惑を表さず、「理屈や季節といった思惑」は成り立たない。"}, {"text": "海", "is_correct": false, "explanation": "海は人為的な思惑ではなく、「理屈や海といった思惑」は文脈に合わない。"}], "explanations": {"打算": "「理屈や打算といった人為的な思惑」は損得を計算する考え方を指し、文脈に合う。", "天気": "天気は人為的な思惑ではないので、「理屈や天気といった思惑」は意味が通らない。", "季節": "季節は人為的な思惑を表さず、「理屈や季節といった思惑」は成り立たない。", "海": "海は人為的な思惑ではなく、「理屈や海といった思惑」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "おつりの打算を間違えて、店員が謝った。", "explanation": "「打算」は損得の見積もりを表すので、おつりの数え間違いには使えない。"}, {"text": "食事のあと、店の打算を払って店を出た。", "explanation": "「打算」は損得の見積もりを表すので、払う代金の意味では使えない。"}, {"text": "ボクサーは強い打算を受けて倒れた。", "explanation": "「打算」は損得の見積もりを表すので、殴られる衝撃の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52100, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "「大人のような打算がない」は損得を考える態度を指し、子どもの純粋な好意との対比に合う。"}, {"text": "足音", "is_correct": false, "explanation": "足音は好意の性質を表さず、「大人のような足音がない」は意味が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は人の性質を表さず、「大人のような雲がない」は成り立たない。"}, {"text": "稲妻", "is_correct": false, "explanation": "稲妻は人の性質ではなく、「大人のような稲妻がない」は文脈に合わない。"}], "explanations": {"打算": "「大人のような打算がない」は損得を考える態度を指し、子どもの純粋な好意との対比に合う。", "足音": "足音は好意の性質を表さず、「大人のような足音がない」は意味が通らない。", "雲": "雲は人の性質を表さず、「大人のような雲がない」は成り立たない。", "稲妻": "稲妻は人の性質ではなく、「大人のような稲妻がない」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "キーボードで資料の文字を一つずつ打算した。", "explanation": "「打算」は損得の見積もりを表すので、文字入力の動作には使えない。"}, {"text": "この膠着状態を打算するには、第三者の助けが必要だ。", "explanation": "「打算」は損得の見積もりを表すので、膠着した状況を切り開く意味では使えない。"}, {"text": "彼は打算が高く、チームの主力として活躍している。", "explanation": "「打算」は損得の見積もりを表すので、安打の割合の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52100, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の打算を、私は悲しくなった。", "corrected_sentence": "彼の打算に、私は悲しくなった。", "error_description": "「悲しくなる」の原因は「に」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52100, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は打算を持ち込みて、友人の信頼を失った。", "corrected_sentence": "彼は打算を持ち込んで、友人の信頼を失った。", "error_description": "「持ち込む」のて形は「持ち込んで」。「持ち込みて」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52101, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「利害」を「介在している」の主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「介在する」は目的語を取らないので「利害を介在している」は誤り。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「利害で介在している」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「利害へ介在している」は文の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「利害」を「介在している」の主語として示す。", "を": "目的語を示すが、「介在する」は目的語を取らないので「利害を介在している」は誤り。", "で": "手段や場所を示すが、「利害で介在している」は意味が通らない。", "へ": "方向を示すが、「利害へ介在している」は文の主語を示せない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52101, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「偶然」を「介在する」の主語として示す。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示すが、「偶然と介在する」では主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「偶然から介在する」では主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「偶然より介在する」では主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「偶然」を「介在する」の主語として示す。", "と": "並列や共同を示すが、「偶然と介在する」では主語にならない。", "から": "起点を示すが、「偶然から介在する」では主語を示せない。", "より": "比較を示すが、「偶然より介在する」では主語を示せない。"}, "error_tags": {"と": "並列・共同", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52101, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かと何かの間に、別のものが入り込むこと。", "primary_collocate": null, "pronunciation": "かいざい", "ipa": "kaizai", "syllable_count": 4, "sentences": [{"text": "二人の間には、深い誤解が介在していた。", "target_word": "介在", "complexity_tier": "T3", "furigana": "二人[ふたり]の間[あいだ]には、深[ふか]い誤解[ごかい]が介在[かいざい]していた。", "sentence_source": "generated"}, {"text": "この問題には、多くの利害が介在している。", "target_word": "介在", "complexity_tier": "T3", "furigana": "この問題[もんだい]には、多[おお]くの利害[りがい]が介在[かいざい]している。", "sentence_source": "generated"}, {"text": "仲介者が介在すると、話がまとまりやすい。", "target_word": "介在", "complexity_tier": "T3", "furigana": "仲介者[ちゅうかいしゃ]が介在[かいざい]すると、話[はなし]がまとまりやすい。", "sentence_source": "generated"}, {"text": "両国の対立には、宗教の違いが介在している。", "target_word": "介在", "complexity_tier": "T4", "furigana": "両国[りょうこく]の対立[たいりつ]には、宗教[しゅうきょう]の違[ちが]いが介在[かいざい]している。", "sentence_source": "generated"}, {"text": "親子の間に第三者が介在することで、かえって話がこじれた。", "target_word": "介在", "complexity_tier": "T4", "furigana": "親子[おやこ]の間[あいだ]に第三者[だいさんしゃ]が介在[かいざい]することで、かえって話[はなし]がこじれた。", "sentence_source": "generated"}, {"text": "事故の原因には、人の判断ミスが介在していた。", "target_word": "介在", "complexity_tier": "T4", "furigana": "事故[じこ]の原因[げんいん]には、人[ひと]の判断[はんだん]ミスが介在[かいざい]していた。", "sentence_source": "generated"}, {"text": "途中に業者が介在するので、値段が高くなる。", "target_word": "介在", "complexity_tier": "T3", "furigana": "途中[とちゅう]に業者[ぎょうしゃ]が介在[かいざい]するので、値段[ねだん]が高[たか]くなる。", "sentence_source": "generated"}, {"text": "偶然が介在する余地のない、完璧な計画だった。", "target_word": "介在", "complexity_tier": "T4", "furigana": "偶然[ぐうぜん]が介在[かいざい]する余地[よち]のない、完璧[かんぺき]な計画[けいかく]だった。", "sentence_source": "generated"}, {"text": "感情が介在すると、公平な判断が難しくなる。", "target_word": "介在", "complexity_tier": "T3", "furigana": "感情[かんじょう]が介在[かいざい]すると、公平[こうへい]な判断[はんだん]が難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "二人の会話には、常に通訳が介在していた。", "target_word": "介在", "complexity_tier": "T3", "furigana": "二人[ふたり]の会話[かいわ]には、常[つね]に通訳[つうやく]が介在[かいざい]していた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "介在", "label": "基本形"}, {"form": "介在する", "label": "サ変動詞"}, {"form": "介在している", "label": "状態"}, {"form": "介在した", "label": "過去形"}], "register": "やや改まった標準", "sense_fingerprint": "名詞(サ変)。二つのものの間に、別の人・物・事情が入り込んで存在すること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52101, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "介在", "is_correct": true, "explanation": "「深い誤解が〜していた」に入り、間に存在していたという意味が通る。"}, {"text": "謝罪", "is_correct": false, "explanation": "謝る行為の語で、「深い誤解が謝罪していた」は主語と合わず成り立たない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝する行為の語で、誤解が感謝するという文は意味をなさない。"}, {"text": "招待", "is_correct": false, "explanation": "人を招く行為の語で、「深い誤解が招待していた」は主語と合わない。"}], "explanations": {"介在": "「深い誤解が〜していた」に入り、間に存在していたという意味が通る。", "謝罪": "謝る行為の語で、「深い誤解が謝罪していた」は主語と合わず成り立たない。", "感謝": "感謝する行為の語で、誤解が感謝するという文は意味をなさない。", "招待": "人を招く行為の語で、「深い誤解が招待していた」は主語と合わない。"}, "sentence_index": 0, "correct_answer": "介在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼が両社の介在をして、話をまとめた。", "explanation": "ここは〈仲介〉の意味。介在は間に存在する意味で、人が取り持つ行為には使わない。"}, {"text": "大統領が式典に介在して、スピーチをした。", "explanation": "ここは〈出席〉の意味。介在は間に存在する意味で、式典に参加する行為は表せない。"}, {"text": "蚊が病気を介在する。", "explanation": "ここは〈媒介〉の意味。介在は間に存在することで、病気を次へ運ぶ働きは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52101, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "介在", "is_correct": true, "explanation": "「業者が〜するので」に入り、間に入って値段に影響するという意味が通る。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを振り返る語で、「業者が反省するので値段が高くなる」は因果が成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩く行為の語で、業者の動作として文が成り立たない。"}, {"text": "雑談", "is_correct": false, "explanation": "話をする行為の語で、値段が高くなる理由にならず文が通らない。"}], "explanations": {"介在": "「業者が〜するので」に入り、間に入って値段に影響するという意味が通る。", "反省": "自分の行いを振り返る語で、「業者が反省するので値段が高くなる」は因果が成り立たない。", "散歩": "歩く行為の語で、業者の動作として文が成り立たない。", "雑談": "話をする行為の語で、値段が高くなる理由にならず文が通らない。"}, "sentence_index": 6, "correct_answer": "介在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察官が二人の争いに介在して、けんかを止めた。", "explanation": "ここは〈仲裁〉の意味。介在は間に存在する意味で、争いを裁いて収める働きは表せない。"}, {"text": "彼は新車に介在して、お金を払った。", "explanation": "ここは〈購入〉の意味。介在は間に存在する意味で、物を買う行為は表せない。"}, {"text": "彼は実験の結果に介在して、論文にまとめた。", "explanation": "ここは〈整理〉の意味。介在は間に存在する意味で、資料を整える働きは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52101, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その判断には、感情を介在していた。", "corrected_sentence": "その判断には、感情が介在していた。", "error_description": "「介在する」は「が」で主語を示す。「を」は目的語を表すので誤り。正しくは「感情が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52101, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この勝利には、運が介在しいた。", "corrected_sentence": "この勝利には、運が介在していた。", "error_description": "「介在する」の活用で「て」が抜けている。「介在していた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
