INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52103, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がそうなる理由や仕組みを説明する考え方。", "primary_collocate": null, "pronunciation": "りくつ", "ipa": "ɾʲikɯtsɯ", "syllable_count": 3, "sentences": [{"text": "この機械が動く理屈を、先生が図を使って説明してくれた。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "この機械[きかい]が動[うご]く理屈[りくつ]を、先生[せんせい]が図[ず]を使[つか]って説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "飛行機が空を飛ぶ理屈は、意外と単純だ。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が空[そら]を飛[と]ぶ理屈[りくつ]は、意外[いがい]と単純[たんじゅん]だ。", "sentence_source": "generated"}, {"text": "なぜ氷が水に浮くのか、その理屈を知りたい。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "なぜ氷[こおり]が水[みず]に浮[う]くのか、その理屈[りくつ]を知[し]りたい。", "sentence_source": "generated"}, {"text": "彼の説明は理屈が分かりやすくて、すぐに理解できた。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]は理屈[りくつ]が分[わ]かりやすくて、すぐに理解[りかい]できた。", "sentence_source": "generated"}, {"text": "料理には、味がよくなる理屈がちゃんとある。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "料理[りょうり]には、味[あじ]がよくなる理屈[りくつ]がちゃんとある。", "sentence_source": "generated"}, {"text": "てこの理屈を使えば、小さな力で重い石も動かせる。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "てこの理屈[りくつ]を使[つか]えば、小[ちい]さな力[ちから]で重[おも]い石[いし]も動[うご]かせる。", "sentence_source": "generated"}, {"text": "理屈が分かると、数学の問題が楽しくなった。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "理屈[りくつ]が分[わ]かると、数学[すうがく]の問題[もんだい]が楽[たの]しくなった。", "sentence_source": "generated"}, {"text": "兄は電気が通る理屈を、絵を描いて弟に教えた。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "兄[あに]は電気[でんき]が通[とお]る理屈[りくつ]を、絵[え]を描[か]いて弟[おとうと]に教[おし]えた。", "sentence_source": "generated"}, {"text": "「なぜそうなるのか、理屈を教えてください」と生徒が言った。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "「なぜそうなるのか、理屈[りくつ]を教[おし]えてください」と生徒[せいと]が言[い]った。", "sentence_source": "generated"}, {"text": "この方法がうまくいく理屈は、実験の結果を見れば分かる。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "この方法[ほうほう]がうまくいく理屈[りくつ]は、実験[じっけん]の結果[けっか]を見[み]れば分[わ]かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理屈", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事がそうなる理由やしくみを説明する考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52103, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理屈", "is_correct": true, "explanation": "ここは「物事がそうなる仕組み・理由」の意味。「動く理屈を説明する」と自然に続く。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の働きで、機械が動く仕組みを指せず「動く感情を説明する」は成立しない。"}, {"text": "機嫌", "is_correct": false, "explanation": "機嫌は人の気分を表す語で、機械の仕組みには当てはまらない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは機械が動く仕組みを表さず、説明の対象にはならない。"}], "explanations": {"理屈": "ここは「物事がそうなる仕組み・理由」の意味。「動く理屈を説明する」と自然に続く。", "感情": "感情は心の働きで、機械が動く仕組みを指せず「動く感情を説明する」は成立しない。", "機嫌": "機嫌は人の気分を表す語で、機械の仕組みには当てはまらない。", "香り": "香りは機械が動く仕組みを表さず、説明の対象にはならない。"}, "sentence_index": 0, "correct_answer": "理屈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは理屈が濃くて、体が温まる。", "explanation": "ここは「味」の意味。理屈は味の濃さを表さないので、「濃い」とは言えない。"}, {"text": "夕焼けの理屈が空一面に広がっていた。", "explanation": "ここは「色」の意味。理屈は色を持たず、空に広がるものではない。"}, {"text": "廊下から理屈の足音が近づいてきた。", "explanation": "ここは「足音」の意味。理屈は音を立てて近づくものではないので、足音には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52103, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理屈", "is_correct": true, "explanation": "ここは「仕組み・理由」の意味。「理屈が分かる」は、理由がつかめる、という意味で自然。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の量で、「体重が分かると数学が楽しい」とは結びつかない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目の性質で、数学の問題の楽しさとは因果がつながらない。"}, {"text": "手触り", "is_correct": false, "explanation": "手触りは触感で、数学の問題とは関係せず文が成り立たない。"}], "explanations": {"理屈": "ここは「仕組み・理由」の意味。「理屈が分かる」は、理由がつかめる、という意味で自然。", "体重": "体重は身体の量で、「体重が分かると数学が楽しい」とは結びつかない。", "色": "色は見た目の性質で、数学の問題の楽しさとは因果がつながらない。", "手触り": "手触りは触感で、数学の問題とは関係せず文が成り立たない。"}, "sentence_index": 6, "correct_answer": "理屈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この布は理屈が滑らかで、肌によくなじむ。", "explanation": "ここは「手触り」の意味。理屈は触れて感じる性質を持たないので、滑らかさとは言えない。"}, {"text": "このかばんは理屈が高くて、なかなか買えない。", "explanation": "ここは「値段」の意味。理屈は値段を持たないので、高い・安いとは言えない。"}, {"text": "ダイエットの成果で、彼の理屈が三キロ減った。", "explanation": "ここは「体重」の意味。理屈は重さを量れないので、キロ数で減ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52103, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このポンプが水を送る理屈が、父が図で説明してくれた。", "corrected_sentence": "このポンプが水を送る理屈を、父が図で説明してくれた。", "error_description": "正しくは「理屈を説明する」の「を」。「理屈が」は主語を示すが、「説明する」の対象は理屈なので目的語の「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52103, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "理屈が分からると、道具の使い方に迷わなくなる。", "corrected_sentence": "理屈が分かると、道具の使い方に迷わなくなる。", "error_description": "正しくは「分かると」（「分かる」に「と」が続く形）。「分からると」は活用の誤りで、日本語として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52104, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「理屈が通っている」で、理屈が主語になる。文が自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「通っている」は自動詞なので、目的語を示す「を」は付かない。"}, {"text": "か", "is_correct": false, "explanation": "「か」は選択・疑問を表す助詞で、「理屈か通っている」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を表すため、「理屈と通っている」では文意が通らない。"}], "correct_answer": "が", "explanations": {"が": "「理屈が通っている」で、理屈が主語になる。文が自然に成り立つ。", "を": "「通っている」は自動詞なので、目的語を示す「を」は付かない。", "か": "「か」は選択・疑問を表す助詞で、「理屈か通っている」では文が成り立たない。", "と": "「と」は並列や共同を表すため、「理屈と通っている」では文意が通らない。"}, "error_tags": {"を": "自動詞「通る」には目的語が付かない", "か": "選択・疑問の助詞で、通っている文の格関係に入らない", "と": "並列・共同の格で、文の主語関係が崩れる"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52104, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52104, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の道理や筋道。また、論理的に考えられた理由づけ。時に、現実や感情にそぐわない、形式的な理論や言い訳を指すこともある。", "primary_collocate": null, "pronunciation": "りくつ", "ipa": "ɾʲikɯtsɯ", "syllable_count": 3, "sentences": [{"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "理屈", "complexity_tier": "T5", "furigana": "そこには、理屈[りくつ]や打算[ださん]といった人為的[じんいてき]な思惑[おもわく]が介在[かいざい]する余地[よち]はなく、ただ生命[せいめい]の根源的[こんげんてき]な渇望[かつぼう]と、眼前[がんぜん]の事物[じぶつ]に対[たい]する純粋[じゅんすい]な受容[じゅよう]があるのみだ。", "sentence_source": "mined"}, {"text": "彼の話は理屈が通っているので、反対しにくい。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は理屈[りくつ]が通[とお]っているので、反対[はんたい]しにくい。", "sentence_source": "generated"}, {"text": "理屈では分かっていても、気持ちがついていかない。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "理屈[りくつ]では分[わ]かっていても、気持[きも]ちがついていかない。", "sentence_source": "generated"}, {"text": "言い訳ばかりの理屈を並べても、だれも納得しない。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "言い訳[いいわけ]ばかりの理屈[りくつ]を並[なら]べても、だれも納得[なっとく]しない。", "sentence_source": "generated"}, {"text": "子どもは理屈ではなく、感情で動くことが多い。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "子[こ]どもは理屈[りくつ]ではなく、感情[かんじょう]で動[うご]くことが多[おお]い。", "sentence_source": "generated"}, {"text": "彼女は何にでも理屈をつけて、自分のミスを認めようとしない。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なん]にでも理屈[りくつ]をつけて、自分[じぶん]のミスを認[みと]めようとしない。", "sentence_source": "generated"}, {"text": "その計画は理屈の上では完璧だが、実際にやると難しい。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "その計画[けいかく]は理屈[りくつ]の上[うえ]では完璧[かんぺき]だが、実際[じっさい]にやると難[むずか]しい。", "sentence_source": "generated"}, {"text": "会議では、感情的な意見より筋の通った理屈のほうが人を動かす。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、感情的[かんじょうてき]な意見[いけん]より筋[すじ]の通[とお]った理屈[りくつ]のほうが人[ひと]を動[うご]かす。", "sentence_source": "generated"}, {"text": "理屈を言う前に、まず手を動かして作ってみなさい。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "理屈[りくつ]を言[い]う前[まえ]に、まず手[て]を動[うご]かして作[つく]ってみなさい。", "sentence_source": "generated"}, {"text": "祖父は昔気質で、理屈よりも行動で示す人だった。", "target_word": "理屈", "complexity_tier": "T3", "furigana": "祖父[そふ]は昔気質[むかしかたぎ]で、理屈[りくつ]よりも行動[こうどう]で示[しめ]す人[ひと]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理屈", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "筋道の通った論理。感情や現実と対比される理論や言い訳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 6 words above tier T3 (max 3): 打算 (Zipf 2.82), 人為 (Zipf 3.32), 介在 (Zipf 2.95), 渇望 (Zipf 2.92), 眼前 (Zipf 2.87), 事物 (Zipf 2.75)']::text[], 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52104, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理屈", "is_correct": true, "explanation": "ここは「道理・論理」の意味。「理屈や打算」は、人が自分に都合よく組み立てる理由づけを並べる言い方として自然。"}, {"text": "重力", "is_correct": false, "explanation": "物理の重力は、人為的な思惑と並ぶ要素ではないので文が成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は人の思惑と並べて語る対象ではなく、「季節や打算」という組み合わせが不自然。"}, {"text": "香り", "is_correct": false, "explanation": "香りは嗅覚で感じるものであり、人為的な思惑と並ぶ語として不適。"}], "explanations": {"理屈": "ここは「道理・論理」の意味。「理屈や打算」は、人が自分に都合よく組み立てる理由づけを並べる言い方として自然。", "重力": "物理の重力は、人為的な思惑と並ぶ要素ではないので文が成り立たない。", "季節": "季節は人の思惑と並べて語る対象ではなく、「季節や打算」という組み合わせが不自然。", "香り": "香りは嗅覚で感じるものであり、人為的な思惑と並ぶ語として不適。"}, "sentence_index": 0, "correct_answer": "理屈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は理屈が柔らかく、肌触りがいい。", "explanation": "ここは「生地」の意味。理屈は道理や論理を指すので、布の柔らかさには使えない。"}, {"text": "彼女の理屈は、いつも顔に出る。", "explanation": "ここは「感情」の意味。理屈は論理的な筋道なので、表情に表れるものではない。"}, {"text": "花の理屈が、部屋いっぱいに広がっている。", "explanation": "ここは「香り」の意味。理屈は匂いを持たないので、部屋に広がるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52104, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理屈", "is_correct": true, "explanation": "ここは「理論上」の意味。「理屈の上では」は、考え方の上では、という意味で自然。"}, {"text": "疲労", "is_correct": false, "explanation": "疲労は身体の状態を表す語で、計画の完成度を測る語にはならず「疲労の上では完璧」は成立しない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の量を表す語で、計画の出来には当てはまらない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は計画の条件にはなっても完璧さの基準にはならず、「天気の上では完璧」は意味をなさない。"}], "explanations": {"理屈": "ここは「理論上」の意味。「理屈の上では」は、考え方の上では、という意味で自然。", "疲労": "疲労は身体の状態を表す語で、計画の完成度を測る語にはならず「疲労の上では完璧」は成立しない。", "体重": "体重は身体の量を表す語で、計画の出来には当てはまらない。", "天気": "天気は計画の条件にはなっても完璧さの基準にはならず、「天気の上では完璧」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "理屈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱が下がって、理屈が平熱に戻った。", "explanation": "ここは「体温」の意味。理屈は体の温度を表さないので、平熱に戻るとは言えない。"}, {"text": "会議室の理屈が重く、だれも口を開かなかった。", "explanation": "ここは「空気」の意味。理屈は場の雰囲気を表さず、重さで語るのは合わない。"}, {"text": "彼は理屈がおおらかで、人を責めることがない。", "explanation": "ここは「性格」の意味。理屈は人柄を表す語ではないので、おおらかだとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52104, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の説明は理屈を通っていて、みんなが納得した。", "corrected_sentence": "彼女の説明は理屈が通っていて、みんなが納得した。", "error_description": "正しくは「理屈が通る」（自動詞「通る」）。「を」を付けると他動詞扱いになり、「通っている」と合わない。「理屈を通す」（他動詞）とは別の形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52104, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その説明は理屈がしっかり通るていて、だれも反論できなかった。", "corrected_sentence": "その説明は理屈がしっかり通っていて、だれも反論できなかった。", "error_description": "正しくは「通っていて」（「通る」のて形は「通って」）。「通るていて」は活用の誤りで、日本語として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52105, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在を表す「ある」の主語を示す「が」。「思惑があって」と続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「ある」は目的語を取らないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「思惑のあって」では述語が続かず非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「思惑へあって」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "存在を表す「ある」の主語を示す「が」。「思惑があって」と続く。", "を": "目的語を表す「を」。「ある」は目的語を取らないので不自然。", "の": "連体修飾の「の」。「思惑のあって」では述語が続かず非文。", "へ": "方向を表す「へ」。「思惑へあって」は成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52105, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「何か思惑がある」の主語を示す「が」。何らかの狙いが存在することを述べる。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を表す「と」。「思惑とある」では存在の主語を示せず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点や理由を表す「から」。「思惑からある」では存在を述べる文の主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。「思惑よりあるのだ」では比べる対象がなく不自然。"}], "correct_answer": "が", "explanations": {"が": "「何か思惑がある」の主語を示す「が」。何らかの狙いが存在することを述べる。", "と": "並列や引用を表す「と」。「思惑とある」では存在の主語を示せず、文が成り立たない。", "から": "起点や理由を表す「から」。「思惑からある」では存在を述べる文の主語にならない。", "より": "比較を表す「より」。「思惑よりあるのだ」では比べる対象がなく不自然。"}, "error_tags": {"と": "並列・引用", "から": "起点・理由", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52105, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が「こうしたい」「こうなってほしい」と思うこと。", "primary_collocate": null, "pronunciation": "おもわく", "ipa": "omowakɯ", "syllable_count": 4, "sentences": [{"text": "母の思惑では、私は大学で法律を学ぶはずだった。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "母[はは]の思惑[おもわく]では、私[わたし]は大学[だいがく]で法律[ほうりつ]を学[まな]ぶはずだった。", "sentence_source": "generated"}, {"text": "店長には店長なりの思惑があって、そのメニューを決めた。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "店長[てんちょう]には店長[てんちょう]なりの思惑[おもわく]があって、そのメニューを決[き]めた。", "sentence_source": "generated"}, {"text": "計画は私の思惑とは違う方向に進んでしまった。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "計画[けいかく]は私[わたし]の思惑[おもわく]とは違[ちが]う方向[ほうこう]に進[すす]んでしまった。", "sentence_source": "generated"}, {"text": "二人は同じ目標でも、それぞれ違う思惑を持っている。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "二人[ふたり]は同[おな]じ目標[もくひょう]でも、それぞれ違[ちが]う思惑[おもわく]を持[も]っている。", "sentence_source": "generated"}, {"text": "あの人がわざわざ手紙を送ってきた思惑が、私には分からない。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "あの人[ひと]がわざわざ手紙[てがみ]を送[おく]ってきた思惑[おもわく]が、私[わたし]には分[わ]からない。", "sentence_source": "generated"}, {"text": "思惑が外れて、チケットは完売しなかった。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "思惑[おもわく]が外[はず]れて、チケットは完売[かんばい]しなかった。", "sentence_source": "generated"}, {"text": "私の思惑どおり、新商品はよく売れた。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "私[わたし]の思惑[おもわく]どおり、新商品[しんしょうひん]はよく売[う]れた。", "sentence_source": "generated"}, {"text": "先生はあえて何も言わなかった。きっと何か思惑があるのだ。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "先生[せんせい]はあえて何[なに]も言[い]わなかった。きっと何[なに]か思惑[おもわく]があるのだ。", "sentence_source": "generated"}, {"text": "彼女は自分の思惑を隠して、笑顔で話を聞いていた。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の思惑[おもわく]を隠[かく]して、笑顔[えがお]で話[はなし]を聞[き]いていた。", "sentence_source": "generated"}, {"text": "弟の思惑は、兄に宿題を手伝ってもらうことだった。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "弟[おとうと]の思惑[おもわく]は、兄[あに]に宿題[しゅくだい]を手伝[てつだ]ってもらうことだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "思惑", "label": "基本形"}, {"form": "思惑どおり", "label": "慣用的な連語形"}], "register": "neutral", "sense_fingerprint": "こうしたい、こうなってほしいという人の心づもりや願い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52105, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思惑", "is_correct": true, "explanation": "母が望んだ進路という、人の願いを表す語として「母の思惑」と合う。"}, {"text": "方角", "is_correct": false, "explanation": "向きを表す語で、母の望みという文脈には合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "音の流れを表す語で、人の期待を述べる文には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、母が望んだことを表せない。"}], "explanations": {"思惑": "母が望んだ進路という、人の願いを表す語として「母の思惑」と合う。", "方角": "向きを表す語で、母の望みという文脈には合わない。", "旋律": "音の流れを表す語で、人の期待を述べる文には合わない。", "季節": "時期を表す語で、母が望んだことを表せない。"}, "sentence_index": 0, "correct_answer": "思惑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は英語の思惑が豊富で、留学生の質問によく答える。", "explanation": "ここは〈知識〉の意味。思惑は「こうしたい」という心の中の願いや打算を指すので、知っていることの量には使わない。"}, {"text": "今夜の思惑を買って、店を出た。", "explanation": "ここは〈食べ物〉の意味。思惑は人が「こうしたい」と思うことなので、買える食品や品物には使わない。"}, {"text": "雨の思惑が、午後にはやんだ。", "explanation": "ここは〈天候〉の意味。思惑は人が「こうなってほしい」と思うことなので、雨が上がるような天候の変化には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52105, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思惑", "is_correct": true, "explanation": "「私の思惑どおり」という形で、こうなってほしいという願いや狙いを表す。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具を表す語で、「どおり」と続く文脈に合わない。"}, {"text": "照明", "is_correct": false, "explanation": "明かりを指す語で、「〜どおり」の表現には合わない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を指す語で、人の願いを表す文脈とは合わない。"}], "explanations": {"思惑": "「私の思惑どおり」という形で、こうなってほしいという願いや狙いを表す。", "寝具": "寝るための道具を表す語で、「どおり」と続く文脈に合わない。", "照明": "明かりを指す語で、「〜どおり」の表現には合わない。", "天候": "空模様を指す語で、人の願いを表す文脈とは合わない。"}, "sentence_index": 6, "correct_answer": "思惑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この職人は長年の思惑を磨いて、腕を上げた。", "explanation": "ここは〈技術〉の意味。思惑は心の中の願いや打算で、磨いて腕を上げる対象にはならない。"}, {"text": "布を触ると、柔らかい思惑が指に残った。", "explanation": "ここは〈感触〉の意味。思惑は人の願いを表すので、物に触れたときの手ざわりは指せない。"}, {"text": "この絵は思惑が鮮やかで、見る人を引きつける。", "explanation": "ここは〈色彩〉の意味。思惑は人の心の中の願いなので、絵の色づかいには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52105, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父の思惑が外して、弟は就職を選んだ。", "corrected_sentence": "父の思惑が外れて、弟は就職を選んだ。", "error_description": "「外す」は他動詞で目的語を取るため、「思惑が」を主語にできない。自動詞の「外れる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52105, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟の思惑を見え透いていて、みんな笑った。", "corrected_sentence": "弟の思惑が見え透いていて、みんな笑った。", "error_description": "「見え透く」は「〜が見え透く」の形で主語に「が」をとる。「思惑を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52106, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の主語を表す「が」。「何か思惑がある」で、何らかの意図が存在することを述べる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「ある」は目的語を取らないので、ここでは合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」。存在の主語にはならず、ここでは不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「思惑へあるように」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「ある」の主語を表す「が」。「何か思惑がある」で、何らかの意図が存在することを述べる。", "を": "目的語を表す「を」。「ある」は目的語を取らないので、ここでは合わない。", "で": "場所や手段を表す「で」。存在の主語にはならず、ここでは不自然。", "へ": "方向を表す「へ」。「思惑へあるように」は成り立たない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52106, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52106, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の心の中で考えていること。特に、ある目的や期待に基づいた意図や打算。また、心配や懸念。", "primary_collocate": null, "pronunciation": "おもわく", "ipa": "omowakɯ", "syllable_count": 4, "sentences": [{"text": "彼の申し出には、どんな思惑があるのだろう。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "彼[かれ]の申し出[もうしで]には、どんな思惑[おもわく]があるのだろう。", "sentence_source": "generated"}, {"text": "彼の親切には、何か思惑があるように感じた。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "彼[かれ]の親切[しんせつ]には、何[なに]か思惑[おもわく]があるように感[かん]じた。", "sentence_source": "generated"}, {"text": "二つの会社の思惑が食い違い、交渉は進まなかった。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]の思惑[おもわく]が食[く]い違[ちが]い、交渉[こうしょう]は進[すす]まなかった。", "sentence_source": "generated"}, {"text": "周りの思惑を気にしすぎて、自分の意見が言えない。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "周[まわ]りの思惑[おもわく]を気[き]にしすぎて、自分[じぶん]の意見[いけん]が言[い]えない。", "sentence_source": "generated"}, {"text": "思惑どおりに事が運んで、彼は満足そうだった。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "思惑[おもわく]どおりに事[こと]が運[はこ]んで、彼[かれ]は満足[まんぞく]そうだった。", "sentence_source": "generated"}, {"text": "それぞれの思惑が絡み合い、会議は長引いた。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "それぞれの思惑[おもわく]が絡[から]み合[あ]い、会議[かいぎ]は長引[ながび]いた。", "sentence_source": "generated"}, {"text": "彼女は何の思惑もなく、ただ手伝いたかっただけだ。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なん]の思惑[おもわく]もなく、ただ手伝[てつだ]いたかっただけだ。", "sentence_source": "generated"}, {"text": "市場では投資家の思惑で、株価が大きく動いた。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "市場[しじょう]では投資家[とうしか]の思惑[おもわく]で、株価[かぶか]が大[おお]きく動[うご]いた。", "sentence_source": "generated"}, {"text": "政治家たちの思惑が、法案の行方を左右している。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "政治家[せいじか]たちの思惑[おもわく]が、法案[ほうあん]の行方[ゆくえ]を左右[さゆう]している。", "sentence_source": "generated"}, {"text": "相手の思惑を読み取るのは、簡単なことではない。", "target_word": "思惑", "complexity_tier": "T3", "furigana": "相手[あいて]の思惑[おもわく]を読[よ]み取[と]るのは、簡単[かんたん]なことではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "思惑", "label": "基本形"}, {"form": "思惑どおり", "label": "慣用的な連語形"}], "register": "neutral", "sense_fingerprint": "目的や期待に基づく心の中の意図や打算。他人の思惑への懸念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52106, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思惑", "is_correct": true, "explanation": "人の心の中の意図を表し、「どんな思惑があるのだろう」という文脈に合う。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を指す語で、申し出の裏にある狙いとしては合わない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、申し出の裏にある狙いとは合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "音の流れを表す語で、申し出の意図を表せない。"}], "explanations": {"思惑": "人の心の中の意図を表し、「どんな思惑があるのだろう」という文脈に合う。", "天候": "空模様を指す語で、申し出の裏にある狙いとしては合わない。", "季節": "時期を表す語で、申し出の裏にある狙いとは合わない。", "旋律": "音の流れを表す語で、申し出の意図を表せない。"}, "sentence_index": 0, "correct_answer": "思惑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の思惑が夕日に染まって、美しかった。", "explanation": "〈景色〉の意味。思惑は人の心の中の意図を指すので、山の姿には使えない。"}, {"text": "天気の思惑が外れて、傘を持たずに出かけた。", "explanation": "ここは〈予想〉の意味。思惑は人の心の中の意図を指すので、天気には使えない。天気については「予想が外れた」と言う。"}, {"text": "会議室の思惑が重くて、息が詰まりそうだった。", "explanation": "ここは〈雰囲気〉の意味。思惑は人の意図や打算を指すので、場の空気が重いという意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52106, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思惑", "is_correct": true, "explanation": "「下心がない」という文脈で、心の中の打算や意図を表す。"}, {"text": "規模", "is_correct": false, "explanation": "組織や事業の大きさを表す語で、心の中の意図とは合わない。"}, {"text": "順序", "is_correct": false, "explanation": "物事の並び方を表す語で、「何の〜もなく」の文脈に合わない。"}, {"text": "方式", "is_correct": false, "explanation": "やり方や型を表す語で、心の動機を否定する文には合わない。"}], "explanations": {"思惑": "「下心がない」という文脈で、心の中の打算や意図を表す。", "規模": "組織や事業の大きさを表す語で、心の中の意図とは合わない。", "順序": "物事の並び方を表す語で、「何の〜もなく」の文脈に合わない。", "方式": "やり方や型を表す語で、心の動機を否定する文には合わない。"}, "sentence_index": 6, "correct_answer": "思惑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町の思惑は、古い石畳の道沿いに並んでいる。", "explanation": "〈町並み〉の意味。思惑は人の心の中の意図を指すので、建物や道の並びには使えない。"}, {"text": "映画の思惑を、友人に詳しく話した。", "explanation": "ここは〈感想〉の意味。思惑は人の意図や打算を表すので、作品を見ての受け止めには使わない。"}, {"text": "事故の思惑を、警察がていねいに調べた。", "explanation": "ここは〈原因〉の意味。思惑は人の心の中の意図を指すので、事故が起きた理由には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52106, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の思惑を気づいて、距離を置いた。", "corrected_sentence": "彼女の思惑に気づいて、距離を置いた。", "error_description": "「気づく」は「〜に気づく」の形で助詞「に」をとる。「思惑を」は誤りで、正しくは「思惑に気づいて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52106, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼には何か思惑がいる。", "corrected_sentence": "彼には何か思惑がある。", "error_description": "「思惑」は物事として存在するので「ある」を使う。「いる」は人や動物の存在に使うため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52107, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自由」を「渇望して」の目的語として示す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「自由が渇望して」では渇望する対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「自由へ渇望して」は目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や状態を示すが、「自由で渇望して」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「自由」を「渇望して」の目的語として示す。", "が": "主格を示すが、「自由が渇望して」では渇望する対象を示せない。", "へ": "方向を示すが、「自由へ渇望して」は目的語にならない。", "で": "手段や状態を示すが、「自由で渇望して」は意味が通らない。"}, "error_tags": {"が": "主格", "へ": "方向", "で": "手段・状態"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52107, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「渇望」を「向かわせた」の主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「渇望を、彼を留学へと向かわせた」では二つ目の目的語になり不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、「渇望の、」では文の主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「渇望と、彼を」では主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「渇望」を「向かわせた」の主語として示す。", "を": "目的語を示すが、「渇望を、彼を留学へと向かわせた」では二つ目の目的語になり不自然。", "の": "連体修飾を示すが、「渇望の、」では文の主語を示せない。", "と": "並列を示すが、「渇望と、彼を」では主語にならない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52107, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とてもほしいと思うこと。がまんできないくらい、ほしいと思うこと。", "primary_collocate": null, "pronunciation": "かつぼう", "ipa": "kat͡sɯboː", "syllable_count": 4, "sentences": [{"text": "長い戦争のあと、人々は平和を渇望していた。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "長[なが]い戦争[せんそう]のあと、人々[ひとびと]は平和[へいわ]を渇望[かつぼう]していた。", "sentence_source": "generated"}, {"text": "彼は自由を渇望して、故郷を飛び出した。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "彼[かれ]は自由[じゆう]を渇望[かつぼう]して、故郷[こきょう]を飛[と]び出[だ]した。", "sentence_source": "generated"}, {"text": "砂漠を歩く旅人は、一杯の水を渇望した。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "砂漠[さばく]を歩[ある]く旅人[たびびと]は、一杯[いっぱい]の水[みず]を渇望[かつぼう]した。", "sentence_source": "generated"}, {"text": "彼女の心には、認められたいという渇望があった。", "target_word": "渇望", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の心[こころ]には、認[みと]められたいという渇望[かつぼう]があった。", "sentence_source": "generated"}, {"text": "選手は勝利への渇望から、毎日練習を重ねた。", "target_word": "渇望", "complexity_tier": "T4", "furigana": "選手[せんしゅ]は勝利[しょうり]への渇望[かつぼう]から、毎日[まいにち]練習[れんしゅう]を重[かさ]ねた。", "sentence_source": "generated"}, {"text": "愛情への渇望が、彼の行動を支えていた。", "target_word": "渇望", "complexity_tier": "T4", "furigana": "愛情[あいじょう]への渇望[かつぼう]が、彼[かれ]の行動[こうどう]を支[ささ]えていた。", "sentence_source": "generated"}, {"text": "病室の少年は、外の空気を渇望していた。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "病室[びょうしつ]の少年[しょうねん]は、外[そと]の空気[くうき]を渇望[かつぼう]していた。", "sentence_source": "generated"}, {"text": "新しい知識に対する渇望が、彼を留学へと向かわせた。", "target_word": "渇望", "complexity_tier": "T4", "furigana": "新[あたら]しい知識[ちしき]に対[たい]する渇望[かつぼう]が、彼[かれ]を留学[りゅうがく]へと向[む]かわせた。", "sentence_source": "generated"}, {"text": "長年の渇望がかない、彼はついに頂上に立った。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "長年[ながねん]の渇望[かつぼう]がかない、彼[かれ]はついに頂上[ちょうじょう]に立[た]った。", "sentence_source": "generated"}, {"text": "彼は成功を渇望するあまり、休むことを忘れた。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "彼[かれ]は成功[せいこう]を渇望[かつぼう]するあまり、休[やす]むことを忘[わす]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "渇望", "label": "基本形"}, {"form": "渇望する", "label": "サ変動詞"}, {"form": "渇望した", "label": "過去形"}, {"form": "渇望している", "label": "状態"}], "register": "やや改まった書き言葉寄り", "sense_fingerprint": "名詞(サ変)。水や自由、愛情などを、がまんできないほど強く求めること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52107, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渇望", "is_correct": true, "explanation": "「平和を」に続き、強く求めるという意味で空所に入り文が通る。"}, {"text": "散歩", "is_correct": false, "explanation": "歩く行為の語で、「平和を散歩していた」は成り立たない。"}, {"text": "宿泊", "is_correct": false, "explanation": "泊まる行為の語で、「平和を宿泊していた」は意味をなさない。"}, {"text": "雑談", "is_correct": false, "explanation": "話をする行為の語で、「平和を雑談していた」は目的語と合わない。"}], "explanations": {"渇望": "「平和を」に続き、強く求めるという意味で空所に入り文が通る。", "散歩": "歩く行為の語で、「平和を散歩していた」は成り立たない。", "宿泊": "泊まる行為の語で、「平和を宿泊していた」は意味をなさない。", "雑談": "話をする行為の語で、「平和を雑談していた」は目的語と合わない。"}, "sentence_index": 0, "correct_answer": "渇望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は将来に、ささやかな渇望を抱いていた。", "explanation": "ここは〈希望〉の意味。渇望は強く満たされない欲求を指すので、ささやかな望みには使わない。"}, {"text": "来年の渇望として、英語の勉強を続けると決めた。", "explanation": "ここは〈目標〉の意味。渇望は強い感情で、計画として立てる目標の意味は持たない。"}, {"text": "彼女の渇望に合う服を選んだ。", "explanation": "ここは〈好み〉の意味。渇望は強い欲求で、服の趣味に合うという意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52107, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渇望", "is_correct": true, "explanation": "「外の空気を」に続き、強く求めるという意味で空所に入り文が通る。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼む行為の語で、「外の空気を注文していた」は成り立たない。"}, {"text": "運転", "is_correct": false, "explanation": "乗り物を操る行為の語で、「外の空気を運転していた」は意味をなさない。"}, {"text": "採点", "is_correct": false, "explanation": "答えを評価する行為の語で、「外の空気を採点していた」は文が通らない。"}], "explanations": {"渇望": "「外の空気を」に続き、強く求めるという意味で空所に入り文が通る。", "注文": "品物を頼む行為の語で、「外の空気を注文していた」は成り立たない。", "運転": "乗り物を操る行為の語で、「外の空気を運転していた」は意味をなさない。", "採点": "答えを評価する行為の語で、「外の空気を採点していた」は文が通らない。"}, "sentence_index": 6, "correct_answer": "渇望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "少しだけ、彼はその本を渇望した。", "explanation": "ここは〈ちょっと欲しい〉の意味。渇望は強く求める気持ちで、軽い望みには使わない。"}, {"text": "夏の午後、彼はのどが渇望して、一気に水を飲んだ。", "explanation": "ここは〈のどの渇き〉の意味。渇望は心の強い欲求を指すので、体の渇きは表さない。"}, {"text": "彼は約束の時間を渇望して、遅刻した。", "explanation": "ここは〈軽んじる〉の意味。渇望は強く求める気持ちで、時間を軽んじる態度は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52107, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は長い間、名誉に渇望していた。", "corrected_sentence": "彼は長い間、名誉を渇望していた。", "error_description": "「渇望する」は「を」で目的語を示す。「名誉に」の「に」は誤り。正しくは「名誉を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52107, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "少年は、外の世界を渇望いた。", "corrected_sentence": "少年は、外の世界を渇望していた。", "error_description": "サ変動詞「する」の活用が抜けている。「渇望していた」が正しく、「して」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
