INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52109, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするための可能性や自由が残っているスペースのこと。", "primary_collocate": null, "pronunciation": "よち", "ipa": "jotɕi", "syllable_count": 2, "sentences": [{"text": "満員電車では、足を動かす余地さえなかった。", "target_word": "余地", "complexity_tier": "T3", "furigana": "満員(まんいん)電車(でんしゃ)では、足(あし)を動(うご)かす余地(よち)さえなかった。", "sentence_source": "generated"}, {"text": "部屋が狭くて、新しい本棚を置く余地がない。", "target_word": "余地", "complexity_tier": "T3", "furigana": "部屋(へや)が狭(せま)くて、新(あたら)しい本棚(ほんだな)を置(お)く余地(よち)がない。", "sentence_source": "generated"}, {"text": "この文章にはまだ直す余地が残っている。", "target_word": "余地", "complexity_tier": "T3", "furigana": "この文章(ぶんしょう)にはまだ直(なお)す余地(よち)が残(のこ)っている。", "sentence_source": "generated"}, {"text": "結果が決まるまで、逆転の余地は十分にある。", "target_word": "余地", "complexity_tier": "T3", "furigana": "結果(けっか)が決(き)まるまで、逆転(ぎゃくてん)の余地(よち)は十分(じゅうぶん)にある。", "sentence_source": "generated"}, {"text": "彼の話は筋が通っていて、疑う余地がなかった。", "target_word": "余地", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はなし)は筋(すじ)が通(とお)っていて、疑(うたが)う余地(よち)がなかった。", "sentence_source": "generated"}, {"text": "駐車場は車でいっぱいで、もう止める余地がなかった。", "target_word": "余地", "complexity_tier": "T3", "furigana": "駐車場(ちゅうしゃじょう)は車(くるま)でいっぱいで、もう止(と)める余地(よち)がなかった。", "sentence_source": "generated"}, {"text": "予算に余裕があるので、計画を変更する余地はある。", "target_word": "余地", "complexity_tier": "T3", "furigana": "予算(よさん)に余裕(よゆう)があるので、計画(けいかく)を変更(へんこう)する余地(よち)はある。", "sentence_source": "generated"}, {"text": "この問題には、いろいろな解釈が成り立つ余地がある。", "target_word": "余地", "complexity_tier": "T4", "furigana": "この問題(もんだい)には、いろいろな解釈(かいしゃく)が成(な)り立(た)つ余地(よち)がある。", "sentence_source": "generated"}, {"text": "彼女の予定は詰まっていて、休む余地もない。", "target_word": "余地", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の予定(よてい)は詰(つ)まっていて、休(やす)む余地(よち)もない。", "sentence_source": "generated"}, {"text": "庭には、花を植える余地がまだ少し残っている。", "target_word": "余地", "complexity_tier": "T3", "furigana": "庭(にわ)には、花(はな)を植(う)える余地(よち)がまだ少(すこ)し残(のこ)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余地", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かをする余裕・隙間が残っていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52109, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余地", "is_correct": true, "explanation": "「足を動かす余地さえなかった」と、体を動かす空間の余裕を表し、文脈に合う。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、足を動かす空間の文脈には合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "音の流れを表す語で、足の動きとは意味が通らない。"}, {"text": "色彩", "is_correct": false, "explanation": "色のまとまりを表す語で、「足を動かす」文には入らない。"}], "explanations": {"余地": "「足を動かす余地さえなかった」と、体を動かす空間の余裕を表し、文脈に合う。", "季節": "時期を表す語で、足を動かす空間の文脈には合わない。", "旋律": "音の流れを表す語で、足の動きとは意味が通らない。", "色彩": "色のまとまりを表す語で、「足を動かす」文には入らない。"}, "sentence_index": 0, "correct_answer": "余地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアの余地から、光が差し込んでいた。", "explanation": "ここは〈隙間〉の意味。余地は行動や物を置くための余裕のあるスペースを指すので、ドアのすき間から光が入るような意味では使わない。"}, {"text": "コンサートの余地が、夜まで続いていた。", "explanation": "ここは〈余韻〉の意味。余地は行動の余裕の範囲で、音や感動が残る様子には使わない。"}, {"text": "廊下に余地が響いて、誰かが来たと分かった。", "explanation": "ここは〈足音〉の意味。余地は音を出す語ではなく空間の余裕を指すので、響く対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52109, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余地", "is_correct": true, "explanation": "「計画を変更する余地はある」と、変更の可能性の範囲を表す。"}, {"text": "照明", "is_correct": false, "explanation": "明かりを指す語で、計画を変更するという文脈には合わない。"}, {"text": "方角", "is_correct": false, "explanation": "向きを表す語で、計画の変更とは意味が通らない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具を表す語で、計画の変更には合わない。"}], "explanations": {"余地": "「計画を変更する余地はある」と、変更の可能性の範囲を表す。", "照明": "明かりを指す語で、計画を変更するという文脈には合わない。", "方角": "向きを表す語で、計画の変更とは意味が通らない。", "寝具": "寝るための道具を表す語で、計画の変更には合わない。"}, "sentence_index": 6, "correct_answer": "余地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作業には、余地がかかった。", "explanation": "ここは〈時間〉の意味。余地は行動の可能性や場所の範囲を指すので、作業にかかる長さは表せない。"}, {"text": "壁の余地を、きれいに落とした。", "explanation": "ここは〈汚れ〉の意味。余地は余裕の範囲を表し、落としたり拭き取ったりする対象にはならない。"}, {"text": "この料理は余地が濃くて、ご飯がすすむ。", "explanation": "ここは〈味〉の意味。余地は範囲や空きを表すので、料理の味の濃さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52109, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この棚にはまだ本を並べる余地で、ある。", "corrected_sentence": "この棚にはまだ本を並べる余地がある。", "error_description": "「ある」は存在するものを「が」で示す。「で」は場所や手段を表し、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52109, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の話には、疑う余地をない。", "corrected_sentence": "彼女の話には、疑う余地がない。", "error_description": "「ない」は存在・否定の主語を「が」で示す。「を」は目的語を表し、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52110, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52110, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す「を」。「大切にする」の対象を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「余地へ大切にしている」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」。「大切にする」の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "相手や共同を表す「と」。「余地と大切にしている」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す「を」。「大切にする」の対象を表す。", "へ": "方向を表す「へ」。「余地へ大切にしている」は成り立たない。", "で": "場所や手段を表す「で」。「大切にする」の対象にはならない。", "と": "相手や共同を表す「と」。「余地と大切にしている」は成り立たない。"}, "error_tags": {"へ": "方向", "で": "場所・手段", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52110, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "行動や判断をするときに、選べる可能性や自由の範囲。また、そうした選択が許される空間。", "primary_collocate": null, "pronunciation": "よち", "ipa": "jotɕi", "syllable_count": 2, "sentences": [{"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "余地", "complexity_tier": "T4", "furigana": "そこには、理屈(りくつ)や打算(ださん)といった人為的(じんいてき)な思惑(おもわく)が介在(かいざい)する余地(よち)はなく、ただ生命(せいめい)の根源的(こんげんてき)な渇望(かつぼう)と、眼前(がんぜん)の事物(じぶつ)に対(たい)する純粋(じゅんすい)な受容(じゅよう)があるのみだ。", "sentence_source": "mined"}, {"text": "彼の無実は明らかで、疑う余地はまったくない。", "target_word": "余地", "complexity_tier": "T3", "furigana": "彼(かれ)の無実(むじつ)は明(あき)らかで、疑(うたが)う余地(よち)はまったくない。", "sentence_source": "generated"}, {"text": "この計画にはまだ改善の余地が大いにある。", "target_word": "余地", "complexity_tier": "T3", "furigana": "この計画(けいかく)にはまだ改善(かいぜん)の余地(よち)が大(おお)いにある。", "sentence_source": "generated"}, {"text": "契約の条件は決まっていて、交渉の余地はほとんど残されていない。", "target_word": "余地", "complexity_tier": "T3", "furigana": "契約(けいやく)の条件(じょうけん)は決(き)まっていて、交渉(こうしょう)の余地(よち)はほとんど残(のこ)されていない。", "sentence_source": "generated"}, {"text": "時間がなかったので、私には選択の余地がなかった。", "target_word": "余地", "complexity_tier": "T3", "furigana": "時間(じかん)がなかったので、私(わたし)には選択(せんたく)の余地(よち)がなかった。", "sentence_source": "generated"}, {"text": "証拠がそろっているため、被告に弁解の余地はなかった。", "target_word": "余地", "complexity_tier": "T3", "furigana": "証拠(しょうこ)がそろっているため、被告(ひこく)に弁解(べんかい)の余地(よち)はなかった。", "sentence_source": "generated"}, {"text": "新しい意見を取り入れる余地を、会議の進め方に残しておくべきだ。", "target_word": "余地", "complexity_tier": "T3", "furigana": "新(あたら)しい意見(いけん)を取(と)り入(い)れる余地(よち)を、会議(かいぎ)の進(すす)め方(かた)に残(のこ)しておくべきだ。", "sentence_source": "generated"}, {"text": "先生は生徒の自主性が育つ余地を大切にしている。", "target_word": "余地", "complexity_tier": "T3", "furigana": "先生(せんせい)は生徒(せいと)の自主性(じしゅせい)が育(そだ)つ余地(よち)を大切(たいせつ)にしている。", "sentence_source": "generated"}, {"text": "彼女の決意は固く、説得する余地はないと分かった。", "target_word": "余地", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の決意(けつい)は固(かた)く、説得(せっとく)する余地(よち)はないと分(わ)かった。", "sentence_source": "generated"}, {"text": "規則が細かすぎて、現場の判断が入る余地がない。", "target_word": "余地", "complexity_tier": "T3", "furigana": "規則(きそく)が細(こま)かすぎて、現場(げんば)の判断(はんだん)が入(はい)る余地(よち)がない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余地", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "選択や判断の可能性・自由が残る範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 6 words above tier T3 (max 3): 打算 (Zipf 2.82), 人為 (Zipf 3.32), 介在 (Zipf 2.95), 渇望 (Zipf 2.92), 眼前 (Zipf 2.87), 事物 (Zipf 2.75)']::text[], 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52110, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余地", "is_correct": true, "explanation": "「介在する余地はなく」と、選べる可能性の範囲が残らないことを表し、文脈に合う。"}, {"text": "旋律", "is_correct": false, "explanation": "音の流れを表す語で、「介在する」ものとして意味が通らない。"}, {"text": "方角", "is_correct": false, "explanation": "向きを表す語で、人為的な介在という文脈とは合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "色のまとまりを表す語で、「介在する」ものとしては成り立たない。"}], "explanations": {"余地": "「介在する余地はなく」と、選べる可能性の範囲が残らないことを表し、文脈に合う。", "旋律": "音の流れを表す語で、「介在する」ものとして意味が通らない。", "方角": "向きを表す語で、人為的な介在という文脈とは合わない。", "色彩": "色のまとまりを表す語で、「介在する」ものとしては成り立たない。"}, "sentence_index": 0, "correct_answer": "余地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布の中の余地を数えた。", "explanation": "ここは〈お金〉の意味。余地は選べる可能性や空いている空間を指すので、数えられる硬貨や紙幣には使わない。"}, {"text": "壁の余地から、冷たい風が入ってくる。", "explanation": "ここは〈隙間〉の意味。余地は判断や行動の自由を表し、壁のすき間を指さない。"}, {"text": "料理の余地は、明日のお弁当に入れよう。", "explanation": "ここは〈余り〉の意味。余地は可能性の範囲で、食べ残しの量には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52110, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余地", "is_correct": true, "explanation": "「取り入れる余地を残す」と、意見を受け入れる可能性の範囲を表す。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具を表す語で、意見を取り入れる文脈には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、意見を取り入れる範囲を表せない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を指す語で、この文の意味が通らない。"}], "explanations": {"余地": "「取り入れる余地を残す」と、意見を受け入れる可能性の範囲を表す。", "寝具": "寝るための道具を表す語で、意見を取り入れる文脈には合わない。", "季節": "時期を表す語で、意見を取り入れる範囲を表せない。", "天候": "空模様を指す語で、この文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "余地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転職のよい余地を逃して、後悔している。", "explanation": "ここは〈機会〉の意味。余地は可能性の範囲で、チャンスそのものとして逃すものではないので合わない。"}, {"text": "この部屋は余地が高くて、開放感がある。", "explanation": "ここは〈天井〉の意味。余地は選択の範囲を表し、建物の高さには使わない。"}, {"text": "大会で新しい余地を出して、優勝した。", "explanation": "ここは〈記録〉の意味。余地は選べる範囲で、競技の成績として出すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52110, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この案には、まだ検討する余地を残っている。", "corrected_sentence": "この案には、まだ検討する余地が残っている。", "error_description": "「残っている」は自動詞で、主語を「が」で示す。「を」は他動詞「残す」の目的語にしか使えず、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52110, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女には、反論する余地などあった。", "corrected_sentence": "彼女には、反論する余地などなかった。", "error_description": "「〜など」は否定の文脈で使うので、「余地などあった」は不自然。否定の「なかった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52111, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「並んでいる」の主語を示す「が」。事物が主語となり正しい。"}, {"text": "を", "is_correct": false, "explanation": "「並ぶ」は目的語をとらない自動詞なので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、主語を示す役割にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「事物から並んでいる」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「並んでいる」の主語を示す「が」。事物が主語となり正しい。", "を": "「並ぶ」は目的語をとらない自動詞なので、「を」は合わない。", "で": "「で」は場所や手段を表すので、主語を示す役割にはならない。", "から": "「から」は起点を表すので、「事物から並んでいる」は意味が通らない。"}, "error_tags": {"を": "自動詞に目的語（誤）", "で": "場所・手段（誤）", "から": "起点（誤）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52111, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52111, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "目に見えるものや、手で触れられるもののことです。", "primary_collocate": null, "pronunciation": "じぶつ", "ipa": "dʑibɯtsɯ", "syllable_count": 3, "sentences": [{"text": "机や椅子のように、手で触れられる事物を数えてみた。", "target_word": "事物", "complexity_tier": "T3", "furigana": "机(つくえ)や椅子(いす)のように、手(て)で触(ふ)れられる事物(じぶつ)を数(かぞ)えてみた。", "sentence_source": "generated"}, {"text": "展覧会には、昔の暮らしを伝える事物が並んでいる。", "target_word": "事物", "complexity_tier": "T3", "furigana": "展覧会(てんらんかい)には、昔(むかし)の暮(く)らしを伝(つた)える事物(じぶつ)が並(なら)んでいる。", "sentence_source": "generated"}, {"text": "幼い子は、身近な事物を指さして名前を聞く。", "target_word": "事物", "complexity_tier": "T3", "furigana": "幼(おさな)い子(こ)は、身近(みぢか)な事物(じぶつ)を指(ゆび)さして名前(なまえ)を聞(き)く。", "sentence_source": "generated"}, {"text": "彼は、目の前の事物を丁寧にスケッチした。", "target_word": "事物", "complexity_tier": "T3", "furigana": "彼(かれ)は、目(め)の前(まえ)の事物(じぶつ)を丁寧(ていねい)にスケッチした。", "sentence_source": "generated"}, {"text": "理科の授業では、実際の事物を使って実験する。", "target_word": "事物", "complexity_tier": "T3", "furigana": "理科(りか)の授業(じゅぎょう)では、実際(じっさい)の事物(じぶつ)を使(つか)って実験(じっけん)する。", "sentence_source": "generated"}, {"text": "暗い部屋では、事物の形がはっきり見えない。", "target_word": "事物", "complexity_tier": "T3", "furigana": "暗(くら)い部屋(へや)では、事物(じぶつ)の形(かたち)がはっきり見(み)えない。", "sentence_source": "generated"}, {"text": "外国語を学ぶとき、まず身の回りの事物の名前から覚えた。", "target_word": "事物", "complexity_tier": "T3", "furigana": "外国語(がいこくご)を学(まな)ぶとき、まず身(み)の回(まわ)りの事物(じぶつ)の名前(なまえ)から覚(おぼ)えた。", "sentence_source": "generated"}, {"text": "霧が深くて、周りの事物がぼんやりとしか見えなかった。", "target_word": "事物", "complexity_tier": "T3", "furigana": "霧(きり)が深(ふか)くて、周(まわ)りの事物(じぶつ)がぼんやりとしか見(み)えなかった。", "sentence_source": "generated"}, {"text": "写真は、その場にあった事物をそのまま記録する。", "target_word": "事物", "complexity_tier": "T3", "furigana": "写真(しゃしん)は、その場(ば)にあった事物(じぶつ)をそのまま記録(きろく)する。", "sentence_source": "generated"}, {"text": "手で触れられる事物は、頭の中の考えより理解しやすい。", "target_word": "事物", "complexity_tier": "T3", "furigana": "手(て)で触(ふ)れられる事物(じぶつ)は、頭(あたま)の中(なか)の考(かんが)えより理解(りかい)しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事物", "label": "基本形"}], "register": "書き言葉（やや硬い）", "sense_fingerprint": "目に見え手で触れられる具体的な物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52111, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "手で触れられる物を指し、「数えてみた」対象として文意に合う。"}, {"text": "気配", "is_correct": false, "explanation": "感じ取るもので、手で触れられるものではないので合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "耳で聞くもので、手で触れられない。"}, {"text": "匂い", "is_correct": false, "explanation": "鼻で嗅ぐもので、手で触れられる対象ではない。"}], "explanations": {"事物": "手で触れられる物を指し、「数えてみた」対象として文意に合う。", "気配": "感じ取るもので、手で触れられるものではないので合わない。", "旋律": "耳で聞くもので、手で触れられない。", "匂い": "鼻で嗅ぐもので、手で触れられる対象ではない。"}, "sentence_index": 0, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒さで、指先の事物がすっかりなくなった。", "explanation": "〈感覚〉の意味。感覚は体で感じる働きで、目で見たり手で触れたりできる物とは合わない。"}, {"text": "遠くから響いてくる事物を、彼は耳を澄まして聞き取った。", "explanation": "〈音〉の意味。音は耳で聞くもので、目で見たり手で触れたりできる物ではないので合わない。"}, {"text": "幼い頃の思い出という事物を、彼は今も大切にしまっている。", "explanation": "ここは〈記憶〉の意味で使っている。事物は手で触れられる物を指すので、頭の中にしまっておく記憶には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52111, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "「身の回りの事物の名前」として、身の回りの物を指し、文意に合う。"}, {"text": "痛み", "is_correct": false, "explanation": "体で感じる感覚で、名前を覚える対象の物にはならない。"}, {"text": "温もり", "is_correct": false, "explanation": "肌で感じるもので、名前を覚える対象の物とは合わない。"}, {"text": "感触", "is_correct": false, "explanation": "手で触れて感じるもので、名前を覚える対象の物とは合わない。"}], "explanations": {"事物": "「身の回りの事物の名前」として、身の回りの物を指し、文意に合う。", "痛み": "体で感じる感覚で、名前を覚える対象の物にはならない。", "温もり": "肌で感じるもので、名前を覚える対象の物とは合わない。", "感触": "手で触れて感じるもので、名前を覚える対象の物とは合わない。"}, "sentence_index": 6, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の事物が部屋いっぱいに広がり、気持ちがよかった。", "explanation": "〈香り〉の意味。香りは鼻で感じるもので、目で見たり手で触れたりできる物ではない。"}, {"text": "来月の旅行の事物は、もう決まっている。", "explanation": "〈計画〉の意味。計画は未来の予定で、今ある物を指す事物とは合わない。"}, {"text": "彼女の事物は穏やかで、皆に好かれている。", "explanation": "〈性格〉の意味。性格は人の心の性質で、現実に存在する物を指す事物とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52111, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は床に落ちていた事物で手に取った。", "corrected_sentence": "彼は床に落ちていた事物を手に取った。", "error_description": "「手に取る」は目的語に「を」をとる。「事物で」の「で」は手段を表すので目的語として誤り。正しくは「事物を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52111, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは庭の事物に一つずつ集めた。", "corrected_sentence": "子どもたちは庭の事物を一つずつ集めた。", "error_description": "「集める」は目的語に「を」をとる。「事物に」の「に」が誤りで、正しくは「事物を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52112, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「興味を示す」の相手（対象）を表す「に」。「事物に」で文意に合う。"}, {"text": "が", "is_correct": false, "explanation": "「事物が」にすると事物が「示す」の主語になり、主語は子どもなので文が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「示す」の目的語はすでに「興味」なので、「事物を」を置くと目的語が二つになり不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「興味を示す」の対象を示す役割には合わない。"}], "correct_answer": "に", "explanations": {"に": "「興味を示す」の相手（対象）を表す「に」。「事物に」で文意に合う。", "が": "「事物が」にすると事物が「示す」の主語になり、主語は子どもなので文が崩れる。", "を": "「示す」の目的語はすでに「興味」なので、「事物を」を置くと目的語が二つになり不自然。", "で": "「で」は場所や手段を表すので、「興味を示す」の対象を示す役割には合わない。"}, "error_tags": {"が": "主語（誤）", "を": "目的語の重複（誤）", "で": "場所・手段（誤）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52112, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「事物の本質」の「の」。名詞どうしをつなぐ連体修飾で、「事物の本質とは何か」として正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、名詞「事物」と「本質」をつなぐ役割にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「事物が本質とは何か」と主語が重なり、「問い続けた」の主語は哲学者なので文が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「事物より本質」は文の関係が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「事物の本質」の「の」。名詞どうしをつなぐ連体修飾で、「事物の本質とは何か」として正しい。", "へ": "「へ」は方向を表すので、名詞「事物」と「本質」をつなぐ役割にはならない。", "が": "「事物が本質とは何か」と主語が重なり、「問い続けた」の主語は哲学者なので文が崩れる。", "より": "「より」は比較を表すので、「事物より本質」は文の関係が崩れる。"}, "error_tags": {"へ": "方向（誤）", "が": "主語の重複（誤）", "より": "比較（誤）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52112, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "現実に存在する、具体的な物や事柄。", "primary_collocate": null, "pronunciation": "じぶつ", "ipa": "dʑibɯtsɯ", "syllable_count": 3, "sentences": [{"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "事物", "complexity_tier": "T4", "furigana": "そこには、理屈(りくつ)や打算(ださん)といった人為的(じんいてき)な思惑(おもわく)が介在(かいざい)する余地(よち)はなく、ただ生命(せいめい)の根源的(こんげんてき)な渇望(かつぼう)と、眼前(がんぜん)の事物(じぶつ)に対(たい)する純粋(じゅんすい)な受容(じゅよう)があるのみだ。", "sentence_source": "mined"}, {"text": "子どもは身の回りの事物に強い興味を示す。", "target_word": "事物", "complexity_tier": "T3", "furigana": "子(こ)どもは身(み)の回(まわ)りの事物(じぶつ)に強(つよ)い興味(きょうみ)を示(しめ)す。", "sentence_source": "generated"}, {"text": "科学者は自然界の事物を注意深く観察した。", "target_word": "事物", "complexity_tier": "T3", "furigana": "科学者(かがくしゃ)は自然界(しぜんかい)の事物(じぶつ)を注意深(ちゅういぶか)く観察(かんさつ)した。", "sentence_source": "generated"}, {"text": "絵本には、日常の事物の名前が絵と一緒に載っている。", "target_word": "事物", "complexity_tier": "T3", "furigana": "絵本(えほん)には、日常(にちじょう)の事物(じぶつ)の名前(なまえ)が絵(え)と一緒(いっしょ)に載(の)っている。", "sentence_source": "generated"}, {"text": "彼は事物を正しく分類するのが得意だ。", "target_word": "事物", "complexity_tier": "T3", "furigana": "彼(かれ)は事物(じぶつ)を正(ただ)しく分類(ぶんるい)するのが得意(とくい)だ。", "sentence_source": "generated"}, {"text": "目に入る事物を、そのまま言葉にして書いてみよう。", "target_word": "事物", "complexity_tier": "T3", "furigana": "目(め)に入(はい)る事物(じぶつ)を、そのまま言葉(ことば)にして書(か)いてみよう。", "sentence_source": "generated"}, {"text": "赤ちゃんは、最初に見る事物をすぐ覚えてしまう。", "target_word": "事物", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんは、最初(さいしょ)に見(み)る事物(じぶつ)をすぐ覚(おぼ)えてしまう。", "sentence_source": "generated"}, {"text": "哲学者は、事物の本質とは何かを問い続けた。", "target_word": "事物", "complexity_tier": "T4", "furigana": "哲学者(てつがくしゃ)は、事物(じぶつ)の本質(ほんしつ)とは何(なに)かを問(と)い続(つづ)けた。", "sentence_source": "generated"}, {"text": "この辞典は、さまざまな事物を図で説明している。", "target_word": "事物", "complexity_tier": "T3", "furigana": "この辞典(じてん)は、さまざまな事物(じぶつ)を図(ず)で説明(せつめい)している。", "sentence_source": "generated"}, {"text": "旅先では、見慣れない事物ばかりで驚いた。", "target_word": "事物", "complexity_tier": "T3", "furigana": "旅先(たびさき)では、見慣(みな)れない事物(じぶつ)ばかりで驚(おどろ)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事物", "label": "基本形"}], "register": "書き言葉（やや硬い）", "sense_fingerprint": "現実に存在する物や事柄の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52112, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "「眼前の事物」として、目の前にある具体的な物や事柄を指し、文意に合う。"}, {"text": "足音", "is_correct": false, "explanation": "耳で聞くものなので、「眼前の」（目の前の）対象にはならない。"}, {"text": "匂い", "is_correct": false, "explanation": "鼻で嗅ぐもので、目の前に見える対象としては合わない。"}, {"text": "感触", "is_correct": false, "explanation": "手で触れて感じるもので、「眼前」の視覚的な対象とは合わない。"}], "explanations": {"事物": "「眼前の事物」として、目の前にある具体的な物や事柄を指し、文意に合う。", "足音": "耳で聞くものなので、「眼前の」（目の前の）対象にはならない。", "匂い": "鼻で嗅ぐもので、目の前に見える対象としては合わない。", "感触": "手で触れて感じるもので、「眼前」の視覚的な対象とは合わない。"}, "sentence_index": 0, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は喜びという事物を、素直に顔に出した。", "explanation": "〈感情〉の意味で使っている。事物は現実に存在する物や事柄を指すので、喜びという心の状態には合わない。"}, {"text": "会社の事物を社員に浸透させるのが、彼の仕事だ。", "explanation": "〈理念〉の意味。理念は抽象的な考え方なので、具体的な物を指す事物とは合わない。"}, {"text": "子どもの頃からの夢の事物を、今も大切にしている。", "explanation": "ここは〈願望〉の意味で使っている。事物は現実に存在する物や事柄を指すので、心の中に描く願いには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52112, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "「最初に見る事物」として、目に入る物を指し、文意に合う。"}, {"text": "味", "is_correct": false, "explanation": "舌で感じるもので、「見る」対象にはならない。"}, {"text": "温もり", "is_correct": false, "explanation": "肌で感じるもので、目で見る対象とは合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "耳で聞くもので、「見る」とは合わない。"}], "explanations": {"事物": "「最初に見る事物」として、目に入る物を指し、文意に合う。", "味": "舌で感じるもので、「見る」対象にはならない。", "温もり": "肌で感じるもので、目で見る対象とは合わない。", "旋律": "耳で聞くもので、「見る」とは合わない。"}, "sentence_index": 6, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅館の事物がとても穏やかで、心が落ち着いた。", "explanation": "〈雰囲気〉の意味。事物は物や事柄を指すので、場の空気や感じを表す言葉としては使えない。"}, {"text": "彼に対する第一の事物は、今も変わらない。", "explanation": "〈印象〉の意味。印象は心に残る感じで、現実に存在する物を指す事物とは合わない。"}, {"text": "試験前の不安という事物が、ずっと胸を重くしていた。", "explanation": "ここは〈気がかり〉の意味で使っている。事物は現実に存在する具体的な物や事柄を指すので、胸を重くする心の状態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52112, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は実験室の事物に一つずつ確かめた。", "corrected_sentence": "研究者は実験室の事物を一つずつ確かめた。", "error_description": "「確かめる」は目的語に「を」をとる。「事物に」の「に」が誤りで、正しくは「事物を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52112, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは集めた事物が箱に分けた。", "corrected_sentence": "子どもたちは集めた事物を箱に分けた。", "error_description": "「分ける」は目的語に「を」をとる。「事物が」にすると事物が主語になり、文が成り立たない。正しくは「事物を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
