INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52113, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "ただ一つだけ、それだけで、ほかにないこと。", "primary_collocate": null, "pronunciation": "ただ", "ipa": "tada", "syllable_count": 2, "sentences": [{"text": "唯、彼だけが本当のことを知っていた。", "target_word": "唯", "complexity_tier": "T3", "furigana": "唯[ただ]、彼[かれ]だけが本当[ほんとう]のことを知[し]っていた。", "sentence_source": "generated"}, {"text": "私は唯、あなたに会いたかっただけです。", "target_word": "唯", "complexity_tier": "T3", "furigana": "私[わたし]は唯[ただ]、あなたに会[あ]いたかっただけです。", "sentence_source": "generated"}, {"text": "唯それだけの理由で、彼は会社を辞めた。", "target_word": "唯", "complexity_tier": "T3", "furigana": "唯[ただ]それだけの理由[りゆう]で、彼[かれ]は会社[かいしゃ]を辞[や]めた。", "sentence_source": "generated"}, {"text": "出発の日まで、唯待つしかなかった。", "target_word": "唯", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]の日[ひ]まで、唯[ただ]待[ま]つしかなかった。", "sentence_source": "generated"}, {"text": "彼は何も言わず、唯笑っていた。", "target_word": "唯", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]も言[い]わず、唯[ただ]笑[わら]っていた。", "sentence_source": "generated"}, {"text": "言いわけはしない。唯、事実を話すだけだ。", "target_word": "唯", "complexity_tier": "T3", "furigana": "言[い]いわけはしない。唯[ただ]、事実[じじつ]を話[はな]すだけだ。", "sentence_source": "generated"}, {"text": "彼が求めていたのは唯、静かな時間だけだった。", "target_word": "唯", "complexity_tier": "T3", "furigana": "彼[かれ]が求[もと]めていたのは唯[ただ]、静[しず]かな時[とき]間[かん]だけだった。", "sentence_source": "generated"}, {"text": "母は唯黙って、私の話を聞いてくれた。", "target_word": "唯", "complexity_tier": "T3", "furigana": "母[はは]は唯[ただ]黙[だま]って、私[わたし]の話[はなし]を聞[き]いてくれた。", "sentence_source": "generated"}, {"text": "唯ひとつ心配なのは、天気だけだ。", "target_word": "唯", "complexity_tier": "T3", "furigana": "唯[ただ]ひとつ心配[しんぱい]なのは、天気[てんき]だけだ。", "sentence_source": "generated"}, {"text": "彼女は唯ひたすら走り続けた。", "target_word": "唯", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は唯[ただ]ひたすら走[はし]り続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "唯", "label": "基本形（副詞）"}], "register": "neutral", "sense_fingerprint": "ほかには何もなく、それだけであることを表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52113, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唯", "is_correct": true, "explanation": "「唯」は「ただそれだけ」の意味で、ここでは「彼だけが」を強める。空欄に入る正しい語。"}, {"text": "急に", "is_correct": false, "explanation": "「急に」は突然の意味。「彼だけが本当のことを知っていた」という文とは意味が合わない。"}, {"text": "ずいぶん", "is_correct": false, "explanation": "「ずいぶん」は程度の大きさを表すので、「彼だけが〜知っていた」の文の空欄には入らない。"}, {"text": "ぜひ", "is_correct": false, "explanation": "「ぜひ」は強い願望や依頼を表す副詞。事実を述べる文には入らない。"}], "explanations": {"唯": "「唯」は「ただそれだけ」の意味で、ここでは「彼だけが」を強める。空欄に入る正しい語。", "急に": "「急に」は突然の意味。「彼だけが本当のことを知っていた」という文とは意味が合わない。", "ずいぶん": "「ずいぶん」は程度の大きさを表すので、「彼だけが〜知っていた」の文の空欄には入らない。", "ぜひ": "「ぜひ」は強い願望や依頼を表す副詞。事実を述べる文には入らない。"}, "sentence_index": 0, "correct_answer": "唯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は上司の命令に唯々諾々と従った。", "explanation": "ここは〈言われるままに〉の意味（唯々諾々、読みは「いい」）。〈ただ・それだけ〉の意味ではないので合わない。"}, {"text": "唯我独尊の態度が、周りの反感を買った。", "explanation": "ここは〈自分だけが偉いと思う〉の意味（唯我独尊、読みは「ゆい」）。〈ただ・それだけ〉の意味ではないので合わない。"}, {"text": "唯ちゃんは、今日も元気に学校へ行った。", "explanation": "ここは人の名前の「唯」（読みは「ゆい」）。〈ただ・それだけ〉の意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52113, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唯", "is_correct": true, "explanation": "「唯」は「ただ〜だけ」の意味で、ここでは「静かな時間だけ」を指す。空欄に入る正しい語。"}, {"text": "突然", "is_correct": false, "explanation": "「突然」は出来事が急に起きる意味。「求めていたのは」の文には合わない。"}, {"text": "早速", "is_correct": false, "explanation": "「早速」はすぐに行う意味。求めていたものを説明する文には入らない。"}, {"text": "急いで", "is_correct": false, "explanation": "「急いで」は速さを表す。求めていたものを述べる文の空欄には入らない。"}], "explanations": {"唯": "「唯」は「ただ〜だけ」の意味で、ここでは「静かな時間だけ」を指す。空欄に入る正しい語。", "突然": "「突然」は出来事が急に起きる意味。「求めていたのは」の文には合わない。", "早速": "「早速」はすぐに行う意味。求めていたものを説明する文には入らない。", "急いで": "「急いで」は速さを表す。求めていたものを述べる文の空欄には入らない。"}, "sentence_index": 6, "correct_answer": "唯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このサービスは唯で使える。", "explanation": "ここは〈無料〉の意味。唯は〈ただ一つ・それだけ〉なので、無料の意味では使わない（無料は「ただ」と書くのが普通）。"}, {"text": "彼女は周りの意見を聞かず、唯我独尊で突き進んだ。", "explanation": "ここは〈自分だけが正しいと思う〉の意味（唯我独尊、読みは「ゆい」）。〈ただ・それだけ〉の意味ではないので合わない。"}, {"text": "唯さんの家は、駅の近くにある。", "explanation": "ここは人の名前の「唯」（読みは「ゆい」）。〈ただ・それだけ〉の意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52113, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は唯の黙って、私の話を最後まで聞いてくれた。", "corrected_sentence": "母は唯黙って、私の話を最後まで聞いてくれた。", "error_description": "副詞「唯」に「の」は続かない。「唯の」は誤りで、正しくは「唯黙って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52113, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は唯の笑って、何も答えなかった。", "corrected_sentence": "彼は唯笑って、何も答えなかった。", "error_description": "副詞「唯」に「の」は続かない。「唯の笑って」は誤りで、正しくは「唯笑って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52115, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「眼前の山」の「の」。眼前が山を修飾する連体修飾で、文意に合う。"}, {"text": "が", "is_correct": false, "explanation": "「眼前が山は」では主語が重なり、「眼前」が文の主語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「眼前と山は」では結びつかず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「眼前へ山は」の形は文の主語にならない。"}], "correct_answer": "の", "explanations": {"の": "「眼前の山」の「の」。眼前が山を修飾する連体修飾で、文意に合う。", "が": "「眼前が山は」では主語が重なり、「眼前」が文の主語として成り立たない。", "と": "「眼前と山は」では結びつかず、意味が通らない。", "へ": "「へ」は方向を表すので、「眼前へ山は」の形は文の主語にならない。"}, "error_tags": {"が": "主語の重複（誤）", "と": "誤った格（誤）", "へ": "方向（誤）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52115, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「通り過ぎる」の目的語を示す。眼前（その場所）を通過したことを表し、文意に合う。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「眼前より一台の車が」では通過の場所を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「眼前が一台の車が」と主語が重なり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「眼前と一台の車が」は並列の名詞句となり、通り過ぎる主語として不自然。"}], "correct_answer": "を", "explanations": {"を": "「通り過ぎる」の目的語を示す。眼前（その場所）を通過したことを表し、文意に合う。", "より": "「より」は比較を表すので、「眼前より一台の車が」では通過の場所を示せない。", "が": "「眼前が一台の車が」と主語が重なり、文が成り立たない。", "と": "「眼前と一台の車が」は並列の名詞句となり、通り過ぎる主語として不自然。"}, "error_tags": {"より": "比較（誤）", "が": "主語の重複（誤）", "と": "並列（誤）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52115, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "目の前にあるもののこと。", "primary_collocate": null, "pronunciation": "がんぜん", "ipa": "ɡaɴdzeɴ", "syllable_count": 4, "sentences": [{"text": "窓を開けると、眼前に満開の桜が見えた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "窓(まど)を開(あ)けると、眼前(がんぜん)に満開(まんかい)の桜(さくら)が見(み)えた。", "sentence_source": "generated"}, {"text": "眼前の山は、朝日を受けて赤く染まっていた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "眼前(がんぜん)の山(やま)は、朝日(あさひ)を受(う)けて赤(あか)く染(そ)まっていた。", "sentence_source": "generated"}, {"text": "彼女は眼前に置かれた料理に、そっと手を合わせた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は眼前(がんぜん)に置(お)かれた料理(りょうり)に、そっと手(て)を合(あ)わせた。", "sentence_source": "generated"}, {"text": "霧が晴れて、眼前に古い城が姿を現した。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "霧(きり)が晴(は)れて、眼前(がんぜん)に古(ふる)い城(しろ)が姿(すがた)を現(あらわ)した。", "sentence_source": "generated"}, {"text": "眼前の川を、白い船がゆっくり渡っていく。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "眼前(がんぜん)の川(かわ)を、白(しろ)い船(ふね)がゆっくり渡(わた)っていく。", "sentence_source": "generated"}, {"text": "観客は、眼前で演じられる劇に引き込まれた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "観客(かんきゃく)は、眼前(がんぜん)で演(えん)じられる劇(げき)に引(ひ)き込(こ)まれた。", "sentence_source": "generated"}, {"text": "坂を上りきると、眼前に町全体が広がっていた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "坂(さか)を上(のぼ)りきると、眼前(がんぜん)に町(まち)全体(ぜんたい)が広(ひろ)がっていた。", "sentence_source": "generated"}, {"text": "眼前を一台の車が猛スピードで通り過ぎた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "眼前(がんぜん)を一台(いちだい)の車(くるま)が猛(もう)スピードで通(とお)り過(す)ぎた。", "sentence_source": "generated"}, {"text": "眼前の景色を、彼は一枚の絵に描きとめた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "眼前(がんぜん)の景色(けしき)を、彼(かれ)は一枚(いちまい)の絵(え)に描(か)きとめた。", "sentence_source": "generated"}, {"text": "長い旅の末、眼前に目的の港が見えてきた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "長(なが)い旅(たび)の末(すえ)、眼前(がんぜん)に目的(もくてき)の港(みなと)が見(み)えてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眼前", "label": "基本形"}], "register": "書き言葉（硬い）", "sense_fingerprint": "目の前にあるもの・見えている光景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52115, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "窓の外に見える景色を指し、「眼前に満開の桜が見えた」と文意に合う。"}, {"text": "地下", "is_correct": false, "explanation": "地面の下を指すので、窓の外に見える桜とは合わない。"}, {"text": "記憶", "is_correct": false, "explanation": "頭の中にあるもので、窓の外の景色ではない。"}, {"text": "海底", "is_correct": false, "explanation": "海の底を指すので、窓の外に咲く桜とは合わない。"}], "explanations": {"眼前": "窓の外に見える景色を指し、「眼前に満開の桜が見えた」と文意に合う。", "地下": "地面の下を指すので、窓の外に見える桜とは合わない。", "記憶": "頭の中にあるもので、窓の外の景色ではない。", "海底": "海の底を指すので、窓の外に咲く桜とは合わない。"}, "sentence_index": 0, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電話の向こうから、眼前の声がはっきり聞こえた。", "explanation": "ここは耳で聞く〈音〉の意味で使っている。眼前は目で見える近さを指すので、電話の向こうの音には合わない。"}, {"text": "冬の眼前が、いつの間にか終わってしまった。", "explanation": "ここは〈時期〉の意味で使っている。眼前は目に見える場所や物を指すので、季節の区切りには合わない。"}, {"text": "この箱の眼前の重みに、腰がひどく痛んだ。", "explanation": "ここは〈重さ〉の意味で使っている。眼前は目で見える近さを指すので、持ち上げて感じる重さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52115, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "坂の上から目の前に広がる町を指し、文意に合う。"}, {"text": "水底", "is_correct": false, "explanation": "川や湖の底を指すので、坂の上から見える町とは合わない。"}, {"text": "海底", "is_correct": false, "explanation": "海の底を指すので、坂の上の町の眺めとは合わない。"}, {"text": "室内", "is_correct": false, "explanation": "建物の中を指すので、坂の上の眺めとは合わない。"}], "explanations": {"眼前": "坂の上から目の前に広がる町を指し、文意に合う。", "水底": "川や湖の底を指すので、坂の上から見える町とは合わない。", "海底": "海の底を指すので、坂の上の町の眺めとは合わない。", "室内": "建物の中を指すので、坂の上の眺めとは合わない。"}, "sentence_index": 6, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "握手したときの眼前の感触が、今も手に残っている。", "explanation": "ここは手で触れて感じる〈触感〉の意味で使っている。眼前は目で見える近さを指すので、手で触れて感じるものには合わない。"}, {"text": "夏の眼前の熱気に、少しめまいがした。", "explanation": "ここは〈暑さ〉の意味で使っている。眼前は目で見える近さを指すので、肌で感じる暑さには合わない。"}, {"text": "彼の眼前の学力は、クラスで一番だ。", "explanation": "ここは〈現在の状態〉の意味で使っている。眼前は目で見える近さを指すので、今の学力という抽象的な状態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52115, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展望台から、眼前を湖を見渡した。", "corrected_sentence": "展望台から、眼前の湖を見渡した。", "error_description": "「見渡す」の目的語は「眼前の湖」。「の」を「を」に変えると目的語が二つ重なり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52115, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谷を見下ろすと、眼前を白い霧が広がっていた。", "corrected_sentence": "谷を見下ろすと、眼前に白い霧が広がっていた。", "error_description": "「広がる」は自動詞で「を」をとらない。場所を示す「に」が必要で、正しくは「眼前に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52116, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「眼前に広がった」の「に」。広がる場所を示し、文意に合う。"}, {"text": "を", "is_correct": false, "explanation": "「広がる」は自動詞なので目的語の「を」は取らない。"}, {"text": "が", "is_correct": false, "explanation": "「眼前が大きな湖が広がった」は主語が重なり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「眼前と大きな湖」では結びつかず、「広がった」の場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「眼前に広がった」の「に」。広がる場所を示し、文意に合う。", "を": "「広がる」は自動詞なので目的語の「を」は取らない。", "が": "「眼前が大きな湖が広がった」は主語が重なり、文が成り立たない。", "と": "「眼前と大きな湖」では結びつかず、「広がった」の場所を示せない。"}, "error_tags": {"を": "自動詞に目的語（誤）", "が": "主語の重複（誤）", "と": "誤った格（誤）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52116, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「眼前に差し出された」の「に」。差し出す先・場所を示し、文意に合う。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「眼前より差し出された」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「眼前を差し出された手紙を」と目的語が二つ重なり、文が崩れる。"}, {"text": "が", "is_correct": false, "explanation": "「眼前が差し出された」では差し出す主体が示されず、主語が合わない。"}], "correct_answer": "に", "explanations": {"に": "「眼前に差し出された」の「に」。差し出す先・場所を示し、文意に合う。", "より": "「より」は比較を表すので、「眼前より差し出された」は意味が通らない。", "を": "「眼前を差し出された手紙を」と目的語が二つ重なり、文が崩れる。", "が": "「眼前が差し出された」では差し出す主体が示されず、主語が合わない。"}, "error_tags": {"より": "比較（誤）", "を": "目的語の重複（誤）", "が": "主語の不一致（誤）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52116, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "目と鼻の先。自分のすぐ近くにあるものや場所。", "primary_collocate": null, "pronunciation": "がんぜん", "ipa": "ɡaɴdzeɴ", "syllable_count": 4, "sentences": [{"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "眼前", "complexity_tier": "T4", "furigana": "そこには、理屈(りくつ)や打算(ださん)といった人為的(じんいてき)な思惑(おもわく)が介在(かいざい)する余地(よち)はなく、ただ生命(せいめい)の根源的(こんげんてき)な渇望(かつぼう)と、眼前(がんぜん)の事物(じぶつ)に対(たい)する純粋(じゅんすい)な受容(じゅよう)があるのみだ。", "sentence_source": "mined"}, {"text": "山を越えると、眼前に大きな湖が広がった。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "山(やま)を越(こ)えると、眼前(がんぜん)に大(おお)きな湖(みずうみ)が広(ひろ)がった。", "sentence_source": "generated"}, {"text": "突然、眼前に大きなトラックが迫ってきた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "突然(とつぜん)、眼前(がんぜん)に大(おお)きなトラックが迫(せま)ってきた。", "sentence_source": "generated"}, {"text": "眼前の光景に、私はしばらく言葉を失った。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "眼前(がんぜん)の光景(こうけい)に、私(わたし)はしばらく言葉(ことば)を失(うしな)った。", "sentence_source": "generated"}, {"text": "幕が上がり、眼前に華やかな舞台が現れた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "幕(まく)が上(あ)がり、眼前(がんぜん)に華(はな)やかな舞台(ぶたい)が現(あらわ)れた。", "sentence_source": "generated"}, {"text": "敵の大軍が眼前に迫り、兵士たちは息をのんだ。", "target_word": "眼前", "complexity_tier": "T4", "furigana": "敵(てき)の大軍(たいぐん)が眼前(がんぜん)に迫(せま)り、兵士(へいし)たちは息(いき)をのんだ。", "sentence_source": "generated"}, {"text": "頂上に立つと、眼前には雲の海が見えた。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "頂上(ちょうじょう)に立(た)つと、眼前(がんぜん)には雲(くも)の海(うみ)が見(み)えた。", "sentence_source": "generated"}, {"text": "眼前に差し出された手紙を、彼は黙って受け取った。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "眼前(がんぜん)に差(さ)し出(だ)された手紙(てがみ)を、彼(かれ)は黙(だま)って受(う)け取(と)った。", "sentence_source": "generated"}, {"text": "長いトンネルを抜けると、眼前に青い海があった。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "長(なが)いトンネルを抜(ぬ)けると、眼前(がんぜん)に青(あお)い海(うみ)があった。", "sentence_source": "generated"}, {"text": "眼前で起きた事故が、今も頭から離れない。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "眼前(がんぜん)で起(お)きた事故(じこ)が、今(いま)も頭(あたま)から離(はな)れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眼前", "label": "基本形"}], "register": "書き言葉（硬い）", "sense_fingerprint": "目と鼻の先、自分のすぐ近くの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52116, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "「眼前の事物」として、目の前にある対象を指し、文意に合う。"}, {"text": "記憶", "is_correct": false, "explanation": "頭の中にあるもので、目の前の現実の物とは合わない。"}, {"text": "幻影", "is_correct": false, "explanation": "実際には存在しないものを指すので、「現実の事物に対する受容」の対象にはならない。"}, {"text": "内心", "is_correct": false, "explanation": "心の中を指すので、目の前にある事物とは合わない。"}], "explanations": {"眼前": "「眼前の事物」として、目の前にある対象を指し、文意に合う。", "記憶": "頭の中にあるもので、目の前の現実の物とは合わない。", "幻影": "実際には存在しないものを指すので、「現実の事物に対する受容」の対象にはならない。", "内心": "心の中を指すので、目の前にある事物とは合わない。"}, "sentence_index": 0, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "遠くで鳴った鐘が、眼前にゆっくり響いた。", "explanation": "ここは耳で聞く〈音〉の意味で使っている。眼前は目で見える近さを指すので、遠くで鳴る鐘の響きには合わない。"}, {"text": "転んだときの痛みが、眼前でじんじんと残った。", "explanation": "ここは体で感じる〈感覚〉の意味で使っている。眼前は目で見える近さを指すので、転んで生じた痛みの感覚には合わない。"}, {"text": "焼けたゴムのにおいが、眼前でつんと鼻をついた。", "explanation": "ここは〈香り〉の意味で使っている。眼前は目で見える近さを指すので、鼻で感じるにおいには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52116, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "目の前、すぐ近くの空間を指し、「見えた」と合う。"}, {"text": "背後", "is_correct": false, "explanation": "背中側を指すので、「雲の海が見えた」と合わない。"}, {"text": "地底", "is_correct": false, "explanation": "地面の下を指すので、頂上から見える雲の海とは矛盾する。"}, {"text": "室内", "is_correct": false, "explanation": "建物の中を指すので、頂上の眺めとは合わない。"}], "explanations": {"眼前": "目の前、すぐ近くの空間を指し、「見えた」と合う。", "背後": "背中側を指すので、「雲の海が見えた」と合わない。", "地底": "地面の下を指すので、頂上から見える雲の海とは矛盾する。", "室内": "建物の中を指すので、頂上の眺めとは合わない。"}, "sentence_index": 6, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "給料の眼前が、十万円も上がった。", "explanation": "ここは〈金額〉の意味で使っている。眼前は目で見える近さを指すので、お金の額には合わない。"}, {"text": "彼の眼前の年は、もう三十を超えている。", "explanation": "ここは〈年齢〉の意味で使っている。眼前は目で見える近さを指すので、生まれてからの年数には合わない。"}, {"text": "町の眼前の人口が、ここ十年で半分に減った。", "explanation": "ここは〈人数〉の意味で使っている。眼前は目で見える近さを指すので、人の数には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52116, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "眼前を広がる海は、夕日で金色に輝いていた。", "corrected_sentence": "眼前に広がる海は、夕日で金色に輝いていた。", "error_description": "「広がる」は自動詞で「を」をとらない。場所を示す「に」が必要で、正しくは「眼前に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52116, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "眼前の広がる山脈を、彼は窓から眺めていた。", "corrected_sentence": "眼前に広がる山脈を、彼は窓から眺めていた。", "error_description": "「広がる」は場所を「に」で示す。「眼前の」にすると修飾の形が崩れて不自然な文になる。正しくは「眼前に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52117, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不純", "is_correct": true, "explanation": "「まじりけがある」の意味で、純粋の対義語として辞典に並ぶ。"}, {"text": "清潔", "is_correct": false, "explanation": "清潔は汚れがないことで、まじりけの有無とは別の意味。対義語は不潔。"}, {"text": "豊富", "is_correct": false, "explanation": "豊富は数量が多いこと。まじりけとは関係がない。"}, {"text": "快適", "is_correct": false, "explanation": "快適は心地よいこと。純粋と対になる関係にはない。"}], "correct_answer": "不純", "explanations": {"不純": "「まじりけがある」の意味で、純粋の対義語として辞典に並ぶ。", "清潔": "清潔は汚れがないことで、まじりけの有無とは別の意味。対義語は不潔。", "豊富": "豊富は数量が多いこと。まじりけとは関係がない。", "快適": "快適は心地よいこと。純粋と対になる関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52117, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不純", "is_correct": true, "explanation": "「まじりけがある」の意味で、純粋の対義語として辞典に並ぶ。"}, {"text": "単調", "is_correct": false, "explanation": "単調は変化が少ないこと。まじりけとは関係がない。"}, {"text": "軽快", "is_correct": false, "explanation": "軽快は軽やかで身が軽いこと。対義関係にはない。"}, {"text": "面倒", "is_correct": false, "explanation": "面倒は手間がかかること。純粋の対義語ではない。"}], "correct_answer": "不純", "explanations": {"不純": "「まじりけがある」の意味で、純粋の対義語として辞典に並ぶ。", "単調": "単調は変化が少ないこと。まじりけとは関係がない。", "軽快": "軽快は軽やかで身が軽いこと。対義関係にはない。", "面倒": "面倒は手間がかかること。純粋の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52117, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "まじりけがないこと。", "primary_collocate": null, "pronunciation": "じゅんすい", "ipa": "dʑɯnsɯi", "syllable_count": 4, "sentences": [{"text": "この指輪は純粋な金でできている。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "この指輪[ゆびわ]は純粋[じゅんすい]な金[きん]でできている。", "sentence_source": "generated"}, {"text": "純粋な水には、味もにおいもない。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "純粋[じゅんすい]な水[みず]には、味[あじ]もにおいもない。", "sentence_source": "generated"}, {"text": "この蜂蜜は純粋なもので、何も加えていない。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "この蜂蜜[はちみつ]は純粋[じゅんすい]なもので、何[なに]も加[くわ]えていない。", "sentence_source": "generated"}, {"text": "この工場では、純粋な銅だけを材料に使っている。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、純粋[じゅんすい]な銅[どう]だけを材料[ざいりょう]に使[つか]っている。", "sentence_source": "generated"}, {"text": "実験には、純粋なエタノールを使った。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "実験[じっけん]には、純粋[じゅんすい]なエタノールを使[つか]った。", "sentence_source": "generated"}, {"text": "このシャンプーは、純粋な植物成分だけを使っている。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "このシャンプーは、純粋[じゅんすい]な植物[しょくぶつ]成分[せいぶん]だけを使[つか]っている。", "sentence_source": "generated"}, {"text": "純粋な好奇心だけで、その実験を始めた。", "target_word": "純粋", "complexity_tier": "T4", "furigana": "純粋[じゅんすい]な好奇心[こうきしん]だけで、その実験[じっけん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "この湖の水は、驚くほど純粋だ。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "この湖[みずうみ]の水[みず]は、驚[おどろ]くほど純粋[じゅんすい]だ。", "sentence_source": "generated"}, {"text": "純粋なウールのセーターは、とてもあたたかい。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "純粋[じゅんすい]なウールのセーターは、とてもあたたかい。", "sentence_source": "generated"}, {"text": "利益のためではなく、純粋な善意で手伝った。", "target_word": "純粋", "complexity_tier": "T4", "furigana": "利益[りえき]のためではなく、純粋[じゅんすい]な善意[ぜんい]で手伝[てつだ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "純粋", "label": "基本形"}, {"form": "純粋な", "label": "連体形"}, {"form": "純粋だ", "label": "終止形"}, {"form": "純粋で", "label": "連用形(で)"}, {"form": "純粋に", "label": "連用形(に)"}], "register": "標準", "sense_fingerprint": "形状詞。ほかのものがまざっておらず、それだけでできていること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52117, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "純粋", "is_correct": true, "explanation": "「純粋な金」で、まじりけのない金を表す。"}, {"text": "自由", "is_correct": false, "explanation": "自由は束縛がないことで、金の質を表さない。「自由な金」は意味が通らない。"}, {"text": "複雑", "is_correct": false, "explanation": "複雑は要素が入り組むことで、金の純度の話とは合わない。"}, {"text": "穏やか", "is_correct": false, "explanation": "穏やかは落ち着いた様子を表し、素材の状態には使わない。"}], "explanations": {"純粋": "「純粋な金」で、まじりけのない金を表す。", "自由": "自由は束縛がないことで、金の質を表さない。「自由な金」は意味が通らない。", "複雑": "複雑は要素が入り組むことで、金の純度の話とは合わない。", "穏やか": "穏やかは落ち着いた様子を表し、素材の状態には使わない。"}, "sentence_index": 0, "correct_answer": "純粋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その子は、りんごを純粋に一個食べた。", "explanation": "ここは〈まるごと〉の意味（丸ごと）。純粋は〈まじりけがない〉で、食べ方や量の話には使わない。"}, {"text": "この答えは純粋だ。", "explanation": "ここは〈欠けたところがない〉の意味（完全）。純粋は〈まじりけがない〉で、答えの完成度には使わない。"}, {"text": "その作業は純粋だ。", "explanation": "ここは〈手順がやさしい〉の意味（単純）。純粋は〈まじりけがない〉で、作業の難しさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52117, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "純粋", "is_correct": true, "explanation": "「純粋な好奇心」で、ほかの動機がまじらない好奇心を表す。"}, {"text": "失礼", "is_correct": false, "explanation": "失礼は礼を欠くことで、好奇心の性質を表す語ではない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るく楽しい様子。「陽気な好奇心」は意味が合わない。"}, {"text": "不安", "is_correct": false, "explanation": "不安は心配なことで、好奇心の形容には使わない。"}], "explanations": {"純粋": "「純粋な好奇心」で、ほかの動機がまじらない好奇心を表す。", "失礼": "失礼は礼を欠くことで、好奇心の性質を表す語ではない。", "陽気": "陽気は明るく楽しい様子。「陽気な好奇心」は意味が合わない。", "不安": "不安は心配なことで、好奇心の形容には使わない。"}, "sentence_index": 6, "correct_answer": "純粋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この魚は、今朝とれたばかりで、とても純粋だ。", "explanation": "ここは〈鮮度がよい〉の意味（新鮮）。純粋はまじりけのなさを表し、魚の鮮度には使わない。"}, {"text": "部屋はいつも純粋にしている。", "explanation": "ここは〈汚れがなく保つ〉の意味（清潔）。純粋は〈まじりけがない〉で、掃除や衛生の話には使わない。"}, {"text": "仕上げが純粋だった。", "explanation": "ここは〈ていねいでない〉の意味（雑）。純粋は〈まじりけがない〉で、仕上がりの出来には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52117, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このジュースは純粋の果汁だけで作られている。", "corrected_sentence": "このジュースは純粋な果汁だけで作られている。", "error_description": "「純粋」は形容動詞なので、名詞の前では「純粋な」となる。「純粋の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "純粋な", "is_correct": true, "explanation": "連体形。「な」を付けて名詞「水」を直接修飾する形。"}, {"text": "純粋だ", "is_correct": false, "explanation": "「だ」は文末の形。名詞の前には「な」が必要なので、ここには入らない。"}, {"text": "純粋に", "is_correct": false, "explanation": "「に」は連用形で動詞を修飾する。名詞の「水」を直接修飾できない。"}, {"text": "純粋で", "is_correct": false, "explanation": "「で」は中止形で、名詞を修飾できない。「純粋で水には」は成り立たない。"}], "correct_form": "純粋な", "base_form": "純粋", "form_label": "連体形", "sentence_index": 1, "explanations": {"純粋な": "連体形。「な」を付けて名詞「水」を直接修飾する形。", "純粋だ": "「だ」は文末の形。名詞の前には「な」が必要なので、ここには入らない。", "純粋に": "「に」は連用形で動詞を修飾する。名詞の「水」を直接修飾できない。", "純粋で": "「で」は中止形で、名詞を修飾できない。「純粋で水には」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52117, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この氷は、驚くほど純粋が。", "corrected_sentence": "この氷は、驚くほど純粋だ。", "error_description": "文末は「純粋だ」。「だ」を「が」に変えると、述語として文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "純粋だ", "is_correct": true, "explanation": "終止形。「だ」で文末が終わる形。"}, {"text": "純粋な", "is_correct": false, "explanation": "名詞の前につく連体形。文末に置くと「驚くほど純粋な。」と文が途切れる。"}, {"text": "純粋なら", "is_correct": false, "explanation": "仮定の形。「驚くほど純粋なら。」では条件の途中で文が切れ、述語として文が終わらない。", "base_form": "純粋", "form_label": "仮定形"}, {"text": "純粋に", "is_correct": false, "explanation": "連用形。「驚くほど純粋に。」と文末に置くと述語にならず、文が途切れる。"}], "correct_form": "純粋だ", "base_form": "純粋", "form_label": "終止形", "sentence_index": 7, "explanations": {"純粋だ": "終止形。「だ」で文末が終わる形。", "純粋な": "名詞の前につく連体形。文末に置くと「驚くほど純粋な。」と文が途切れる。", "純粋なら": "仮定の形。「驚くほど純粋なら。」では条件の途中で文が切れ、述語として文が終わらない。", "純粋に": "連用形。「驚くほど純粋に。」と文末に置くと述語にならず、文が途切れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
