INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52121, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "おなかがすいて、何かを食べたいと強く思うこと。", "primary_collocate": null, "pronunciation": "うえ", "ipa": "ɯe", "syllable_count": 2, "sentences": [{"text": "一日歩き続けて、飢えで動けなくなった。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "一日(いちにち)歩(ある)き続(つづ)けて、飢(う)えで動(うご)けなくなった。", "sentence_source": "generated"}, {"text": "山で道に迷い、飢えと疲れで倒れそうだった。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "山(やま)で道(みち)に迷(まよ)い、飢(う)えと疲(つか)れで倒(たお)れそうだった。", "sentence_source": "generated"}, {"text": "彼は飢えをしのぐために、木の実を食べた。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "彼(かれ)は飢(う)えをしのぐために、木(き)の実(み)を食(た)べた。", "sentence_source": "generated"}, {"text": "飢えを感じて、冷蔵庫を開けた。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "飢(う)えを感(かん)じて、冷蔵庫(れいぞうこ)を開(あ)けた。", "sentence_source": "generated"}, {"text": "猫は飢えに耐えかねたように、強く鳴いた。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "猫[ねこ]は飢[う]えに耐[た]えかねたように、強[つよ]く鳴[な]いた。", "sentence_source": "generated"}, {"text": "何日も食べず、飢えが限界に近づいた。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "何日(なんにち)も食(た)べず、飢(う)えが限界(げんかい)に近(ちか)づいた。", "sentence_source": "generated"}, {"text": "厳しい冬、飢えがオオカミを村の近くまで追いやった。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "厳[きび]しい冬[ふゆ]、飢[う]えがオオカミを村[むら]の近[ちか]くまで追[お]いやった。", "sentence_source": "generated"}, {"text": "飢えに負けて、夜中にパンを食べてしまった。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "飢(う)えに負(ま)けて、夜中(よなか)にパンを食(た)べてしまった。", "sentence_source": "generated"}, {"text": "飢えは、どんな食べ物も特別においしくする。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "飢(う)えは、どんな食(た)べ物(もの)も特別(とくべつ)においしくする。", "sentence_source": "generated"}, {"text": "パンの香りがして、飢えがいっそう強くなった。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "パンの香(かお)りがして、飢(う)えがいっそう強(つよ)くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飢え", "label": "基本形"}], "register": "やや書き言葉（常体）", "sense_fingerprint": "空腹で食べたいと強く感じる身体的な状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52121, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飢え", "is_correct": true, "explanation": "空腹で動けなくなる原因として『飢えで』と続き、身体の空腹を表す語として合う。"}, {"text": "地図", "is_correct": false, "explanation": "『地図で動けなくなった』は原因として成り立たない。"}, {"text": "椅子", "is_correct": false, "explanation": "『椅子で動けなくなった』は不自然で、歩き続けた文脈と合わない。"}, {"text": "紙", "is_correct": false, "explanation": "『紙で動けなくなった』は意味をなさず、原因を示せない。"}], "explanations": {"飢え": "空腹で動けなくなる原因として『飢えで』と続き、身体の空腹を表す語として合う。", "地図": "『地図で動けなくなった』は原因として成り立たない。", "椅子": "『椅子で動けなくなった』は不自然で、歩き続けた文脈と合わない。", "紙": "『紙で動けなくなった』は意味をなさず、原因を示せない。"}, "sentence_index": 0, "correct_answer": "飢え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喉の飢えを感じて、水を飲んだ。", "explanation": "〈渇き〉の意味。水を求める感覚は渇きであり、飢えとは言わない。"}, {"text": "寒い夜、飢えを感じて暖房をつけた。", "explanation": "〈寒さ〉の意味。暖房をつける理由は寒さであり、飢えは当てはまらない。"}, {"text": "別れの知らせに、彼は深い飢えを覚えて泣いた。", "explanation": "〈悲しみ〉の意味。別れの知らせで感じるのは悲しみで、飢えとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52121, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飢え", "is_correct": true, "explanation": "『厳しい冬、飢えがオオカミを追いやった』の主語として、飢えによる空腹が村へ追いやる文脈に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "『鍵がオオカミを追いやった』は意味をなさず、文脈に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "『窓がオオカミを追いやった』は不自然で、冬の文脈と合わない。"}, {"text": "絵具", "is_correct": false, "explanation": "『絵具がオオカミを追いやった』は成り立たず、文の主語にならない。"}], "explanations": {"飢え": "『厳しい冬、飢えがオオカミを追いやった』の主語として、飢えによる空腹が村へ追いやる文脈に合う。", "鍵": "『鍵がオオカミを追いやった』は意味をなさず、文脈に合わない。", "窓": "『窓がオオカミを追いやった』は不自然で、冬の文脈と合わない。", "絵具": "『絵具がオオカミを追いやった』は成り立たず、文の主語にならない。"}, "sentence_index": 6, "correct_answer": "飢え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "足の飢えで、彼は歩けなくなった。", "explanation": "〈痛み〉の意味。足が痛んで歩けない場合は痛みで、飢えとは言わない。"}, {"text": "まぶしい飢えに、目を細めた。", "explanation": "〈光〉の意味。まぶしさは光によるもので、飢えとは言わない。"}, {"text": "飢えに濡れて、体が冷えた。", "explanation": "〈雨〉の意味。濡れて体が冷えるのは雨によるもので、飢えは当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52121, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山道を歩き続けて、飢えを動けなくなった。", "corrected_sentence": "山道を歩き続けて、飢えで動けなくなった。", "error_description": "原因を表す『で』を使う。『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52121, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪深い冬、飢えるがオオカミを村の近くまで追いやった。", "corrected_sentence": "雪深い冬、飢えがオオカミを村の近くまで追いやった。", "error_description": "『飢え』は名詞。動詞『飢える』の形を名詞の位置に置いたのが誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52122, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『苦しむ』の原因・対象を示す『に』。『飢えに苦しむ』として自然。"}, {"text": "が", "is_correct": false, "explanation": "『飢えが苦しんだ』は飢えが主体になり、文の意味が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "『の』は連体修飾で、『飢えの苦しんだ』は文として成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は『苦しむ』の対象にならず、不自然。"}], "correct_answer": "に", "explanations": {"に": "『苦しむ』の原因・対象を示す『に』。『飢えに苦しむ』として自然。", "が": "『飢えが苦しんだ』は飢えが主体になり、文の意味が崩れる。", "の": "『の』は連体修飾で、『飢えの苦しんだ』は文として成立しない。", "へ": "方向を示す『へ』は『苦しむ』の対象にならず、不自然。"}, "error_tags": {"が": "主語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52122, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『しのぐ』の目的語（飢え）を示す『を』。『飢えをしのぐ』として自然。"}, {"text": "に", "is_correct": false, "explanation": "『飢えにしのぐ』は成り立たず、『しのぐ』は対象に『を』をとる。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を示す『と』は『飢えとしのぐ』と続かず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す『より』は『飢えよりしのぐ』と続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『しのぐ』の目的語（飢え）を示す『を』。『飢えをしのぐ』として自然。", "に": "『飢えにしのぐ』は成り立たず、『しのぐ』は対象に『を』をとる。", "と": "並列・相手を示す『と』は『飢えとしのぐ』と続かず、不自然。", "より": "比較を示す『より』は『飢えよりしのぐ』と続かず、文が成り立たない。"}, "error_tags": {"に": "位置・相手", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52122, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "食べ物がなくて苦しむこと。また、何かを強く求める気持ち。", "primary_collocate": null, "pronunciation": "うえ", "ipa": "ɯe", "syllable_count": 2, "sentences": [{"text": "彼は長い冬の間、心の飢えを抱えて暮らした。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "彼(かれ)は長(なが)い冬(ふゆ)の間(あいだ)、心(こころ)の飢(う)えを抱(かか)えて暮(く)らした。", "sentence_source": "generated"}, {"text": "戦争のあと、多くの人が飢えに苦しんだ。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "戦争(せんそう)のあと、多(おお)くの人(ひと)が飢(う)えに苦(くる)しんだ。", "sentence_source": "generated"}, {"text": "世界から飢えをなくすための活動が続いている。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "世界(せかい)から飢(う)えをなくすための活動(かつどう)が続(つづ)いている。", "sentence_source": "generated"}, {"text": "長い旅の間、彼は飢えと寒さに耐えた。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "長(なが)い旅(たび)の間(あいだ)、彼(かれ)は飢(う)えと寒(さむ)さに耐(た)えた。", "sentence_source": "generated"}, {"text": "食料が届かず、村では飢えが広がった。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "食料(しょくりょう)が届(とど)かず、村(むら)では飢(う)えが広(ひろ)がった。", "sentence_source": "generated"}, {"text": "彼は知識への飢えが強く、毎日図書館に通った。", "target_word": "飢え", "complexity_tier": "T4", "furigana": "彼(かれ)は知識(ちしき)への飢(う)えが強(つよ)く、毎日(まいにち)図書館(としょかん)に通(かよ)った。", "sentence_source": "generated"}, {"text": "愛情への飢えが、彼女の心を孤独にした。", "target_word": "飢え", "complexity_tier": "T4", "furigana": "愛情(あいじょう)への飢(う)えが、彼女(かのじょ)の心(こころ)を孤独(こどく)にした。", "sentence_source": "generated"}, {"text": "飢えをしのぐために、川で魚をとった。", "target_word": "飢え", "complexity_tier": "T4", "furigana": "飢(う)えをしのぐために、川(かわ)で魚(さかな)をとった。", "sentence_source": "generated"}, {"text": "災害のあと、飢えを抱えた人々に温かいスープが配られた。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "災害[さいがい]のあと、飢[う]えを抱[かか]えた人々[ひとびと]に温[あたた]かいスープが配[くば]られた。", "sentence_source": "generated"}, {"text": "豊かな国でも、飢えに苦しむ人は少なくない。", "target_word": "飢え", "complexity_tier": "T3", "furigana": "豊(ゆた)かな国(くに)でも、飢(う)えに苦(くる)しむ人(ひと)は少(すく)なくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飢え", "label": "基本形"}], "register": "やや書き言葉（常体）", "sense_fingerprint": "食料不足による苦しみ、および比喩的な強い渇望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52122, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飢え", "is_correct": true, "explanation": "『心の飢えを抱えて』の『飢え』で、内面の強い渇望を表す語として合う。"}, {"text": "気温", "is_correct": false, "explanation": "『心の気温』は文脈に合わず、内面を表す語ではない。"}, {"text": "釘", "is_correct": false, "explanation": "『心の釘を抱えて』は意味をなさず、文脈に合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "『心の椅子』は成り立たず、内面の描写と合わない。"}], "explanations": {"飢え": "『心の飢えを抱えて』の『飢え』で、内面の強い渇望を表す語として合う。", "気温": "『心の気温』は文脈に合わず、内面を表す語ではない。", "釘": "『心の釘を抱えて』は意味をなさず、文脈に合わない。", "椅子": "『心の椅子』は成り立たず、内面の描写と合わない。"}, "sentence_index": 0, "correct_answer": "飢え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂漠で水を失い、彼は強い飢えに苦しんだ。", "explanation": "〈渇き〉の意味。水分が足りない苦しさは『飢え』とは言わない。"}, {"text": "寒い夜、彼は強い飢えを覚えて震えた。", "explanation": "〈寒さ〉の意味。震える原因は寒さで、飢えとは言わない。"}, {"text": "腕の飢えに、彼は顔をゆがめた。", "explanation": "〈痛み〉の意味。腕の痛みを表す語であり、飢えは当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52122, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飢え", "is_correct": true, "explanation": "『愛情への飢え』として、強い渇望が心を孤独にする文脈に合う。"}, {"text": "靴", "is_correct": false, "explanation": "『愛情への靴』は成り立たず、心の描写と合わない。"}, {"text": "窓", "is_correct": false, "explanation": "『愛情への窓』は意味をなさず、文脈に合わない。"}, {"text": "石炭", "is_correct": false, "explanation": "『愛情への石炭』は不自然で、心の状態を表せない。"}], "explanations": {"飢え": "『愛情への飢え』として、強い渇望が心を孤独にする文脈に合う。", "靴": "『愛情への靴』は成り立たず、心の描写と合わない。", "窓": "『愛情への窓』は意味をなさず、文脈に合わない。", "石炭": "『愛情への石炭』は不自然で、心の状態を表せない。"}, "sentence_index": 6, "correct_answer": "飢え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真夏の日差しに、彼の体はひどい飢えを帯びた。", "explanation": "〈熱〉の意味。日差しで体が熱くなるのは熱であり、飢えとは言わない。"}, {"text": "別れの飢えに、彼女は沈んだ。", "explanation": "〈悲しみ〉の意味。別れによる感情は悲しみで、飢えとは言わない。"}, {"text": "荷物の飢えに、腕が痛んだ。", "explanation": "〈重さ〉の意味。荷物の重さを表す語で、飢えは当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52122, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "災禍のあと、多くの人が飢えを苦しんだ。", "corrected_sentence": "災禍のあと、多くの人が飢えに苦しんだ。", "error_description": "『苦しむ』は『に』で受ける。『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52122, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い冬、山の村では飢えるに苦しんだ。", "corrected_sentence": "寒い冬、山の村では飢えに苦しんだ。", "error_description": "『飢え』は名詞。動詞『飢える』の形を名詞の位置に使ったのが誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52123, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "を", "is_correct": false, "explanation": "『海からを恵み』は格助詞が重なり、名詞の恵みを修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "『海からに恵み』は〈から〉の後に〈に〉が続かず、文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "『海からで恵み』は場所や手段を示す〈で〉が恵みにつながらない。"}, {"text": "の", "is_correct": true, "explanation": "『海からの恵み』で、海から与えられる産物であることを表す。"}], "correct_answer": "の", "explanations": {"を": "『海からを恵み』は格助詞が重なり、名詞の恵みを修飾できない。", "に": "『海からに恵み』は〈から〉の後に〈に〉が続かず、文が崩れる。", "で": "『海からで恵み』は場所や手段を示す〈で〉が恵みにつながらない。", "の": "『海からの恵み』で、海から与えられる産物であることを表す。"}, "error_tags": {"を": "目的語", "に": "帰着", "で": "場所・手段", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
