INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52123, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然が人に与える、うれしいものや良いことです。", "primary_collocate": null, "pronunciation": "めぐみ", "ipa": "meɡɯmi", "syllable_count": 3, "sentences": [{"text": "秋は、果物がたくさんとれる恵みの季節だ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "秋(あき)は、果物(くだもの)がたくさんとれる恵(めぐ)みの季節(きせつ)だ。", "sentence_source": "generated"}, {"text": "海からの恵みを使った料理が人気だ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "海(うみ)からの恵(めぐ)みを使(つか)った料理(りょうり)が人気(にんき)だ。", "sentence_source": "generated"}, {"text": "この森は、きのこや木の実などの恵みを与えてくれる。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "この森(もり)は、きのこや木(き)の実(み)などの恵(めぐ)みを与(あた)えてくれる。", "sentence_source": "generated"}, {"text": "温泉は、火山がくれる自然の恵みだ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "温泉(おんせん)は、火山(かざん)がくれる自然(しぜん)の恵(めぐ)みだ。", "sentence_source": "generated"}, {"text": "川の水は、町の人々に恵みをもたらす。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "川(かわ)の水(みず)は、町(まち)の人々(ひとびと)に恵(めぐ)みをもたらす。", "sentence_source": "generated"}, {"text": "今年は雨が多く、米も野菜も恵みが豊かだ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "今年(ことし)は雨(あめ)が多(おお)く、米(こめ)も野菜(やさい)も恵(めぐ)みが豊(ゆた)かだ。", "sentence_source": "generated"}, {"text": "畑でとれた野菜は、土の恵みの味がする。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "畑(はたけ)でとれた野菜(やさい)は、土(つち)の恵(めぐ)みの味(あじ)がする。", "sentence_source": "generated"}, {"text": "日の光は、すべての生き物への恵みだ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "日(ひ)の光(ひかり)は、すべての生(い)き物(もの)への恵(めぐ)みだ。", "sentence_source": "generated"}, {"text": "山の恵みをいただいて、みんなで鍋を作った。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "山(やま)の恵(めぐ)みをいただいて、みんなで鍋(なべ)を作(つく)った。", "sentence_source": "generated"}, {"text": "雪どけ水は、春の恵みとして田に流れ込む。", "target_word": "恵み", "complexity_tier": "T4", "furigana": "雪(ゆき)どけ水(みず)は、春(はる)の恵(めぐ)みとして田(た)に流(なが)れ込(こ)む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "恵み", "label": "基本形"}], "register": "やや書き言葉（常体）", "sense_fingerprint": "自然が人にもたらす収穫などのうれしい産物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 雪どけ (Zipf 1.81)']::text[], '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52123, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罰", "is_correct": false, "explanation": "罰の季節は意味が通らず、果物がたくさんとれる豊作の文脈と合わない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝床の季節は文として成り立たず、豊作を表す文脈に合わない。"}, {"text": "恵み", "is_correct": true, "explanation": "果物などがたくさんとれる自然の産物を指し、豊作の季節を表す文に合う。"}, {"text": "鉄骨", "is_correct": false, "explanation": "鉄骨は建築材料で、果物の豊作を表す文脈とは無関係。"}], "explanations": {"罰": "罰の季節は意味が通らず、果物がたくさんとれる豊作の文脈と合わない。", "寝床": "寝床の季節は文として成り立たず、豊作を表す文脈に合わない。", "恵み": "果物などがたくさんとれる自然の産物を指し、豊作の季節を表す文に合う。", "鉄骨": "鉄骨は建築材料で、果物の豊作を表す文脈とは無関係。"}, "sentence_index": 0, "correct_answer": "恵み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の排水は、川の生き物に恵みをもたらす。", "explanation": "ここは〈害〉の意味。恵みは良い産物を指すので、生き物に害を与える排水には合わない。"}, {"text": "引っ越しの費用は、家計にとって大きな恵みだ。", "explanation": "ここは〈負担〉の意味。恵みは喜ばしいものを指すので、家計への重い負担には合わない。"}, {"text": "彼は嘘をついた恵みとして、一週間外出禁止になった。", "explanation": "ここは〈罰〉の意味。恵みは喜ばしいものを指すので、罰として外出を禁じる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52123, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煙", "is_correct": false, "explanation": "煙は燃焼で生じるもので、土の産物の味を表す文には合わない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は不快な音で、野菜の味を表す文脈とは無関係。"}, {"text": "鉄くず", "is_correct": false, "explanation": "鉄くずは金属の廃材で、畑でとれた野菜の味とは結びつかない。"}, {"text": "恵み", "is_correct": true, "explanation": "土が与える自然の産物を指し、野菜の味を土の恵みとして表す文に合う。"}], "explanations": {"煙": "煙は燃焼で生じるもので、土の産物の味を表す文には合わない。", "騒音": "騒音は不快な音で、野菜の味を表す文脈とは無関係。", "鉄くず": "鉄くずは金属の廃材で、畑でとれた野菜の味とは結びつかない。", "恵み": "土が与える自然の産物を指し、野菜の味を土の恵みとして表す文に合う。"}, "sentence_index": 6, "correct_answer": "恵み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "袖についた恵みは、なかなか落ちない。", "explanation": "ここは〈汚れ〉の意味。恵みは良いものを指すので、落ちにくい汚れには使わない。"}, {"text": "この計画の最大の恵みは、費用が高すぎることだ。", "explanation": "ここは〈欠点〉の意味。恵みは利点を指すので、欠点を述べる文には合わない。"}, {"text": "会場には大きな恵みが渦巻いた。", "explanation": "ここは〈怒り〉の意味。恵みは喜ばしいものを指すので、会場に渦巻く怒りの描写には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52123, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地方は山の恵みを頼って暮らしている。", "corrected_sentence": "この地方は山の恵みに頼って暮らしている。", "error_description": "〈頼る〉は〈に〉で対象を取るため、恵みに〈を〉を付けたのは誤り。正しくは〈恵みに頼って〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52123, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この森の水は恵みなから、安心して飲める。", "corrected_sentence": "この森の水は恵みだから、安心して飲める。", "error_description": "恵みは名詞なので、理由を表す〈だから〉の〈だ〉を〈な〉にした形は誤り。正しくは〈恵みだから〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52124, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "を", "is_correct": false, "explanation": "『天を恵み』は名詞の恵みに対する目的語の形にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『天で恵み』は場所や手段を表すが、名詞の恵みにつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "『天へ恵み』は方向を表すが、恵みを修飾する形にならない。"}, {"text": "の", "is_correct": true, "explanation": "『天の恵み』で、天に所属する恵みであることを表す。"}], "correct_answer": "の", "explanations": {"を": "『天を恵み』は名詞の恵みに対する目的語の形にならず、文が成り立たない。", "で": "『天で恵み』は場所や手段を表すが、名詞の恵みにつながらない。", "へ": "『天へ恵み』は方向を表すが、恵みを修飾する形にならない。", "の": "『天の恵み』で、天に所属する恵みであることを表す。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52124, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "で", "is_correct": false, "explanation": "『神で恵みだと思った』は場所や手段の〈で〉が名詞の恵みにつながらず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『神から恵みだと思った』は起点の〈から〉が恵みの判定に直接つながらず、文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "『神へ恵みだと思った』は方向の〈へ〉が恵みの判定につながらず、文が成り立たない。"}, {"text": "の", "is_correct": true, "explanation": "『神の恵み』で、神から与えられる恵みであることを表す。"}], "correct_answer": "の", "explanations": {"で": "『神で恵みだと思った』は場所や手段の〈で〉が名詞の恵みにつながらず、文が成り立たない。", "から": "『神から恵みだと思った』は起点の〈から〉が恵みの判定に直接つながらず、文が崩れる。", "へ": "『神へ恵みだと思った』は方向の〈へ〉が恵みの判定につながらず、文が成り立たない。", "の": "『神の恵み』で、神から与えられる恵みであることを表す。"}, "error_tags": {"で": "場所・手段", "から": "起点", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52124, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然や神などから与えられる、ありがたい助けや幸福。", "primary_collocate": null, "pronunciation": "めぐみ", "ipa": "meɡɯmi", "syllable_count": 3, "sentences": [{"text": "木漏れ日がその頬を静かに照らす中、彼はただ黙々と、自らの内なる飢えと、この季節の恵みとを一体化させていくのである。", "target_word": "恵み", "complexity_tier": "T5", "furigana": "木漏(こも)れ日(び)がその頬(ほお)を静(しず)かに照(て)らす中(なか)、彼(かれ)はただ黙々(もくもく)と、自(みずか)らの内(うち)なる飢(う)えと、この季節(きせつ)の恵(めぐ)みとを一体化(いったいか)させていくのである。", "sentence_source": "mined"}, {"text": "雨は農家にとって天の恵みだ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "雨(あめ)は農家(のうか)にとって天(てん)の恵(めぐ)みだ。", "sentence_source": "generated"}, {"text": "人々は神の恵みに感謝して祈った。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "人々(ひとびと)は神(かみ)の恵(めぐ)みに感謝(かんしゃ)して祈(いの)った。", "sentence_source": "generated"}, {"text": "山の恵みを分けてもらい、村人は冬を越した。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "山(やま)の恵(めぐ)みを分(わ)けてもらい、村人(むらびと)は冬(ふゆ)を越(こ)した。", "sentence_source": "generated"}, {"text": "海の恵みのおかげで、この町は豊かだ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "海(うみ)の恵(めぐ)みのおかげで、この町(まち)は豊(ゆた)かだ。", "sentence_source": "generated"}, {"text": "長い干ばつのあとの雨は、まさに恵みだった。", "target_word": "恵み", "complexity_tier": "T4", "furigana": "長(なが)い干(かん)ばつのあとの雨(あめ)は、まさに恵(めぐ)みだった。", "sentence_source": "generated"}, {"text": "自然の恵みを大切にしなければならない。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "自然(しぜん)の恵(めぐ)みを大切(たいせつ)にしなければならない。", "sentence_source": "generated"}, {"text": "彼は友人に会えたことを神の恵みだと思った。", "target_word": "恵み", "complexity_tier": "T4", "furigana": "彼(かれ)は友人(ゆうじん)に会(あ)えたことを神(かみ)の恵(めぐ)みだと思(おも)った。", "sentence_source": "generated"}, {"text": "春の日差しは、冬を越えた草木への恵みだ。", "target_word": "恵み", "complexity_tier": "T3", "furigana": "春(はる)の日差(ひざ)しは、冬(ふゆ)を越(こ)えた草木(くさき)への恵(めぐ)みだ。", "sentence_source": "generated"}, {"text": "大地の恵みに感謝して、収穫祭を開く。", "target_word": "恵み", "complexity_tier": "T4", "furigana": "大地(だいち)の恵(めぐ)みに感謝(かんしゃ)して、収穫祭(しゅうかくさい)を開(ひら)く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "恵み", "label": "基本形"}], "register": "やや書き言葉（常体）", "sense_fingerprint": "自然や神から授かるありがたい助け・幸福", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 木漏れ日 (Zipf 2.6), 照らす (Zipf 3.37), 黙々と (Zipf 3.25), 一体化 (Zipf 3.35)']::text[], '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52124, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罰", "is_correct": false, "explanation": "罰は罪に対して科されるもので、自然から与えられる季節の恵みとは意味が合わない。"}, {"text": "恵み", "is_correct": true, "explanation": "自然から与えられるありがたい産物を指し、飢えを抱えた彼がこの季節の恵みを受け入れる文脈に合う。"}, {"text": "災い", "is_correct": false, "explanation": "災いは被害を表し、自然と一体化していく肯定的な流れと噛み合わない。"}, {"text": "報い", "is_correct": false, "explanation": "報いは行為の結果として受けるもので、季節の自然の産物を指す文には合わない。"}], "explanations": {"罰": "罰は罪に対して科されるもので、自然から与えられる季節の恵みとは意味が合わない。", "恵み": "自然から与えられるありがたい産物を指し、飢えを抱えた彼がこの季節の恵みを受け入れる文脈に合う。", "災い": "災いは被害を表し、自然と一体化していく肯定的な流れと噛み合わない。", "報い": "報いは行為の結果として受けるもので、季節の自然の産物を指す文には合わない。"}, "sentence_index": 0, "correct_answer": "恵み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は厳しい恵みに耐え、最後まで旅を続けた。", "explanation": "ここは〈苦難〉の意味。恵みはありがたいものを指すので、耐え忍ぶ苦難の文には合わない。"}, {"text": "彼は怠けの恵みを受けた。", "explanation": "ここは〈報い〉の意味。恵みは与えられるありがたいものなので、怠けの結果には合わない。"}, {"text": "大雨という恵みが村を襲った。", "explanation": "ここは〈災い〉の意味。恵みは良いものを指すので、村を襲う被害には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52124, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怠慢", "is_correct": false, "explanation": "怠慢は怠けることで、自然の産物を大切にする文脈に合わない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は不快な音で、自然を大切にするという文の意味に合わない。"}, {"text": "恵み", "is_correct": true, "explanation": "自然が与えるありがたい産物を指し、大切にすべき対象として自然に入る。"}, {"text": "混雑", "is_correct": false, "explanation": "混雑は人や物が込み合う状態で、自然を大切にする文に意味が合わない。"}], "explanations": {"怠慢": "怠慢は怠けることで、自然の産物を大切にする文脈に合わない。", "騒音": "騒音は不快な音で、自然を大切にするという文の意味に合わない。", "恵み": "自然が与えるありがたい産物を指し、大切にすべき対象として自然に入る。", "混雑": "混雑は人や物が込み合う状態で、自然を大切にする文に意味が合わない。"}, "sentence_index": 6, "correct_answer": "恵み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎年、収入の一部を恵みとして納めている。", "explanation": "ここは〈税金〉の意味。恵みは与えられるありがたいものなので、納める対象にはならない。"}, {"text": "彼は通勤途中、大きな恵みに遭って入院した。", "explanation": "ここは〈事故〉の意味。恵みは良いことを指すので、事故に遭って入院する文には合わない。"}, {"text": "昨夜から恵みをひいてしまった。", "explanation": "ここは〈風邪〉の意味。恵みは病気を表さず、『ひく』とも結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52124, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その村は山の恵みに得て、冬を越すことができた。", "corrected_sentence": "その村は山の恵みを得て、冬を越すことができた。", "error_description": "〈得る〉は対象を〈を〉で取るため、恵みに〈に〉を付けたのは誤り。正しくは〈恵みを得て〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52124, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川の水は大地の恵みなから、大切に使おう。", "corrected_sentence": "川の水は大地の恵みだから、大切に使おう。", "error_description": "恵みは名詞なので、理由を表す〈だから〉の〈だ〉を〈な〉にした形は誤り。正しくは〈恵みだから〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
