INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52127, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "で", "is_correct": false, "explanation": "『一体でものなので』は場所や手段の〈で〉が名詞の修飾にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『一体にものなので』は〈に〉が〈もの〉を修飾できず、不自然で文が崩れる。"}, {"text": "から", "is_correct": false, "explanation": "『一体からものなので』は起点の〈から〉が名詞の修飾にならず、文が成り立たない。"}, {"text": "の", "is_correct": true, "explanation": "『一体のものなので』の〈の〉で、一つにまとまったものであることを表す。"}], "correct_answer": "の", "explanations": {"で": "『一体でものなので』は場所や手段の〈で〉が名詞の修飾にならず、文が成り立たない。", "に": "『一体にものなので』は〈に〉が〈もの〉を修飾できず、不自然で文が崩れる。", "から": "『一体からものなので』は起点の〈から〉が名詞の修飾にならず、文が成り立たない。", "の": "『一体のものなので』の〈の〉で、一つにまとまったものであることを表す。"}, "error_tags": {"で": "場所・手段", "に": "帰着", "から": "起点", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52127, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一つにまとまったもの。全部。", "primary_collocate": null, "pronunciation": "いったい", "ipa": "itːai", "syllable_count": 4, "sentences": [{"text": "この家具は椅子と机が一体のものなので、分けて使うことはできない。", "target_word": "一体", "complexity_tier": "T3", "furigana": "このかぐはいすとつくえがいったいのものなので、わけてつかうことはできない。", "sentence_source": "generated"}, {"text": "土地と建物は一体として売られるので、片方だけは買えない。", "target_word": "一体", "complexity_tier": "T3", "furigana": "とちとたてものはいったいとしてうられるので、かたほうだけはかえない。", "sentence_source": "generated"}, {"text": "心と体は一体であり、疲れた心は体にも影響する。", "target_word": "一体", "complexity_tier": "T3", "furigana": "こころとからだはいったいであり、つかれたこころはからだにもえいきょうする。", "sentence_source": "generated"}, {"text": "この部品は三つの部分が一体に作られているため、壊れにくい。", "target_word": "一体", "complexity_tier": "T3", "furigana": "このぶひんはみっつのぶぶんがいったいにつくられているため、こわれにくい。", "sentence_source": "generated"}, {"text": "二つの店は別の名前だが、経営は一体で行われている。", "target_word": "一体", "complexity_tier": "T3", "furigana": "ふたつのみせはべつのなまえだが、けいえいはいったいでおこなわれている。", "sentence_source": "generated"}, {"text": "国と国民は一体であるべきだと、市長は演説で述べた。", "target_word": "一体", "complexity_tier": "T3", "furigana": "くにとこくみんはいったいであるべきだと、しちょうはえんぜつでのべた。", "sentence_source": "generated"}, {"text": "この像は台と一体の石から彫り出されている。", "target_word": "一体", "complexity_tier": "T3", "furigana": "このぞうはだいといったいのいしからほりだされている。", "sentence_source": "generated"}, {"text": "言葉と文化は一体のものなので、語学を学ぶと文化も知りたくなる。", "target_word": "一体", "complexity_tier": "T3", "furigana": "ことばとぶんかはいったいのものなので、ごがくをまなぶとぶんかもしりたくなる。", "sentence_source": "generated"}, {"text": "家族は一体だから、悩みがあれば分け合うものだ。", "target_word": "一体", "complexity_tier": "T3", "furigana": "かぞくはいったいだから、なやみがあればわけあうものだ。", "sentence_source": "generated"}, {"text": "セットの商品は本体と付属品を一体として扱い、返品も一緒にする。", "target_word": "一体", "complexity_tier": "T3", "furigana": "セットのしょうひんはほんたいとふぞくひんをいったいとしてあつかい、へんぴんもいっしょにする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一体", "label": "基本形"}], "register": "中立", "sense_fingerprint": "分けられない一つのまとまりとして扱われるもの(一体のもの・一体として)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52127, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑草", "is_correct": false, "explanation": "雑草は野に生える植物で、椅子と机の組み合わせを表す文には合わない。"}, {"text": "氷河", "is_correct": false, "explanation": "氷河は大規模な氷の塊で、家具の組み合わせを表す文とは無関係。"}, {"text": "紙袋", "is_correct": false, "explanation": "紙袋は包装に使うもので、家具が一つにまとまっている状態を表さない。"}, {"text": "一体", "is_correct": true, "explanation": "椅子と机が一つにまとまったものであることを表し、分けて使えない理由として合う。"}], "explanations": {"雑草": "雑草は野に生える植物で、椅子と机の組み合わせを表す文には合わない。", "氷河": "氷河は大規模な氷の塊で、家具の組み合わせを表す文とは無関係。", "紙袋": "紙袋は包装に使うもので、家具が一つにまとまっている状態を表さない。", "一体": "椅子と机が一つにまとまったものであることを表し、分けて使えない理由として合う。"}, "sentence_index": 0, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その村には、一体の住人しか残っていない。", "explanation": "ここは助数詞の〈人〉。一体は人形や像などを数える語で、人を数える文には使えない。"}, {"text": "この家具の一体は別売りです。", "explanation": "ここは〈一部〉の意味。一体は全部を表すので、部分を別売りとする文には合わない。"}, {"text": "この店では、りんごを一体ずつ売っている。", "explanation": "ここは助数詞の〈個〉。一体は人形や像などを数える語で、果物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52127, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墨", "is_correct": false, "explanation": "墨は書画に使う黒い材料で、石の作り方を表す文には合わない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は携帯用の寝具で、台と石の関係を表す文とは無関係。"}, {"text": "雨漏り", "is_correct": false, "explanation": "雨漏りは建物の不具合で、像を彫り出す文脈に合わない。"}, {"text": "一体", "is_correct": true, "explanation": "台と一つに続く石から像が彫り出されていることを表し、文の意味に合う。"}], "explanations": {"墨": "墨は書画に使う黒い材料で、石の作り方を表す文には合わない。", "寝袋": "寝袋は携帯用の寝具で、台と石の関係を表す文とは無関係。", "雨漏り": "雨漏りは建物の不具合で、像を彫り出す文脈に合わない。", "一体": "台と一つに続く石から像が彫り出されていることを表し、文の意味に合う。"}, "sentence_index": 6, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の一体は、とても優しい性格だ。", "explanation": "ここは〈人柄〉の意味。一体は全体のまとまりや全部を表すので、人の性格を述べる文には合わない。"}, {"text": "彼は一体の年齢を聞かれて困った。", "explanation": "ここは〈年齢〉の意味。一体は全体やまとまりを表すので、年齢を指す文には合わない。"}, {"text": "彼の一体はとても背が高い。", "explanation": "ここは〈体〉の意味。一体は全体のまとまりを表す語で、人の身体を指す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52127, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部品は一体なから、取り外せない。", "corrected_sentence": "この部品は一体だから、取り外せない。", "error_description": "名詞の〈だ〉を理由の〈だから〉に続ける形なので、〈なから〉は誤り。正しくは〈一体だから〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52127, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この製品は本体と付属品を一体を扱い、保証も一緒にする。", "corrected_sentence": "この製品は本体と付属品を一体として扱い、保証も一緒にする。", "error_description": "〈一体として扱う〉の形なので、〈として〉を〈を〉にした形は誤り。〈一体〉を扱うには〈として〉で資格を示す必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
