INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52128, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "を", "is_correct": false, "explanation": "『一体を動いた』は〈動く〉が目的語を取らず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『一体へ動いた』は方向を示すが、動作の様子を表す〈で〉の位置に合わない。"}, {"text": "より", "is_correct": false, "explanation": "『一体より動いた』は比較の形になり、動作の仕方を表さない。"}, {"text": "で", "is_correct": true, "explanation": "『一体で動いた』で、全体が一つにまとまって動いたという動作の仕方を表す。"}], "correct_answer": "で", "explanations": {"を": "『一体を動いた』は〈動く〉が目的語を取らず、文が成り立たない。", "へ": "『一体へ動いた』は方向を示すが、動作の様子を表す〈で〉の位置に合わない。", "より": "『一体より動いた』は比較の形になり、動作の仕方を表さない。", "で": "『一体で動いた』で、全体が一つにまとまって動いたという動作の仕方を表す。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較", "で": "動作の仕方・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52128, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体が一つにまとまっていること。また、そのもの。統一された状態。", "primary_collocate": null, "pronunciation": "いったい", "ipa": "itːai", "syllable_count": 4, "sentences": [{"text": "長い話し合いの末、二つの村は互いの暮らしを分けられないほど一体となった。", "target_word": "一体", "complexity_tier": "T4", "furigana": "長(なが)い話(はなし)し合(あ)いの末(すえ)、二(ふた)つの村(むら)は互(たが)いの暮(く)らしを分(わ)けられないほど一体(いったい)となった。", "sentence_source": "generated"}, {"text": "この二つの会社は一体となって新しい町づくりを進めている。", "target_word": "一体", "complexity_tier": "T3", "furigana": "このふたつのかいしゃはいったいとなってあたらしいまちづくりをすすめている。", "sentence_source": "generated"}, {"text": "選手とファンが一体になって、スタジアムは大きな声に包まれた。", "target_word": "一体", "complexity_tier": "T3", "furigana": "せんしゅとファンがいったいになって、スタジアムはおおきなこえにつつまれた。", "sentence_source": "generated"}, {"text": "建物と庭が一体のデザインなので、部屋から見る景色が広く感じられる。", "target_word": "一体", "complexity_tier": "T3", "furigana": "たてものとにわがいったいのデザインなので、へやからみるけしきがひろくかんじられる。", "sentence_source": "generated"}, {"text": "親と学校が一体で取り組まなければ、いじめはなくならない。", "target_word": "一体", "complexity_tier": "T3", "furigana": "おやとがっこうがいったいでとりくまなければ、いじめはなくならない。", "sentence_source": "generated"}, {"text": "踊り手と音楽が一体となった瞬間、会場は静まり返った。", "target_word": "一体", "complexity_tier": "T3", "furigana": "おどりてとおんがくがいったいとなったしゅんかん、かいじょうはしずまりかえった。", "sentence_source": "generated"}, {"text": "この机は棚と一体に作られているため、場所を取らない。", "target_word": "一体", "complexity_tier": "T3", "furigana": "このつくえはたなといったいにつくられているため、ばしょをとらない。", "sentence_source": "generated"}, {"text": "政府と地方が一体で動いたおかげで、復旧は予定より早く進んだ。", "target_word": "一体", "complexity_tier": "T3", "furigana": "せいふとちほうがいったいでうごいたおかげで、ふっきゅうはよていよりはやくすすんだ。", "sentence_source": "generated"}, {"text": "馬と人が一体になって走る姿は、とても美しい。", "target_word": "一体", "complexity_tier": "T3", "furigana": "うまとひとがいったいになってはしるすがたは、とてもうつくしい。", "sentence_source": "generated"}, {"text": "全員の気持ちが一体になれば、どんな困難も乗り越えられると信じている。", "target_word": "一体", "complexity_tier": "T3", "furigana": "ぜんいんのきもちがいったいになれば、どんなこんなんものりこえられるとしんじている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一体", "label": "基本形"}, {"form": "一体に", "label": "副詞的用法"}], "register": "中立", "sense_fingerprint": "複数のものが分けられず一つにまとまった状態(一体となる・一体の)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 静まり返っ (Zipf 2.4)']::text[], '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52128, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一体", "is_correct": true, "explanation": "二つの村の暮らしが分けられないほど結びつく文脈で、『一体となった』の語として合う。"}, {"text": "分裂", "is_correct": false, "explanation": "分裂は分かれることで、分けられないほど結びつく文の意味と逆になる。"}, {"text": "孤立", "is_correct": false, "explanation": "孤立は単独になることで、互いの暮らしを結びつける文脈に合わない。"}, {"text": "対立", "is_correct": false, "explanation": "対立は互いに争うことで、分けられないほど結びつく文の流れと噛み合わない。"}], "explanations": {"一体": "二つの村の暮らしが分けられないほど結びつく文脈で、『一体となった』の語として合う。", "分裂": "分裂は分かれることで、分けられないほど結びつく文の意味と逆になる。", "孤立": "孤立は単独になることで、互いの暮らしを結びつける文脈に合わない。", "対立": "対立は互いに争うことで、分けられないほど結びつく文の流れと噛み合わない。"}, "sentence_index": 0, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "チームの一体を固めるため、合宿を開いた。", "explanation": "ここは〈結束〉の意味。「結束を固める」とは言うが、「一体を固める」とは言わないので、この文には合わない。"}, {"text": "試験の答えの一体を確認した。", "explanation": "ここは〈一致〉の意味。答えを照合するときは「答えの一致」と言い、一体では表せない。"}, {"text": "この寺には、古い仏像が一体安置されている。", "explanation": "ここは助数詞の〈体〉。仏像などを数える用法で、統一された状態の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52128, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紙袋", "is_correct": false, "explanation": "紙袋は包装用品で、机の作りを表す文脈には合わない。"}, {"text": "一体", "is_correct": true, "explanation": "棚と一つにまとめて作られた机であることを表し、場所を取らない理由として合う。"}, {"text": "機密", "is_correct": false, "explanation": "機密は秘密の情報を指し、家具の作られ方を表す文には合わない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は携帯用の寝具で、棚と机の作りを表す文の意味に合わない。"}], "explanations": {"紙袋": "紙袋は包装用品で、机の作りを表す文脈には合わない。", "一体": "棚と一つにまとめて作られた机であることを表し、場所を取らない理由として合う。", "機密": "機密は秘密の情報を指し、家具の作られ方を表す文には合わない。", "寝袋": "寝袋は携帯用の寝具で、棚と机の作りを表す文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄弟は財産をめぐって激しい一体を続けた。", "explanation": "ここは〈争い〉の意味。一体は一つにまとまることで、争いを表す文には合わない。"}, {"text": "彼は故郷を離れて一体を感じた。", "explanation": "ここは〈孤独〉の意味。一体は仲間とまとまる状態で、ひとりで感じる孤独には合わない。"}, {"text": "地震で多くの一体が出た。", "explanation": "ここは〈損失〉の意味。一体は欠けていない状態なので、被害の数を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52128, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この二つの団体は一体をなって地域を守ってきた。", "corrected_sentence": "この二つの団体は一体となって地域を守ってきた。", "error_description": "〈一体となる〉は〈と〉で結ばれる形なので、〈を〉を使ったのは誤り。正しくは〈一体となって〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52128, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人々が一体にして祭りを盛り上げた。", "corrected_sentence": "町の人々が一体になって祭りを盛り上げた。", "error_description": "人々がまとまる場面なので〈一体になって〉が正しい。〈一体にして〉は〈一つにする〉の他動詞の形で、人々が主語の文に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52129, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「摂理に逆らう」で、逆らう相手を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を表すが、「逆らう」は「に」を取るので誤り。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段。「摂理で逆らう」では相手を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語。「摂理が逆らう」では意味が逆転して不自然。"}], "correct_answer": "に", "explanations": {"に": "「摂理に逆らう」で、逆らう相手を表す。", "を": "「を」は対象を表すが、「逆らう」は「に」を取るので誤り。", "で": "「で」は場所・手段。「摂理で逆らう」では相手を示せない。", "が": "「が」は主語。「摂理が逆らう」では意味が逆転して不自然。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52129, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「摂理にかなう」で、道理に合うことを表す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向。「摂理へかなう」では対象が合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点。「摂理からかなう」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「摂理のかなう」では述語とつながらない。"}], "correct_answer": "に", "explanations": {"に": "「摂理にかなう」で、道理に合うことを表す。", "へ": "「へ」は方向。「摂理へかなう」では対象が合わない。", "から": "「から」は起点。「摂理からかなう」では意味が通らない。", "の": "「の」は名詞をつなぐ。「摂理のかなう」では述語とつながらない。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52129, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世界の決まりや道理のこと。", "primary_collocate": null, "pronunciation": "せつり", "ipa": "set͡sɯɾi", "syllable_count": 3, "sentences": [{"text": "生き物がいつか死ぬのは、自然の摂理だ。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "生[い]き物[もの]がいつか死[し]ぬのは、自然[しぜん]の摂理[せつり]だ。", "sentence_source": "generated"}, {"text": "彼は、摂理に逆らって生きることはできないと悟った。", "target_word": "摂理", "complexity_tier": "T4", "furigana": "彼[かれ]は、摂理[せつり]に逆[さか]らって生[い]きることはできないと悟[さと]った。", "sentence_source": "generated"}, {"text": "季節がめぐるのは、世界の摂理である。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "季節[きせつ]がめぐるのは、世界[せかい]の摂理[せつり]である。", "sentence_source": "generated"}, {"text": "弱い者が強い者に食べられるのも、自然界の摂理だ。", "target_word": "摂理", "complexity_tier": "T4", "furigana": "弱[よわ]い者[もの]が強[つよ]い者[もの]に食[た]べられるのも、自然界[しぜんかい]の摂理[せつり]だ。", "sentence_source": "generated"}, {"text": "親より先に子が死ぬのは、摂理に反する悲しいことだ。", "target_word": "摂理", "complexity_tier": "T4", "furigana": "親[おや]より先[さき]に子[こ]が死[し]ぬのは、摂理[せつり]に反[はん]する悲[かな]しいことだ。", "sentence_source": "generated"}, {"text": "昼のあとに夜が来るのは、宇宙の摂理と言える。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "昼[ひる]のあとに夜[よる]が来[く]るのは、宇宙[うちゅう]の摂理[せつり]と言[い]える。", "sentence_source": "generated"}, {"text": "老いることは摂理だと分かっていても、さびしい。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "老[お]いることは摂理[せつり]だと分[わ]かっていても、さびしい。", "sentence_source": "generated"}, {"text": "水が低い所へ流れるのは、自然の摂理にかなっている。", "target_word": "摂理", "complexity_tier": "T4", "furigana": "水[みず]が低[ひく]い所[ところ]へ流[なが]れるのは、自然[しぜん]の摂理[せつり]にかなっている。", "sentence_source": "generated"}, {"text": "人間が自然の摂理を無視すれば、いつか困ることになる。", "target_word": "摂理", "complexity_tier": "T4", "furigana": "人間[にんげん]が自然[しぜん]の摂理[せつり]を無視[むし]すれば、いつか困[こま]ることになる。", "sentence_source": "generated"}, {"text": "祖父は、命がめぐる摂理を静かに語ってくれた。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "祖父[そふ]は、命[いのち]がめぐる摂理[せつり]を静[しず]かに語[かた]ってくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "摂理", "label": "基本形"}, {"form": "摂理の", "label": "連体形(の)"}, {"form": "摂理に", "label": "に格"}], "register": "改まった書き言葉寄り", "sense_fingerprint": "名詞。自然や世界を成り立たせている、人の力では変えられない決まり・道理。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52129, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摂理", "is_correct": true, "explanation": "「自然の摂理」で、自然界を成り立たせる決まりを表す。"}, {"text": "悩み", "is_correct": false, "explanation": "悩みは心配ごとで、自然界の決まりを表さない。"}, {"text": "名誉", "is_correct": false, "explanation": "名誉は評価や誉れで、自然の決まりとは合わない。"}, {"text": "不満", "is_correct": false, "explanation": "不満は満たされない気持ちで、自然界の道理には使わない。"}], "explanations": {"摂理": "「自然の摂理」で、自然界を成り立たせる決まりを表す。", "悩み": "悩みは心配ごとで、自然界の決まりを表さない。", "名誉": "名誉は評価や誉れで、自然の決まりとは合わない。", "不満": "不満は満たされない気持ちで、自然界の道理には使わない。"}, "sentence_index": 0, "correct_answer": "摂理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の摂理は、世界一のパン職人になることだ。", "explanation": "ここは〈目標・夢〉の意味（目標）。摂理は世界の決まりや道理で、個人の目指すことには使わない。"}, {"text": "学校の摂理では、遅刻は禁止だ。", "explanation": "ここは〈取り決め〉の意味（規則）。摂理は人が定める決まりではないので合わない。"}, {"text": "この地域には、古い摂理が今も残っている。", "explanation": "ここは〈しきたり〉の意味（慣習）。摂理は自然の道理で、地域の古い風習には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52129, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摂理", "is_correct": true, "explanation": "「摂理だと分かっていても」で、老いが避けられない世界の道理を表す。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の動きで、老いを道理として言う文には合わない。"}, {"text": "信用", "is_correct": false, "explanation": "信用は相手を頼れると思うこと。老いの説明には使わない。"}, {"text": "旋律", "is_correct": false, "explanation": "旋律は音楽の流れで、老いの説明には合わない。"}], "explanations": {"摂理": "「摂理だと分かっていても」で、老いが避けられない世界の道理を表す。", "感情": "感情は心の動きで、老いを道理として言う文には合わない。", "信用": "信用は相手を頼れると思うこと。老いの説明には使わない。", "旋律": "旋律は音楽の流れで、老いの説明には合わない。"}, "sentence_index": 6, "correct_answer": "摂理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この失敗から摂理を得た。", "explanation": "ここは〈得た学び〉の意味（教訓）。摂理は自然の決まりで、学んで得る内容には使わない。"}, {"text": "この摂理で面積を求められる。", "explanation": "ここは〈計算の決まり〉の意味（公式）。摂理は自然界の道理で、計算の手順には使わない。"}, {"text": "食卓では、箸の摂理を守ろう。", "explanation": "ここは〈礼儀としての決まり〉の意味（作法）。摂理は自然の道理で、人の礼儀には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52129, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は自然の摂理を従って生きている。", "corrected_sentence": "彼は自然の摂理に従って生きている。", "error_description": "「従う」は「〜に従う」の形で、助詞は「に」。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52129, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人は摂理を開くことはできない。", "corrected_sentence": "人は摂理を破ることはできない。", "error_description": "「摂理」と結びつく動詞は「破る」「逆らう」など。「開く」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52131, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「宇宙に」で、星が存在する場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象につく。「宇宙を」では「ある」と結べず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「宇宙の」の後に「は」が続いても存在の場所にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表す。存在を述べる文では場所は「に」で表す。"}], "correct_answer": "に", "explanations": {"に": "「宇宙に」で、星が存在する場所を表す。", "を": "「を」は動作の対象につく。「宇宙を」では「ある」と結べず不自然。", "の": "「の」は名詞をつなぐ。「宇宙の」の後に「は」が続いても存在の場所にならない。", "へ": "「へ」は移動の方向を表す。存在を述べる文では場所は「に」で表す。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52131, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「宇宙の果て」で、宇宙の端を表す。「の」が果てを修飾する。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を表す。「宇宙で果て」では名詞同士がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向。「宇宙へ果て」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点。「宇宙から果て」では果てを限定できない。"}], "correct_answer": "の", "explanations": {"の": "「宇宙の果て」で、宇宙の端を表す。「の」が果てを修飾する。", "で": "「で」は場所・手段を表す。「宇宙で果て」では名詞同士がつながらない。", "へ": "「へ」は方向。「宇宙へ果て」では意味が通らない。", "から": "「から」は起点。「宇宙から果て」では果てを限定できない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52131, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "すべてのほしや ちきゅうが ある とても ひろい ところ", "primary_collocate": null, "pronunciation": "うちゅう", "ipa": "ɯt͡ɕɯː", "syllable_count": 3, "sentences": [{"text": "夜空を見ていると、宇宙の広さを感じる。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "夜空[よぞら]を見[み]ていると、宇宙[うちゅう]の広[ひろ]さを感[かん]じる。", "sentence_source": "generated"}, {"text": "宇宙には、数え切れないほどの星がある。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]には、数[かぞ]え切[き]れないほどの星[ほし]がある。", "sentence_source": "generated"}, {"text": "子どものころ、宇宙に行くのが夢だった。", "target_word": "宇宙", "complexity_tier": "T2", "furigana": "子[こ]どものころ、宇宙[うちゅう]に行[い]くのが夢[ゆめ]だった。", "sentence_source": "generated"}, {"text": "宇宙では、音が伝わらないと言われている。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]では、音[おと]が伝[つた]わらないと言[い]われている。", "sentence_source": "generated"}, {"text": "ロケットが宇宙へ向かって飛び立った。", "target_word": "宇宙", "complexity_tier": "T2", "furigana": "ロケットが宇宙[うちゅう]へ向[む]かって飛[と]び立[た]った。", "sentence_source": "generated"}, {"text": "宇宙は今も広がり続けているそうだ。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]は今[いま]も広[ひろ]がり続[つづ]けているそうだ。", "sentence_source": "generated"}, {"text": "宇宙から見た地球は、青くて美しかった。", "target_word": "宇宙", "complexity_tier": "T2", "furigana": "宇宙[うちゅう]から見[み]た地球[ちきゅう]は、青[あお]くて美[うつく]しかった。", "sentence_source": "generated"}, {"text": "望遠鏡で宇宙の果てを調べる研究が進んでいる。", "target_word": "宇宙", "complexity_tier": "T4", "furigana": "望遠鏡[ぼうえんきょう]で宇宙[うちゅう]の果[は]てを調[しら]べる研究[けんきゅう]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "宇宙に比べれば、私たちの悩みはとても小さい。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]に比[くら]べれば、私[わたし]たちの悩[なや]みはとても小[ちい]さい。", "sentence_source": "generated"}, {"text": "宇宙の中で、生き物がいる星は地球だけかもしれない。", "target_word": "宇宙", "complexity_tier": "T4", "furigana": "宇宙[うちゅう]の中[なか]で、生[い]き物[もの]がいる星[ほし]は地球[ちきゅう]だけかもしれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "宇宙", "label": "基本形"}, {"form": "宇宙の", "label": "連体形(の)"}, {"form": "宇宙に", "label": "に格"}], "register": "標準", "sense_fingerprint": "名詞。地球や星などをすべて含む、果てしなく広い空間。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52131, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宇宙", "is_correct": true, "explanation": "「宇宙の広さ」で、星や空間を含む果てしない空間を表す。"}, {"text": "夜明け", "is_correct": false, "explanation": "夜明けは時刻を表し、広さを感じる対象にはならない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は家電で、夜空の広さを感じる文脈では合わない。"}, {"text": "悲鳴", "is_correct": false, "explanation": "悲鳴は叫び声で、空の広がりには結びつかない。"}], "explanations": {"宇宙": "「宇宙の広さ」で、星や空間を含む果てしない空間を表す。", "夜明け": "夜明けは時刻を表し、広さを感じる対象にはならない。", "洗濯機": "洗濯機は家電で、夜空の広さを感じる文脈では合わない。", "悲鳴": "悲鳴は叫び声で、空の広がりには結びつかない。"}, "sentence_index": 0, "correct_answer": "宇宙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宇宙が暗くなってきた。", "explanation": "ここは〈空〉の意味。宇宙は地球の外の空間を指し、夕方の空模様には使わない。"}, {"text": "この宇宙は三人乗りで、とても狭い。", "explanation": "宇宙船は「宇宙船」と言い、「宇宙」だけで乗り物を指すことはない。"}, {"text": "この部屋は広くて、宇宙がゆったりしている。", "explanation": "ここは〈空間〉の意味。宇宙は地球の外の空間を指すので、部屋の広さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52131, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宇宙", "is_correct": true, "explanation": "「宇宙から見た地球」で、地球の外の空間を指す。"}, {"text": "教室", "is_correct": false, "explanation": "「教室から見た地球」は成り立たない。場所として文が通らない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は家の一部で、地球を見る視点としては合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は感覚で、地球を見る場所を表さない。"}], "explanations": {"宇宙": "「宇宙から見た地球」で、地球の外の空間を指す。", "教室": "「教室から見た地球」は成り立たない。場所として文が通らない。", "台所": "台所は家の一部で、地球を見る視点としては合わない。", "眠気": "眠気は感覚で、地球を見る場所を表さない。"}, "sentence_index": 6, "correct_answer": "宇宙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁の宇宙から風が入ってくる。", "explanation": "宇宙は地球の外の空間を指し、壁の穴やすき間の意味では使わない。"}, {"text": "山の宇宙はとても澄んでいる。", "explanation": "宇宙は地球の外の空間を指し、空気の澄み具合の話には使わない。"}, {"text": "畑の宇宙は、ふかふかしている。", "explanation": "宇宙は地球の外の空間を指し、土の状態を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52131, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族と宇宙で行く日を夢見ている。", "corrected_sentence": "家族と宇宙へ行く日を夢見ている。", "error_description": "「行く」は行き先に「へ」を使う。「で」は行為の場所を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52131, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宇宙な果てを想像してみる。", "corrected_sentence": "宇宙の果てを想像してみる。", "error_description": "「宇宙」は名詞なので、名詞修飾は「の」。「な」は形容動詞の語尾で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52135, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「今日の昼食は」の「は」。話題を示す主題の助詞で、正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「昼食へ」は方向を表し、ここは主題として合わない。"}, {"text": "から", "is_correct": false, "explanation": "「昼食から」は起点を表し、主題にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「昼食より」は比較を表し、ここでは意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「今日の昼食は」の「は」。話題を示す主題の助詞で、正しい。", "へ": "「昼食へ」は方向を表し、ここは主題として合わない。", "から": "「昼食から」は起点を表し、主題にはならない。", "より": "「昼食より」は比較を表し、ここでは意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
