INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52135, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お昼に食べるご飯のことです。", "primary_collocate": null, "pronunciation": "ちゅうしょく", "ipa": "tɕɯːɕokɯ", "syllable_count": 4, "sentences": [{"text": "昼食は、いつも教室で友達と食べます。", "target_word": "昼食", "complexity_tier": "T2", "furigana": "昼食[ちゅうしょく]は、いつも教室[きょうしつ]で友達[ともだち]と食[た]べます。", "sentence_source": "generated"}, {"text": "今日の昼食は、カレーライスでした。", "target_word": "昼食", "complexity_tier": "T2", "furigana": "今日[きょう]の昼食[ちゅうしょく]は、カレーライスでした。", "sentence_source": "generated"}, {"text": "昼食の前に、手をきれいに洗いましょう。", "target_word": "昼食", "complexity_tier": "T2", "furigana": "昼食[ちゅうしょく]の前[まえ]に、手[て]をきれいに洗[あら]いましょう。", "sentence_source": "generated"}, {"text": "学校では、十二時半から昼食を食べます。", "target_word": "昼食", "complexity_tier": "T2", "furigana": "学校[がっこう]では、十二時半[じゅうにじはん]から昼食[ちゅうしょく]を食[た]べます。", "sentence_source": "generated"}, {"text": "妹は昼食にサンドイッチを食べた。", "target_word": "昼食", "complexity_tier": "T2", "furigana": "妹[いもうと]は昼食[ちゅうしょく]にサンドイッチを食[た]べた。", "sentence_source": "generated"}, {"text": "昼食を食べたあと、眠くなってしまった。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "昼食[ちゅうしょく]を食[た]べたあと、眠[ねむ]くなってしまった。", "sentence_source": "generated"}, {"text": "弟は朝寝坊をして、昼食まで何も食べなかった。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "弟[おとうと]は朝寝坊[あさねぼう]をして、昼食[ちゅうしょく]まで何[なに]も食[た]べなかった。", "sentence_source": "generated"}, {"text": "雨だったので、昼食は家の中で食べた。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "雨[あめ]だったので、昼食[ちゅうしょく]は家[いえ]の中[なか]で食[た]べた。", "sentence_source": "generated"}, {"text": "父は昼食におにぎりを二つ持っていく。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "父[ちち]は昼食[ちゅうしょく]におにぎりを二[ふた]つ持[も]っていく。", "sentence_source": "generated"}, {"text": "昼食が終わると、すぐに午後の授業が始まる。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "昼食[ちゅうしょく]が終[お]わると、すぐに午後[ごご]の授業[じゅぎょう]が始[はじ]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昼食", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "お昼に食べるご飯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52135, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昼食", "is_correct": true, "explanation": "食べ物で、教室で友達と食べるものとして文が成り立つ。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は勉強に使う本で、食べるものではない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具で、食べるものとして合わない。"}, {"text": "雑巾", "is_correct": false, "explanation": "雑巾は掃除用の布で、食べる対象ではない。"}], "explanations": {"昼食": "食べ物で、教室で友達と食べるものとして文が成り立つ。", "教科書": "教科書は勉強に使う本で、食べるものではない。", "窓": "窓は建具で、食べるものとして合わない。", "雑巾": "雑巾は掃除用の布で、食べる対象ではない。"}, "sentence_index": 0, "correct_answer": "昼食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昼食は、校庭で遊ぶ時間です。", "explanation": "ここは〈昼休み〉の意味。昼食は食べ物なので、遊ぶ時間の意味にはならない。"}, {"text": "先生は昼食を黒板に貼って、授業を始めた。", "explanation": "ここは〈掲示物〉（黒板に貼る紙）の意味。昼食は食べ物なので、貼るものにはならない。"}, {"text": "昼食は、テストの答えを書く紙です。", "explanation": "ここは〈答案用紙〉の意味。昼食は食べ物なので、答えを書く紙にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52135, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昼食", "is_correct": true, "explanation": "「昼食まで何も食べなかった」で、食べ物としての食事を指す。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は勉強の課題で食べ物ではないので、「何も食べなかった」と合わない。"}, {"text": "布団", "is_correct": false, "explanation": "布団は寝具で、食べる対象ではない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は衣類で、食べるものではない。"}], "explanations": {"昼食": "「昼食まで何も食べなかった」で、食べ物としての食事を指す。", "宿題": "宿題は勉強の課題で食べ物ではないので、「何も食べなかった」と合わない。", "布団": "布団は寝具で、食べる対象ではない。", "靴下": "靴下は衣類で、食べるものではない。"}, "sentence_index": 6, "correct_answer": "昼食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昼食のページを開いて、答えを探した。", "explanation": "ここは〈ページ〉（本の一枚）の意味。昼食は食べ物なので、開いて読むものにはならない。"}, {"text": "昼食の帽子をかぶって、校庭へ出た。", "explanation": "ここは〈帽子〉の意味。昼食は食べ物なので、頭にかぶるものにはならない。"}, {"text": "昼食の笛が鳴ったので、みんな集まった。", "explanation": "ここは〈笛〉（合図に吹くもの）の意味。昼食は食べ物なので、鳴らして合図する道具にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
