INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52136, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "昼の食事。昼ごはん。ランチ。", "primary_collocate": null, "pronunciation": "ちゅうしょく", "ipa": "tɕɯːɕokɯ", "syllable_count": 4, "sentences": [{"text": "忙しい日でも、限られた昼食の時間を大切にしたい。", "target_word": "昼食", "complexity_tier": "T5", "furigana": "忙[いそが]しい日[ひ]でも、限[かぎ]られた昼食[ちゅうしょく]の時間[じかん]を大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "今日の昼食は、会社の近くのそば屋で食べた。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "今日[きょう]の昼食[ちゅうしょく]は、会社[かいしゃ]の近[ちか]くのそば屋[や]で食[た]べた。", "sentence_source": "generated"}, {"text": "昼食に、母が作ったお弁当を持っていく。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "昼食[ちゅうしょく]に、母[はは]が作[つく]ったお弁当[べんとう]を持[も]っていく。", "sentence_source": "generated"}, {"text": "昼食の後、少し散歩をして眠気をさました。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "昼食[ちゅうしょく]の後[あと]、少[すこ]し散歩[さんぽ]をして眠気[ねむけ]をさました。", "sentence_source": "generated"}, {"text": "十二時になったので、みんなで昼食をとった。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "十二時[じゅうにじ]になったので、みんなで昼食[ちゅうしょく]をとった。", "sentence_source": "generated"}, {"text": "昼食を抜くと、午後は集中できなくなる。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "昼食[ちゅうしょく]を抜[ぬ]くと、午後[ごご]は集中[しゅうちゅう]できなくなる。", "sentence_source": "generated"}, {"text": "遠足の昼食は、公園のベンチで食べます。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "遠足[えんそく]の昼食[ちゅうしょく]は、公園[こうえん]のベンチで食[た]べます。", "sentence_source": "generated"}, {"text": "昼食にかける予算は、一日五百円までと決めている。", "target_word": "昼食", "complexity_tier": "T4", "furigana": "昼食[ちゅうしょく]にかける予算[よさん]は、一日[いちにち]五百円[ごひゃくえん]までと決[き]めている。", "sentence_source": "generated"}, {"text": "会議が長引いて、昼食の時間がなくなってしまった。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "会議[かいぎ]が長引[ながび]いて、昼食[ちゅうしょく]の時間[じかん]がなくなってしまった。", "sentence_source": "generated"}, {"text": "日曜日は家族そろって昼食を楽しんだ。", "target_word": "昼食", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は家族[かぞく]そろって昼食[ちゅうしょく]を楽[たの]しんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昼食", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "昼にとる食事、ランチ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52136, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昼食", "is_correct": true, "explanation": "「昼食の時間」で、食事をとる時間を指す。"}, {"text": "皿", "is_correct": false, "explanation": "皿は食器で、「皿の時間」は意味をなさない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、時間を限る対象として合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、時間を限る対象として合わない。"}], "explanations": {"昼食": "「昼食の時間」で、食事をとる時間を指す。", "皿": "皿は食器で、「皿の時間」は意味をなさない。", "鍋": "鍋は調理器具で、時間を限る対象として合わない。", "天気": "天気は空模様で、時間を限る対象として合わない。"}, "sentence_index": 0, "correct_answer": "昼食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昼になると、昼食は学生で混みあう。", "explanation": "ここは〈食堂〉（食事をする場所）の意味。昼食は食事そのものなので、混みあう場所にはならない。"}, {"text": "母は朝早く、昼食の鍵を開けた。", "explanation": "ここは〈鍵〉の意味。昼食は食事なので、開ける道具にはならない。"}, {"text": "母は毎朝、昼食を畑で育てている。", "explanation": "ここは〈野菜〉（畑で育つ作物）の意味。昼食は食事なので、畑で育てる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52136, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昼食", "is_correct": true, "explanation": "「遠足の昼食」で、食べる食事を指す。ベンチで食べると続く。"}, {"text": "水筒", "is_correct": false, "explanation": "水筒は飲み物を入れる容器で、ベンチで食べるものではない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は場所を示す紙で、食べる対象として合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子は頭にかぶるもので、食べる文の主語にはならない。"}], "explanations": {"昼食": "「遠足の昼食」で、食べる食事を指す。ベンチで食べると続く。", "水筒": "水筒は飲み物を入れる容器で、ベンチで食べるものではない。", "地図": "地図は場所を示す紙で、食べる対象として合わない。", "帽子": "帽子は頭にかぶるもので、食べる文の主語にはならない。"}, "sentence_index": 6, "correct_answer": "昼食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昼食が鳴ったので、目が覚めた。", "explanation": "ここは〈目覚まし時計〉の意味。昼食は食べ物なので、鳴って目を覚まさせる働きはしない。"}, {"text": "昼食の改札を通って、三番線のホームへ向かった。", "explanation": "ここは〈改札〉の意味。昼食は食事なので、通る対象にはならない。"}, {"text": "昼食の段差につまずいて、ひざをすりむいた。", "explanation": "ここは〈段差〉（床の高さの差）の意味。昼食は食べ物なので、つまずく段差にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52136, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼食に弁当で済ませた。", "corrected_sentence": "昼食を弁当で済ませた。", "error_description": "「済ませる」の対象を表す「を」が正しい。「昼食に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52136, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昼食を飲んで、仕事を続けた。", "corrected_sentence": "昼食を抜いて、仕事を続けた。", "error_description": "「昼食を飲む」は誤り。「昼食を抜く」が正しく、動詞が昼食と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52137, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52137, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「書斎の本棚」の「の」。書斎にある本棚だという所属を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「書斎へ本棚」だと行き先の意味になり、本棚の所属を示せない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「書斎を本棚から歴史の本を」と目的語が二つ重なり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「書斎が本棚から取り出した」だと書斎が動作主になり、「彼は」と主語が重なって成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「書斎の本棚」の「の」。書斎にある本棚だという所属を示す。", "へ": "方向を表す「へ」。「書斎へ本棚」だと行き先の意味になり、本棚の所属を示せない。", "を": "目的語の「を」。「書斎を本棚から歴史の本を」と目的語が二つ重なり、文が成り立たない。", "が": "主語の「が」。「書斎が本棚から取り出した」だと書斎が動作主になり、「彼は」と主語が重なって成り立たない。"}, "error_tags": {"へ": "方向", "を": "目的語", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52137, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "本を読んだり、勉強したりするためのへや。", "primary_collocate": null, "pronunciation": "しょさい", "ipa": "ɕosai", "syllable_count": 3, "sentences": [{"text": "祖父の書斎には、天井まで届く本棚が並んでいる。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "祖父[そふ]の書斎[しょさい]には、天井[てんじょう]まで届[とど]く本棚[ほんだな]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "兄は試験前になると、書斎にこもって勉強する。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "兄[あに]は試験前[しけんまえ]になると、書斎[しょさい]にこもって勉強[べんきょう]する。", "sentence_source": "generated"}, {"text": "書斎で本を読んでいたら、いつの間にか日が暮れていた。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "書斎[しょさい]で本[ほん]を読[よ]んでいたら、いつの間[ま]にか日[ひ]が暮[く]れていた。", "sentence_source": "generated"}, {"text": "古い辞典が好きな教授の書斎は、紙とインクのにおいがする。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "古[ふる]い辞典[じてん]が好[す]きな教授[きょうじゅ]の書斎[しょさい]は、紙[かみ]とインクのにおいがする。", "sentence_source": "generated"}, {"text": "子どものころ、私は父の書斎でこっそり絵本を読んだ。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "子[こ]どものころ、私[わたし]は父[ちち]の書斎[しょさい]でこっそり絵本[えほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "この書斎は静かなので、集中して読書ができる。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "この書斎[しょさい]は静[しず]かなので、集中[しゅうちゅう]して読書[どくしょ]ができる。", "sentence_source": "generated"}, {"text": "書斎の窓から庭が見えるので、疲れたときに眺める。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "書斎[しょさい]の窓[まど]から庭[にわ]が見[み]えるので、疲[つか]れたときに眺[なが]める。", "sentence_source": "generated"}, {"text": "彼は書斎の本棚から歴史の本を一冊取り出した。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "彼[かれ]は書斎[しょさい]の本棚[ほんだな]から歴史[れきし]の本[ほん]を一冊[いっさつ]取[と]り出[だ]した。", "sentence_source": "generated"}, {"text": "雨の日は、書斎でゆっくり本を読むのが楽しみだ。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、書斎[しょさい]でゆっくり本[ほん]を読[よ]むのが楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "学生時代、友人の家の書斎を借りて一緒に勉強した。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "学生時代[がくせいじだい]、友人[ゆうじん]の家[いえ]の書斎[しょさい]を借[か]りて一緒[いっしょ]に勉強[べんきょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書斎", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "読書や勉強のための部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52137, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書斎", "is_correct": true, "explanation": "「祖父の書斎には本棚が並んでいる」の場所。読書や勉強のための部屋の意味で、文に合う。"}, {"text": "週末", "is_correct": false, "explanation": "時間を表す語。「祖父の週末には本棚が並んでいる」は場所にならず不自然。"}, {"text": "食事", "is_correct": false, "explanation": "食べることを指す語。場所を示せず、「祖父の食事には」は文が成り立たない。"}, {"text": "予算", "is_correct": false, "explanation": "金額を表す語。「祖父の予算には本棚が並ぶ」は場所にならず成り立たない。"}], "explanations": {"書斎": "「祖父の書斎には本棚が並んでいる」の場所。読書や勉強のための部屋の意味で、文に合う。", "週末": "時間を表す語。「祖父の週末には本棚が並んでいる」は場所にならず不自然。", "食事": "食べることを指す語。場所を示せず、「祖父の食事には」は文が成り立たない。", "予算": "金額を表す語。「祖父の予算には本棚が並ぶ」は場所にならず成り立たない。"}, "sentence_index": 0, "correct_answer": "書斎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "被告人は書斎で判決を言い渡された。", "explanation": "ここは〈法廷〉の意味。判決を言い渡す公的な場を指すので、本を読んだり勉強したりする個人の部屋とは合わない。"}, {"text": "父の車は書斎に停めてある。", "explanation": "ここは〈駐車場〉の意味。車を停めておく場所を指すので、読書や勉強のための書斎とは合わない。"}, {"text": "新刊は駅前の書斎で買える。", "explanation": "ここは〈書店〉の意味。本を売る店を指すので、読書や勉強のための部屋である書斎とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52137, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書斎", "is_correct": true, "explanation": "「書斎の窓から庭が見える」の所在。読書や勉強のための部屋で、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語。「天気の窓から庭が見える」は場所にならず不自然。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとを指す語。窓の所在を示せず、文が成り立たない。"}, {"text": "印象", "is_correct": false, "explanation": "受けた感じを表す語。「印象の窓から」は場所にならず成り立たない。"}], "explanations": {"書斎": "「書斎の窓から庭が見える」の所在。読書や勉強のための部屋で、文に合う。", "天気": "空模様を表す語。「天気の窓から庭が見える」は場所にならず不自然。", "規則": "決まりごとを指す語。窓の所在を示せず、文が成り立たない。", "印象": "受けた感じを表す語。「印象の窓から」は場所にならず成り立たない。"}, "sentence_index": 6, "correct_answer": "書斎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は書斎で鍋を火にかけて、夕食を作った。", "explanation": "ここは〈台所〉の意味。料理をする場所を指すので、読書や勉強のための書斎とは合わない。"}, {"text": "工員たちは書斎で機械を動かして、部品を作った。", "explanation": "ここは〈工場〉の意味。機械で製品を作る場所を指すので、個人の仕事部屋である書斎とは合わない。"}, {"text": "患者は書斎で手術を受けた。", "explanation": "ここは〈病院〉の意味。治療を受ける施設を指すので、読書や勉強のための書斎とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52137, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は、学校の帰りに書斎へ本を読む。", "corrected_sentence": "兄は、学校の帰りに書斎で本を読む。", "error_description": "誤りは「書斎へ」。「へ」は移動の方向を表すので、読む場所は「で」で示すのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52137, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は毎晩、書斎に英語の単語を覚える。", "corrected_sentence": "妹は毎晩、書斎で英語の単語を覚える。", "error_description": "誤りは「書斎に」。覚える場所は「で」で示すのが正しく、「に」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52138, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「書斎にこもる」の「に」。こもる場所、つまり入って留まる場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。「書斎がこもって」だと書斎が主語になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。こもるは自動詞なので「書斎をこもって」とは使えない。"}, {"text": "と", "is_correct": false, "explanation": "同伴を表す「と」。「書斎とこもって」だと誰かと一緒に閉じこもる意味になり、文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「書斎にこもる」の「に」。こもる場所、つまり入って留まる場所を示す。", "が": "主語を表す「が」。「書斎がこもって」だと書斎が主語になり、文が成り立たない。", "を": "目的語を表す「を」。こもるは自動詞なので「書斎をこもって」とは使えない。", "と": "同伴を表す「と」。「書斎とこもって」だと誰かと一緒に閉じこもる意味になり、文脈に合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "同伴"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52138, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「書斎のドア」の「の」。書斎に属するドアだという所属を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「書斎へドア」だと行き先の意味になり、ドアの所属を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。「書斎からドア」だと出どころの意味になり、所属の説明にならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「閉まっている」は自動詞なので、「書斎をドアが閉まっている」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「書斎のドア」の「の」。書斎に属するドアだという所属を示す。", "へ": "方向を表す「へ」。「書斎へドア」だと行き先の意味になり、ドアの所属を示せない。", "から": "起点を表す「から」。「書斎からドア」だと出どころの意味になり、所属の説明にならない。", "を": "目的語の「を」。「閉まっている」は自動詞なので、「書斎をドアが閉まっている」は成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52138, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "勉強や仕事をするための部屋。特に、自宅にある個人の仕事部屋。", "primary_collocate": null, "pronunciation": "しょさい", "ipa": "ɕosai", "syllable_count": 3, "sentences": [{"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "書斎", "complexity_tier": "T5", "furigana": "多忙[たぼう]な現代[げんだい]の専門職[せんもんしょく]に就[つ]く我々[われわれ]にとって、オフィスや書斎[しょさい]で迎[むか]える限[かぎ]られた昼食[ちゅうしょく]の時間[じかん]はいかにして精神的[せいしんてき]・肉体的[にくたいてき]充足[じゅうそく]へと転換[てんかん]され得[う]るだろうか。", "sentence_source": "mined"}, {"text": "父は仕事を持ち帰ると、自宅の書斎にこもって夜遅くまで原稿を書く。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]を持[も]ち帰[かえ]ると、自宅[じたく]の書斎[しょさい]にこもって夜遅[よるおそ]くまで原稿[げんこう]を書[か]く。", "sentence_source": "generated"}, {"text": "在宅勤務が増えたので、使っていない部屋を書斎に改装した。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "在宅勤務[ざいたくきんむ]が増[ふ]えたので、使[つか]っていない部屋[へや]を書斎[しょさい]に改装[かいそう]した。", "sentence_source": "generated"}, {"text": "書斎の机には、締め切りが近い資料が山のように積まれている。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "書斎[しょさい]の机[つくえ]には、締[し]め切[き]りが近[ちか]い資料[しりょう]が山[やま]のように積[つ]まれている。", "sentence_source": "generated"}, {"text": "彼女は電話会議のために、静かな書斎へ移動した。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は電話会議[でんわかいぎ]のために、静[しず]かな書斎[しょさい]へ移動[いどう]した。", "sentence_source": "generated"}, {"text": "家が狭くて書斎を作れないため、リビングの隅で仕事をしている。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "家[いえ]が狭[せま]くて書斎[しょさい]を作[つく]れないため、リビングの隅[すみ]で仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "弁護士の叔父は、自宅の書斎で依頼人の書類を調べている。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "弁護士[べんごし]の叔父[おじ]は、自宅[じたく]の書斎[しょさい]で依頼人[いらいにん]の書類[しょるい]を調[しら]べている。", "sentence_source": "generated"}, {"text": "書斎のドアが閉まっているときは、父が仕事中だという合図だ。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "書斎[しょさい]のドアが閉[し]まっているときは、父[ちち]が仕事中[しごとちゅう]だという合図[あいず]だ。", "sentence_source": "generated"}, {"text": "新しい家を建てるとき、妻は台所を、私は書斎を優先した。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]を建[た]てるとき、妻[つま]は台所[だいどころ]を、私[わたし]は書斎[しょさい]を優先[ゆうせん]した。", "sentence_source": "generated"}, {"text": "作家は毎朝、書斎で四時間だけ執筆すると決めている。", "target_word": "書斎", "complexity_tier": "T3", "furigana": "作家[さっか]は毎朝[まいあさ]、書斎[しょさい]で四時間[よじかん]だけ執筆[しっぴつ]すると決[き]めている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書斎", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自宅にある個人用の仕事部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52138, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書斎", "is_correct": true, "explanation": "「オフィスや書斎で迎える」の場所を表す語。仕事や勉強のための部屋という意味で文に合う。"}, {"text": "予算", "is_correct": false, "explanation": "金額を表す語。「オフィスや予算で迎える」では場所にならず、文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語。「オフィスや天気で迎える」と場所を示せないので不自然。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとを指す語。「オフィスや規則で迎える」は場所にならず成り立たない。"}], "explanations": {"書斎": "「オフィスや書斎で迎える」の場所を表す語。仕事や勉強のための部屋という意味で文に合う。", "予算": "金額を表す語。「オフィスや予算で迎える」では場所にならず、文が成り立たない。", "天気": "空模様を表す語。「オフィスや天気で迎える」と場所を示せないので不自然。", "規則": "決まりごとを指す語。「オフィスや規則で迎える」は場所にならず成り立たない。"}, "sentence_index": 0, "correct_answer": "書斎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "生徒たちは書斎で一斉に漢字を書いた。", "explanation": "ここは〈教室〉の意味。多くの生徒が授業を受ける場を指すので、個人の仕事部屋である書斎とは合わない。"}, {"text": "売店の店員は、書斎に弁当を並べた。", "explanation": "ここは〈売店〉の意味。商品を並べて売る店を指すので、個人の仕事部屋である書斎とは合わない。"}, {"text": "研究員たちは書斎で実験装置を組み立てている。", "explanation": "ここは〈研究室〉の意味。実験設備のある研究の場を指すので、個人の仕事部屋である書斎は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52138, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書斎", "is_correct": true, "explanation": "「自宅の書斎で依頼人の書類を調べている」の場所。仕事用の自宅の部屋を表し、文に合う。"}, {"text": "食事", "is_correct": false, "explanation": "食べることを指す語。「自宅の食事で書類を調べている」と場所にならず不自然。"}, {"text": "歴史", "is_correct": false, "explanation": "過去の出来事や学問を指す語。場所を示せず、文が成り立たない。"}, {"text": "印象", "is_correct": false, "explanation": "受けた感じを表す語。場所にならず、「自宅の印象で」は不自然。"}], "explanations": {"書斎": "「自宅の書斎で依頼人の書類を調べている」の場所。仕事用の自宅の部屋を表し、文に合う。", "食事": "食べることを指す語。「自宅の食事で書類を調べている」と場所にならず不自然。", "歴史": "過去の出来事や学問を指す語。場所を示せず、文が成り立たない。", "印象": "受けた感じを表す語。場所にならず、「自宅の印象で」は不自然。"}, "sentence_index": 6, "correct_answer": "書斎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "社員全員が社長の書斎に集まって朝礼を行った。", "explanation": "ここは〈事務所〉の意味。多くの社員が働く職場を指すので、個人用の書斎は合わない。"}, {"text": "書斎の湯船に浸かって、父は体を洗った。", "explanation": "ここは〈浴室〉の意味。体を洗う場所を指すので、読書や勉強のための書斎とは合わない。"}, {"text": "祖母は書斎に入院して、毎日検査を受けている。", "explanation": "ここは〈病室〉の意味。患者が入院する部屋を指すので、個人の仕事部屋である書斎とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52138, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、自宅の書斎に毎朝新聞を読む。", "corrected_sentence": "祖父は、自宅の書斎で毎朝新聞を読む。", "error_description": "誤りは「書斎に」。読む動作の場所は「で」で示すのが正しく、「に」は到着点や存在の場所を表すので合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52138, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は夕食のあと、書斎が家計簿をつける。", "corrected_sentence": "母は夕食のあと、書斎で家計簿をつける。", "error_description": "誤りは「書斎が」。家計簿をつける場所は「で」で示す。「が」は書斎を主語にしてしまい、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
