INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52139, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほしいものが全部そろって、もうこれ以上いらないと思うこと。", "primary_collocate": null, "pronunciation": "じゅうそく", "ipa": "dʑɯːsokɯ", "syllable_count": 4, "sentences": [{"text": "好きな本に囲まれて、彼は充足した気持ちで眠りについた。", "target_word": "充足", "complexity_tier": "T3", "furigana": "好[す]きな本[ほん]に囲[かこ]まれて、彼[かれ]は充足[じゅうそく]した気持[きも]ちで眠[ねむ]りについた。", "sentence_source": "generated"}, {"text": "欲しかった道具が全部そろい、今は充足している。", "target_word": "充足", "complexity_tier": "T3", "furigana": "欲[ほ]しかった道具[どうぐ]が全部[ぜんぶ]そろい、今[いま]は充足[じゅうそく]している。", "sentence_source": "generated"}, {"text": "彼女は小さな家での暮らしに、深い充足を覚えている。", "target_word": "充足", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は小[ちい]さな家[いえ]での暮[く]らしに、深[ふか]い充足[じゅうそく]を覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "もう何も足りないものはないと思えるとき、人は充足を知る。", "target_word": "充足", "complexity_tier": "T3", "furigana": "もう何[なに]も足[た]りないものはないと思[おも]えるとき、人[ひと]は充足[じゅうそく]を知[し]る。", "sentence_source": "generated"}, {"text": "休日に好きな料理を作って食べるだけで、私は充足する。", "target_word": "充足", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]に好[す]きな料理[りょうり]を作[つく]って食[た]べるだけで、私[わたし]は充足[じゅうそく]する。", "sentence_source": "generated"}, {"text": "夢だった自分の店を持ち、父は充足した表情で笑っていた。", "target_word": "充足", "complexity_tier": "T3", "furigana": "夢[ゆめ]だった自分[じぶん]の店[みせ]を持[も]ち、父[ちち]は充足[じゅうそく]した表情[ひょうじょう]で笑[わら]っていた。", "sentence_source": "generated"}, {"text": "物があふれる時代でも、充足を感じる人は多くない。", "target_word": "充足", "complexity_tier": "T3", "furigana": "物[もの]があふれる時代[じだい]でも、充足[じゅうそく]を感[かん]じる人[ひと]は多[おお]くない。", "sentence_source": "generated"}, {"text": "祖母は、孫たちの顔を見て充足した様子だった。", "target_word": "充足", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、孫[まご]たちの顔[かお]を見[み]て充足[じゅうそく]した様子[ようす]だった。", "sentence_source": "generated"}, {"text": "彼は充足した毎日を送り、これ以上の望みはないと言う。", "target_word": "充足", "complexity_tier": "T3", "furigana": "彼[かれ]は充足[じゅうそく]した毎日[まいにち]を送[おく]り、これ以上[いじょう]の望[のぞ]みはないと言[い]う。", "sentence_source": "generated"}, {"text": "欲しいものが全部手に入っても、充足せずに次を求める人もいる。", "target_word": "充足", "complexity_tier": "T3", "furigana": "欲[ほ]しいものが全部[ぜんぶ]手[て]に入[はい]っても、充足[じゅうそく]せずに次[つぎ]を求[もと]める人[ひと]もいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "充足する", "label": "辞書形"}, {"form": "充足した", "label": "過去形"}, {"form": "充足している", "label": "継続形"}], "register": "neutral", "sense_fingerprint": "ほしいものがそろい満ち足りた気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52139, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "「充足した気持ち」の充足。ほしいものがそろって満ち足りた気持ちを表し、文に合う。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いを指す語。「会議した気持ち」とならず、文が不自然になる。"}, {"text": "予算", "is_correct": false, "explanation": "金額を表す語。「予算した気持ち」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語。「天気した気持ち」は文が成り立たない。"}], "explanations": {"充足": "「充足した気持ち」の充足。ほしいものがそろって満ち足りた気持ちを表し、文に合う。", "会議": "話し合いを指す語。「会議した気持ち」とならず、文が不自然になる。", "予算": "金額を表す語。「予算した気持ち」は成り立たない。", "天気": "空模様を表す語。「天気した気持ち」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "結果を聞いて、彼は充足して胸をなでおろした。", "explanation": "ここは〈安心〉の意味。ほっとして緊張がゆるむ気持ちを表すので、欲しいものがそろう充足とは違う。"}, {"text": "先生の説明に充足して、彼はうなずいた。", "explanation": "ここは〈納得〉の意味。内容を理解して受け入れることを表すので、満ち足りた気持ちを指す充足とは合わない。"}, {"text": "優勝の知らせを聞き、彼女は充足して涙を流した。", "explanation": "ここは〈感激〉の意味。強く心を動かされることを表すので、静かに満ち足りた状態を指す充足とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52139, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "「充足を感じる人」の充足。満ち足りた気持ちを表し、文に合う。"}, {"text": "食事", "is_correct": false, "explanation": "食べることを指す語。「食事を感じる人」は不自然。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとを指す語。感じる対象にならず、文が成り立たない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵送を指す語。感じる対象にならず、「郵便を感じる」は成り立たない。"}], "explanations": {"充足": "「充足を感じる人」の充足。満ち足りた気持ちを表し、文に合う。", "食事": "食べることを指す語。「食事を感じる人」は不自然。", "規則": "決まりごとを指す語。感じる対象にならず、文が成り立たない。", "郵便": "郵送を指す語。感じる対象にならず、「郵便を感じる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員は売り切れた棚に菓子を充足した。", "explanation": "ここは〈補充〉の意味。棚に品物を足す動作を表すので、満ち足りた気持ちを指す充足とは合わない。"}, {"text": "祖父は古い時計に充足を持ち、毎日丁寧に磨いている。", "explanation": "ここは〈愛着〉の意味。物に深く心を寄せることを表すので、満足して欲しいものがそろった状態を指す充足とは合わない。"}, {"text": "締め切りが迫り、彼は充足して机に向かった。", "explanation": "ここは〈焦り〉の意味。急かされて落ち着かない気持ちを表すので、満ち足りた状態を指す充足とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52139, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、充足に表情で庭の花を眺めていた。", "corrected_sentence": "祖父は、充足した表情で庭の花を眺めていた。", "error_description": "誤りは「充足に」。名詞の充足を「表情」にかけるには「充足した」の形が必要で、「に」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52139, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その日は一日中、充足を過ごし、夜はぐっすり眠れた。", "corrected_sentence": "その日は一日中、充足して過ごし、夜はぐっすり眠れた。", "error_description": "誤りは「充足を」。「過ごす」は時間を目的語に取るので、状態を表す充足は「して」で述語にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52140, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「充足が確認される」の「が」。受け身の主語で、確認される対象が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。受け身では充足が主語になるため「充足を確認される」は誤り。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」。「充足で確認される」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「充足から確認される」では起点にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「充足が確認される」の「が」。受け身の主語で、確認される対象が主語になる。", "を": "目的語の「を」。受け身では充足が主語になるため「充足を確認される」は誤り。", "で": "手段や場所の「で」。「充足で確認される」は意味が通らない。", "から": "起点の「から」。「充足から確認される」では起点にならず、文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "「不足」は必要なものが十分でない状態を指し、この語義で充足の対義語にあたる。"}, {"text": "余暇", "is_correct": false, "explanation": "自由に使える時間を指す語で、必要なものが満たされた状態の反対ではない。"}, {"text": "寛容", "is_correct": false, "explanation": "人を受け入れる心の広さを指す語で、充足と対になる関係ではない。"}, {"text": "節約", "is_correct": false, "explanation": "無駄を省く行為を指す語で、充足の対義語にはならない。"}], "correct_answer": "不足", "explanations": {"不足": "「不足」は必要なものが十分でない状態を指し、この語義で充足の対義語にあたる。", "余暇": "自由に使える時間を指す語で、必要なものが満たされた状態の反対ではない。", "寛容": "人を受け入れる心の広さを指す語で、充足と対になる関係ではない。", "節約": "無駄を省く行為を指す語で、充足の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52140, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「図書の充足を最優先の課題として」の「を」。充足を目的語にして、課題として位置づける。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「充足へ最優先」では対象を示せず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表す「と」。「充足と最優先」では並べるだけで目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "到達点を表す「に」。「充足に最優先の課題として」では目的語を示せず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「図書の充足を最優先の課題として」の「を」。充足を目的語にして、課題として位置づける。", "へ": "方向を表す「へ」。「充足へ最優先」では対象を示せず、文が成り立たない。", "と": "並列を表す「と」。「充足と最優先」では並べるだけで目的語にならない。", "に": "到達点を表す「に」。「充足に最優先の課題として」では目的語を示せず、意味が通らない。"}, "error_tags": {"へ": "方向", "と": "並列", "に": "到達点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "「不足」は必要なものが十分でない状態を指し、この語義で充足の対義語にあたる。"}, {"text": "旅行", "is_correct": false, "explanation": "各地を出かけて巡ることを指す語で、充足と対になる関係ではない。"}, {"text": "贅沢", "is_correct": false, "explanation": "必要以上に物事を楽しむことを指す語で、充足の対義語ではない。"}, {"text": "寝坊", "is_correct": false, "explanation": "朝に遅く起きることを指す語で、充足と対になる関係ではない。"}], "correct_answer": "不足", "explanations": {"不足": "「不足」は必要なものが十分でない状態を指し、この語義で充足の対義語にあたる。", "旅行": "各地を出かけて巡ることを指す語で、充足と対になる関係ではない。", "贅沢": "必要以上に物事を楽しむことを指す語で、充足の対義語ではない。", "寝坊": "朝に遅く起きることを指す語で、充足と対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52140, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "必要なものが十分に満たされて、不満や不足がない状態。", "primary_collocate": null, "pronunciation": "じゅうそく", "ipa": "dʑɯːsokɯ", "syllable_count": 4, "sentences": [{"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "充足", "complexity_tier": "T5", "furigana": "多忙[たぼう]な現代[げんだい]の専門職[せんもんしょく]に就[つ]く我々[われわれ]にとって、オフィスや書斎[しょさい]で迎[むか]える限[かぎ]られた昼食[ちゅうしょく]の時間[じかん]はいかにして精神的[せいしんてき]・肉体的[にくたいてき]充足[じゅうそく]へと転換[てんかん]され得[う]るだろうか。", "sentence_source": "mined"}, {"text": "食料の充足が確認されるまで、避難所の配給は続けられた。", "target_word": "充足", "complexity_tier": "T3", "furigana": "食料[しょくりょう]の充足[じゅうそく]が確認[かくにん]されるまで、避難所[ひなんじょ]の配給[はいきゅう]は続[つづ]けられた。", "sentence_source": "generated"}, {"text": "新しい制度で、地域の医療需要の充足を目指している。", "target_word": "充足", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]で、地域[ちいき]の医療需要[いりょうじゅよう]の充足[じゅうそく]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "彼は物質的な充足よりも、心の充足を大切にしている。", "target_word": "充足", "complexity_tier": "T3", "furigana": "彼[かれ]は物質的[ぶっしつてき]な充足[じゅうそく]よりも、心[こころ]の充足[じゅうそく]を大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "必要な条件の充足が確かめられたので、申請は認められた。", "target_word": "充足", "complexity_tier": "T3", "furigana": "必要[ひつよう]な条件[じょうけん]の充足[じゅうそく]が確[たし]かめられたので、申請[しんせい]は認[みと]められた。", "sentence_source": "generated"}, {"text": "在庫の充足により、品切れの心配はなくなった。", "target_word": "充足", "complexity_tier": "T3", "furigana": "在庫[ざいこ]の充足[じゅうそく]により、品切[しなぎ]れの心配[しんぱい]はなくなった。", "sentence_source": "generated"}, {"text": "収入が増えても、生活の充足を感じられない人もいる。", "target_word": "充足", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]が増[ふ]えても、生活[せいかつ]の充足[じゅうそく]を感[かん]じられない人[ひと]もいる。", "sentence_source": "generated"}, {"text": "学校は、図書の充足を最優先の課題として予算を組んだ。", "target_word": "充足", "complexity_tier": "T3", "furigana": "学校[がっこう]は、図書[としょ]の充足[じゅうそく]を最優先[さいゆうせん]の課題[かだい]として予算[よさん]を組[く]んだ。", "sentence_source": "generated"}, {"text": "必要な栄養素の充足が、子どもの健全な発育を支える。", "target_word": "充足", "complexity_tier": "T3", "furigana": "必要な栄養素の充足[じゅうそく]が、子どもの健全[けんぜん]な発育[はついく]を支える。", "sentence_source": "generated"}, {"text": "部屋に家具が揃っても、気持ちの充足は得られない。", "target_word": "充足", "complexity_tier": "T3", "furigana": "部屋[へや]に家具[かぐ]が揃[そろ]っても、気持[きも]ちの充足[じゅうそく]は得[え]られない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "充足する", "label": "辞書形"}, {"form": "充足した", "label": "過去形"}, {"form": "充足される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "必要なものが満たされ不足や不満がない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52140, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "「精神的・肉体的充足へと転換」の充足。必要なものが満たされた状態を表し、文に合う。"}, {"text": "週末", "is_correct": false, "explanation": "時間を表す語。「精神的・肉体的週末へと転換」は成り立たない。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとを指す語。「へと転換」の対象にならず、文が不自然になる。"}, {"text": "予算", "is_correct": false, "explanation": "金額や割り当てを表す語。精神的・肉体的な状態にはならない。"}], "explanations": {"充足": "「精神的・肉体的充足へと転換」の充足。必要なものが満たされた状態を表し、文に合う。", "週末": "時間を表す語。「精神的・肉体的週末へと転換」は成り立たない。", "規則": "決まりごとを指す語。「へと転換」の対象にならず、文が不自然になる。", "予算": "金額や割り当てを表す語。精神的・肉体的な状態にはならない。"}, "sentence_index": 0, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "充電が切れたので、彼はスマホを充足してから出かけた。", "explanation": "ここは〈充電〉の意味。機器に電気を入れる動作を表すので、必要なものが満たされた状態を指す充足は合わない。"}, {"text": "夜更かしで、彼の目は充足していた。", "explanation": "ここは〈充血〉の意味。目が赤くなる状態を指すので、必要なものが満ちた状態を指す充足とは合わない。"}, {"text": "排気の止まった地下室に、ガスが充足した。", "explanation": "ここは〈充満〉の意味。気体が空間いっぱいに広がることを表すので、必要なものが満たされた状態の充足とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52140, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "「生活の充足を感じられない」の充足。生活の必要が満たされた感覚を表し、文に合う。"}, {"text": "食事", "is_correct": false, "explanation": "食べることを指す語。「生活の食事を感じられない」は不自然。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語。感じる対象にならず、文が成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指す語。「生活の会議を感じる」は成り立たない。"}], "explanations": {"充足": "「生活の充足を感じられない」の充足。生活の必要が満たされた感覚を表し、文に合う。", "食事": "食べることを指す語。「生活の食事を感じられない」は不自然。", "天気": "空模様を表す語。感じる対象にならず、文が成り立たない。", "会議": "話し合いの場を指す語。「生活の会議を感じる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電池切れの腕時計を、彼は夜中に充足した。", "explanation": "ここは〈充電〉の意味。機器に電気を入れる動作を表すので、必要なものが満たされた状態の充足とは合わない。"}, {"text": "職人は壁のひび割れに漆喰を充足した。", "explanation": "ここは〈充填〉の意味。隙間に詰める動作を表すので、充足では言えない。"}, {"text": "締め切った部屋に煙が充足した。", "explanation": "ここは〈充満〉の意味。気体などが空間いっぱいに広がることを表すので、充足とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52140, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "災害時には、水や食料の充足を最優先となる。", "corrected_sentence": "災害時には、水や食料の充足が最優先となる。", "error_description": "誤りは「充足を」。「最優先となる」の主語は「充足が」で、目的語の「を」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52140, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい制度で、保育の需要の充足を進んでいる。", "corrected_sentence": "新しい制度で、保育の需要の充足が進んでいる。", "error_description": "誤りは「充足を」。「進む」は目的語を取らない自動詞なので、充足は「が」で主語にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52141, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見つけた」の目的語を示す格助詞。「解答を見つけた」と自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「解答が見つけた」では誰が見つけたのかが合わない。"}, {"text": "に", "is_correct": false, "explanation": "対象や到達点を示す。「解答に見つけた」では目的語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。比べる対象がないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「見つけた」の目的語を示す格助詞。「解答を見つけた」と自然に続く。", "が": "主語を示す。「解答が見つけた」では誰が見つけたのかが合わない。", "に": "対象や到達点を示す。「解答に見つけた」では目的語として成り立たない。", "より": "比較を示す。比べる対象がないので合わない。"}, "error_tags": {"が": "主語", "に": "対象・到達", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
