INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52141, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "問題の答えのこと。", "primary_collocate": null, "pronunciation": "かいとう", "ipa": "kaitoː", "syllable_count": 4, "sentences": [{"text": "算数の問題の解答を、ノートに丁寧に書いた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "算数[さんすう]の問題[もんだい]の解答[かいとう]を、ノートに丁寧[ていねい]に書[か]いた。", "sentence_source": "generated"}, {"text": "兄は難しいパズルの解答を、ようやく見つけた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "兄[あに]は難[むずか]しいパズルの解答[かいとう]を、ようやく見[み]つけた。", "sentence_source": "generated"}, {"text": "答え合わせのとき、自分の解答と本の解答が違っていた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "答[こた]え合[あ]わせのとき、自分[じぶん]の解答[かいとう]と本[ほん]の解答[かいとう]が違[ちが]っていた。", "sentence_source": "generated"}, {"text": "先生は、生徒たちの解答を一枚ずつ確かめた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]たちの解答[かいとう]を一枚[いちまい]ずつ確[たし]かめた。", "sentence_source": "generated"}, {"text": "宿題の解答がわからなくて、母に聞いた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]の解答[かいとう]がわからなくて、母[はは]に聞[き]いた。", "sentence_source": "generated"}, {"text": "解答は、決められた欄に書くことになっている。", "target_word": "解答", "complexity_tier": "T3", "furigana": "解答[かいとう]は、決[き]められた欄[らん]に書[か]くことになっている。", "sentence_source": "generated"}, {"text": "正しい解答を選べば、次の問題に進める。", "target_word": "解答", "complexity_tier": "T3", "furigana": "正[ただ]しい解答[かいとう]を選[えら]べば、次[つぎ]の問題[もんだい]に進[すす]める。", "sentence_source": "generated"}, {"text": "彼は問題を読むと、すぐに解答を思いついた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "彼[かれ]は問題[もんだい]を読[よ]むと、すぐに解答[かいとう]を思[おも]いついた。", "sentence_source": "generated"}, {"text": "授業が終わってから、先生が解答を配った。", "target_word": "解答", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が終[お]わってから、先生[せんせい]が解答[かいとう]を配[くば]った。", "sentence_source": "generated"}, {"text": "彼女の解答はいつも短くて、わかりやすい。", "target_word": "解答", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の解答[かいとう]はいつも短[みじか]くて、わかりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解答する", "label": "辞書形"}, {"form": "解答した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "問題の答え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52141, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解答", "is_correct": true, "explanation": "問題の答えの意味で、「算数の問題の解答をノートに書いた」と自然に続く。"}, {"text": "手紙", "is_correct": false, "explanation": "人に伝える文章。算数の問題の内容をノートに書く文には合わない。"}, {"text": "日記", "is_correct": false, "explanation": "その日の出来事を記す記録。問題の答えを書く文には合わない。"}, {"text": "図鑑", "is_correct": false, "explanation": "動植物などを紹介する本。ノートに書き込む内容として合わない。"}], "explanations": {"解答": "問題の答えの意味で、「算数の問題の解答をノートに書いた」と自然に続く。", "手紙": "人に伝える文章。算数の問題の内容をノートに書く文には合わない。", "日記": "その日の出来事を記す記録。問題の答えを書く文には合わない。", "図鑑": "動植物などを紹介する本。ノートに書き込む内容として合わない。"}, "sentence_index": 0, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壊れた機械の解答を調べて、故障の原因をつきとめた。", "explanation": "ここは〈解析〉（細かく分けて調べること）の意味。機械を調べるなら解析を使い、解答は問題への答えを指すので合わない。"}, {"text": "会議は三時間続いたが、最後まで解答が出なかった。", "explanation": "ここは〈結論〉（話し合いの最終的な判断）の意味。会議のまとめには結論を使い、解答とは言わない。"}, {"text": "カエルの解答実験を、理科の授業で行った。", "explanation": "ここは〈解剖〉（生き物の体を切り開いて調べること）の意味。体を切り開いて調べることには解剖を使い、解答は問題への答えを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52141, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解答", "is_correct": true, "explanation": "問題の答えの意味で、「正しい解答を選べば」と文が成り立つ。"}, {"text": "飲料", "is_correct": false, "explanation": "飲み物のこと。問題を解く流れには合わない。"}, {"text": "天気", "is_correct": false, "explanation": "その日の空模様のこと。「正しい天気を選べば」では意味が通らない。"}, {"text": "足跡", "is_correct": false, "explanation": "歩いたあとに残る跡。選択と次の問題の文脈に合わない。"}], "explanations": {"解答": "問題の答えの意味で、「正しい解答を選べば」と文が成り立つ。", "飲料": "飲み物のこと。問題を解く流れには合わない。", "天気": "その日の空模様のこと。「正しい天気を選べば」では意味が通らない。", "足跡": "歩いたあとに残る跡。選択と次の問題の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に解答が美術館に忍び込み、絵を盗んだ。", "explanation": "ここは〈怪盗〉（こっそり盗みを働く人）の意味。解答は問題の答えなので、人を指す文には使わない。"}, {"text": "来月、アユ漁の解答日が決まった。", "explanation": "ここは〈解禁〉（禁止を解いて自由にすること）の意味。漁の開始日には解禁を使い、解答は問題への答えを指すので合わない。"}, {"text": "トラブルの解答がやっとついて、みんなほっとした。", "explanation": "ここは〈解決〉（問題を片付けること）の意味。トラブルの片付きには解決を使い、解答は問題への答えを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52141, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は宿題の解答が、ノートに丁寧に書いた。", "corrected_sentence": "妹は宿題の解答を、ノートに丁寧に書いた。", "error_description": "「書く」は目的語に「を」を取る。「解答が」は主語の形で誤り。正しくは「解答を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52141, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は、テストの解答に何度も確かめた。", "corrected_sentence": "弟は、テストの解答を何度も確かめた。", "error_description": "「確かめる」は他動詞で目的語に「を」を取る。「解答に」は誤りで、正しくは「解答を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52142, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「書いた」の目的語を示す格助詞。「解答を」と直後の「黒板に書いた」が続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「解答が書いた」では誰が書いたのかが合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「解答へ書いた」では書く対象が示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。ここでは比べる対象がなく合わない。"}], "correct_answer": "を", "explanations": {"を": "「書いた」の目的語を示す格助詞。「解答を」と直後の「黒板に書いた」が続く。", "が": "主語を示す。「解答が書いた」では誰が書いたのかが合わない。", "へ": "方向を示す。「解答へ書いた」では書く対象が示せない。", "より": "比較を示す。ここでは比べる対象がなく合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52142, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「のっている」の主語を示す。「解答がのっている」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「のっている」は自動詞なので「を」は続かない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す。「解答でのっている」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示す。「解答とのっている」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「のっている」の主語を示す。「解答がのっている」と自然に続く。", "を": "目的語を示す。「のっている」は自動詞なので「を」は続かない。", "で": "場所や手段を示す。「解答でのっている」では文が成り立たない。", "と": "並列や引用を示す。「解答とのっている」では文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52142, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "問題や質問に対する答え。", "primary_collocate": null, "pronunciation": "かいとう", "ipa": "kaitoː", "syllable_count": 4, "sentences": [{"text": "自分の解答を一つずつ見直して、ミスを減らした。", "target_word": "解答", "complexity_tier": "T3", "furigana": "自分[じぶん]の解答[かいとう]を一[ひと]つずつ見直[みなお]して、ミスを減[へ]らした。", "sentence_source": "generated"}, {"text": "先生は試験のあと、全問の解答を黒板に書いた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "先生[せんせい]は試験[しけん]のあと、全問[ぜんもん]の解答[かいとう]を黒板[こくばん]に書[か]いた。", "sentence_source": "generated"}, {"text": "彼の解答は途中の式が正しく、点がもらえた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "彼[かれ]の解答[かいとう]は途中[とちゅう]の式[しき]が正[ただ]しく、点[てん]がもらえた。", "sentence_source": "generated"}, {"text": "試験の終わりに、解答を見直してから提出した。", "target_word": "解答", "complexity_tier": "T3", "furigana": "試験[しけん]の終[お]わりに、解答[かいとう]を見直[みなお]してから提出[ていしゅつ]した。", "sentence_source": "generated"}, {"text": "この問題には、解答が二つあると思う。", "target_word": "解答", "complexity_tier": "T3", "furigana": "この問題[もんだい]には、解答[かいとう]が二[ふた]つあると思[おも]う。", "sentence_source": "generated"}, {"text": "数学の宿題の解答を、友だちと見比べた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "数学[すうがく]の宿題[しゅくだい]の解答[かいとう]を、友[とも]だちと見比[みくら]べた。", "sentence_source": "generated"}, {"text": "私の解答は間違っていたが、考え方は先生にほめられた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "私[わたし]の解答[かいとう]は間違[まちが]っていたが、考[かんが]え方[かた]は先生[せんせい]にほめられた。", "sentence_source": "generated"}, {"text": "問題集の後ろには、詳しい解説付きの解答がのっている。", "target_word": "解答", "complexity_tier": "T3", "furigana": "問題集[もんだいしゅう]の後[うし]ろには、詳[くわ]しい解説付[かいせつつ]きの解答[かいとう]がのっている。", "sentence_source": "generated"}, {"text": "解答を見る前に、もう一度自分の力で考えてみた。", "target_word": "解答", "complexity_tier": "T3", "furigana": "解答[かいとう]を見[み]る前[まえ]に、もう一度[いちど]自分[じぶん]の力[ちから]で考[かんが]えてみた。", "sentence_source": "generated"}, {"text": "制限時間が終わる直前に、最後の解答を書き込んだ。", "target_word": "解答", "complexity_tier": "T3", "furigana": "制限時間[せいげんじかん]が終[お]わる直前[ちょくぜん]に、最後[さいご]の解答[かいとう]を書[か]き込[こ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解答する", "label": "辞書形"}, {"form": "解答した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "問題や質問に対する答え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52142, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解答", "is_correct": true, "explanation": "問題に対する答えの意味で、「自分の解答を一つずつ見直して」と文に合う。"}, {"text": "解剖", "is_correct": false, "explanation": "生物などを切り開いて調べること。「自分の解剖を一つずつ見直して」では文の内容に合わない。"}, {"text": "解約", "is_correct": false, "explanation": "契約を取り消すこと。「自分の解約を一つずつ見直して」では意味が通らない。"}, {"text": "解体", "is_correct": false, "explanation": "組み立てたものをばらすこと。「自分の解体を一つずつ見直して」では意味が通らない。"}], "explanations": {"解答": "問題に対する答えの意味で、「自分の解答を一つずつ見直して」と文に合う。", "解剖": "生物などを切り開いて調べること。「自分の解剖を一つずつ見直して」では文の内容に合わない。", "解約": "契約を取り消すこと。「自分の解約を一つずつ見直して」では意味が通らない。", "解体": "組み立てたものをばらすこと。「自分の解体を一つずつ見直して」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "集めたデータの解答を、専門家に頼んだ。", "explanation": "ここは〈解析〉（細かく分けて調べ、仕組みを明らかにすること）の意味。データの分析には解析を使い、解答は問題への答えを指すので合わない。"}, {"text": "トラブルの解答がやっとついて、みんなほっとした。", "explanation": "ここは〈解決〉（問題を片付けること）の意味。トラブルの片付きには解決を使い、解答は問題への答えを指すので合わない。"}, {"text": "古い校舎の解答工事が、来月から始まる。", "explanation": "ここは〈解体〉（建物を取り壊すこと）の意味。建物の取り壊しには解体を使い、解答は問題への答えを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52142, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解答", "is_correct": true, "explanation": "私の答案という意味で、「私の解答は間違っていた」と文が成立する。"}, {"text": "解熱", "is_correct": false, "explanation": "熱を下げること。「私の解熱は間違っていた」では文が成り立たない。"}, {"text": "解毒", "is_correct": false, "explanation": "毒の作用を取り除くこと。考え方の評価の文には合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解くこと。答えを書いた内容とは結びつかない。"}], "explanations": {"解答": "私の答案という意味で、「私の解答は間違っていた」と文が成立する。", "解熱": "熱を下げること。「私の解熱は間違っていた」では文が成り立たない。", "解毒": "毒の作用を取り除くこと。考え方の評価の文には合わない。", "解散": "集まりを解くこと。答えを書いた内容とは結びつかない。"}, "sentence_index": 6, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に解答が美術館に忍び込み、絵を盗んだ。", "explanation": "ここは〈怪盗〉（こっそり盗みを働く人）の意味。解答は問題の答えなので、人を指す文には使わない。"}, {"text": "会議は三時間続いたが、最後まで解答が出なかった。", "explanation": "ここは〈結論〉（話し合いの最終的な判断）の意味。会議のまとめには結論を使い、解答とは言わない。"}, {"text": "冷凍肉の解答作業が、朝のうちに終わった。", "explanation": "ここは〈解凍〉（凍ったものをとかすこと）の意味。食品をとかす作業には解凍を使い、解答は問題への答えを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52142, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は授業のあと、解答が黒板に書いた。", "corrected_sentence": "先生は授業のあと、解答を黒板に書いた。", "error_description": "「書く」は目的語に「を」を取る。「解答が」は主語の形で誤り。正しくは「解答を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52142, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は宿題の解答に見直して、間違いを探した。", "corrected_sentence": "母は宿題の解答を見直して、間違いを探した。", "error_description": "「見直す」は他動詞で目的語に「を」を取る。「解答に」は誤りで、正しくは「解答を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52143, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暇", "is_correct": true, "explanation": "することがなく時間に余裕がある状態で、多忙の対義語。"}, {"text": "活発", "is_correct": false, "explanation": "動きが盛んなこと。忙しさの反対を表す語ではない。"}, {"text": "厳格", "is_correct": false, "explanation": "厳しく規律を守る様子。時間の余裕とは関係しない。"}, {"text": "豊か", "is_correct": false, "explanation": "物や量が十分にあること。時間の余裕の反対にはならない。"}], "correct_answer": "暇", "explanations": {"暇": "することがなく時間に余裕がある状態で、多忙の対義語。", "活発": "動きが盛んなこと。忙しさの反対を表す語ではない。", "厳格": "厳しく規律を守る様子。時間の余裕とは関係しない。", "豊か": "物や量が十分にあること。時間の余裕の反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52143, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暇", "is_correct": true, "explanation": "することがなく時間に余裕がある状態で、多忙の対義語。"}, {"text": "平穏", "is_correct": false, "explanation": "変わったことがなく穏やかなこと。時間の余裕の反対を表す語ではない。"}, {"text": "柔軟", "is_correct": false, "explanation": "状況に合わせて変えられること。忙しさとは関係しない。"}, {"text": "巧妙", "is_correct": false, "explanation": "細かく工夫されてうまいこと。時間の余裕とは関係しない。"}], "correct_answer": "暇", "explanations": {"暇": "することがなく時間に余裕がある状態で、多忙の対義語。", "平穏": "変わったことがなく穏やかなこと。時間の余裕の反対を表す語ではない。", "柔軟": "状況に合わせて変えられること。忙しさとは関係しない。", "巧妙": "細かく工夫されてうまいこと。時間の余裕とは関係しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52143, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもいそがしいこと。", "primary_collocate": null, "pronunciation": "たぼう", "ipa": "tabo̞ː", "syllable_count": 3, "sentences": [{"text": "今月は多忙で、友だちと会う約束を延ばした。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "今月[こんげつ]は多忙[たぼう]で、友[とも]だちと会[あ]う約束[やくそく]を延[の]ばした。", "sentence_source": "generated"}, {"text": "多忙な店長は、電話をしながら書類を書いている。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]な店長[てんちょう]は、電話[でんわ]をしながら書類[しょるい]を書[か]いている。", "sentence_source": "generated"}, {"text": "姉は多忙のため、結婚式の準備が進まない。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "姉[あね]は多忙[たぼう]のため、結婚式[けっこんしき]の準備[じゅんび]が進[すす]まない。", "sentence_source": "generated"}, {"text": "春は多忙な季節で、引っ越しの会社はどこも予約でいっぱいだ。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "春[はる]は多忙[たぼう]な季節[きせつ]で、引[ひ]っ越[こ]しの会社[かいしゃ]はどこも予約[よやく]でいっぱいだ。", "sentence_source": "generated"}, {"text": "多忙な日々を送っていると、趣味の時間がなくなる。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]な日々[ひび]を送[おく]っていると、趣味[しゅみ]の時間[じかん]がなくなる。", "sentence_source": "generated"}, {"text": "社長は多忙だから、会うなら先に予約したほうがいい。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は多忙[たぼう]だから、会[あ]うなら先[さき]に予約[よやく]したほうがいい。", "sentence_source": "generated"}, {"text": "多忙のなか来てくれて、本当にありがとう。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]のなか来[き]てくれて、本当[ほんとう]にありがとう。", "sentence_source": "generated"}, {"text": "父は多忙な仕事のせいで、ほとんど家にいない。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "父[ちち]は多忙[たぼう]な仕事[しごと]のせいで、ほとんど家[いえ]にいない。", "sentence_source": "generated"}, {"text": "試験前は多忙になり、アルバイトを休むことにした。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "試験前[しけんまえ]は多忙[たぼう]になり、アルバイトを休[やす]むことにした。", "sentence_source": "generated"}, {"text": "多忙を極める救急の現場では、一秒の判断が命を左右する。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]を極[きわ]める救急[きゅうきゅう]の現場[げんば]では、一秒[いちびょう]の判断[はんだん]が命[いのち]を左右[さゆう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多忙", "label": "語幹"}, {"form": "多忙な", "label": "連体形"}, {"form": "多忙で", "label": "連用形"}, {"form": "多忙だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "とてもいそがしい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52143, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多忙", "is_correct": true, "explanation": "とてもいそがしいという意味で、友だちとの約束を延ばした理由として文が成り立つ。"}, {"text": "乱雑", "is_correct": false, "explanation": "散らかって整っていない様子。約束を延ばす理由にならない。"}, {"text": "豪快", "is_correct": false, "explanation": "大胆で勢いがある様子。約束を延ばした理由として合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "汚れがなく衛生的なこと。予定の変更の理由には合わない。"}], "explanations": {"多忙": "とてもいそがしいという意味で、友だちとの約束を延ばした理由として文が成り立つ。", "乱雑": "散らかって整っていない様子。約束を延ばす理由にならない。", "豪快": "大胆で勢いがある様子。約束を延ばした理由として合わない。", "清潔": "汚れがなく衛生的なこと。予定の変更の理由には合わない。"}, "sentence_index": 0, "correct_answer": "多忙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その発表は、社会に多忙な影響を与えた。", "explanation": "ここは〈多大〉（影響などが大きいこと）の意味。影響の大きさには多大を使い、多忙は人の時間の余裕に使う。"}, {"text": "開店の日、お客さんが多忙に押し寄せた。", "explanation": "ここは〈殺到〉（一度に大勢が押し寄せること）の意味。客の集まりには殺到を使い、多忙は人の忙しさを表す。"}, {"text": "ごみの量が多忙で、回収が追いつかない。", "explanation": "ここは〈過多〉（多すぎること）の意味。量が多すぎる状態には過多を使い、多忙は人の忙しさに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52143, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多忙", "is_correct": true, "explanation": "「多忙の中」は忙しい中でという意味で、来てくれたことへの感謝の文に合う。"}, {"text": "豪華", "is_correct": false, "explanation": "ぜいたくで派手な様子。来てくれたことへの感謝の文脈に合わない。"}, {"text": "陰気", "is_correct": false, "explanation": "暗くじめじめした様子。感謝の言葉の前置きとして合わない。"}, {"text": "平凡", "is_correct": false, "explanation": "特に変わったところがないこと。「平凡の中」とは言わない。"}], "explanations": {"多忙": "「多忙の中」は忙しい中でという意味で、来てくれたことへの感謝の文に合う。", "豪華": "ぜいたくで派手な様子。来てくれたことへの感謝の文脈に合わない。", "陰気": "暗くじめじめした様子。感謝の言葉の前置きとして合わない。", "平凡": "特に変わったところがないこと。「平凡の中」とは言わない。"}, "sentence_index": 6, "correct_answer": "多忙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題は多忙な角度から検討する必要がある。", "explanation": "ここは〈多角〉（いろいろな方面から見ること）の意味。物事を見る観点には多角を使い、多忙は人がいそがしいことを表すので合わない。"}, {"text": "救急の現場では、多忙な数の患者が次々に運ばれてくる。", "explanation": "ここは〈多数〉（数が多いこと）の意味。数の多さには多数を使い、多忙は人がいそがしいことを表すので合わない。"}, {"text": "夜間は救急車の出動が多忙に頻発する。", "explanation": "ここは〈頻発〉（同じことが続けて起きること）の意味。出来事が起きる回数には頻発を使い、多忙は人の忙しさを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52143, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長は多忙の、会議を延ばした。", "corrected_sentence": "社長は多忙で、会議を延ばした。", "error_description": "「の」の後には名詞（または「ため」などの形式名詞）が続くため、「多忙の、」は文が途切れて誤り。理由は「多忙で、」と続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "多忙", "is_correct": true, "explanation": "語幹の「多忙」。直後の「な店長」がつながり、文が成り立つ。"}, {"text": "多忙だ", "is_correct": false, "explanation": "終止形で、「多忙だな店長」とは続かない。"}, {"text": "多忙に", "is_correct": false, "explanation": "副詞形で、「多忙になな店長」となり続かない。"}, {"text": "多忙化", "is_correct": false, "explanation": "「化」を付けた名詞で、「多忙化な店長」とは続かない。"}], "correct_form": "多忙", "base_form": "多忙", "form_label": "語幹", "sentence_index": 1, "explanations": {"多忙": "語幹の「多忙」。直後の「な店長」がつながり、文が成り立つ。", "多忙だ": "終止形で、「多忙だな店長」とは続かない。", "多忙に": "副詞形で、「多忙になな店長」となり続かない。", "多忙化": "「化」を付けた名詞で、「多忙化な店長」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52143, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救急の現場は多忙に極めていて、休憩が取れない。", "corrected_sentence": "救急の現場は多忙を極めていて、休憩が取れない。", "error_description": "「多忙を極める」は目的語に「を」を取る慣用。「多忙に極める」は誤りで、正しくは「多忙を極める」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "多忙", "is_correct": true, "explanation": "語幹の「多忙」。直後の「な仕事」がつながり、文が成り立つ。"}, {"text": "多忙ならば", "is_correct": false, "explanation": "仮定形で、「多忙ならばな仕事」とは続かない。"}, {"text": "多忙すぎ", "is_correct": false, "explanation": "程度を強める形で、「多忙すぎな仕事」とは続かない。"}, {"text": "多忙さ", "is_correct": false, "explanation": "名詞形で、「多忙さな仕事」とは続かない。"}], "correct_form": "多忙", "base_form": "多忙", "form_label": "語幹", "sentence_index": 7, "explanations": {"多忙": "語幹の「多忙」。直後の「な仕事」がつながり、文が成り立つ。", "多忙ならば": "仮定形で、「多忙ならばな仕事」とは続かない。", "多忙すぎ": "程度を強める形で、「多忙すぎな仕事」とは続かない。", "多忙さ": "名詞形で、「多忙さな仕事」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52144, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暇", "is_correct": true, "explanation": "することがなく時間に余裕がある状態で、多忙の対義語。"}, {"text": "静か", "is_correct": false, "explanation": "音や動きが少ない様子。忙しさの反対を表す語ではない。"}, {"text": "簡単", "is_correct": false, "explanation": "手間がかからない様子。多忙の反対語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "行き届いた態度や仕上がり。時間の余裕の反対にはならない。"}], "correct_answer": "暇", "explanations": {"暇": "することがなく時間に余裕がある状態で、多忙の対義語。", "静か": "音や動きが少ない様子。忙しさの反対を表す語ではない。", "簡単": "手間がかからない様子。多忙の反対語ではない。", "丁寧": "行き届いた態度や仕上がり。時間の余裕の反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52144, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暇", "is_correct": true, "explanation": "することがなく時間に余裕がある状態で、多忙の対義語。"}, {"text": "穏やか", "is_correct": false, "explanation": "波風が立たない落ち着いた様子。時間の余裕の反対を表す語ではない。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくいこと。忙しさとは関係しない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新しくて生き生きしていること。時間の余裕の反対にはならない。"}], "correct_answer": "暇", "explanations": {"暇": "することがなく時間に余裕がある状態で、多忙の対義語。", "穏やか": "波風が立たない落ち着いた様子。時間の余裕の反対を表す語ではない。", "頑丈": "丈夫で壊れにくいこと。忙しさとは関係しない。", "新鮮": "新しくて生き生きしていること。時間の余裕の反対にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52144, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "することがたくさんあって、時間が足りないこと。", "primary_collocate": null, "pronunciation": "たぼう", "ipa": "tabo̞ː", "syllable_count": 3, "sentences": [{"text": "多忙な専門職に就く人は、昼食に割ける時間が十五分しかないことも多い。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]な専門職[せんもんしょく]に就[つ]く人[ひと]は、昼食[ちゅうしょく]に割[さ]ける時間[じかん]が十五分[じゅうごふん]しかないことも多[おお]い。", "sentence_source": "generated"}, {"text": "年末は仕事が多忙で、昼ご飯を食べる時間もない。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "年末[ねんまつ]は仕事[しごと]が多忙[たぼう]で、昼[ひる]ご飯[はん]を食[た]べる時間[じかん]もない。", "sentence_source": "generated"}, {"text": "多忙な毎日が続いたので、週末は一日中寝ていた。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]な毎日[まいにち]が続[つづ]いたので、週末[しゅうまつ]は一日中[いちにちじゅう]寝[ね]ていた。", "sentence_source": "generated"}, {"text": "彼は多忙を理由に、同窓会への出席を断った。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "彼[かれ]は多忙[たぼう]を理由[りゆう]に、同窓会[どうそうかい]への出席[しゅっせき]を断[ことわ]った。", "sentence_source": "generated"}, {"text": "部長は出張が重なって多忙だが、メールにはいつも早く返事をくれる。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は出張[しゅっちょう]が重[かさ]なって多忙[たぼう]だが、メールにはいつも早[はや]く返事[へんじ]をくれる。", "sentence_source": "generated"}, {"text": "多忙な母のかわりに、私が夕飯を作ることにした。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]な母[はは]のかわりに、私[わたし]が夕飯[ゆうはん]を作[つく]ることにした。", "sentence_source": "generated"}, {"text": "多忙の中、お時間をいただきありがとうございます。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]の中[なか]、お時間[じかん]をいただきありがとうございます。", "sentence_source": "generated"}, {"text": "医者は多忙で、患者一人にかけられる時間が短い。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "医者[いしゃ]は多忙[たぼう]で、患者[かんじゃ]一人[ひとり]にかけられる時間[じかん]が短[みじか]い。", "sentence_source": "generated"}, {"text": "新学期は行事が多く、先生たちは多忙を極める。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "新学期[しんがっき]は行事[ぎょうじ]が多[おお]く、先生[せんせい]たちは多忙[たぼう]を極[きわ]める。", "sentence_source": "generated"}, {"text": "多忙だからといって、健康管理をおろそかにしてはいけない。", "target_word": "多忙", "complexity_tier": "T3", "furigana": "多忙[たぼう]だからといって、健康[けんこう]管理[かんり]をおろそかにしてはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多忙", "label": "語幹"}, {"form": "多忙な", "label": "連体形"}, {"form": "多忙で", "label": "連用形"}, {"form": "多忙だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "用事が多く時間の余裕がない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52144, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多忙", "is_correct": true, "explanation": "時間の余裕がないほど用事が多い意味で、昼食に割ける時間が少ない文脈と合う。"}, {"text": "退屈", "is_correct": false, "explanation": "することがなくて時間をもてあます意味。忙しい専門職の文脈と逆になる。"}, {"text": "清潔", "is_correct": false, "explanation": "汚れがなく衛生的なこと。忙しさを表す文の意味に合わない。"}, {"text": "元気", "is_correct": false, "explanation": "心身が健やかな様子。忙しさが問題になる文脈に合わない。"}], "explanations": {"多忙": "時間の余裕がないほど用事が多い意味で、昼食に割ける時間が少ない文脈と合う。", "退屈": "することがなくて時間をもてあます意味。忙しい専門職の文脈と逆になる。", "清潔": "汚れがなく衛生的なこと。忙しさを表す文の意味に合わない。", "元気": "心身が健やかな様子。忙しさが問題になる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "多忙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は多忙な額の寄付を集めて、建て直した。", "explanation": "ここは〈多額〉（金額が大きいこと）の意味。金額の大きさには多額を使い、多忙は人の時間の余裕に使う。"}, {"text": "彼女は多忙な年頃で、ささいなことで傷つく。", "explanation": "ここは〈多感〉（感じやすいこと）の意味。感受性が強い年頃には多感を使い、多忙は時間が足りない状態を表すので合わない。"}, {"text": "駅の構内は多忙で、身動きが取れなかった。", "explanation": "ここは〈混雑〉（人が込み合うこと）の意味。場所が込むことには混雑を使い、多忙は人の仕事の忙しさに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52144, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多忙", "is_correct": true, "explanation": "「多忙の中」は忙しい中でという意味で、時間を割いてもらったことへの感謝の文に合う。"}, {"text": "乱雑", "is_correct": false, "explanation": "散らかって整っていない様子。時間を割いてくれたことの前置きには合わない。"}, {"text": "豪快", "is_correct": false, "explanation": "大胆で勢いがある様子。忙しい中での来訪という文脈と合わない。"}, {"text": "迅速", "is_correct": false, "explanation": "速いこと。「迅速の中」とは言わない。"}], "explanations": {"多忙": "「多忙の中」は忙しい中でという意味で、時間を割いてもらったことへの感謝の文に合う。", "乱雑": "散らかって整っていない様子。時間を割いてくれたことの前置きには合わない。", "豪快": "大胆で勢いがある様子。忙しい中での来訪という文脈と合わない。", "迅速": "速いこと。「迅速の中」とは言わない。"}, "sentence_index": 6, "correct_answer": "多忙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は多忙な金額の借金を、やっと返し終えた。", "explanation": "ここは〈多額〉（金額が大きいこと）の意味。金額には多額を使い、多忙は時間の余裕に使う。"}, {"text": "このデパートは多忙な品ぞろえで、何でも揃う。", "explanation": "ここは〈多様〉（種類がいろいろあること）の意味。品ぞろえの種類には多様を使い、多忙は人の忙しさを表すので合わない。"}, {"text": "この地域は事故が多忙で、警察も大変だ。", "explanation": "ここは〈多発〉（同じ出来事が何度も起きること）の意味。出来事の回数には多発を使い、多忙は人の忙しさを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52144, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は多忙の日々で、休みが取れない。", "corrected_sentence": "彼女は多忙な日々で、休みが取れない。", "error_description": "形状詞「多忙」は名詞を修飾するとき「多忙な」になる。「多忙の日々」は誤りで、正しくは「多忙な日々」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "多忙", "is_correct": true, "explanation": "語幹の「多忙」。直後の「で」がつながって「多忙で」となり、文が成り立つ。"}, {"text": "多忙な", "is_correct": false, "explanation": "連体形で名詞の前に付くため、直後の「で」とは続かない。"}, {"text": "多忙だ", "is_correct": false, "explanation": "終止形で、「多忙だで」となり「で」とは続かない。"}, {"text": "多忙に", "is_correct": false, "explanation": "副詞形で、「多忙にで」となり「で」とは続かない。"}], "correct_form": "多忙", "base_form": "多忙", "form_label": "語幹", "sentence_index": 1, "explanations": {"多忙": "語幹の「多忙」。直後の「で」がつながって「多忙で」となり、文が成り立つ。", "多忙な": "連体形で名詞の前に付くため、直後の「で」とは続かない。", "多忙だ": "終止形で、「多忙だで」となり「で」とは続かない。", "多忙に": "副詞形で、「多忙にで」となり「で」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52144, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "担任の先生は多忙ので、補習を休んだ。", "corrected_sentence": "担任の先生は多忙で、補習を休んだ。", "error_description": "形状詞「多忙」は理由を表すとき「多忙なので」「多忙で」と続ける。「多忙ので」は「な」が抜けていて誤り。正しくは「多忙で」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "多忙", "is_correct": true, "explanation": "語幹の「多忙」。直後の「で」が続いて「多忙で」となり、文が成り立つ。"}, {"text": "多忙ならば", "is_correct": false, "explanation": "仮定形で、「ならばで」と「で」は続かない。"}, {"text": "多忙すぎ", "is_correct": false, "explanation": "程度を強める形で、「すぎで」と「で」は続かない。"}, {"text": "多忙である", "is_correct": false, "explanation": "「である」の後に「で」は続かず、文が不自然になる。"}], "correct_form": "多忙", "base_form": "多忙", "form_label": "語幹", "sentence_index": 7, "explanations": {"多忙": "語幹の「多忙」。直後の「で」が続いて「多忙で」となり、文が成り立つ。", "多忙ならば": "仮定形で、「ならばで」と「で」は続かない。", "多忙すぎ": "程度を強める形で、「すぎで」と「で」は続かない。", "多忙である": "「である」の後に「で」は続かず、文が不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52145, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ピーナッツの殻」の修飾を示す「の」で、殻を修飾する位置に入る。"}, {"text": "を", "is_correct": false, "explanation": "「ピーナッツを殻を」となり、目的語が二つ重なって不自然。"}, {"text": "に", "is_correct": false, "explanation": "着点の「に」は「殻」を修飾できず、ここでは続かない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」は「殻」の修飾に使えず、文が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「ピーナッツの殻」の修飾を示す「の」で、殻を修飾する位置に入る。", "を": "「ピーナッツを殻を」となり、目的語が二つ重なって不自然。", "に": "着点の「に」は「殻」を修飾できず、ここでは続かない。", "が": "主格の「が」は「殻」の修飾に使えず、文が崩れる。"}, "error_tags": {"を": "対格", "に": "着点", "が": "主格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52145, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52145, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ピーナッツは、かたいからに包まれた小さな豆のような食べ物です。", "primary_collocate": null, "pronunciation": "ぴーなっつ", "ipa": "piːnattsɯ", "syllable_count": 5, "sentences": [{"text": "ピーナッツは、かたい殻の中に入っている。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "ピーナッツは、かたい殻[から]の中[なか]に入[はい]っている。", "sentence_source": "generated"}, {"text": "公園で、ピーナッツの殻をむいて食べた。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "公園[こうえん]で、ピーナッツの殻[から]をむいて食[た]べた。", "sentence_source": "generated"}, {"text": "兄はピーナッツが好きで、映画を見ながらよく食べる。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "兄[あに]はピーナッツが好[す]きで、映画[えいが]を見[み]ながらよく食[た]べる。", "sentence_source": "generated"}, {"text": "ピーナッツを割ると、中に豆が二つ入っていた。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "ピーナッツを割[わ]ると、中[なか]に豆[まめ]が二[ふた]つ入[はい]っていた。", "sentence_source": "generated"}, {"text": "机の上にピーナッツが落ちていたので、拾ってごみ箱に入れた。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]にピーナッツが落[お]ちていたので、拾[ひろ]ってごみ箱[ばこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "母は、ピーナッツを小さく切ってサラダにのせた。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "母[はは]は、ピーナッツを小[ちい]さく切[き]ってサラダにのせた。", "sentence_source": "generated"}, {"text": "野球場では、ピーナッツを売る人が席の間を歩いている。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "野球場[やきゅうじょう]では、ピーナッツを売[う]る人[ひと]が席[せき]の間[あいだ]を歩[ある]いている。", "sentence_source": "generated"}, {"text": "豆に似ているけれど、ピーナッツは土の中で育つ。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "豆[まめ]に似[に]ているけれど、ピーナッツは土[つち]の中[なか]で育[そだ]つ。", "sentence_source": "generated"}, {"text": "遠足のおやつに、ピーナッツを一袋持っていった。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "遠足[えんそく]のおやつに、ピーナッツを一袋[ひとふくろ]持[も]っていった。", "sentence_source": "generated"}, {"text": "このピーナッツは塩味がきいていて、ビールによく合う。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "このピーナッツは塩味[しおあじ]がきいていて、ビールによく合[あ]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ピーナッツ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "かたい殻に入った小さな豆状の食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52145, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ピーナッツ", "is_correct": true, "explanation": "かたい殻の中に入っている小さな豆状の食べ物として、ピーナッツが入る。"}, {"text": "ねぎ", "is_correct": false, "explanation": "ねぎはかたい殻に入った食べ物ではないので、空所に入らない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳は殻に入った食べ物ではないので、空所に入らない。"}, {"text": "ワイン", "is_correct": false, "explanation": "ワインは殻の中に入っているものではないので、空所に入らない。"}], "explanations": {"ピーナッツ": "かたい殻の中に入っている小さな豆状の食べ物として、ピーナッツが入る。", "ねぎ": "ねぎはかたい殻に入った食べ物ではないので、空所に入らない。", "牛乳": "牛乳は殻に入った食べ物ではないので、空所に入らない。", "ワイン": "ワインは殻の中に入っているものではないので、空所に入らない。"}, "sentence_index": 0, "correct_answer": "ピーナッツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このピーナッツは、かたい貝殻に包まれた食べ物で、酒蒸しにする。", "explanation": "ここは〈はまぐり〉の説明（貝殻に包まれた食べ物）。ピーナッツは貝ではないので、酒蒸しにはしない。"}, {"text": "このピーナッツは、かたい殻に包まれていて、割ると白身が出てくる。", "explanation": "ここは〈たまご〉の説明（殻を割ると白身が出る）。ピーナッツは白身ではなく、豆が入っている。"}, {"text": "このピーナッツは、大きな花の中心にできて、花が枯れると摘み取る。", "explanation": "ここは〈ひまわりの種〉の説明（花の中心にできる）。ピーナッツは花の中心ではなく、地中のさやにできる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52145, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ピーナッツ", "is_correct": true, "explanation": "野球場で売られる、殻付きの豆の食べ物として、ピーナッツが入る。"}, {"text": "ねぎ", "is_correct": false, "explanation": "ねぎは食べ物だが、球場の席の間で売り歩かれるものではないので、空所に入らない。"}, {"text": "ガソリン", "is_correct": false, "explanation": "ガソリンは食べ物ではなく、席の間を歩いて売る対象として成り立たない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは食べ物ではなく、売り子が席の間を歩いて売る文脈に合わない。"}], "explanations": {"ピーナッツ": "野球場で売られる、殻付きの豆の食べ物として、ピーナッツが入る。", "ねぎ": "ねぎは食べ物だが、球場の席の間で売り歩かれるものではないので、空所に入らない。", "ガソリン": "ガソリンは食べ物ではなく、席の間を歩いて売る対象として成り立たない。", "消しゴム": "消しゴムは食べ物ではなく、売り子が席の間を歩いて売る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ピーナッツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このピーナッツは、魚のすり身を蒸して作る。", "explanation": "ここは〈かまぼこ〉の説明（魚のすり身を蒸した食品）。ピーナッツは魚ではないので合わない。"}, {"text": "このピーナッツは、砂糖を水で煮溶かして作る、とろりとした液体だ。", "explanation": "ここは〈シロップ〉の説明（砂糖を煮溶かした液体）。ピーナッツは殻入りの豆で、液体ではない。"}, {"text": "このピーナッツは、飲み物を口に運ぶ細い管だ。", "explanation": "ここは〈ストロー〉の説明（飲み物を運ぶ細い管）。ピーナッツは管ではなく食べ物だ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52145, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は縁側で、ピーナッツに剥いて、孫に配った。", "corrected_sentence": "祖父は縁側で、ピーナッツを剥いて、孫に配った。", "error_description": "「剥く」の目的語は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52145, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は、ピーナッツで細かく刻んで、ごはんに混ぜた。", "corrected_sentence": "弟は、ピーナッツを細かく刻んで、ごはんに混ぜた。", "error_description": "「刻む」の目的語は「を」で示す。「で」は道具を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
