INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52146, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ピーナッツが」は「かかっている」の主語で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「かかる」は目的語を取らず、「を」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」では、かかっている状態を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の「と」は、ここでは続かない。"}], "correct_answer": "が", "explanations": {"が": "「ピーナッツが」は「かかっている」の主語で、正しい。", "を": "「かかる」は目的語を取らず、「を」では文が成り立たない。", "で": "手段・場所の「で」では、かかっている状態を示せない。", "と": "並列・相手の「と」は、ここでは続かない。"}, "error_tags": {"を": "対格", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52146, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ピーナッツは、マメ科の植物の種子で、炒って食べることが多い。ピーナッツバターなどの加工品にも使われる。", "primary_collocate": null, "pronunciation": "ぴーなっつ", "ipa": "piːnattsɯ", "syllable_count": 5, "sentences": [{"text": "その解答の一つが、ピーナッツとジャムを掛け合わせたサンドイッチの構築にある。", "target_word": "ピーナッツ", "complexity_tier": "T5", "furigana": "その解答[かいとう]の一[ひと]つが、ピーナッツとジャムを掛[か]け合[あ]わせたサンドイッチの構築[こうちく]にある。", "sentence_source": "generated"}, {"text": "まず、良質な全粒粉のパンを用意し、その表面にピーナッツを砕いてのせる。", "target_word": "ピーナッツ", "complexity_tier": "T5", "furigana": "まず、良質[りょうしつ]な全粒粉[ぜんりゅうふん]のパンを用意[ようい]し、その表面[ひょうめん]にピーナッツを砕[くだ]いてのせる。", "sentence_source": "generated"}, {"text": "ピーナッツは豆の仲間で、土の中で実がなる。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "ピーナッツは豆[まめ]の仲間[なかま]で、土[つち]の中[なか]で実[み]がなる。", "sentence_source": "generated"}, {"text": "祖母は畑でピーナッツを育てて、秋に収穫する。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は畑[はたけ]でピーナッツを育[そだ]てて、秋[あき]に収穫[しゅうかく]する。", "sentence_source": "generated"}, {"text": "千葉県は、ピーナッツの産地として有名だ。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "千葉県[ちばけん]は、ピーナッツの産地[さんち]として有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "塩を振って炒ったピーナッツは、お酒のおつまみによく合う。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "塩[しお]を振[ふ]って炒[い]ったピーナッツは、お酒[さけ]のおつまみによく合[あ]う。", "sentence_source": "generated"}, {"text": "ピーナッツをすりつぶして砂糖と混ぜると、甘いペーストになる。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "ピーナッツをすりつぶして砂糖[さとう]と混[ま]ぜると、甘[あま]いペーストになる。", "sentence_source": "generated"}, {"text": "この店のカレーには、砕いたピーナッツがかかっている。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "この店[みせ]のカレーには、砕[くだ]いたピーナッツがかかっている。", "sentence_source": "generated"}, {"text": "ピーナッツを食べると発疹が出るので、弟は食品の表示を必ず確かめる。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "ピーナッツを食[た]べると発疹[ほっしん]が出[で]るので、弟[おとうと]は食品[しょくひん]の表示[ひょうじ]を必[かなら]ず確[たし]かめる。", "sentence_source": "generated"}, {"text": "ピーナッツから油をとって、料理に使うこともある。", "target_word": "ピーナッツ", "complexity_tier": "T3", "furigana": "ピーナッツから油[あぶら]をとって、料理[りょうり]に使[つか]うこともある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ピーナッツ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "マメ科植物の種子としての落花生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52146, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ピーナッツ", "is_correct": true, "explanation": "ピーナッツとジャムを掛け合わせた具として、豆のピーナッツが入る。"}, {"text": "ねぎ", "is_correct": false, "explanation": "ねぎはジャムと掛け合わせるサンドイッチの具にはならず、空所に入らない。"}, {"text": "ガソリン", "is_correct": false, "explanation": "ガソリンは食べ物ではなく、サンドイッチの具として入らない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは食べ物ではなく、サンドイッチの具として入らない。"}], "explanations": {"ピーナッツ": "ピーナッツとジャムを掛け合わせた具として、豆のピーナッツが入る。", "ねぎ": "ねぎはジャムと掛け合わせるサンドイッチの具にはならず、空所に入らない。", "ガソリン": "ガソリンは食べ物ではなく、サンドイッチの具として入らない。", "消しゴム": "消しゴムは食べ物ではなく、サンドイッチの具として入らない。"}, "sentence_index": 0, "correct_answer": "ピーナッツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このピーナッツは、大豆を炒って粉にしたもので、餅にまぶして食べる。", "explanation": "ここは〈きな粉〉の説明。ピーナッツは大豆の粉ではないので、きな粉の意味とは合わない。"}, {"text": "このピーナッツは、木の枝に実る硬い実で、そのまま割って食べる。", "explanation": "ここは〈くるみ〉のように木に実る硬い実の意味。ピーナッツは地中で実るので、木の枝には実らない。"}, {"text": "このピーナッツは房になって実り、一粒ずつ摘んで集める。", "explanation": "ここは〈ぶどう〉のように房になって実る意味。ピーナッツは房にならず、さやごと地中に実る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52146, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ピーナッツ", "is_correct": true, "explanation": "すりつぶして砂糖と混ぜる材料として、ピーナッツが入る。"}, {"text": "ねぎ", "is_correct": false, "explanation": "ねぎを砂糖と混ぜても甘いペーストにはならず、空所に入らない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳は液体なので、すりつぶす対象にならない。"}, {"text": "ワイン", "is_correct": false, "explanation": "ワインは液体なので、すりつぶす対象にならない。"}], "explanations": {"ピーナッツ": "すりつぶして砂糖と混ぜる材料として、ピーナッツが入る。", "ねぎ": "ねぎを砂糖と混ぜても甘いペーストにはならず、空所に入らない。", "牛乳": "牛乳は液体なので、すりつぶす対象にならない。", "ワイン": "ワインは液体なので、すりつぶす対象にならない。"}, "sentence_index": 6, "correct_answer": "ピーナッツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このピーナッツは海で育ち、乾かして板にしてから、焼いて食べる。", "explanation": "ここは〈のり〉の説明。ピーナッツは海藻ではなく陸の植物なので、板状にはならない。"}, {"text": "ピーナッツはいもを原料にして固めた食品で、おでんに入れる。", "explanation": "ここは〈こんにゃく〉の説明（いもを固めた食品）。ピーナッツはいもではないので合わない。"}, {"text": "このピーナッツは牛乳を発酵させて作り、朝食に添える。", "explanation": "ここは〈ヨーグルト〉の説明（牛乳を発酵させたもの）。ピーナッツは牛乳を使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52146, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は裏庭で、ピーナッツが育てて、毎年少し収穫している。", "corrected_sentence": "父は裏庭で、ピーナッツを育てて、毎年少し収穫している。", "error_description": "「育てる」の目的語は「を」で示す。「ピーナッツが」は誤りで、正しくは「ピーナッツを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52146, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私はピーナッツで砕いて、ヨーグルトに混ぜた。", "corrected_sentence": "私はピーナッツを砕いて、ヨーグルトに混ぜた。", "error_description": "「砕く」の目的語は「を」で示す。「で」は道具を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52147, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「いちごのジャムより」で比較の基準を示し、後の「ほうが好き」に続く。"}, {"text": "を", "is_correct": false, "explanation": "「ジャムを」では比較の文脈に入らず、「好きだ」の対象も不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "着点の「に」は比較の文脈に合わず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は比較を示せず、ここでは続かない。"}], "correct_answer": "より", "explanations": {"より": "「いちごのジャムより」で比較の基準を示し、後の「ほうが好き」に続く。", "を": "「ジャムを」では比較の文脈に入らず、「好きだ」の対象も不自然になる。", "に": "着点の「に」は比較の文脈に合わず、文が成り立たない。", "へ": "方向の「へ」は比較を示せず、ここでは続かない。"}, "error_tags": {"を": "対格", "に": "着点・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
