INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52147, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンにぬって食べる、くだものから作ったあまいもの。", "primary_collocate": null, "pronunciation": "じゃむ", "ipa": "dʑamɯ", "syllable_count": 2, "sentences": [{"text": "朝ごはんに、パンにジャムをぬって食べた。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに、パンにジャムをぬって食[た]べた。", "sentence_source": "generated"}, {"text": "私はいちごのジャムより、オレンジのジャムのほうが好きだ。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "私[わたし]はいちごのジャムより、オレンジのジャムのほうが好[す]きだ。", "sentence_source": "generated"}, {"text": "スコーンには、ジャムとクリームがよく合う。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "スコーンには、ジャムとクリームがよく合[あ]う。", "sentence_source": "generated"}, {"text": "弟はジャムをたくさんぬりすぎて、手がべたべたになった。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "弟[おとうと]はジャムをたくさんぬりすぎて、手[て]がべたべたになった。", "sentence_source": "generated"}, {"text": "スーパーで、ブルーベリーのジャムを一つ買った。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "スーパーで、ブルーベリーのジャムを一[ひと]つ買[か]った。", "sentence_source": "generated"}, {"text": "ジャムがなくなったので、母に新しいのを頼んだ。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "ジャムがなくなったので、母[はは]に新[あたら]しいのを頼[たの]んだ。", "sentence_source": "generated"}, {"text": "トーストにバターとジャムをのせると、おいしい。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "トーストにバターとジャムをのせると、おいしい。", "sentence_source": "generated"}, {"text": "台所のたなには、ジャムの瓶が三つ並んでいる。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "台所[だいどころ]のたなには、ジャムの瓶[びん]が三[みっ]つ並[なら]んでいる。", "sentence_source": "generated"}, {"text": "ジャムの甘い匂いがして、台所をのぞいた。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "ジャムの甘[あま]い匂[にお]いがして、台所[だいどころ]をのぞいた。", "sentence_source": "generated"}, {"text": "友だちからもらった手作りのジャムは、りんごの味がした。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "友[とも]だちからもらった手作[てづく]りのジャムは、りんごの味[あじ]がした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジャム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "パンにぬる、くだもので作った甘いもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52147, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジャム", "is_correct": true, "explanation": "パンにぬる対象として、ジャムが入る。"}, {"text": "ワイン", "is_correct": false, "explanation": "ワインはパンにぬって食べるものではなく、空所に入らない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳をパンにぬるとは言わず、空所に入らない。"}, {"text": "ねぎ", "is_correct": false, "explanation": "ねぎをパンにぬって食べるのは不自然で、文に合わない。"}], "explanations": {"ジャム": "パンにぬる対象として、ジャムが入る。", "ワイン": "ワインはパンにぬって食べるものではなく、空所に入らない。", "牛乳": "牛乳をパンにぬるとは言わず、空所に入らない。", "ねぎ": "ねぎをパンにぬって食べるのは不自然で、文に合わない。"}, "sentence_index": 0, "correct_answer": "ジャム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジャムは、卵と油と酢を混ぜて作り、サラダにかける。", "explanation": "ここは〈マヨネーズ〉の説明（卵と油と酢で作る）。ジャムは果物と砂糖で作るので、卵や油は使わない。"}, {"text": "ジャムは、すりおろして刺身に添える、辛い薬味だ。", "explanation": "ここは〈わさび〉の説明（辛い薬味）。ジャムは甘い保存食なので、辛い薬味とは合わない。"}, {"text": "ジャムは、大豆と米麹を発酵させて作る調味料だ。", "explanation": "ここは〈みそ〉の説明（大豆と米麹を発酵させた調味料）。ジャムは果物と砂糖で作るので、みその意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52147, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジャム", "is_correct": true, "explanation": "トーストにバターと並べてのせる対象として、ジャムが入る。"}, {"text": "ごはん", "is_correct": false, "explanation": "トーストにバターとごはんをのせる組み合わせは不自然で、空所に入らない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは食べ物ではなく、トーストにのせる対象として成り立たない。"}, {"text": "スープ", "is_correct": false, "explanation": "スープは液体でトーストにのせられず、空所に入らない。"}], "explanations": {"ジャム": "トーストにバターと並べてのせる対象として、ジャムが入る。", "ごはん": "トーストにバターとごはんをのせる組み合わせは不自然で、空所に入らない。", "消しゴム": "消しゴムは食べ物ではなく、トーストにのせる対象として成り立たない。", "スープ": "スープは液体でトーストにのせられず、空所に入らない。"}, "sentence_index": 6, "correct_answer": "ジャム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジャムは、牛乳を固めて発酵させた食品で、パンにのせて食べる。", "explanation": "ここは〈チーズ〉の説明（牛乳を固めて発酵させた食品）。ジャムは果物から作る甘いペーストで、乳製品ではない。"}, {"text": "ジャムは、鍋に水と具材を入れて煮込んだ汁物で、体が温まる。", "explanation": "ここは〈スープ〉の説明（具材を煮込んだ汁物）。ジャムは汁物ではなく、甘いペーストだ。"}, {"text": "ジャムは、紙と紙をはり合わせるために使う、ねばりのある接着剤だ。", "explanation": "ここは〈のり〉の説明（紙を貼り合わせる接着剤）。ジャムは食べ物で、接着には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52147, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は、トーストにジャムが少しぬって食べた。", "corrected_sentence": "私は、トーストにジャムを少しぬって食べた。", "error_description": "「ぬる」の目的語は「を」で示す。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52147, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、りんごのジャムに瓶に入れて、保存した。", "corrected_sentence": "祖母は、りんごのジャムを瓶に入れて、保存した。", "error_description": "「入れる」の目的語は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
