INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52148, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ジャムを」が「煮る」の目的語になるので、対格の「を」。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」は「煮る」の目的語を示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "着点の「に」は「煮る」の対象を示せず、ここでは続かない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」は、ここでは「ジャムを」の位置に入らない。"}], "correct_answer": "を", "explanations": {"を": "「ジャムを」が「煮る」の目的語になるので、対格の「を」。", "が": "主格の「が」は「煮る」の目的語を示せず、文が成り立たない。", "に": "着点の「に」は「煮る」の対象を示せず、ここでは続かない。", "で": "手段・場所の「で」は、ここでは「ジャムを」の位置に入らない。"}, "error_tags": {"が": "主格", "に": "着点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52148, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "果実に砂糖を加えて煮詰めた、保存食としても用いられる甘いペースト。", "primary_collocate": null, "pronunciation": "じゃむ", "ipa": "dʑamɯ", "syllable_count": 2, "sentences": [{"text": "その解答の一つが、ピーナッツバターとジャムを掛け合わせたサンドイッチの構築にある。", "target_word": "ジャム", "complexity_tier": "T5", "furigana": "その解答[かいとう]の一[ひと]つが、ピーナッツバターとジャムを掛[か]け合[あ]わせたサンドイッチの構築[こうちく]にある。", "sentence_source": "mined"}, {"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "ジャム", "complexity_tier": "T5", "furigana": "この際[さい]、脂質[ししつ]の膜[まく]がジャムの水分[すいぶん]浸透[しんとう]を防[ふせ]ぐバリアーとして機能[きのう]するという科学的[かがくてき]裏付[うらづ]けも無視[むし]できない。", "sentence_source": "mined"}, {"text": "冷蔵庫の奥に、去年作った柚子のジャムが残っていた。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の奥[おく]に、去年[きょねん]作[つく]った柚子[ゆず]のジャムが残[のこ]っていた。", "sentence_source": "generated"}, {"text": "ジャムは、果物に砂糖を加えて煮詰めて作る。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "ジャムは、果物[くだもの]に砂糖[さとう]を加[くわ]えて煮詰[につ]めて作[つく]る。", "sentence_source": "generated"}, {"text": "夏に採れたいちごをジャムにして、冬まで保存する。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "夏[なつ]に採[と]れたいちごをジャムにして、冬[ふゆ]まで保存[ほぞん]する。", "sentence_source": "generated"}, {"text": "開けたジャムは冷蔵庫に入れて、早めに食べきるほうがいい。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "開[あ]けたジャムは冷蔵庫[れいぞうこ]に入[い]れて、早[はや]めに食[た]べきるほうがいい。", "sentence_source": "generated"}, {"text": "手作りのジャムは、砂糖が少ないぶん、果物の酸味がよく残る。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "手作[てづく]りのジャムは、砂糖[さとう]が少[すく]ないぶん、果物[くだもの]の酸味[さんみ]がよく残[のこ]る。", "sentence_source": "generated"}, {"text": "祖母は庭のりんごで、毎年ジャムを大きな鍋で煮る。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "祖母[そぼ]は庭[にわ]のりんごで、毎年[まいとし]ジャムを大[おお]きな鍋[なべ]で煮[に]る。", "sentence_source": "generated"}, {"text": "ヨーグルトにジャムを混ぜると、さっぱりした甘さになる。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "ヨーグルトにジャムを混[ま]ぜると、さっぱりした甘[あま]さになる。", "sentence_source": "generated"}, {"text": "ジャムの瓶のふたが固くて、開けるのに苦労した。", "target_word": "ジャム", "complexity_tier": "T3", "furigana": "ジャムの瓶[びん]のふたが固[かた]くて、開[あ]けるのに苦労[くろう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジャム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "果実を砂糖で煮詰めた保存性のある甘いペースト", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b2554a-d708-4448-92dc-38f2c32c1b81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52148, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジャム", "is_correct": true, "explanation": "ピーナッツバターと掛け合わせる甘いペーストとして、ジャムが入る。"}, {"text": "ねぎ", "is_correct": false, "explanation": "ピーナッツバターと掛け合わせる具としては、ねぎは成り立たず、空所に入らない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳はペーストではなく、掛け合わせてサンドイッチの具にはならない。"}, {"text": "ワイン", "is_correct": false, "explanation": "ワインはサンドイッチの材料として文が成り立たず、空所に入らない。"}], "explanations": {"ジャム": "ピーナッツバターと掛け合わせる甘いペーストとして、ジャムが入る。", "ねぎ": "ピーナッツバターと掛け合わせる具としては、ねぎは成り立たず、空所に入らない。", "牛乳": "牛乳はペーストではなく、掛け合わせてサンドイッチの具にはならない。", "ワイン": "ワインはサンドイッチの材料として文が成り立たず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "ジャム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ステーキには、ジャムをかけると、肉の味が引き立つ。", "explanation": "ここは〈ケチャップ〉のような肉料理の調味料の意味。ジャムは甘い保存食で、ステーキの調味料には合わない。"}, {"text": "ジャムは、油と酢を混ぜて、サラダにかける。", "explanation": "油と酢で作るのはドレッシング。ジャムは果物の甘いペーストなので合わない。"}, {"text": "ジャムは、塩をふって焼き、肉料理の付け合わせにする。", "explanation": "ここは〈おかずのソース〉の意味で使われている。ジャムは甘い果物のペーストで、塩味の付け合わせにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52148, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジャム", "is_correct": true, "explanation": "手作りの甘いペーストとして、ジャムが入る。"}, {"text": "ハム", "is_correct": false, "explanation": "ハムは砂糖を使わない食品で、「砂糖が少ないぶん酸味が残る」の文に合わない。"}, {"text": "ツナ", "is_correct": false, "explanation": "ツナは果物の酸味の話と合わず、「手作りの」ものとして文が成り立たない。"}, {"text": "チーズ", "is_correct": false, "explanation": "チーズは果物の酸味が残るという文脈に合わず、空所に入らない。"}], "explanations": {"ジャム": "手作りの甘いペーストとして、ジャムが入る。", "ハム": "ハムは砂糖を使わない食品で、「砂糖が少ないぶん酸味が残る」の文に合わない。", "ツナ": "ツナは果物の酸味の話と合わず、「手作りの」ものとして文が成り立たない。", "チーズ": "チーズは果物の酸味が残るという文脈に合わず、空所に入らない。"}, "sentence_index": 6, "correct_answer": "ジャム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジャムは、牛乳の脂肪を固めて作り、パンにぬって食べる。", "explanation": "ここは〈バター〉の説明（牛乳の脂肪を固めたもの）。ジャムは果物から作るので、乳脂肪では作らない。"}, {"text": "ジャムは、ミツバチが集めた花の蜜だ。", "explanation": "ここは〈はちみつ〉の説明（ミツバチが集めた蜜）。ジャムは蜜ではなく、果物と砂糖で作る。"}, {"text": "ジャムは、ごはんにかけて食べる塩味の粉だ。", "explanation": "ここは〈ふりかけ〉の説明（ごはんにかける塩味の粉）。ジャムは甘いペーストで、塩味の粉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52148, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は、冷蔵庫でジャムに開けて、パンにぬった。", "corrected_sentence": "私は、冷蔵庫でジャムを開けて、パンにぬった。", "error_description": "「開ける」の目的語は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52148, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、いちごのジャムでびんに詰めて、冬に備えた。", "corrected_sentence": "祖母は、いちごのジャムをびんに詰めて、冬に備えた。", "error_description": "「詰める」の目的語は「を」で示す。「で」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a3e2a5-97e8-487b-a9c5-1c7cd711c1ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52149, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す。文頭のバターを話題にする役割を果たす。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、ここは「食べ物です」と続く主題の位置なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着や相手を示す。ここで使うと「牛乳から作った」との続きが不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、文の主題の位置には使わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す。文頭のバターを話題にする役割を果たす。", "を": "目的語を示すが、ここは「食べ物です」と続く主題の位置なので合わない。", "に": "帰着や相手を示す。ここで使うと「牛乳から作った」との続きが不自然になる。", "へ": "方向を示すが、文の主題の位置には使わない。"}, "error_tags": {"を": "目的語", "に": "帰着・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52149, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「外に出す」の対象を示す。「バターを外に出す」の形で正しい。"}, {"text": "や", "is_correct": false, "explanation": "例示や並列の助詞で、「バターや外に出す」の形では対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞。「バターより外に出す」の形は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「バターで外に出す」は対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「外に出す」の対象を示す。「バターを外に出す」の形で正しい。", "や": "例示や並列の助詞で、「バターや外に出す」の形では対象を示せない。", "より": "比較を示す助詞。「バターより外に出す」の形は成り立たない。", "で": "手段や場所を示す。「バターで外に出す」は対象を示せない。"}, "error_tags": {"より": "比較", "で": "手段・場所", "や": "並列・例示"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52149, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンにぬって食べる、牛乳から作った甘くない味の食べ物。", "primary_collocate": null, "pronunciation": "ばたー", "ipa": "bataː", "syllable_count": 3, "sentences": [{"text": "毎朝、トーストにバターをぬって食べます。", "target_word": "バター", "complexity_tier": "T2", "furigana": "毎朝[まいあさ]、トーストにバターをぬって食[た]べます。", "sentence_source": "generated"}, {"text": "バターは牛乳から作った食べ物です。", "target_word": "バター", "complexity_tier": "T2", "furigana": "バターは牛乳[ぎゅうにゅう]から作[つく]った食[た]べ物[もの]です。", "sentence_source": "generated"}, {"text": "冷たいバターは固くて、パンにぬりにくいです。", "target_word": "バター", "complexity_tier": "T3", "furigana": "冷[つめ]たいバターは固[かた]くて、パンにぬりにくいです。", "sentence_source": "generated"}, {"text": "兄はフライパンでバターを溶かして、卵を焼きました。", "target_word": "バター", "complexity_tier": "T3", "furigana": "兄[あに]はフライパンでバターを溶[と]かして、卵[たまご]を焼[や]きました。", "sentence_source": "generated"}, {"text": "スーパーでバターを一つ買ってきてください。", "target_word": "バター", "complexity_tier": "T2", "furigana": "スーパーでバターを一[ひと]つ買[か]ってきてください。", "sentence_source": "generated"}, {"text": "バターを入れると、スープがまろやかになります。", "target_word": "バター", "complexity_tier": "T3", "furigana": "バターを入[い]れると、スープがまろやかになります。", "sentence_source": "generated"}, {"text": "日曜日に、バターの入ったクッキーを焼きました。", "target_word": "バター", "complexity_tier": "T2", "furigana": "日曜日[にちようび]に、バターの入[はい]ったクッキーを焼[や]きました。", "sentence_source": "generated"}, {"text": "暑い日にバターを外に出したままにしたら、溶けてしまいました。", "target_word": "バター", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]にバターを外[そと]に出[だ]したままにしたら、溶[と]けてしまいました。", "sentence_source": "generated"}, {"text": "このパンはバターの香りがして、とてもおいしいです。", "target_word": "バター", "complexity_tier": "T2", "furigana": "このパンはバターの香[かお]りがして、とてもおいしいです。", "sentence_source": "generated"}, {"text": "バターが切れたので、夕方に買いに行きます。", "target_word": "バター", "complexity_tier": "T2", "furigana": "バターが切[き]れたので、夕方[ゆうがた]に買[か]いに行[い]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バター", "label": "基本形"}], "register": "標準", "sense_fingerprint": "牛乳から作る、パンにぬる甘くない食べ物。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52149, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バター", "is_correct": true, "explanation": "文中の語そのもの。トーストにぬって食べる食品として自然。"}, {"text": "牛乳", "is_correct": false, "explanation": "液体で、トーストにぬる食品ではないので合わない。"}, {"text": "水", "is_correct": false, "explanation": "液体で、パンにぬって食べる材料ではない。"}, {"text": "紅茶", "is_correct": false, "explanation": "飲み物で、トーストにぬることはない。"}], "explanations": {"バター": "文中の語そのもの。トーストにぬって食べる食品として自然。", "牛乳": "液体で、トーストにぬる食品ではないので合わない。", "水": "液体で、パンにぬって食べる材料ではない。", "紅茶": "飲み物で、トーストにぬることはない。"}, "sentence_index": 0, "correct_answer": "バター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バターは、かき氷にかけて食べる甘いものです。", "explanation": "ここは〈シロップ〉の使い方。バターは甘くない食品で、かき氷にかける使い方はしない。"}, {"text": "バターは、お湯に入れて、ゆでた麺を冷やします。", "explanation": "ここは〈氷〉の役割。バターは麺を冷やす材料ではなく、お湯に入れても冷えないので合わない。"}, {"text": "バターは、お湯に入れて、だしをとります。", "explanation": "ここは〈かつお節〉の使い方。バターは湯に入れてだしを取る食材ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52149, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バター", "is_correct": true, "explanation": "文中の語そのもの。焼いて作るクッキーの材料として自然。"}, {"text": "石けん", "is_correct": false, "explanation": "洗う用品で、クッキーの材料にはならない。"}, {"text": "砂利", "is_correct": false, "explanation": "石の粒で、食べ物の材料ではない。"}, {"text": "段ボール", "is_correct": false, "explanation": "紙の箱の材料で、クッキーには入らない。"}], "explanations": {"バター": "文中の語そのもの。焼いて作るクッキーの材料として自然。", "石けん": "洗う用品で、クッキーの材料にはならない。", "砂利": "石の粒で、食べ物の材料ではない。", "段ボール": "紙の箱の材料で、クッキーには入らない。"}, "sentence_index": 6, "correct_answer": "バター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バターは、熱いお湯に溶かして、ホットミルクのように飲みます。", "explanation": "ここは〈ココア〉の飲み方。バターは飲み物にする食品ではないので、この使い方は合わない。"}, {"text": "バターは、お風呂あがりに肌に塗ります。", "explanation": "ここは〈ボディクリーム〉の用途。バターは食べる食品で、肌に塗る化粧品ではない。"}, {"text": "バターは、体を温めるために飲むお茶の一種です。", "explanation": "ここは〈ほうじ茶〉の説明。バターは茶の種類ではなく、飲み物でもない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52149, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝、焼いたパンにバターにぬって食べます。", "corrected_sentence": "朝、焼いたパンにバターをぬって食べます。", "error_description": "「ぬる」の目的語は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52149, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スープにバターを溶くと、まろやかになります。", "corrected_sentence": "スープにバターを溶かすと、まろやかになります。", "error_description": "「溶く」は粉や卵を液体に混ぜる動詞で、固体のバターを溶かす場合は「溶かす」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
