INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52151, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "よい性質を持っていること。", "primary_collocate": null, "pronunciation": "りょうしつ", "ipa": "ɾʲoːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "この土地の粘土は良質で、焼き物に向いています。", "target_word": "良質", "complexity_tier": "T3", "furigana": "この土地[とち]の粘土[ねんど]は良質[りょうしつ]で、焼[や]き物[もの]に向[む]いています。", "sentence_source": "generated"}, {"text": "良質なたんぱく質は、魚や豆からとれます。", "target_word": "良質", "complexity_tier": "T3", "furigana": "良質[りょうしつ]なたんぱく質[しつ]は、魚[さかな]や豆[まめ]からとれます。", "sentence_source": "generated"}, {"text": "この石けんは良質な油から作られているので、肌にやさしいです。", "target_word": "良質", "complexity_tier": "T3", "furigana": "この石[せっ]けんは良質[りょうしつ]な油[あぶら]から作[つく]られているので、肌[はだ]にやさしいです。", "sentence_source": "generated"}, {"text": "祖父の畑には、野菜がよく育つ良質な土があります。", "target_word": "良質", "complexity_tier": "T3", "furigana": "祖父[そふ]の畑[はたけ]には、野菜[やさい]がよく育[そだ]つ良質[りょうしつ]な土[つち]があります。", "sentence_source": "generated"}, {"text": "良質な脂質をとるために、毎日ナッツを少し食べています。", "target_word": "良質", "complexity_tier": "T3", "furigana": "良質[りょうしつ]な脂質[ししつ]をとるために、毎日[まいにち]ナッツを少[すこ]し食[た]べています。", "sentence_source": "generated"}, {"text": "彼女は良質なコーヒー豆だけを選んで店に置いています。", "target_word": "良質", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は良質[りょうしつ]なコーヒー豆[まめ]だけを選[えら]んで店[みせ]に置[お]いています。", "sentence_source": "generated"}, {"text": "良質の鉄鉱石が採れるため、この町は製鉄で栄えました。", "target_word": "良質", "complexity_tier": "T4", "furigana": "良質[りょうしつ]の鉄鉱石[てっこうせき]が採[と]れるため、この町[まち]は製鉄[せいてつ]で栄[さか]えました。", "sentence_source": "generated"}, {"text": "病院は、良質な医療を受けられるように設備を整えています。", "target_word": "良質", "complexity_tier": "T4", "furigana": "病院[びょういん]は、良質[りょうしつ]な医療[いりょう]を受[う]けられるように設備[せつび]を整[ととの]えています。", "sentence_source": "generated"}, {"text": "この糸は良質で、何度洗っても傷みません。", "target_word": "良質", "complexity_tier": "T3", "furigana": "この糸[いと]は良質[りょうしつ]で、何度[なんど]洗[あら]っても傷[いた]みません。", "sentence_source": "generated"}, {"text": "良質な綿で作ったタオルは、柔らかくて水をよく吸います。", "target_word": "良質", "complexity_tier": "T3", "furigana": "良質[りょうしつ]な綿[わた]で作[つく]ったタオルは、柔[やわ]らかくて水[みず]をよく吸[す]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "良質な", "label": "連体形"}, {"form": "良質で", "label": "連用形"}, {"form": "良質だ", "label": "終止形"}, {"form": "良質の", "label": "連体形（の）"}], "register": "標準", "sense_fingerprint": "物や成分がよい性質を持っているさま。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52151, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良質", "is_correct": true, "explanation": "文中の語形。粘土の性質がよいことを表し、文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "人の気分を表す語で、粘土の性質には使わない。"}, {"text": "冷静", "is_correct": false, "explanation": "人の落ち着きを表す語で、粘土の性質には合わない。"}, {"text": "静か", "is_correct": false, "explanation": "様子を表す語だが、粘土の性質のよさは表さないので文が成り立たない。"}], "explanations": {"良質": "文中の語形。粘土の性質がよいことを表し、文脈に合う。", "陽気": "人の気分を表す語で、粘土の性質には使わない。", "冷静": "人の落ち着きを表す語で、粘土の性質には合わない。", "静か": "様子を表す語だが、粘土の性質のよさは表さないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "良質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天気は良質で、旅行にぴったりです。", "explanation": "ここは〈良好〉の意味。良質は物や材料の性質のよさを言い、天気の状態には使わない。"}, {"text": "この工場は、良質の騒音を大量に出しています。", "explanation": "ここは〈やかましい〉の意味。良質は物の性質のよさを表し、騒がしさには使わないので合わない。"}, {"text": "祖父は良質で、もう八十歳になりました。", "explanation": "ここは〈高齢〉の意味。良質は物や成分の性質に使い、人の年齢には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52151, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "良質", "is_correct": true, "explanation": "文中の語形。「の」で名詞を修飾する形として合う。"}, {"text": "無邪気", "is_correct": false, "explanation": "人の様子を表す語で、鉄鉱石には使わない。"}, {"text": "上機嫌", "is_correct": false, "explanation": "人の気分を表す語で、鉱石の性質には合わない。"}, {"text": "厳か", "is_correct": false, "explanation": "おごそかな様子を表す語で、鉱石の説明には合わない。"}], "explanations": {"良質": "文中の語形。「の」で名詞を修飾する形として合う。", "無邪気": "人の様子を表す語で、鉄鉱石には使わない。", "上機嫌": "人の気分を表す語で、鉱石の性質には合わない。", "厳か": "おごそかな様子を表す語で、鉱石の説明には合わない。"}, "sentence_index": 6, "correct_answer": "良質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鍋は良質で、一度に十人分作れます。", "explanation": "ここは〈大きい〉の意味。良質は性質のよさを表し、容量の大きさは表さないので合わない。"}, {"text": "彼は良質で、いつも遅刻ばかりします。", "explanation": "ここは〈怠惰〉の意味。良質は良い性質を表すので、遅刻ばかりの人の様子には使えない。"}, {"text": "この町は良質で、人口がとても多いです。", "explanation": "ここは〈都会〉の意味。良質は性質のよさを表し、町の規模や人の数は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52151, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布は良質を、何度洗っても傷みません。", "corrected_sentence": "この布は良質で、何度洗っても傷みません。", "error_description": "「良質」は形状詞なので、性質を述べるには「で」を使う。「を」は誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "良質な", "is_correct": true, "explanation": "後ろの名詞「たんぱく質」を修飾する連体形で、文中の形と一致する。"}, {"text": "良質さ", "is_correct": false, "explanation": "名詞を直接修飾できない形で、文が成り立たない。"}, {"text": "良質だ", "is_correct": false, "explanation": "文を言い切る終止形で、名詞の前には置けない。"}, {"text": "良質に", "is_correct": false, "explanation": "副詞的な形で、名詞を直接修飾できない。"}], "correct_form": "良質な", "base_form": "良質", "form_label": "連体形（な）", "sentence_index": 1, "explanations": {"良質な": "後ろの名詞「たんぱく質」を修飾する連体形で、文中の形と一致する。", "良質さ": "名詞を直接修飾できない形で、文が成り立たない。", "良質だ": "文を言い切る終止形で、名詞の前には置けない。", "良質に": "副詞的な形で、名詞を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52151, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この鉄は良質くて、建物に使えます。", "corrected_sentence": "この鉄は良質で、建物に使えます。", "error_description": "「良質」は形状詞なので、「くて」は付かない。正しい形は「良質で」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "良質な", "is_correct": true, "explanation": "後ろの名詞「医療」を修飾する連体形で、文中の形と一致する。"}, {"text": "良質さ", "is_correct": false, "explanation": "名詞を直接修飾できない形で、文が成り立たない。"}, {"text": "良質だろう", "is_correct": false, "explanation": "推量の形で、名詞を直接修飾する形ではない。"}, {"text": "良質だと", "is_correct": false, "explanation": "条件を表す形で、この文の名詞修飾にはならない。"}], "correct_form": "良質な", "base_form": "良質", "form_label": "連体形（な）", "sentence_index": 7, "explanations": {"良質な": "後ろの名詞「医療」を修飾する連体形で、文中の形と一致する。", "良質さ": "名詞を直接修飾できない形で、文が成り立たない。", "良質だろう": "推量の形で、名詞を直接修飾する形ではない。", "良質だと": "条件を表す形で、この文の名詞修飾にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52152, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗悪", "is_correct": true, "explanation": "「良質」の対義語で、品質が低いことを表すので、この意味の反対語として合う。"}, {"text": "豪華", "is_correct": false, "explanation": "品質の低さとは関係なく、華やかさを表す語。"}, {"text": "静か", "is_correct": false, "explanation": "品質とは無関係な様子を表す語で、反対語にはならない。"}, {"text": "陽気", "is_correct": false, "explanation": "人の気分を表す語で、品質の反対語ではない。"}], "correct_answer": "粗悪", "explanations": {"粗悪": "「良質」の対義語で、品質が低いことを表すので、この意味の反対語として合う。", "豪華": "品質の低さとは関係なく、華やかさを表す語。", "静か": "品質とは無関係な様子を表す語で、反対語にはならない。", "陽気": "人の気分を表す語で、品質の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52152, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗悪", "is_correct": true, "explanation": "品質が低いことを表し、「良質」と対になる反対語。"}, {"text": "華麗", "is_correct": false, "explanation": "華やかで美しい様子を表し、品質の反対語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "念入りなさまを表し、品質の反対語ではない。"}, {"text": "誠実", "is_correct": false, "explanation": "人柄の誠実さを表し、品質の反対語ではない。"}], "correct_answer": "粗悪", "explanations": {"粗悪": "品質が低いことを表し、「良質」と対になる反対語。", "華麗": "華やかで美しい様子を表し、品質の反対語ではない。", "丁寧": "念入りなさまを表し、品質の反対語ではない。", "誠実": "人柄の誠実さを表し、品質の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52152, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "品質がすぐれていること。また、そのさま。", "primary_collocate": null, "pronunciation": "りょうしつ", "ipa": "ɾʲoːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "まず、良質な全粒粉のパンを用意し、その多孔質な表面にピーナッツバターを均一に塗る。", "target_word": "良質", "complexity_tier": "T4", "furigana": "まず、良質[りょうしつ]な全粒粉[ぜんりゅうふん]のパンを用意[ようい]し、その多孔質[たこうしつ]な表面[ひょうめん]にピーナッツバターを均一[きんいつ]に塗[ぬ]る。", "sentence_source": "mined"}, {"text": "この店は良質な牛乳だけを使ってチーズを作っています。", "target_word": "良質", "complexity_tier": "T3", "furigana": "この店[みせ]は良質[りょうしつ]な牛乳[ぎゅうにゅう]だけを使[つか]ってチーズを作[つく]っています。", "sentence_source": "generated"}, {"text": "値段は高いですが、良質な革なので長く使えます。", "target_word": "良質", "complexity_tier": "T3", "furigana": "値段[ねだん]は高[たか]いですが、良質[りょうしつ]な革[かわ]なので長[なが]く使[つか]えます。", "sentence_source": "generated"}, {"text": "この地方は良質な水に恵まれ、おいしいお酒が作られています。", "target_word": "良質", "complexity_tier": "T3", "furigana": "この地方[ちほう]は良質[りょうしつ]な水[みず]に恵[めぐ]まれ、おいしいお酒[さけ]が作[つく]られています。", "sentence_source": "generated"}, {"text": "良質な土で育てた野菜は、味が濃くておいしいです。", "target_word": "良質", "complexity_tier": "T3", "furigana": "良質[りょうしつ]な土[つち]で育[そだ]てた野菜[やさい]は、味[あじ]が濃[こ]くておいしいです。", "sentence_source": "generated"}, {"text": "彼は良質な材料を選ぶことにこだわる職人です。", "target_word": "良質", "complexity_tier": "T3", "furigana": "彼[かれ]は良質[りょうしつ]な材料[ざいりょう]を選[えら]ぶことにこだわる職人[しょくにん]です。", "sentence_source": "generated"}, {"text": "安くても良質な商品を探すのが、私の楽しみです。", "target_word": "良質", "complexity_tier": "T3", "furigana": "安[やす]くても良質[りょうしつ]な商品[しょうひん]を探[さが]すのが、私[わたし]の楽[たの]しみです。", "sentence_source": "generated"}, {"text": "この家は良質な木材を使っているので、長持ちします。", "target_word": "良質", "complexity_tier": "T3", "furigana": "この家[いえ]は良質[りょうしつ]な木材[もくざい]を使[つか]っているので、長持[ながも]ちします。", "sentence_source": "generated"}, {"text": "この図書館には、子ども向けの良質な絵本がそろっています。", "target_word": "良質", "complexity_tier": "T3", "furigana": "この図書館[としょかん]には、子[こ]ども向[む]けの良質[りょうしつ]な絵本[えほん]がそろっています。", "sentence_source": "generated"}, {"text": "このお茶は良質で、冷めても香りが残ります。", "target_word": "良質", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]は良質[りょうしつ]で、冷[さ]めても香[かお]りが残[のこ]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "良質な", "label": "連体形"}, {"form": "良質で", "label": "連用形"}, {"form": "良質だ", "label": "終止形"}, {"form": "良質の", "label": "連体形（の）"}], "register": "標準", "sense_fingerprint": "品物や材料の品質がすぐれているさま。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52152, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良質", "is_correct": true, "explanation": "文中の語形。品質のよい全粒粉のパンを表し、文脈に合う。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな全粒粉のパン」は意味がつながらず、ここには入らない。"}, {"text": "陽気", "is_correct": false, "explanation": "人の気質を表す語で、パンの材料の説明には使わない。"}, {"text": "冷静", "is_correct": false, "explanation": "人の落ち着きを表す語で、材料の説明には合わない。"}], "explanations": {"良質": "文中の語形。品質のよい全粒粉のパンを表し、文脈に合う。", "静か": "「静かな全粒粉のパン」は意味がつながらず、ここには入らない。", "陽気": "人の気質を表す語で、パンの材料の説明には使わない。", "冷静": "人の落ち着きを表す語で、材料の説明には合わない。"}, "sentence_index": 0, "correct_answer": "良質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は良質な性格で、誰とでも仲良くなれます。", "explanation": "ここは〈よい性質〉の意味。人の性格に〈品質〉の語は使わず、物の品質の高さを表す〈良質〉としては合わない。"}, {"text": "このバッグは良質で、教科書が何冊でも入ります。", "explanation": "ここは〈容量が大きい〉の意味。良質は品質のよさを表し、入る量の多さは表さないので合わない。"}, {"text": "この家は良質で、家族全員が住めます。", "explanation": "ここは〈広い〉の意味。良質は品質を表し、広さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52152, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "良質", "is_correct": true, "explanation": "文中の語形。品質のよい商品を表し、文脈に合う。"}, {"text": "厳か", "is_correct": false, "explanation": "おごそかな様子を表し、商品の説明には合わない。"}, {"text": "上機嫌", "is_correct": false, "explanation": "人の気分を表す語で、商品には使わない。"}, {"text": "無邪気", "is_correct": false, "explanation": "人の飾らない様子を表し、商品の説明には合わない。"}], "explanations": {"良質": "文中の語形。品質のよい商品を表し、文脈に合う。", "厳か": "おごそかな様子を表し、商品の説明には合わない。", "上機嫌": "人の気分を表す語で、商品には使わない。", "無邪気": "人の飾らない様子を表し、商品の説明には合わない。"}, "sentence_index": 6, "correct_answer": "良質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は良質で、いつもテストで一番を取ります。", "explanation": "ここは〈優秀〉の意味。良質は品物の品質に使い、人の能力には使わない。"}, {"text": "この野菜は良質で、一袋に十本も入っています。", "explanation": "ここは〈たくさん〉の意味。良質は品質のよさを表し、数の多さは表さないので合わない。"}, {"text": "このブランドは良質で、来月から社長が替わります。", "explanation": "ここは〈経営〉の話。良質は商品の品質のよさを表し、会社の人事は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52152, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この果物は良質ので、味が濃いです。", "corrected_sentence": "この果物は良質なので、味が濃いです。", "error_description": "「良質」は形状詞なので、「ので」の前に「な」が必要。「良質ので」は誤りで、正しくは「良質なので」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "良質な", "is_correct": true, "explanation": "後ろの名詞「牛乳」を修飾する連体形で、文中の形と一致する。"}, {"text": "良質さ", "is_correct": false, "explanation": "名詞を直接修飾できない形で、文が成り立たない。"}, {"text": "良質だ", "is_correct": false, "explanation": "文を言い切る終止形で、名詞の前には置けない。"}, {"text": "良質に", "is_correct": false, "explanation": "副詞的な形で、名詞を直接修飾できない。"}], "correct_form": "良質な", "base_form": "良質", "form_label": "連体形（な）", "sentence_index": 1, "explanations": {"良質な": "後ろの名詞「牛乳」を修飾する連体形で、文中の形と一致する。", "良質さ": "名詞を直接修飾できない形で、文が成り立たない。", "良質だ": "文を言い切る終止形で、名詞の前には置けない。", "良質に": "副詞的な形で、名詞を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52152, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は年々、商品が良質くなっています。", "corrected_sentence": "この店は年々、商品が良質になっています。", "error_description": "「良質」は形状詞なので、変化を表すには「になる」を使う。「良質くなる」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "良質な", "is_correct": true, "explanation": "後ろの名詞「木材」を修飾する連体形で、文中の形と一致する。"}, {"text": "良質さ", "is_correct": false, "explanation": "名詞を直接修飾できない形で、文が成り立たない。"}, {"text": "良質だろう", "is_correct": false, "explanation": "推量の形で、名詞を直接修飾する形ではない。"}, {"text": "良質だと", "is_correct": false, "explanation": "条件を表す形で、この文の名詞修飾にはならない。"}], "correct_form": "良質な", "base_form": "良質", "form_label": "連体形（な）", "sentence_index": 7, "explanations": {"良質な": "後ろの名詞「木材」を修飾する連体形で、文中の形と一致する。", "良質さ": "名詞を直接修飾できない形で、文が成り立たない。", "良質だろう": "推量の形で、名詞を直接修飾する形ではない。", "良質だと": "条件を表す形で、この文の名詞修飾にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52153, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「全粒の小麦」で、小麦の種類を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示す。「全粒を小麦で作られている」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を表す。「全粒に小麦で作られている」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「全粒が小麦で作られている」は主語にできない。"}], "correct_answer": "の", "explanations": {"の": "「全粒の小麦」で、小麦の種類を表す。", "を": "「を」は対象を示す。「全粒を小麦で作られている」では文が成り立たない。", "に": "「に」は位置や相手を表す。「全粒に小麦で作られている」は不自然。", "が": "「が」は主語を示す。「全粒が小麦で作られている」は主語にできない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52153, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「全粒の生地」で、生地の材料を表す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を表す。「全粒で生地で」では名詞がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「全粒へ生地で」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「全粒から生地で」では材料の関係にならない。"}], "correct_answer": "の", "explanations": {"の": "「全粒の生地」で、生地の材料を表す。", "で": "「で」は場所・手段を表す。「全粒で生地で」では名詞がつながらない。", "へ": "「へ」は方向を表す。「全粒へ生地で」では意味が通らない。", "から": "「から」は起点を表す。「全粒から生地で」では材料の関係にならない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52153, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小麦などの穀物を、精製せず皮や胚芽ごと全部使ったものです。", "primary_collocate": null, "pronunciation": "ぜんりゅう", "ipa": "dzenɾʲɯː", "syllable_count": 4, "sentences": [{"text": "朝食には、全粒のパンを食べるようにしている。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "朝食[ちょうしょく]には、全粒[ぜんりゅう]のパンを食[た]べるようにしている。", "sentence_source": "generated"}, {"text": "このクッキーは全粒の小麦で作られている。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "このクッキーは全粒[ぜんりゅう]の小麦[こむぎ]で作[つく]られている。", "sentence_source": "generated"}, {"text": "全粒の食品は、体によいと言われている。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "全粒[ぜんりゅう]の食品[しょくひん]は、体[からだ]によいと言[い]われている。", "sentence_source": "generated"}, {"text": "白い小麦より、全粒のほうが皮ごと使うので色が濃い。", "target_word": "全粒", "complexity_tier": "T4", "furigana": "白[しろ]い小麦[こむぎ]より、全粒[ぜんりゅう]のほうが皮[かわ]ごと使[つか]うので色[いろ]が濃[こ]い。", "sentence_source": "generated"}, {"text": "母は全粒のマフィンを焼くのが得意だ。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "母[はは]は全粒[ぜんりゅう]のマフィンを焼[や]くのが得意[とくい]だ。", "sentence_source": "generated"}, {"text": "全粒のクラッカーに、チーズをのせて食べた。", "target_word": "全粒", "complexity_tier": "T2", "furigana": "全粒[ぜんりゅう]のクラッカーに、チーズをのせて食[た]べた。", "sentence_source": "generated"}, {"text": "全粒の香ばしさが好きで、いつもこのパンを選ぶ。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "全粒[ぜんりゅう]の香[こう]ばしさが好[す]きで、いつもこのパンを選[えら]ぶ。", "sentence_source": "generated"}, {"text": "この店では、全粒の生地でピザを焼いている。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "この店[みせ]では、全粒[ぜんりゅう]の生地[きじ]でピザを焼[や]いている。", "sentence_source": "generated"}, {"text": "全粒のものは、白いものよりかたい。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "全粒[ぜんりゅう]のものは、白[しろ]いものよりかたい。", "sentence_source": "generated"}, {"text": "袋の表示を見ると、全粒と書かれていた。", "target_word": "全粒", "complexity_tier": "T3", "furigana": "袋[ふくろ]の表示[ひょうじ]を見[み]ると、全粒[ぜんりゅう]と書[か]かれていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全粒", "label": "基本形"}, {"form": "全粒の", "label": "連体形(の)"}], "register": "標準(食品・料理の場面)", "sense_fingerprint": "名詞。小麦などの穀物を、皮や胚芽ごと丸ごと使ったもの。パンや菓子の材料の種類を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2e49d9-d05c-48df-bf87-1feefd7e577a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52153, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全粒", "is_correct": true, "explanation": "「全粒のパン」で、皮や胚芽ごと使った穀物のパンを表す。"}, {"text": "陶器", "is_correct": false, "explanation": "陶器は焼き物で、パンの種類を表す語ではない。"}, {"text": "電気", "is_correct": false, "explanation": "電気はエネルギーのことで、パンの種類としては合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は送付のことで、パンの種類には使わない。"}], "explanations": {"全粒": "「全粒のパン」で、皮や胚芽ごと使った穀物のパンを表す。", "陶器": "陶器は焼き物で、パンの種類を表す語ではない。", "電気": "電気はエネルギーのことで、パンの種類としては合わない。", "郵便": "郵便は送付のことで、パンの種類には使わない。"}, "sentence_index": 0, "correct_answer": "全粒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最後まで全粒で走った。", "explanation": "全粒は穀物の種類を表す語で、走る様子の「全力」の意味は持たない。"}, {"text": "宿題は全粒終わった。", "explanation": "全粒は穀物の種類を表す語で、「全部」の意味は持たない。宿題の完了には使えない。"}, {"text": "魚を全粒焼いた。", "explanation": "全粒は穀物の種類を表す語で、「丸ごと」の意味では使わない。魚には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52153, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全粒", "is_correct": true, "explanation": "「全粒の香ばしさ」で、穀物の皮ごと使ったことによる香りを表す。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は金属で、香ばしさを表す語ではない。"}, {"text": "化学", "is_correct": false, "explanation": "化学は学問や物質の分野で、香ばしさの修飾には合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は衣類で、香ばしさの修飾には合わない。"}], "explanations": {"全粒": "「全粒の香ばしさ」で、穀物の皮ごと使ったことによる香りを表す。", "鉄": "鉄は金属で、香ばしさを表す語ではない。", "化学": "化学は学問や物質の分野で、香ばしさの修飾には合わない。", "靴下": "靴下は衣類で、香ばしさの修飾には合わない。"}, "sentence_index": 6, "correct_answer": "全粒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全粒の高校生が、大会に集まった。", "explanation": "全粒は穀物の種類を表す語で、「全国」の意味は持たない。人の範囲には使えない。"}, {"text": "会費は全粒返金された。", "explanation": "全粒は穀物の種類を表す語で、「全額」の意味は持たない。お金の話には使えない。"}, {"text": "この壁は全粒に塗り直した。", "explanation": "全粒は穀物の種類を表す語で、「全面」の意味は持たない。壁の話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52153, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店では、全粒なパンだけを作っている。", "corrected_sentence": "この店では、全粒のパンだけを作っている。", "error_description": "「全粒」は名詞なので、名詞修飾は「の」。「な」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52153, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店のパンには全粒が使っている。", "corrected_sentence": "この店のパンには全粒を使っている。", "error_description": "「使う」は「〜を使う」で、対象は「を」。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e11801dd-3092-4917-bd6a-8ec226e0a4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52157, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「用意をする」の形で、用意という行為の対象を示す。「用意をしました」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "帰着や相手を示す助詞。「用意にしました」とは言えず、ここには入らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞。「用意でしました」は成り立たず、ここには入らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「用意がしました」では文が成り立たず、ここには入らない。"}], "correct_answer": "を", "explanations": {"を": "「用意をする」の形で、用意という行為の対象を示す。「用意をしました」で正しい。", "に": "帰着や相手を示す助詞。「用意にしました」とは言えず、ここには入らない。", "で": "手段や場所を示す助詞。「用意でしました」は成り立たず、ここには入らない。", "が": "主語を示す助詞。「用意がしました」では文が成り立たず、ここには入らない。"}, "error_tags": {"に": "帰着・相手", "で": "手段・場所", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52157, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「プレゼントを用意する」と、用意の対象を示す「を」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示す「で」は、用意の対象にはならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、プレゼントを何かと比べる文脈がないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は、用意の対象を並べる文脈がないので不自然。"}], "correct_answer": "を", "explanations": {"を": "「プレゼントを用意する」と、用意の対象を示す「を」が正しい。", "で": "手段・場所を示す「で」は、用意の対象にはならないので合わない。", "より": "比較の「より」は、プレゼントを何かと比べる文脈がないので合わない。", "と": "並列の「と」は、用意の対象を並べる文脈がないので不自然。"}, "error_tags": {"で": "手段・場所", "より": "比較", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52157, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをする前に、そのために必要なものをそろえること。", "primary_collocate": null, "pronunciation": "ようい", "ipa": "joːi", "syllable_count": 3, "sentences": [{"text": "朝ごはんの用意は、いつも父がしてくれます。", "target_word": "用意", "complexity_tier": "T2", "furigana": "朝[あさ]ごはんの用意[ようい]は、いつも父[ちち]がしてくれます。", "sentence_source": "generated"}, {"text": "遠足の前の日に、お弁当の用意をしました。", "target_word": "用意", "complexity_tier": "T2", "furigana": "遠足[えんそく]の前[まえ]の日[ひ]に、お弁当[べんとう]の用意[ようい]をしました。", "sentence_source": "generated"}, {"text": "台風が来る前に、食べ物と水を用意しておきましょう。", "target_word": "用意", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る前[まえ]に、食[た]べ物[もの]と水[みず]を用意[ようい]しておきましょう。", "sentence_source": "generated"}, {"text": "授業で使う道具を用意して、教室に集まってください。", "target_word": "用意", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で使[つか]う道具[どうぐ]を用意[ようい]して、教室[きょうしつ]に集[あつ]まってください。", "sentence_source": "generated"}, {"text": "食事の用意ができたので、手を洗ってきてください。", "target_word": "用意", "complexity_tier": "T2", "furigana": "食事[しょくじ]の用意[ようい]ができたので、手[て]を洗[あら]ってきてください。", "sentence_source": "generated"}, {"text": "出かける用意に時間がかかって、電車に乗り遅れました。", "target_word": "用意", "complexity_tier": "T3", "furigana": "出[で]かける用意[ようい]に時間[じかん]がかかって、電車[でんしゃ]に乗[の]り遅[おく]れました。", "sentence_source": "generated"}, {"text": "寒い冬に備えて、毛布を用意しました。", "target_word": "用意", "complexity_tier": "T3", "furigana": "寒[さむ]い冬[ふゆ]に備[そな]えて、毛布[もうふ]を用意[ようい]しました。", "sentence_source": "generated"}, {"text": "友だちの誕生日に、プレゼントを用意しました。", "target_word": "用意", "complexity_tier": "T2", "furigana": "友[とも]だちの誕生日[たんじょうび]に、プレゼントを用意[ようい]しました。", "sentence_source": "generated"}, {"text": "先生は黒板の前に、実験に使う薬品を用意していました。", "target_word": "用意", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]の前[まえ]に、実験[じっけん]に使[つか]う薬品[やくひん]を用意[ようい]していました。", "sentence_source": "generated"}, {"text": "雨の日のために、着替えを用意しておくと安心です。", "target_word": "用意", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]のために、着替[きが]えを用意[ようい]しておくと安心[あんしん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "用意する", "label": "終止形"}, {"form": "用意した", "label": "過去形"}, {"form": "用意して", "label": "て形"}, {"form": "用意しない", "label": "否定形"}, {"form": "用意し", "label": "連用形"}], "register": "polite", "sense_fingerprint": "何かをする前に、必要なものをそろえておくこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52157, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用意", "is_correct": true, "explanation": "「朝ごはんの用意」は食事をそろえる準備を指し、文の主語として自然。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は気持ちを伝えることで、朝ごはんを対象にする文には合わない。"}, {"text": "練習", "is_correct": false, "explanation": "練習は繰り返して身につけることで、朝ごはんの準備を指さない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩いて楽しむことで、朝ごはんの準備には合わない。"}], "explanations": {"用意": "「朝ごはんの用意」は食事をそろえる準備を指し、文の主語として自然。", "感謝": "感謝は気持ちを伝えることで、朝ごはんを対象にする文には合わない。", "練習": "練習は繰り返して身につけることで、朝ごはんの準備を指さない。", "散歩": "散歩は歩いて楽しむことで、朝ごはんの準備には合わない。"}, "sentence_index": 0, "correct_answer": "用意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "授業中は、先生の話を用意して聞きましょう。", "explanation": "ここは〈注意〉の意味。用意は必要なものをそろえることで、気をつけて聞く態度を表さないので合わない。"}, {"text": "うるさい音を用意して、勉強を続けた。", "explanation": "ここは〈無視〉の意味。用意は必要なものをそろえることで、音を気にしないという意味にはならないので合わない。"}, {"text": "能力を用意して、試合に勝った。", "explanation": "ここは〈発揮〉の意味。用意は準備することで、持っている力を出し切る意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52157, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用意", "is_correct": true, "explanation": "「毛布を用意しました」は、冬に備えて必要なものをそろえる意味で自然。"}, {"text": "相談", "is_correct": false, "explanation": "相談は話し合うことで、毛布を対象にすると意味をなさない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は気持ちを伝えることで、物を対象にする文には合わない。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は言葉や動作で礼を示すことで、毛布には合わない。"}], "explanations": {"用意": "「毛布を用意しました」は、冬に備えて必要なものをそろえる意味で自然。", "相談": "相談は話し合うことで、毛布を対象にすると意味をなさない。", "感謝": "感謝は気持ちを伝えることで、物を対象にする文には合わない。", "挨拶": "挨拶は言葉や動作で礼を示すことで、毛布には合わない。"}, "sentence_index": 6, "correct_answer": "用意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の誠意を用意するのは失礼だ。", "explanation": "ここは〈疑う〉の意味。用意は必要なものをそろえることで、相手を信じない意味にはならないので合わない。"}, {"text": "彼は無実を用意するために、裁判で証言した。", "explanation": "ここは〈証明〉の意味。用意は必要なものを整えることで、正しさを示す意味にはならないので合わない。"}, {"text": "ぐっすり眠って、悩みを用意した。", "explanation": "ここは〈解消〉の意味。用意は必要なものをそろえることで、悩みをなくす意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52157, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遠足の前の日に、お菓子に用意をしました。", "corrected_sentence": "遠足の前の日に、お菓子の用意をしました。", "error_description": "「用意」は「〜の用意」の形で名詞に続ける。「お菓子に用意」の「に」が誤りで、正しくは「お菓子の用意をしました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52157, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日の遠足のために、水筒を用意です。", "corrected_sentence": "明日の遠足のために、水筒を用意しました。", "error_description": "「用意です」は名詞に「です」をつけた形で、動詞の文として成り立たない。正しくは「用意しました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52158, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「資料を用意する」と、用意の対象を示す「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "用意の対象は「を」で示すので、「資料に用意」は不自然で合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、用意の対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、資料を何かと比べる文脈がないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「資料を用意する」と、用意の対象を示す「を」が正しい。", "に": "用意の対象は「を」で示すので、「資料に用意」は不自然で合わない。", "へ": "方向を表す「へ」は、用意の対象を示せないので合わない。", "より": "比較の「より」は、資料を何かと比べる文脈がないので合わない。"}, "error_tags": {"に": "格の誤り", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52158, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「運動会の用意」の「の」は、運動会と用意を結ぶ正しい連体修飾。"}, {"text": "が", "is_correct": false, "explanation": "「運動会が」は主語になり、用意の名詞をつなぐ形には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「運動会に用意」は、用意の範囲を示す「に」が不自然で合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、運動会と比べる文脈がないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「運動会の用意」の「の」は、運動会と用意を結ぶ正しい連体修飾。", "が": "「運動会が」は主語になり、用意の名詞をつなぐ形には合わない。", "に": "「運動会に用意」は、用意の範囲を示す「に」が不自然で合わない。", "より": "比較の「より」は、運動会と比べる文脈がないので合わない。"}, "error_tags": {"が": "主語", "に": "時点・対象", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52158, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある目的のために、必要なものや状態を整えて準備すること。", "primary_collocate": null, "pronunciation": "ようい", "ipa": "joːi", "syllable_count": 3, "sentences": [{"text": "まず、良質な全粒粉のパンを用意し、その多孔質な表面にピーナッツバターを均一に塗る。", "target_word": "用意", "complexity_tier": "T4", "furigana": "まず、良質[りょうしつ]な全粒粉[ぜんりゅうふん]のパンを用意[ようい]し、その多孔質[たこうしつ]な表面[ひょうめん]にピーナッツバターを均一[きんいつ]に塗[ぬ]る。", "sentence_source": "mined"}, {"text": "来週の会議のために、資料を用意しておきます。", "target_word": "用意", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の会議[かいぎ]のために、資料[しりょう]を用意[ようい]しておきます。", "sentence_source": "generated"}, {"text": "夕食は私が用意しますので、ゆっくり休んでください。", "target_word": "用意", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]は私[わたし]が用意[ようい]しますので、ゆっくり休[やす]んでください。", "sentence_source": "generated"}, {"text": "雨が降りそうだったので、かさを用意して出かけました。", "target_word": "用意", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]りそうだったので、かさを用意[ようい]して出[で]かけました。", "sentence_source": "generated"}, {"text": "旅行の前に、パスポートの用意はもう済みましたか。", "target_word": "用意", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に、パスポートの用意[ようい]はもう済[す]みましたか。", "sentence_source": "generated"}, {"text": "お客さんが来る前に、お茶とお菓子を用意しました。", "target_word": "用意", "complexity_tier": "T3", "furigana": "お客[きゃく]さんが来[く]る前[まえ]に、お茶[ちゃ]とお菓子[かし]を用意[ようい]しました。", "sentence_source": "generated"}, {"text": "試験の日までに、必要な書類を用意してください。", "target_word": "用意", "complexity_tier": "T3", "furigana": "試験[しけん]の日[ひ]までに、必要[ひつよう]な書類[しょるい]を用意[ようい]してください。", "sentence_source": "generated"}, {"text": "運動会の用意で、先生たちは朝から忙しそうです。", "target_word": "用意", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の用意[ようい]で、先生[せんせい]たちは朝[あさ]から忙[いそが]しそうです。", "sentence_source": "generated"}, {"text": "パーティーの用意ができたら、みんなを呼びます。", "target_word": "用意", "complexity_tier": "T3", "furigana": "パーティーの用意[ようい]ができたら、みんなを呼[よ]びます。", "sentence_source": "generated"}, {"text": "彼は急な来客にも、すぐに座布団を用意してくれました。", "target_word": "用意", "complexity_tier": "T3", "furigana": "彼[かれ]は急[きゅう]な来客[らいきゃく]にも、すぐに座布団[ざぶとん]を用意[ようい]してくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "用意する", "label": "終止形"}, {"form": "用意した", "label": "過去形"}, {"form": "用意して", "label": "て形"}, {"form": "用意しない", "label": "否定形"}, {"form": "用意し", "label": "連用形"}], "register": "polite", "sense_fingerprint": "目的のために必要なものや状態をあらかじめ整えること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 全粒粉 (Zipf 2.32), 多孔 (Zipf 2.46)']::text[], 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52158, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用意", "is_correct": true, "explanation": "「パンを用意し」は、材料をそろえるという意味で文が成り立つ。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は場所や物をきれいにすることで、材料をそろえる文脈には合わない。"}, {"text": "相談", "is_correct": false, "explanation": "相談は話し合うことで、「パンを相談し」は意味をなさない。"}, {"text": "報告", "is_correct": false, "explanation": "報告は知らせることで、材料を対象とする文脈には合わない。"}], "explanations": {"用意": "「パンを用意し」は、材料をそろえるという意味で文が成り立つ。", "掃除": "掃除は場所や物をきれいにすることで、材料をそろえる文脈には合わない。", "相談": "相談は話し合うことで、「パンを相談し」は意味をなさない。", "報告": "報告は知らせることで、材料を対象とする文脈には合わない。"}, "sentence_index": 0, "correct_answer": "用意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "道路を渡るときは、用意して左右をよく確かめてください。", "explanation": "ここは〈注意〉の意味。用意は必要なものをそろえることで、気をつける意味にはならないので合わない。"}, {"text": "お客さんの体調を用意して、温かい飲み物を出した。", "explanation": "ここは〈配慮〉の意味。用意は物をそろえることで、相手の状態を気づかう意味には使えないので合わない。"}, {"text": "鍵がかかっているかどうか、出かける前に用意してください。", "explanation": "ここは〈確認〉の意味。用意は準備することで、かかっているかを調べる意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52158, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用意", "is_correct": true, "explanation": "「必要な書類を用意してください」は、必要なものをそろえる意味で自然に成り立つ。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は気持ちを伝えることで、書類を対象にすると意味をなさない。"}, {"text": "練習", "is_correct": false, "explanation": "練習は繰り返して身につけることで、書類を対象にする文には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩いて楽しむことで、書類には当てはまらない。"}], "explanations": {"用意": "「必要な書類を用意してください」は、必要なものをそろえる意味で自然に成り立つ。", "感謝": "感謝は気持ちを伝えることで、書類を対象にすると意味をなさない。", "練習": "練習は繰り返して身につけることで、書類を対象にする文には合わない。", "散歩": "散歩は歩いて楽しむことで、書類には当てはまらない。"}, "sentence_index": 6, "correct_answer": "用意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の言葉の意味を、もう一度用意してみた。", "explanation": "ここは〈解釈〉の意味。用意は必要なものをそろえることで、言葉の意味を読み取る意味にはならないので合わない。"}, {"text": "失敗の原因を、みんなで用意した。", "explanation": "ここは〈反省〉の意味。用意は準備することで、失敗をふり返る意味にはならないので合わない。"}, {"text": "研究者が新しい星を用意した。", "explanation": "ここは〈発見〉の意味。用意は必要なものを整えることで、まだ見つかっていないものを見つける意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
