INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52159, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンとパンのあいだに、たべものをはさんだものです。", "primary_collocate": null, "pronunciation": "さんどいっち", "ipa": "sandoitt͡ɕi", "syllable_count": 6, "sentences": [{"text": "朝ごはんに、たまごのサンドイッチを食べました。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに、たまごのサンドイッチを食[た]べました。", "sentence_source": "generated"}, {"text": "私はハムとチーズのサンドイッチが好きです。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "私[わたし]はハムとチーズのサンドイッチが好[す]きです。", "sentence_source": "generated"}, {"text": "遠足で、友だちとサンドイッチを分けて食べました。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "遠足[えんそく]で、友[とも]だちとサンドイッチを分[わ]けて食[た]べました。", "sentence_source": "generated"}, {"text": "お母さんがサンドイッチを作って、かばんに入れてくれました。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "お母[かあ]さんがサンドイッチを作[つく]って、かばんに入[い]れてくれました。", "sentence_source": "generated"}, {"text": "駅の近くの店で、サンドイッチを二つ買いました。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くの店[みせ]で、サンドイッチを二[ふた]つ買[か]いました。", "sentence_source": "generated"}, {"text": "パンが足りなかったので、サンドイッチは三つしか作れませんでした。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "パンが足[た]りなかったので、サンドイッチは三[みっ]つしか作[つく]れませんでした。", "sentence_source": "generated"}, {"text": "公園で、サンドイッチを食べながら本を読みました。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "公園[こうえん]で、サンドイッチを食[た]べながら本[ほん]を読[よ]みました。", "sentence_source": "generated"}, {"text": "このサンドイッチは野菜がたくさん入っていて、おいしいです。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "このサンドイッチは野菜[やさい]がたくさん入[はい]っていて、おいしいです。", "sentence_source": "generated"}, {"text": "妹はきゅうりが嫌いなので、サンドイッチには入れません。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "妹[いもうと]はきゅうりが嫌[きら]いなので、サンドイッチには入[い]れません。", "sentence_source": "generated"}, {"text": "昼ごはんは、サンドイッチと牛乳にしました。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんは、サンドイッチと牛乳[ぎゅうにゅう]にしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サンドイッチ", "label": "基本形"}], "register": "polite", "sense_fingerprint": "パンの間に食べ物をはさんだ食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52159, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サンドイッチ", "is_correct": true, "explanation": "「たまごのサンドイッチ」は、卵をはさんだ食べ物として食べられる。"}, {"text": "ノート", "is_correct": false, "explanation": "ノートは文房具で、たまごの料理として食べられない。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは食べられない素材で、たまごの料理とは合わない。"}, {"text": "ゴム", "is_correct": false, "explanation": "ゴムは食べられない素材で、食べる対象に合わない。"}], "explanations": {"サンドイッチ": "「たまごのサンドイッチ」は、卵をはさんだ食べ物として食べられる。", "ノート": "ノートは文房具で、たまごの料理として食べられない。", "ガラス": "ガラスは食べられない素材で、たまごの料理とは合わない。", "ゴム": "ゴムは食べられない素材で、食べる対象に合わない。"}, "sentence_index": 0, "correct_answer": "サンドイッチ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "停電に備えて、サンドイッチに火をつけました。", "explanation": "ここは〈ろうそく〉の意味。サンドイッチは火をつけるものではないので、火をつけるとは言えない。"}, {"text": "夏の夜、冷えたサンドイッチを一気に飲みました。", "explanation": "ここは〈ビール〉の意味。サンドイッチは飲み物ではないので、飲むとは言えない。"}, {"text": "夕方、サンドイッチをさばいて、刺身にしました。", "explanation": "ここは〈魚〉の意味。サンドイッチはさばく対象ではなく、刺身にもできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52159, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サンドイッチ", "is_correct": true, "explanation": "「サンドイッチを食べながら本を読みました」は、食べ物を食べつつ読書をする文として自然。"}, {"text": "定規", "is_correct": false, "explanation": "定規は文房具で、食べながら本を読む文の対象にならない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは文房具で、食べる対象ではない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤は食べるものではないので、食べながら本を読む文に合わない。"}], "explanations": {"サンドイッチ": "「サンドイッチを食べながら本を読みました」は、食べ物を食べつつ読書をする文として自然。", "定規": "定規は文房具で、食べながら本を読む文の対象にならない。", "消しゴム": "消しゴムは文房具で、食べる対象ではない。", "洗剤": "洗剤は食べるものではないので、食べながら本を読む文に合わない。"}, "sentence_index": 6, "correct_answer": "サンドイッチ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝、サンドイッチを研ぎました。", "explanation": "ここは〈お米〉の意味。サンドイッチは米のように研ぐものではないので合わない。"}, {"text": "朝、サンドイッチにお湯を注ぎました。", "explanation": "ここは〈カップ麺〉の意味。サンドイッチはお湯を注いで戻す食べ物ではないので、注ぐとは言えない。"}, {"text": "鍋でサンドイッチを茹でました。", "explanation": "ここは〈スパゲッティ〉の意味。サンドイッチは茹でる料理ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52159, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は、サンドイッチを好きです。", "corrected_sentence": "私は、サンドイッチが好きです。", "error_description": "「好き」は対象を「が」で示す。「サンドイッチを好きです」の「を」が誤りで、正しくは「サンドイッチが好きです」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52159, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝ごはんに、サンドイッチを三本食べました。", "corrected_sentence": "朝ごはんに、サンドイッチを三つ食べました。", "error_description": "サンドイッチは「〜つ」で数える。「三本」は細長い物を数える助数詞なので誤り。正しくは「三つ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52160, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「サンドイッチを食べる」の「を」は、食べる対象を示す正しい形。"}, {"text": "に", "is_correct": false, "explanation": "食べる対象は「を」で示すので、「に」を使うと対象として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、食べる対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、食べる対象を示す文脈がないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「サンドイッチを食べる」の「を」は、食べる対象を示す正しい形。", "に": "食べる対象は「を」で示すので、「に」を使うと対象として不自然。", "へ": "方向を表す「へ」は、食べる対象を示せないので合わない。", "より": "比較の「より」は、食べる対象を示す文脈がないので合わない。"}, "error_tags": {"に": "格の誤り", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52160, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「サンドイッチにも」の「に」は、「にも」として自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」は、トマトを入れないでほしいという文の対象として合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だと「サンドイッチをも」となり、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞をつなぐ働きで、ここでは続かない。"}], "correct_answer": "に", "explanations": {"に": "「サンドイッチにも」の「に」は、「にも」として自然に続く。", "が": "主語の「が」は、トマトを入れないでほしいという文の対象として合わない。", "を": "目的語の「を」だと「サンドイッチをも」となり、文の意味が通らない。", "の": "連体の「の」は名詞をつなぐ働きで、ここでは続かない。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52160, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンに肉や野菜、ジャムなどを挟んだ食べ物。昼食などに食べられる。", "primary_collocate": null, "pronunciation": "さんどいっち", "ipa": "sandoitt͡ɕi", "syllable_count": 6, "sentences": [{"text": "ピーナッツバターとジャムを挟んだサンドイッチは、子どもにも人気がある。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "ピーナッツバターとジャムを挟[はさ]んだサンドイッチは、子[こ]どもにも人気[にんき]がある。", "sentence_source": "generated"}, {"text": "昼ご飯は時間がなかったので、コンビニで買ったサンドイッチを歩きながら食べた。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "昼[ひる]ご飯[はん]は時間[じかん]がなかったので、コンビニで買[か]ったサンドイッチを歩[ある]きながら食[た]べた。", "sentence_source": "generated"}, {"text": "母は毎朝、ハムとレタスを挟んだサンドイッチを作ってくれる。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、ハムとレタスを挟[はさ]んだサンドイッチを作[つく]ってくれる。", "sentence_source": "generated"}, {"text": "遠足のお弁当には、おにぎりではなくサンドイッチを持っていった。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "遠足[えんそく]のお弁当[べんとう]には、おにぎりではなくサンドイッチを持[も]っていった。", "sentence_source": "generated"}, {"text": "このカフェのサンドイッチは、卵がたっぷり入っていて人気がある。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "このカフェのサンドイッチは、卵[たまご]がたっぷり入[はい]っていて人気[にんき]がある。", "sentence_source": "generated"}, {"text": "パンにジャムを塗って挟めば、簡単にサンドイッチができる。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "パンにジャムを塗[ぬ]って挟[はさ]めば、簡単[かんたん]にサンドイッチができる。", "sentence_source": "generated"}, {"text": "公園のベンチでサンドイッチを食べていたら、鳩が集まってきた。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "公園[こうえん]のベンチでサンドイッチを食[た]べていたら、鳩[はと]が集[あつ]まってきた。", "sentence_source": "generated"}, {"text": "彼は野菜が苦手なので、サンドイッチにもトマトを入れないでほしいと頼んだ。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "彼[かれ]は野菜[やさい]が苦手[にがて]なので、サンドイッチにもトマトを入[い]れないでほしいと頼[たの]んだ。", "sentence_source": "generated"}, {"text": "会議の合間に、サンドイッチとコーヒーで軽く昼食を済ませた。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "会議[かいぎ]の合間[あいま]に、サンドイッチとコーヒーで軽[かる]く昼食[ちゅうしょく]を済[す]ませた。", "sentence_source": "generated"}, {"text": "具が多すぎて、サンドイッチを一口で食べられなかった。", "target_word": "サンドイッチ", "complexity_tier": "T3", "furigana": "具[ぐ]が多[おお]すぎて、サンドイッチを一口[ひとくち]で食[た]べられなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サンドイッチ", "label": "基本形"}], "register": "plain", "sense_fingerprint": "パンに具を挟んだ軽食（昼食などの食べ物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52160, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サンドイッチ", "is_correct": true, "explanation": "掛け合わせた食べ物として、パンに具を挟んだサンドイッチが自然に入る。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、食べ物の構築の対象にはならない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は雨具で、食べ物を掛け合わせる文脈には合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は本で、食べ物の一種ではないので合わない。"}], "explanations": {"サンドイッチ": "掛け合わせた食べ物として、パンに具を挟んだサンドイッチが自然に入る。", "机": "机は家具で、食べ物の構築の対象にはならない。", "傘": "傘は雨具で、食べ物を掛け合わせる文脈には合わない。", "辞書": "辞書は本で、食べ物の一種ではないので合わない。"}, "sentence_index": 0, "correct_answer": "サンドイッチ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布を忘れたので、サンドイッチで会計を済ませた。", "explanation": "ここは〈お金〉の意味。サンドイッチは支払いに使えるものではないので、会計を済ませるとは言えない。"}, {"text": "朝、髪をサンドイッチにして結んだ。", "explanation": "ここは〈まとめる〉の意味。サンドイッチは髪をまとめる言葉の使い方ではないので合わない。"}, {"text": "喉が渇いたので、冷たいサンドイッチを飲んだ。", "explanation": "ここは〈ジュース〉の意味。サンドイッチは飲み物ではないので、飲むとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52160, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サンドイッチ", "is_correct": true, "explanation": "「サンドイッチを食べていた」は、食べ物として自然に成り立つ。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は文房具で、公園のベンチで食べる対象にはならない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは文房具で、食べる対象ではないので合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は洗うための物で、食べていたら鳩が集まる文脈に合わない。"}], "explanations": {"サンドイッチ": "「サンドイッチを食べていた」は、食べ物として自然に成り立つ。", "鉛筆": "鉛筆は文房具で、公園のベンチで食べる対象にはならない。", "消しゴム": "消しゴムは文房具で、食べる対象ではないので合わない。", "石鹸": "石鹸は洗うための物で、食べていたら鳩が集まる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "サンドイッチ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝は、サンドイッチをよくかき混ぜてから食べる。", "explanation": "ここは〈納豆〉の意味。サンドイッチはかき混ぜてから食べる料理ではないので合わない。"}, {"text": "鍋でサンドイッチを煮込んだ。", "explanation": "ここは〈カレー〉の意味。サンドイッチは煮込む料理ではないので、鍋で煮込むとは言えない。"}, {"text": "朝ごはんに、サンドイッチを炊いた。", "explanation": "ここは〈ご飯〉の意味。サンドイッチは炊く料理ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52160, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園のベンチで、サンドイッチに食べた。", "corrected_sentence": "公園のベンチで、サンドイッチを食べた。", "error_description": "「食べる」は目的語に「を」を取る。「サンドイッチに食べた」の「に」が誤りで、正しくは「サンドイッチを食べた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52160, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠足のために、サンドイッチを四本作った。", "corrected_sentence": "遠足のために、サンドイッチを四つ作った。", "error_description": "サンドイッチは「〜つ」で数える。「四本」は細長い物を数える助数詞なので誤り。正しくは「四つ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
