INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52161, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "たくさんの小さなあながあること。", "primary_collocate": null, "pronunciation": "たこう", "ipa": "takoː", "syllable_count": 3, "sentences": [{"text": "このスポンジは多孔なので、水をよく吸います。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "このスポンジは多孔[たこう]なので、水[みず]をよく吸[す]います。", "sentence_source": "generated"}, {"text": "軽石は多孔で、水に浮かびます。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "軽石[かるいし]は多孔[たこう]で、水[みず]に浮[う]かびます。", "sentence_source": "generated"}, {"text": "パンの中は多孔で、小さな穴がたくさんあります。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "パンの中[なか]は多孔[たこう]で、小[ちい]さな穴[あな]がたくさんあります。", "sentence_source": "generated"}, {"text": "多孔な石は軽いので、持ち運びが楽です。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "多孔[たこう]な石[いし]は軽[かる]いので、持[も]ち運[はこ]びが楽[らく]です。", "sentence_source": "generated"}, {"text": "この板は多孔ではないので、水がしみ込みません。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "この板[いた]は多孔[たこう]ではないので、水[みず]がしみ込[こ]みません。", "sentence_source": "generated"}, {"text": "炭は多孔なので、においをとってくれます。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "炭[すみ]は多孔[たこう]なので、においをとってくれます。", "sentence_source": "generated"}, {"text": "多孔な材料は、空気をたくさん含んでいます。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "多孔[たこう]な材料[ざいりょう]は、空気[くうき]をたくさん含[ふく]んでいます。", "sentence_source": "generated"}, {"text": "顕微鏡で見ると、この骨は多孔になっていました。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で見[み]ると、この骨[ほね]は多孔[たこう]になっていました。", "sentence_source": "generated"}, {"text": "多孔な素材は、音を吸うので静かになります。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "多孔[たこう]な素材[そざい]は、音[おと]を吸[す]うので静[しず]かになります。", "sentence_source": "generated"}, {"text": "豆腐を凍らせると、中が多孔になります。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "豆腐[とうふ]を凍[こお]らせると、中[なか]が多孔[たこう]になります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多孔", "label": "基本形"}], "register": "polite", "sense_fingerprint": "小さなあながたくさんあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52161, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多孔", "is_correct": true, "explanation": "『多孔なので』の形で、穴が多く水を吸うスポンジの説明に合う。"}, {"text": "多角", "is_correct": false, "explanation": "角が多いという意味。スポンジの性質を表す語として続かない。"}, {"text": "多重", "is_correct": false, "explanation": "重なりが多いという意味。水を吸う理由にはならない。"}, {"text": "多芸", "is_correct": false, "explanation": "多くの芸に秀でているという意味。物の性質には使わない。"}], "explanations": {"多孔": "『多孔なので』の形で、穴が多く水を吸うスポンジの説明に合う。", "多角": "角が多いという意味。スポンジの性質を表す語として続かない。", "多重": "重なりが多いという意味。水を吸う理由にはならない。", "多芸": "多くの芸に秀でているという意味。物の性質には使わない。"}, "sentence_index": 0, "correct_answer": "多孔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は多孔な生徒と練習試合をしました。", "explanation": "ここは〈他校〉（ほかの学校）の意味。多孔は穴の多さを表す語で、人の所属には使いません。"}, {"text": "この作戦は多孔で、すぐに見破られました。", "explanation": "ここは〈穴だらけ〉（欠陥が多い）の意味。多孔は物の小さな穴が多い状態を表すので、作戦の欠陥には使いません。"}, {"text": "今日は多孔な一日で、家族と楽しく過ごせました。", "explanation": "ここは〈多幸〉（幸せが多い）の意味。多孔（穴が多い）では一日の幸福は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52161, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多孔", "is_correct": true, "explanation": "『多孔な材料』の形で、空気を含む材料の説明に合う。"}, {"text": "多額", "is_correct": false, "explanation": "金額が大きいという意味。材料の性質には合わない。"}, {"text": "多発", "is_correct": false, "explanation": "何かが多く起こるという意味。空気を含む材料の説明にはならない。"}, {"text": "多弁", "is_correct": false, "explanation": "話すことが多いという意味。材料には使わない。"}], "explanations": {"多孔": "『多孔な材料』の形で、空気を含む材料の説明に合う。", "多額": "金額が大きいという意味。材料の性質には合わない。", "多発": "何かが多く起こるという意味。空気を含む材料の説明にはならない。", "多弁": "話すことが多いという意味。材料には使わない。"}, "sentence_index": 6, "correct_answer": "多孔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この計算は多孔で表せます。", "explanation": "ここは〈多項〉（項が多い式）の意味。多孔は穴の多さを表す語で、数式の説明には使いません。"}, {"text": "彼女は多孔で、初対面の人ともすぐ打ち解けます。", "explanation": "ここは〈多弁〉（話すことが多い）の意味。多孔（穴が多い）では人の性格は表せない。"}, {"text": "この林は木が多孔に立っています。", "explanation": "ここは〈まばら〉（少なく散らばる）の意味。多孔は穴が多い状態を表すので、木の本数の少なさは表しません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52161, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このスポンジは多孔くて、水をよく吸います。", "corrected_sentence": "このスポンジは多孔で、水をよく吸います。", "error_description": "多孔は形容動詞型なので、い形容詞の『くて』は付かない。誤りは『くて』で、正しくは『多孔で』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52161, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この材料は多孔く、空気をたくさん含んでいます。", "corrected_sentence": "この材料は多孔で、空気をたくさん含んでいます。", "error_description": "多孔は形容動詞型なので『く』は付かない。誤りは『く』で、正しくは『多孔で』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
