INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52162, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "多くの小さな穴や隙間があること。特に、スポンジやパンのように、内部に無数の孔が存在する状態。", "primary_collocate": null, "pronunciation": "たこう", "ipa": "takoː", "syllable_count": 3, "sentences": [{"text": "この紙は表面が多孔で、インクがすぐ染み込む。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "この紙[かみ]は表面[ひょうめん]が多孔[たこう]で、インクがすぐ染[し]み込[こ]む。", "sentence_source": "generated"}, {"text": "スポンジは内部が多孔で、水をたくさん吸い込むことができる。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "スポンジは内部[ないぶ]が多孔[たこう]で、水[みず]をたくさん吸[す]い込[こ]むことができる。", "sentence_source": "generated"}, {"text": "この石は多孔なので、軽くて水がしみ込みやすい。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "この石[いし]は多孔[たこう]なので、軽[かる]くて水[みず]がしみ込[こ]みやすい。", "sentence_source": "generated"}, {"text": "焼きたてのパンの断面は多孔で、小さな穴が全体に広がっている。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "焼[や]きたてのパンの断面[だんめん]は多孔[たこう]で、小[ちい]さな穴[あな]が全体[ぜんたい]に広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "多孔な素材は空気を含むため、熱を伝えにくい。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "多孔[たこう]な素材[そざい]は空気[くうき]を含[ふく]むため、熱[ねつ]を伝[つた]えにくい。", "sentence_source": "generated"}, {"text": "活性炭は表面が多孔であるため、においを吸着する。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "活性炭[かっせいたん]は表面[ひょうめん]が多孔[たこう]であるため、においを吸着[きゅうちゃく]する。", "sentence_source": "generated"}, {"text": "骨が多孔になると、少しの力でも折れやすくなる。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "骨[ほね]が多孔[たこう]になると、少[すこ]しの力[ちから]でも折[お]れやすくなる。", "sentence_source": "generated"}, {"text": "軽石が水に浮くのは、内部が多孔で空気を含んでいるからだ。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "軽石[かるいし]が水[みず]に浮[う]くのは、内部[ないぶ]が多孔[たこう]で空気[くうき]を含[ふく]んでいるからだ。", "sentence_source": "generated"}, {"text": "多孔でない金属の板は、水を全くしみ込ませない。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "多孔[たこう]でない金属[きんぞく]の板[いた]は、水[みず]を全[まった]くしみ込[こ]ませない。", "sentence_source": "generated"}, {"text": "このフィルターは多孔な膜でできていて、小さなごみだけを通す。", "target_word": "多孔", "complexity_tier": "T3", "furigana": "このフィルターは多孔[たこう]な膜[まく]でできていて、小[ちい]さなごみだけを通[とお]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多孔", "label": "基本形"}], "register": "technical", "sense_fingerprint": "スポンジやパンのように内部に無数の小さな孔がある状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52162, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多孔", "is_correct": true, "explanation": "『表面が多孔で』の形で、インクが染み込む紙の説明に合う。"}, {"text": "多角", "is_correct": false, "explanation": "角が多いという意味。表面の状態を表す語として続かない。"}, {"text": "多芸", "is_correct": false, "explanation": "多くの芸に秀でているという意味。紙の性質には使わない。"}, {"text": "多弁", "is_correct": false, "explanation": "話すことが多いという意味。紙の性質には使わない。"}], "explanations": {"多孔": "『表面が多孔で』の形で、インクが染み込む紙の説明に合う。", "多角": "角が多いという意味。表面の状態を表す語として続かない。", "多芸": "多くの芸に秀でているという意味。紙の性質には使わない。", "多弁": "話すことが多いという意味。紙の性質には使わない。"}, "sentence_index": 0, "correct_answer": "多孔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は多孔な一日で、家族みんなが笑って過ごせた。", "explanation": "ここは〈多幸〉（幸せが多い）の意味。多孔（穴が多い）では一日の幸福は表せず、この言葉はこうは使わない。"}, {"text": "この計画は多孔で、すぐに失敗した。", "explanation": "ここは〈穴だらけ〉（欠陥が多い）の意味。多孔は物の小さな穴が多い状態を表すので、計画の欠陥には使わない。"}, {"text": "彼は多孔な生徒と練習試合をした。", "explanation": "ここは〈他校〉（ほかの学校）の意味。多孔は穴の多さを表す語で、人の所属には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52162, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多孔", "is_correct": true, "explanation": "骨が穴の多い状態になるという文に合う。"}, {"text": "多忙", "is_correct": false, "explanation": "忙しいという意味。骨の状態には合わない。"}, {"text": "多額", "is_correct": false, "explanation": "金額が大きいという意味。骨の状態には合わない。"}, {"text": "多弁", "is_correct": false, "explanation": "話すことが多いという意味。骨の状態には合わない。"}], "explanations": {"多孔": "骨が穴の多い状態になるという文に合う。", "多忙": "忙しいという意味。骨の状態には合わない。", "多額": "金額が大きいという意味。骨の状態には合わない。", "多弁": "話すことが多いという意味。骨の状態には合わない。"}, "sentence_index": 6, "correct_answer": "多孔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この関数は多孔で表せる。", "explanation": "ここは〈多項〉（項が多い式）の意味。多孔は穴の多さを表す語で、数式の説明には使わない。"}, {"text": "彼は多孔で、初対面の人ともすぐ打ち解ける。", "explanation": "ここは〈多弁〉（話すことが多い）の意味。多孔（穴が多い）では人の性格は表せない。"}, {"text": "この森は木が多孔に生えている。", "explanation": "ここは〈まばら〉（少なく散らばる）の意味。多孔は穴が多い状態を表すので、木の本数の少なさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52162, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この板は多孔く、軽くて水がしみ込みやすい。", "corrected_sentence": "この板は多孔で、軽くて水がしみ込みやすい。", "error_description": "多孔は形容動詞型なので『く』は付かない。誤りは『く』で、正しくは『多孔で』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52162, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "骨が多孔くなると、少しの力でも折れやすい。", "corrected_sentence": "骨が多孔になると、少しの力でも折れやすい。", "error_description": "多孔は形容動詞型なので『く』は付かない。誤りは『く』で、正しくは『多孔になる』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52163, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『含まれる』の主語は脂質なので『が』。"}, {"text": "を", "is_correct": false, "explanation": "『含まれる』は『が』で主語を示す。『を』では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞で、『含まれる』の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、含まれる対象にはならない。"}], "correct_answer": "が", "explanations": {"が": "『含まれる』の主語は脂質なので『が』。", "を": "『含まれる』は『が』で主語を示す。『を』では文が成り立たない。", "で": "場所や手段を示す助詞で、『含まれる』の主語にはならない。", "へ": "方向を示す助詞で、含まれる対象にはならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52163, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『入っている』の主語は脂質なので『が』。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すので、入っている主語には使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すので、入っている量の説明にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すので、入っている量を表す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "『入っている』の主語は脂質なので『が』。", "を": "目的語を示すので、入っている主語には使えない。", "より": "比較を示すので、入っている量の説明にはならない。", "から": "起点を示すので、入っている量を表す文には合わない。"}, "error_tags": {"を": "目的語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52163, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の中にあって、エネルギーになったり、体の一部になるあぶらです。", "primary_collocate": null, "pronunciation": "ししつ", "ipa": "ɕiɕitsɯ", "syllable_count": 3, "sentences": [{"text": "脂質は体のエネルギーになります。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "脂質[ししつ]は体[からだ]のエネルギーになります。", "sentence_source": "generated"}, {"text": "肉の白いところには、脂質が多く含まれています。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "肉[にく]の白[しろ]いところには、脂質[ししつ]が多[おお]く含[ふく]まれています。", "sentence_source": "generated"}, {"text": "脂質をとりすぎると、太りやすくなります。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "脂質[ししつ]をとりすぎると、太[ふと]りやすくなります。", "sentence_source": "generated"}, {"text": "バターは脂質がとても多い食べ物です。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "バターは脂質[ししつ]がとても多[おお]い食[た]べ物[もの]です。", "sentence_source": "generated"}, {"text": "体は、脂質を使って細胞をつくります。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "体[からだ]は、脂質[ししつ]を使[つか]って細胞[さいぼう]をつくります。", "sentence_source": "generated"}, {"text": "野菜には、脂質があまり入っていません。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "野菜[やさい]には、脂質[ししつ]があまり入[はい]っていません。", "sentence_source": "generated"}, {"text": "医者に「脂質を少なくしてください」と言われました。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "医者[いしゃ]に「脂質[ししつ]を少[すく]なくしてください」と言[い]われました。", "sentence_source": "generated"}, {"text": "この食品には、脂質が十グラム入っています。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "この食品[しょくひん]には、脂質[ししつ]が十[じゅう]グラム入[はい]っています。", "sentence_source": "generated"}, {"text": "魚の脂質は、体にいいと言われています。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "魚[さかな]の脂質[ししつ]は、体[からだ]にいいと言[い]われています。", "sentence_source": "generated"}, {"text": "脂質は水に溶けにくいので、血液の中ではたんぱく質と一緒に運ばれます。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "脂質[ししつ]は水[みず]に溶[と]けにくいので、血液[けつえき]の中[なか]ではたんぱく質と一緒[いっしょ]に運[はこ]ばれます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脂質", "label": "基本形"}], "register": "polite", "sense_fingerprint": "体の中でエネルギーや体の一部になるあぶら", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52163, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脂質", "is_correct": true, "explanation": "主語として『脂質は体のエネルギーになります』と文が成り立つ。"}, {"text": "寝不足", "is_correct": false, "explanation": "睡眠が足りないという意味。体のエネルギーにはならない。"}, {"text": "大声", "is_correct": false, "explanation": "大きな声という意味。体のエネルギーにはならない。"}, {"text": "夜更かし", "is_correct": false, "explanation": "夜遅くまで起きている行動。エネルギーになるものではない。"}], "explanations": {"脂質": "主語として『脂質は体のエネルギーになります』と文が成り立つ。", "寝不足": "睡眠が足りないという意味。体のエネルギーにはならない。", "大声": "大きな声という意味。体のエネルギーにはならない。", "夜更かし": "夜遅くまで起きている行動。エネルギーになるものではない。"}, "sentence_index": 0, "correct_answer": "脂質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "フライパンに脂質を引いて、卵を焼きます。", "explanation": "ここは〈油〉の意味。フライパンに引く油は脂質とは言わず、油を使う。"}, {"text": "壁に脂質を塗ると、きれいになります。", "explanation": "ここは〈塗料〉（壁に塗るペンキ）の意味。脂質は体内の成分の総称で、壁を塗る材料としては使いません。"}, {"text": "このペンは脂質で書くので、水では消えません。", "explanation": "ここは〈油性〉の意味。油性インクの性質を表す語で、書く材料としては脂質とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52163, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脂質", "is_correct": true, "explanation": "『脂質を少なくしてください』の目的語で、食事の制限を指示する文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様という意味。少なくする対象にはならない。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙などを届ける仕組み。少なくする対象にはならない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝る場所という意味。食事の制限の文には合わない。"}], "explanations": {"脂質": "『脂質を少なくしてください』の目的語で、食事の制限を指示する文に合う。", "天気": "空模様という意味。少なくする対象にはならない。", "郵便": "手紙などを届ける仕組み。少なくする対象にはならない。", "寝床": "寝る場所という意味。食事の制限の文には合わない。"}, "sentence_index": 6, "correct_answer": "脂質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この肉は脂質がのっていて、ジューシーです。", "explanation": "ここは〈脂〉（脂がのる）の意味。脂質は栄養素の分類で、この言い方はしない。"}, {"text": "朝は髪を脂質で洗います。", "explanation": "ここは〈シャンプー〉（髪を洗う洗剤）の意味。脂質は体内の成分の総称で、洗剤の代わりには使いません。"}, {"text": "木と木を脂質でつけます。", "explanation": "ここは〈接着剤〉（物を接着する材料）の意味。脂質は体内の成分の総称で、物をくっつける材料には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52163, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "脂質を体のエネルギー源になります。", "corrected_sentence": "脂質は体のエネルギー源になります。", "error_description": "主題の『は』が『を』になっている。『なる』は目的語の『を』を取らない。誤りは助詞『を』。正しくは『脂質は』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52163, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この食品には、脂質を十グラム含まれています。", "corrected_sentence": "この食品には、脂質が十グラム含まれています。", "error_description": "『含まれる』の主語を示す助詞が『を』になっている。正しくは『が』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
