INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52164, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物の体内に含まれる、水に溶けにくい有機化合物の総称。エネルギー源や細胞膜の構成成分として重要。", "primary_collocate": null, "pronunciation": "ししつ", "ipa": "ɕiɕitsɯ", "syllable_count": 3, "sentences": [{"text": "細胞膜は脂質でできています。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "細胞膜[さいぼうまく]は脂質[ししつ]でできています。", "sentence_source": "generated"}, {"text": "脂質は細胞膜をつくる大切な成分で、エネルギー源にもなる。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "脂質[ししつ]は細胞膜[さいぼうまく]をつくる大切[たいせつ]な成分[せいぶん]で、エネルギー源[げん]にもなる。", "sentence_source": "generated"}, {"text": "揚げ物ばかり食べていると、脂質のとりすぎで体重が増えやすい。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "揚[あ]げ物[もの]ばかり食[た]べていると、脂質[ししつ]のとりすぎで体重[たいじゅう]が増[ふ]えやすい。", "sentence_source": "generated"}, {"text": "脂質は水に溶けにくいので、水で洗っても落ちにくい。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "脂質[ししつ]は水[みず]に溶[と]けにくいので、水[みず]で洗[あら]っても落[お]ちにくい。", "sentence_source": "generated"}, {"text": "食品の栄養表示には、たんぱく質、炭水化物とともに脂質の量が書かれている。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "食品[しょくひん]の栄養[えいよう]表示[ひょうじ]には、たんぱく質[しつ]、炭水化物[たんすいかぶつ]とともに脂質[ししつ]の量[りょう]が書[か]かれている。", "sentence_source": "generated"}, {"text": "健康診断で血液中の脂質の値が高いと言われ、食事を見直した。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "健康診断[けんこうしんだん]で血液中[けつえきちゅう]の脂質[ししつ]の値[あたい]が高[たか]いと言[い]われ、食事[しょくじ]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "ナッツには良質な脂質が多く含まれている。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "ナッツには良質[りょうしつ]な脂質[ししつ]が多[おお]く含[ふく]まれている。", "sentence_source": "generated"}, {"text": "脂質は一グラムあたりのエネルギーが多く、糖質の倍以上ある。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "脂質[ししつ]は一[いち]グラムあたりのエネルギーが多[おお]く、糖質[とうしつ]の倍[ばい]以上[いじょう]ある。", "sentence_source": "generated"}, {"text": "脂質が極端に不足すると、脂に溶けるビタミンの吸収が悪くなる。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "脂質[ししつ]が極端[きょくたん]に不足[ふそく]すると、脂[あぶら]に溶[と]けるビタミンの吸収[きゅうしゅう]が悪[わる]くなる。", "sentence_source": "generated"}, {"text": "この牛乳は脂質を減らしてあるので、あっさりした味がする。", "target_word": "脂質", "complexity_tier": "T3", "furigana": "この牛乳[ぎゅうにゅう]は脂質[ししつ]を減[へ]らしてあるので、あっさりした味[あじ]がする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脂質", "label": "基本形"}], "register": "technical", "sense_fingerprint": "水に溶けにくく、エネルギー源や細胞膜の成分となる有機化合物の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0f9d265-bf07-45fd-a4e6-6cf5a4b81fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52164, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脂質", "is_correct": true, "explanation": "細胞膜の主な材料として『脂質でできています』の形で文に合う。"}, {"text": "塩分", "is_correct": false, "explanation": "食塩の量を表す語。細胞膜の材料としては使わない。"}, {"text": "炭水化物", "is_correct": false, "explanation": "糖質と食物繊維をまとめた栄養素の名前。細胞膜の材料にはならない。"}, {"text": "糖分", "is_correct": false, "explanation": "甘さの成分を指す語。細胞膜の材料には使わない。"}], "explanations": {"脂質": "細胞膜の主な材料として『脂質でできています』の形で文に合う。", "塩分": "食塩の量を表す語。細胞膜の材料としては使わない。", "炭水化物": "糖質と食物繊維をまとめた栄養素の名前。細胞膜の材料にはならない。", "糖分": "甘さの成分を指す語。細胞膜の材料には使わない。"}, "sentence_index": 0, "correct_answer": "脂質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この魚は脂質がのっていて、とても美味しい。", "explanation": "ここは〈脂〉（脂がのる＝脂肪が多く味が濃い）の意味。脂質は栄養素の分類で、「脂がのる」の言い方には使わない。"}, {"text": "彼は脂質で風景画を描くのが得意だ。", "explanation": "ここは〈油〉（油絵具）の意味。脂質は栄養素の分類で、絵の具として使う語ではない。"}, {"text": "機械の動く部分に脂質を差して、きしみを止める。", "explanation": "ここは〈グリース〉（機械の潤滑剤）の意味。脂質は体内の成分の総称で、機械の潤滑には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52164, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脂質", "is_correct": true, "explanation": "『良質な脂質』の形で、ナッツの栄養を表す文に合う。"}, {"text": "寝不足", "is_correct": false, "explanation": "睡眠が足りないという意味。食品の成分としては続かない。"}, {"text": "騒音", "is_correct": false, "explanation": "うるさい音という意味。食品には使わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様という意味。食品の成分としては続かない。"}], "explanations": {"脂質": "『良質な脂質』の形で、ナッツの栄養を表す文に合う。", "寝不足": "睡眠が足りないという意味。食品の成分としては続かない。", "騒音": "うるさい音という意味。食品には使わない。", "天気": "空模様という意味。食品の成分としては続かない。"}, "sentence_index": 6, "correct_answer": "脂質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床を脂質で磨くと、つやが出る。", "explanation": "ここは〈ワックス〉（床用の蝋）の意味。脂質は体内の成分の総称で、掃除の材料としては言わない。"}, {"text": "手を脂質で洗うと、さっぱりする。", "explanation": "ここは〈石けん〉（汚れを落とす洗剤）の意味。脂質は体内の成分の総称で、洗う道具としては使わない。"}, {"text": "このマジックは脂質で書くので、水では消えない。", "explanation": "ここは〈油性〉の意味。油性インクの性質を表す語で、字を書く材料としては脂質とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52164, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "脂質を大切な成分で、エネルギー源にもなる。", "corrected_sentence": "脂質は大切な成分で、エネルギー源にもなる。", "error_description": "主題の『は』が『を』になっている。誤りは助詞『を』。正しくは『脂質は』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52164, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "脂質を一グラムあたり多くのエネルギーがあり、糖質の倍以上ある。", "corrected_sentence": "脂質は一グラムあたり多くのエネルギーがあり、糖質の倍以上ある。", "error_description": "主題を示す『は』が『を』になっている。脂質が主題なので『は』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '903e694e-ef11-49e4-a5f9-5268b2179c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
