INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52165, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かの上に、のりやペンキなどをのばしてつける。", "primary_collocate": null, "pronunciation": "ぬる", "ipa": "nɯɾɯ", "syllable_count": 2, "sentences": [{"text": "週末に父と一緒に、庭の柵に白いペンキを塗った。", "target_word": "塗った", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]に父[ちち]と一緒[いっしょ]に、庭[にわ]の柵[さく]に白[しろ]いペンキを塗[ぬ]った。", "sentence_source": "generated"}, {"text": "紙を貼る前に、裏側にのりを塗る。", "target_word": "塗る", "complexity_tier": "T3", "furigana": "紙[かみ]を貼[は]る前[まえ]に、裏側[うらがわ]にのりを塗[ぬ]る。", "sentence_source": "generated"}, {"text": "錆びないように、鉄の棚に油性のペンキを塗ることにした。", "target_word": "塗る", "complexity_tier": "T3", "furigana": "錆[さ]びないように、鉄[てつ]の棚[たな]に油性[ゆせい]のペンキを塗[ぬ]ることにした。", "sentence_source": "generated"}, {"text": "壁を青く塗ったら、部屋が明るい印象になった。", "target_word": "塗ったら", "complexity_tier": "T3", "furigana": "壁[かべ]を青[あお]く塗[ぬ]ったら、部屋[へや]が明[あか]るい印象[いんしょう]になった。", "sentence_source": "generated"}, {"text": "子どもたちは大きな紙に、絵の具を自由に塗って遊んでいる。", "target_word": "塗って", "complexity_tier": "T3", "furigana": "子[こ]どもたちは大[おお]きな紙[かみ]に、絵[え]の具[ぐ]を自由[じゆう]に塗[ぬ]って遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "雨が降りそうなので、今日は屋根にペンキを塗らないことにした。", "target_word": "塗らない", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]りそうなので、今日[きょう]は屋根[やね]にペンキを塗[ぬ]らないことにした。", "sentence_source": "generated"}, {"text": "木の板に接着剤を塗って、しばらく押さえておく。", "target_word": "塗って", "complexity_tier": "T3", "furigana": "木[き]の板[いた]に接着剤[せっちゃくざい]を塗[ぬ]って、しばらく押[お]さえておく。", "sentence_source": "generated"}, {"text": "古い門は黒く塗れば、見違えるほどきれいになる。", "target_word": "塗れば", "complexity_tier": "T3", "furigana": "古[ふる]い門[もん]は黒[くろ]く塗[ぬ]れば、見違[みちが]えるほどきれいになる。", "sentence_source": "generated"}, {"text": "運動会の看板は、赤と黄色のペンキで塗るつもりだ。", "target_word": "塗る", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の看板[かんばん]は、赤[あか]と黄色[きいろ]のペンキで塗[ぬ]るつもりだ。", "sentence_source": "generated"}, {"text": "兄は床の割れ目にパテを塗って、なめらかに整えた。", "target_word": "塗って", "complexity_tier": "T3", "furigana": "兄[あに]は床[ゆか]の割[わ]れ目[め]にパテを塗[ぬ]って、なめらかに整[ととの]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塗る", "label": "終止形"}, {"form": "塗り", "label": "連用形"}, {"form": "塗った", "label": "夕形"}, {"form": "塗って", "label": "て形"}, {"form": "塗らない", "label": "否定形"}, {"form": "塗れば", "label": "仮定形"}, {"form": "塗ろう", "label": "意志形"}], "register": "標準（普通体）", "sense_fingerprint": "ペンキ・のり・絵の具などを物の上にのばして覆うようにつける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52165, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塗った", "is_correct": true, "explanation": "過去の完了を表す夕形で、週末にペンキを塗ったという報告に合う。正解。"}, {"text": "塗って", "is_correct": false, "explanation": "て形は文末で完結できず、「白いペンキを塗って。」では文が終わらない。"}, {"text": "塗り", "is_correct": false, "explanation": "連用形は文を言い切れず、文末に置けない。"}, {"text": "塗れば", "is_correct": false, "explanation": "仮定形は条件節なので、「塗れば。」では事実を述べる文にならない。"}], "explanations": {"塗った": "過去の完了を表す夕形で、週末にペンキを塗ったという報告に合う。正解。", "塗って": "て形は文末で完結できず、「白いペンキを塗って。」では文が終わらない。", "塗り": "連用形は文を言い切れず、文末に置けない。", "塗れば": "仮定形は条件節なので、「塗れば。」では事実を述べる文にならない。"}, "sentence_index": 0, "correct_answer": "塗った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉛筆を小刀で塗った。", "explanation": "ここは〈削る〉の意味。塗るは面にのばしてつける動作で、刃物で表面を削り取る意味には使わないので合わない。"}, {"text": "庭に種を塗った。", "explanation": "ここは〈撒く〉の意味。塗るは面にのばしてつける動作で、粒状の種を散らす意味には使わないので合わない。"}, {"text": "ポスターを壁に塗った。", "explanation": "ここは〈貼る〉の意味。ポスターは貼るもので、のりやペンキを面にのばす塗るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52165, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塗って", "is_correct": true, "explanation": "て形で後ろに「押さえておく」が続き、塗ってから押さえるという手順になる。正解。"}, {"text": "塗る", "is_correct": false, "explanation": "終止形は後に続く「しばらく押さえておく」と連続せず、「塗る、」では文がつながらない。"}, {"text": "塗らなかった", "is_correct": false, "explanation": "否定の過去形で、塗らずに押さえるという意味になり手順の文と合わない。"}, {"text": "塗ってた", "is_correct": false, "explanation": "継続の過去形で、手順を指示する文には合わない。"}], "explanations": {"塗って": "て形で後ろに「押さえておく」が続き、塗ってから押さえるという手順になる。正解。", "塗る": "終止形は後に続く「しばらく押さえておく」と連続せず、「塗る、」では文がつながらない。", "塗らなかった": "否定の過去形で、塗らずに押さえるという意味になり手順の文と合わない。", "塗ってた": "継続の過去形で、手順を指示する文には合わない。"}, "sentence_index": 6, "correct_answer": "塗って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝は玄関の床をほうきで塗った。", "explanation": "ここは〈掃く〉の意味。塗るは面にのばす動作で、ほうきで払う意味には使わないので合わない。"}, {"text": "夕食のあと、皿を塗った。", "explanation": "ここは〈洗う〉の意味。塗るは表面に薄くのばす動作で、水で汚れを落とす意味には使わないので合わない。"}, {"text": "庭の花を塗った。", "explanation": "ここは〈摘む〉の意味。塗るは表面にのばす動作で、花を手でもぎ取る意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52165, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペンキを塗らって、乾くまで待った。", "corrected_sentence": "ペンキを塗って、乾くまで待った。", "error_description": "「塗る」のて形は「塗って」。「塗らって」は余分な「ら」を入れた誤りで、正しくは「塗って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "塗る", "is_correct": true, "explanation": "文末の終止形で、のりを塗るという手順を言い切る形。正解。"}, {"text": "塗れば", "is_correct": false, "explanation": "仮定形は条件を表し、文末では完結しない。事実を述べる文には合わない。"}, {"text": "塗らない", "is_correct": false, "explanation": "否定形なので、のりを塗らないという反対の指示になる。"}, {"text": "塗ろう", "is_correct": false, "explanation": "意志形は勧誘や決意を表すため、手順を言い切る文には合わない。"}], "correct_form": "塗る", "base_form": "塗る", "form_label": "終止形", "sentence_index": 1, "explanations": {"塗る": "文末の終止形で、のりを塗るという手順を言い切る形。正解。", "塗れば": "仮定形は条件を表し、文末では完結しない。事実を述べる文には合わない。", "塗らない": "否定形なので、のりを塗らないという反対の指示になる。", "塗ろう": "意志形は勧誘や決意を表すため、手順を言い切る文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52165, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋根に防水ペンキを塗りた。", "corrected_sentence": "屋根に防水ペンキを塗った。", "error_description": "過去の形は「塗った」。「塗りた」は連用形に「た」を付けた誤りで、促音の形になっていない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "塗れば", "is_correct": true, "explanation": "仮定形で「塗ると・塗ったら」という条件を表し、結果を述べる文に合う。正解。"}, {"text": "塗る", "is_correct": false, "explanation": "終止形では条件を表せず、「黒く塗る、見違える…」と条件の関係が成り立たない。"}, {"text": "塗らなかった", "is_correct": false, "explanation": "否定の過去形で、塗らなかった場合の話になり文意と合わない。"}, {"text": "塗ってた", "is_correct": false, "explanation": "継続の過去形で、条件を述べる文として成り立たない。"}], "correct_form": "塗れば", "base_form": "塗る", "form_label": "仮定形", "sentence_index": 7, "explanations": {"塗れば": "仮定形で「塗ると・塗ったら」という条件を表し、結果を述べる文に合う。正解。", "塗る": "終止形では条件を表せず、「黒く塗る、見違える…」と条件の関係が成り立たない。", "塗らなかった": "否定の過去形で、塗らなかった場合の話になり文意と合わない。", "塗ってた": "継続の過去形で、条件を述べる文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52166, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「日焼け止め」を受けて塗るの目的語を示す格助詞。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞だが、「日焼け止めが塗った」では塗る対象が示せず文意が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示すが、「日焼け止めに塗った」は塗る対象の表し方として不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同を示す助詞で、「日焼け止めと塗った」は塗る対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「日焼け止め」を受けて塗るの目的語を示す格助詞。正解。", "が": "主語を示す助詞だが、「日焼け止めが塗った」では塗る対象が示せず文意が成り立たない。", "に": "場所や相手を示すが、「日焼け止めに塗った」は塗る対象の表し方として不自然。", "と": "並列・共同を示す助詞で、「日焼け止めと塗った」は塗る対象にならない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52166, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ジャム」を受けて塗るの目的語を示す格助詞。正解。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「ジャムの塗る」は文の述語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞だが、「ジャムへ塗る」は塗る対象の表し方として合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示す語で、「ジャムより塗る」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ジャム」を受けて塗るの目的語を示す格助詞。正解。", "の": "連体修飾の助詞で、「ジャムの塗る」は文の述語として成り立たない。", "へ": "方向を示す助詞だが、「ジャムへ塗る」は塗る対象の表し方として合わない。", "より": "比較や起点を示す語で、「ジャムより塗る」は文として成り立たない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52166, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体やクリーム状のものを、表面に薄くのばしてつけること。", "primary_collocate": null, "pronunciation": "ぬる", "ipa": "nɯɾɯ", "syllable_count": 2, "sentences": [{"text": "まず、良質な全粒粉のパンを用意し、その多孔質な表面にピーナッツバターを均一に塗る。", "target_word": "塗る", "complexity_tier": "T4", "furigana": "まず、良質[りょうしつ]な全粒粉[ぜんりゅうふん]のパンを用意[ようい]し、その多孔質[たこうしつ]な表面[ひょうめん]にピーナッツバターを均一[きんいつ]に塗[ぬ]る。", "sentence_source": "mined"}, {"text": "外に出る前に、顔と腕に日焼け止めを塗った。", "target_word": "塗った", "complexity_tier": "T3", "furigana": "外[そと]に出[で]る前[まえ]に、顔[かお]と腕[うで]に日焼[ひや]け止[ど]めを塗[ぬ]った。", "sentence_source": "generated"}, {"text": "手が荒れたので、寝る前にハンドクリームを塗ることにしている。", "target_word": "塗る", "complexity_tier": "T3", "furigana": "手[て]が荒[あ]れたので、寝[ね]る前[まえ]にハンドクリームを塗[ぬ]ることにしている。", "sentence_source": "generated"}, {"text": "虫に刺されたところに薬を塗ったら、かゆみが収まった。", "target_word": "塗った", "complexity_tier": "T3", "furigana": "虫[むし]に刺[さ]されたところに薬[くすり]を塗[ぬ]ったら、かゆみが収[おさ]まった。", "sentence_source": "generated"}, {"text": "焼きたてのトーストにバターを薄く塗って食べた。", "target_word": "塗って", "complexity_tier": "T3", "furigana": "焼[や]きたてのトーストにバターを薄[うす]く塗[ぬ]って食[た]べた。", "sentence_source": "generated"}, {"text": "弟は唇が乾くと、すぐにリップクリームを塗る。", "target_word": "塗る", "complexity_tier": "T3", "furigana": "弟[おとうと]は唇[くちびる]が乾[かわ]くと、すぐにリップクリームを塗[ぬ]る。", "sentence_source": "generated"}, {"text": "傷口に水をかけただけで、薬は何も塗らなかった。", "target_word": "塗らなかった", "complexity_tier": "T3", "furigana": "傷口[きずぐち]に水[みず]をかけただけで、薬[くすり]は何[なに]も塗[ぬ]らなかった。", "sentence_source": "generated"}, {"text": "朝は時間がないので、トーストにはジャムを塗るだけにしている。", "target_word": "塗る", "complexity_tier": "T3", "furigana": "朝[あさ]は時間[じかん]がないので、トーストにはジャムを塗[ぬ]るだけにしている。", "sentence_source": "generated"}, {"text": "肌が弱い人は、先に腕の内側に少し塗って、様子を見るとよい。", "target_word": "塗って", "complexity_tier": "T3", "furigana": "肌[はだ]が弱[よわ]い人[ひと]は、先[さき]に腕[うで]の内側[うちがわ]に少[すこ]し塗[ぬ]って、様子[ようす]を見[み]るとよい。", "sentence_source": "generated"}, {"text": "ケーキの表面にクリームを塗るとき、ナイフを温めると滑らかになる。", "target_word": "塗る", "complexity_tier": "T3", "furigana": "ケーキの表面[ひょうめん]にクリームを塗[ぬ]るとき、ナイフを温[あたた]めると滑[なめ]らかになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塗る", "label": "終止形"}, {"form": "塗り", "label": "連用形"}, {"form": "塗った", "label": "夕形"}, {"form": "塗って", "label": "て形"}, {"form": "塗らない", "label": "否定形"}, {"form": "塗れば", "label": "仮定形"}, {"form": "塗ろう", "label": "意志形"}], "register": "標準（普通体）", "sense_fingerprint": "クリーム・薬・バターなど柔らかいものを表面に薄くのばしてつける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52166, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塗る", "is_correct": true, "explanation": "「まず…用意し」の流れで文末に置く終止形。手順を言い切る形として正しい。"}, {"text": "塗り", "is_correct": false, "explanation": "連用形は文を言い切れず、「均一に塗り。」では文が終わらない。"}, {"text": "塗って", "is_correct": false, "explanation": "て形は後に続く語が必要で、文末の「均一に塗って。」は完結しない。"}, {"text": "塗れば", "is_correct": false, "explanation": "仮定形は条件節なので、文末に置くと「塗れば。」と意味が完結しない。"}], "explanations": {"塗る": "「まず…用意し」の流れで文末に置く終止形。手順を言い切る形として正しい。", "塗り": "連用形は文を言い切れず、「均一に塗り。」では文が終わらない。", "塗って": "て形は後に続く語が必要で、文末の「均一に塗って。」は完結しない。", "塗れば": "仮定形は条件節なので、文末に置くと「塗れば。」と意味が完結しない。"}, "sentence_index": 0, "correct_answer": "塗る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋の焦げを金たわしで塗った。", "explanation": "ここは〈こする〉の意味。塗るは液体やクリームを表面にのばす動作で、こすって汚れを落とす意味には使わないので合わない。"}, {"text": "庭の草を塗った。", "explanation": "ここは〈刈る〉の意味。塗るは表面にのばす動作で、草を刈り取る意味には使わないので合わない。"}, {"text": "グラスにジュースを塗った。", "explanation": "ここは〈注ぐ〉の意味。塗るは表面にのばす動作で、容器に液体を流し入れる意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52166, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塗らなかった", "is_correct": true, "explanation": "「何も」と呼応する否定の過去形。薬を塗らなかったという意味で正解。"}, {"text": "塗った", "is_correct": false, "explanation": "肯定の過去形で、「何も」と呼応せず不自然になる。"}, {"text": "塗る", "is_correct": false, "explanation": "肯定の終止形で、「何も」の否定とは呼応しない。"}, {"text": "塗ろう", "is_correct": false, "explanation": "意志形で、過去に薬を使わなかった事実を述べる文には合わない。"}], "explanations": {"塗らなかった": "「何も」と呼応する否定の過去形。薬を塗らなかったという意味で正解。", "塗った": "肯定の過去形で、「何も」と呼応せず不自然になる。", "塗る": "肯定の終止形で、「何も」の否定とは呼応しない。", "塗ろう": "意志形で、過去に薬を使わなかった事実を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "塗らなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パンに卵焼きを塗った。", "explanation": "ここは〈挟む〉の意味。塗るは液体やクリームを表面にのばす動作で、具材を間に挟む意味には使わないので合わない。"}, {"text": "玉ねぎを細かく塗った。", "explanation": "ここは〈刻む〉の意味。塗るは表面にのばす動作で、食材を細かく切る意味には使わないので合わない。"}, {"text": "鍋で野菜を塗った。", "explanation": "ここは〈茹でる〉の意味。塗るは物を表面にのばす動作で、湯で加熱する意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52166, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝る前に、顔に美容液を塗てから寝た。", "corrected_sentence": "寝る前に、顔に美容液を塗ってから寝た。", "error_description": "「塗る」のて形は「塗って」。「塗て」は促音「っ」が抜けた誤りで、正しくは「塗って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "塗った", "is_correct": true, "explanation": "過去の完了を表す夕形で、既に日焼け止めを塗ったという事実を述べる文に合う。"}, {"text": "塗って", "is_correct": false, "explanation": "て形は文末で完結せず、「顔と腕に日焼け止めを塗って。」では事実を述べる文にならない。"}, {"text": "塗らない", "is_correct": false, "explanation": "否定形なので、塗ったという事実と反対の意味になる。"}, {"text": "塗れば", "is_correct": false, "explanation": "仮定形は条件を表すため、既に行った事実を述べる文には合わない。"}], "correct_form": "塗った", "base_form": "塗る", "form_label": "夕形", "sentence_index": 1, "explanations": {"塗った": "過去の完了を表す夕形で、既に日焼け止めを塗ったという事実を述べる文に合う。", "塗って": "て形は文末で完結せず、「顔と腕に日焼け止めを塗って。」では事実を述べる文にならない。", "塗らない": "否定形なので、塗ったという事実と反対の意味になる。", "塗れば": "仮定形は条件を表すため、既に行った事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52166, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前に、リップクリームを唇で塗るとよい。", "corrected_sentence": "寝る前に、リップクリームを唇に塗るとよい。", "error_description": "「唇に塗る」の「に」が正しい。「唇で塗る」の「で」は手段を表すため、塗る場所を示せず不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "塗る", "is_correct": true, "explanation": "終止形で、「だけにしている」と合わせて習慣的に塗る動作を表す。正解。"}, {"text": "塗った", "is_correct": false, "explanation": "夕形は過去の完了を表すため、習慣を述べる文には合わない。"}, {"text": "塗ろう", "is_correct": false, "explanation": "意志形なので、習慣を説明する文の述語にはならない。"}, {"text": "塗らなかった", "is_correct": false, "explanation": "否定の過去形で、ジャムを塗らないという反対の意味になり文意に合わない。"}], "correct_form": "塗る", "base_form": "塗る", "form_label": "終止形", "sentence_index": 7, "explanations": {"塗る": "終止形で、「だけにしている」と合わせて習慣的に塗る動作を表す。正解。", "塗った": "夕形は過去の完了を表すため、習慣を述べる文には合わない。", "塗ろう": "意志形なので、習慣を説明する文の述語にはならない。", "塗らなかった": "否定の過去形で、ジャムを塗らないという反対の意味になり文意に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
