INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52167, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "うすいかわのようなもの。", "primary_collocate": null, "pronunciation": "まく", "ipa": "makɯ", "syllable_count": 2, "sentences": [{"text": "ゆで卵の殻の内側には、白い膜がぴったりくっついている。", "target_word": "膜", "complexity_tier": "T3", "furigana": "ゆで卵[たまご]の殻[から]の内側[うちがわ]には、白[しろ]い膜[まく]がぴったりくっついている。", "sentence_source": "generated"}, {"text": "スープが冷めて、表面に薄い膜が張った。", "target_word": "膜", "complexity_tier": "T3", "furigana": "スープが冷[さ]めて、表面[ひょうめん]に薄[うす]い膜[まく]が張[は]った。", "sentence_source": "generated"}, {"text": "温めたココアの上にできた膜が苦手で、いつも取ってから飲む。", "target_word": "膜", "complexity_tier": "T3", "furigana": "温[あたた]めたココアの上[うえ]にできた膜[まく]が苦手[にがて]で、いつも取[と]ってから飲[の]む。", "sentence_source": "generated"}, {"text": "水たまりに油が落ちて、水面に虹色の膜ができていた。", "target_word": "膜", "complexity_tier": "T3", "furigana": "水[みず]たまりに油[あぶら]が落[お]ちて、水面[すいめん]に虹色[にじいろ]の膜[まく]ができていた。", "sentence_source": "generated"}, {"text": "肉の表面についている白い膜は、焼く前に包丁で取り除く。", "target_word": "膜", "complexity_tier": "T3", "furigana": "肉[にく]の表面[ひょうめん]についている白[しろ]い膜[まく]は、焼[や]く前[まえ]に包丁[ほうちょう]で取[と]り除[のぞ]く。", "sentence_source": "generated"}, {"text": "水ぶくれの上の薄い膜を、むやみに破らないほうがいい。", "target_word": "膜", "complexity_tier": "T3", "furigana": "水[みず]ぶくれの上[うえ]の薄[うす]い膜[まく]を、むやみに破[やぶ]らないほうがいい。", "sentence_source": "generated"}, {"text": "湯気で曇った鏡に、水の膜がうっすらと広がった。", "target_word": "膜", "complexity_tier": "T3", "furigana": "湯気[ゆげ]で曇[くも]った鏡[かがみ]に、水[みず]の膜[まく]がうっすらと広[ひろ]がった。", "sentence_source": "generated"}, {"text": "イクラの粒の膜が破れて、中の汁があふれ出した。", "target_word": "膜", "complexity_tier": "T3", "furigana": "イクラの粒[つぶ]の膜[まく]が破[やぶ]れて、中[なか]の汁[しる]があふれ出[だ]した。", "sentence_source": "generated"}, {"text": "目の表面が乾かないように、涙が薄い膜をつくっている。", "target_word": "膜", "complexity_tier": "T3", "furigana": "目[め]の表面[ひょうめん]が乾[かわ]かないように、涙[なみだ]が薄[うす]い膜[まく]をつくっている。", "sentence_source": "generated"}, {"text": "凍った湖の上に、薄い氷の膜が張っていた。", "target_word": "膜", "complexity_tier": "T3", "furigana": "凍[こお]った湖[みずうみ]の上[うえ]に、薄[うす]い氷[こおり]の膜[まく]が張[は]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "膜", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "食べ物や液体の表面にできる、皮のように薄いもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52167, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "殻の内側にぴったりくっつく白く薄い層を指し、文の主語として自然。正解。"}, {"text": "黄身", "is_correct": false, "explanation": "黄色い中身で白くないため、「白い黄身」は矛盾し文に合わない。"}, {"text": "芽", "is_correct": false, "explanation": "植物の新芽を指し、卵の殻の内側にくっつくものではないので合わない。"}, {"text": "麺", "is_correct": false, "explanation": "細長い食品を指し、卵の殻の内側にぴったりくっつく状態には合わない。"}], "explanations": {"膜": "殻の内側にぴったりくっつく白く薄い層を指し、文の主語として自然。正解。", "黄身": "黄色い中身で白くないため、「白い黄身」は矛盾し文に合わない。", "芽": "植物の新芽を指し、卵の殻の内側にくっつくものではないので合わない。", "麺": "細長い食品を指し、卵の殻の内側にぴったりくっつく状態には合わない。"}, "sentence_index": 0, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お芝居の膜が下りて、客席が明るくなった。", "explanation": "ここは〈幕〉の意味。膜は薄いかわのようなもので、舞台の幕が下りるという使い方はしないので合わない。"}, {"text": "ワインの膜を抜いた。", "explanation": "ここは〈栓〉の意味。栓は抜くものだが、薄いかわのようなものは抜く対象にならないので合わない。"}, {"text": "焚き火の膜が立ち上った。", "explanation": "ここは〈煙〉の意味。膜は薄い層で、煙のように立ち上るという意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52167, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "薄く広がる水の層を指し、鏡の表面にうっすら広がる状態に合う。正解。"}, {"text": "粉", "is_correct": false, "explanation": "細かい粒状のもので、水の層として広がるとは言えないので合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "甘味料で、水の層として鏡に広がるという意味にはならないので合わない。"}, {"text": "糸", "is_correct": false, "explanation": "細長いもので、うっすら広がる水の層には合わないので不適切。"}], "explanations": {"膜": "薄く広がる水の層を指し、鏡の表面にうっすら広がる状態に合う。正解。", "粉": "細かい粒状のもので、水の層として広がるとは言えないので合わない。", "砂糖": "甘味料で、水の層として鏡に広がるという意味にはならないので合わない。", "糸": "細長いもので、うっすら広がる水の層には合わないので不適切。"}, "sentence_index": 6, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "シャツの膜を留めた。", "explanation": "ここは〈ボタン〉の意味。ボタンは留めるものだが、薄いかわのようなものは留められないので合わない。"}, {"text": "ペットボトルの膜を開けた。", "explanation": "ここは〈蓋〉の意味。ペットボトルの蓋は開けるもので、薄い膜は開けられないので合わない。"}, {"text": "虫を膜で捕まえた。", "explanation": "ここは〈網〉の意味。虫を捕まえる道具として網を使うが、薄い膜では捕まえられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52167, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "牛乳を冷ますと、表面に薄い膜が張りた。", "corrected_sentence": "牛乳を冷ますと、表面に薄い膜が張った。", "error_description": "「張る」の過去形は「張った」。「張りた」は連用形に「た」を付けた誤りで、促音の形になっていない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52167, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い夜、池の水面に薄い氷の膜に張っていた。", "corrected_sentence": "寒い夜、池の水面に薄い氷の膜が張っていた。", "error_description": "「張る」は主語の「膜が」を取る。「膜に張っていた」の「に」は誤りで、「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52168, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "包む手段や材料を示し、「薄い膜で包まれる」という形を作る。正解。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「膜の包まれて」は動詞に続かず文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、受身の「包まれる」は目的語を取らないので「膜を包まれる」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列・引用を示す助詞で、「膜と包まれる」は成り立たない。"}], "correct_answer": "で", "explanations": {"で": "包む手段や材料を示し、「薄い膜で包まれる」という形を作る。正解。", "の": "連体修飾の助詞で、「膜の包まれて」は動詞に続かず文が成り立たない。", "を": "目的語を示すが、受身の「包まれる」は目的語を取らないので「膜を包まれる」は不自然。", "と": "並列・引用を示す助詞で、「膜と包まれる」は成り立たない。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52168, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「膜ができる」の主語を示す格助詞。正解。"}, {"text": "に", "is_correct": false, "explanation": "「膜にできる」は結果の形として不自然で、「膜ができる」の主語の形ではない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「膜のできて」は述語にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「膜へできて」は「できる」の対象として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「膜ができる」の主語を示す格助詞。正解。", "に": "「膜にできる」は結果の形として不自然で、「膜ができる」の主語の形ではない。", "の": "連体修飾の助詞で、「膜のできて」は述語にならず文が成り立たない。", "へ": "方向を示す助詞で、「膜へできて」は「できる」の対象として成り立たない。"}, "error_tags": {"に": "結果・変化", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52168, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物の細胞や組織を包む薄い層。また、物の表面をおおう薄い皮。", "primary_collocate": null, "pronunciation": "まく", "ipa": "makɯ", "syllable_count": 2, "sentences": [{"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "膜", "complexity_tier": "T4", "furigana": "この際[さい]、脂質[ししつ]の膜[まく]がジャムの水分[すいぶん]浸透[しんとう]を防[ふせ]ぐバリアーとして機能[きのう]するという科学的[かがくてき]裏付[うらづ]けも無視[むし]できない。", "sentence_source": "mined"}, {"text": "細胞は薄い膜で包まれていて、中身が外に出ないようになっている。", "target_word": "膜", "complexity_tier": "T3", "furigana": "細胞[さいぼう]は薄[うす]い膜[まく]で包[つつ]まれていて、中身[なかみ]が外[そと]に出[で]ないようになっている。", "sentence_source": "generated"}, {"text": "牛乳を温めると、表面に膜ができるので、スプーンで取り除いた。", "target_word": "膜", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]を温[あたた]めると、表面[ひょうめん]に膜[まく]ができるので、スプーンで取[と]り除[のぞ]いた。", "sentence_source": "generated"}, {"text": "ゆで卵の殻をむくと、白身を包む薄い膜が残っていた。", "target_word": "膜", "complexity_tier": "T3", "furigana": "ゆで卵[たまご]の殻[から]をむくと、白身[しろみ]を包[つつ]む薄[うす]い膜[まく]が残[のこ]っていた。", "sentence_source": "generated"}, {"text": "シャボン玉は、水と石けんでできた薄い膜が空気を包んだものだ。", "target_word": "膜", "complexity_tier": "T3", "furigana": "シャボン玉[だま]は、水[みず]と石[せっ]けんでできた薄[うす]い膜[まく]が空気[くうき]を包[つつ]んだものだ。", "sentence_source": "generated"}, {"text": "油が水面に広がると、薄い膜になって虹色に光る。", "target_word": "膜", "complexity_tier": "T3", "furigana": "油[あぶら]が水面[すいめん]に広[ひろ]がると、薄[うす]い膜[まく]になって虹色[にじいろ]に光[ひか]る。", "sentence_source": "generated"}, {"text": "長い間放置した絵の具の表面に、固い膜が張っていた。", "target_word": "膜", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]放置[ほうち]した絵[え]の具[ぐ]の表面[ひょうめん]に、固[かた]い膜[まく]が張[は]っていた。", "sentence_source": "generated"}, {"text": "目に涙の膜ができて、景色がぼやけて見えた。", "target_word": "膜", "complexity_tier": "T3", "furigana": "目[め]に涙[なみだ]の膜[まく]ができて、景色[けしき]がぼやけて見[み]えた。", "sentence_source": "generated"}, {"text": "このフライパンは、表面に特殊な膜がついているので、焦げつきにくい。", "target_word": "膜", "complexity_tier": "T3", "furigana": "このフライパンは、表面[ひょうめん]に特殊[とくしゅ]な膜[まく]がついているので、焦[こ]げつきにくい。", "sentence_source": "generated"}, {"text": "肺は胸の中にあり、薄い膜に包まれて守られている。", "target_word": "膜", "complexity_tier": "T3", "furigana": "肺[はい]は胸[むね]の中[なか]にあり、薄[うす]い膜[まく]に包[つつ]まれて守[まも]られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "膜", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "細胞・臓器や物の表面を包んだりおおったりする薄い層", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52168, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "表面を覆う薄い層を指し、脂質の層として水分の浸透を防ぐバリアーに合う。正解。"}, {"text": "糖", "is_correct": false, "explanation": "砂糖などの糖類を指し、水分を防ぐ薄い層にはならないので文意に合わない。"}, {"text": "塩", "is_correct": false, "explanation": "調味料の塩を指し、薄い層として浸透を防ぐ役割はないので合わない。"}, {"text": "芯", "is_correct": false, "explanation": "中心の硬い部分を指し、バリアーとして薄く覆う層ではないので合わない。"}], "explanations": {"膜": "表面を覆う薄い層を指し、脂質の層として水分の浸透を防ぐバリアーに合う。正解。", "糖": "砂糖などの糖類を指し、水分を防ぐ薄い層にはならないので文意に合わない。", "塩": "調味料の塩を指し、薄い層として浸透を防ぐ役割はないので合わない。", "芯": "中心の硬い部分を指し、バリアーとして薄く覆う層ではないので合わない。"}, "sentence_index": 0, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "舞台の膜が上がって、拍手が起きた。", "explanation": "ここは〈幕〉の意味。膜は薄い層で、舞台の幕が上がるという使い方はしないので合わない。"}, {"text": "毛糸の膜を編んだ。", "explanation": "ここは〈毛糸〉の意味。毛糸は編むものだが、薄い膜は編めないので合わない。"}, {"text": "鍋の膜を開けて、中を見た。", "explanation": "ここは〈蓋〉の意味。鍋の蓋は開けるもので、膜は開ける対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52168, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "表面にできた薄く固い層を指し、絵の具の表面に張っている状態に合う。正解。"}, {"text": "粒", "is_correct": false, "explanation": "粒状のものを指し、表面に張る層にはならないので文意に合わない。"}, {"text": "砂", "is_correct": false, "explanation": "細かい砂を指し、表面に張って層になるという意味には合わない。"}, {"text": "針", "is_correct": false, "explanation": "細い棒状のもので、表面に張るものではないので合わない。"}], "explanations": {"膜": "表面にできた薄く固い層を指し、絵の具の表面に張っている状態に合う。正解。", "粒": "粒状のものを指し、表面に張る層にはならないので文意に合わない。", "砂": "細かい砂を指し、表面に張って層になるという意味には合わない。", "針": "細い棒状のもので、表面に張るものではないので合わない。"}, "sentence_index": 6, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "漁師は魚を膜で捕まえた。", "explanation": "ここは〈網〉の意味。網は魚を捕る道具だが、薄い膜では捕まえられないので合わない。"}, {"text": "部屋の膜を開けて、風を入れた。", "explanation": "ここは〈窓〉の意味。窓は開け閉めするものだが、膜は開ける対象ではないので合わない。"}, {"text": "瓶の膜を抜いた。", "explanation": "ここは〈栓〉の意味。栓は抜くものだが、薄い膜は抜く対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52168, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゆで卵をむいたあと、白身を包む薄い膜を残っていた。", "corrected_sentence": "ゆで卵をむいたあと、白身を包む薄い膜が残っていた。", "error_description": "「残る」は自動詞なので、主語を示す「が」が正しい。「膜を残っていた」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52168, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "目に涙の膜を広がって、景色がぼやけた。", "corrected_sentence": "目に涙の膜が広がって、景色がぼやけた。", "error_description": "「広がる」は自動詞なので、主語を示す「が」が正しい。「膜を広がって」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
